insert into public.appearances (place_id, show, season, what_he_ate, note, source_folder) values
  ('000db93b-e0f5-5dfd-a018-2c0596780bec'::uuid, 'the_layover'::show_name, 1, 'Cured meats, cheeses, breads for a picnic in a piazza.', NULL, 'Season 1'),
  ('000e078c-f208-58b5-b187-527232ab0b29'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had eggs and meat here with Paul Pederson, a musician from the Pine Barrens', 'Season 5'),
  ('001ffde7-c56d-5610-b56b-6c2171e7531a'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met with former mayor and mob lawyer, Oscar Goodman.', 'Season 3'),
  ('004b4e19-2de4-5d3a-bda6-5b1607927e33'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had dinner with Jenny Suen, feng shui master Thierry Chow, and chef May Chow. They had sourdough chicken-fat egg waffle with Taiwanese bottarga; sauteed prawns with pan-roasted pumpkin, dried shrimp roe, and prawn oil; tea-smoked pigeon; Hakka-style chicken; and pig brain with burnt-pear vinaigrette.', 'Season 11'),
  ('008ac03f-df81-51b7-89e4-3c93ce52b401'::uuid, 'the_layover'::show_name, 2, NULL, 'Farm to table; interesting menu. Alton Brown frequents this restaurant', 'Season 2'),
  ('0099b55b-1598-52f4-bc13-e0dc0dd60633'::uuid, 'the_layover'::show_name, 2, 'Unique rooms, rooftop pool', NULL, 'Season 2'),
  ('00a33d53-d188-5dc3-9bac-98583b7de930'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had yak milk tea and yak at someone''s house', 'Other Activities'),
  ('00aeb0eb-7bfd-522b-9df7-0b420645fbc6'::uuid, 'no_reservations'::show_name, NULL, 'Beer from regional producers,', NULL, 'Restaurants and Bars'),
  ('00c0ae02-62f1-591a-811c-2719d40cee7b'::uuid, 'the_layover'::show_name, 1, '118 floors up with an excellent view with tapas. Fancy', NULL, 'Season 1'),
  ('00e6514c-1421-5ca8-ab7f-3456f67a960f'::uuid, 'no_reservations'::show_name, NULL, 'Smoked fish, shrimp, fried smelt', NULL, 'Food markets'),
  ('00f9660b-ac81-5edd-b65b-e5e4f24d93a8'::uuid, 'no_reservations'::show_name, NULL, 'Floral arrangements for spiritual ceremonies', NULL, 'Sightseeing'),
  ('0100be77-090a-525f-9366-6952ba47742c'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony’s last meal in Sri Lanka is with local fishermen. They had grouper and squid with beer.', 'Season 10'),
  ('013d0119-f827-5b75-aecd-b5dd63569917'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had ribs and mai tais with author Sean Wilsey.', 'Season 6'),
  ('014610b0-e853-5108-8d97-f26cd06ca5fa'::uuid, 'no_reservations'::show_name, NULL, 'Huge baroque church', NULL, 'Sightseeing'),
  ('0165cad8-96c1-531f-9d67-f6189327ef33'::uuid, 'no_reservations'::show_name, NULL, 'Corned beef hash.with runny eggs and potatoes. HUGE omelets', NULL, 'Restaurants and Bars'),
  ('0190ac0a-9801-5c0e-98ac-8315be24d9dd'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with former rock star Irmin Schmidt of the Krautrock band Can. They had grilled scalllop with black salsify served with a consomme of burned hay, lemon gelee, and walnut oil; grilled lobster with a dashi of eel, marinated algae, fermented kale, and yuzu froth; braised ox cheeks with marrow, beet roots with mustard, gratin potatoes, black truffle.', 'Season 7'),
  ('01935b62-8444-563e-89ce-447017fc428e'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony ate with Fig owner and executive chef Mike Lata, Rebellion Farm owner Jeff Allen, and Sean Brock. They had barbecued turkey, pickled pigs’ feet and collard greens, barbecue coleslaw, potato salad with ramps, baked red peas, mac and cheese', 'Season 6'),
  ('01d36a57-d556-5f0e-93d0-9cd70b4ae20f'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Largest US base on Antarctica, and a tight knit community of researchers, scientists, carpenters, pilots, machine operators, and others who run the station.', 'Season 9'),
  ('01ee9439-c7c4-5e65-9fef-747b2b55cc90'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Chef friends put together a meal with local seasonal ingredients: "90-day aged ribeye steaks from nearby Bear Creek Farms... topped off with oyster mushrooms and bourbon soy, and some nice runny eggs, and garlic. Grits, greasy beans, homemade ricotta with a cold smoked sausage, and roasted acorn squash.', 'Season 8'),
  ('01eee464-41ab-55da-9d79-eba61402dc0c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate typhoon crab on a boat', 'Restaurants and Bars'),
  ('0258a0a6-f187-5381-89cb-723900812caf'::uuid, 'the_layover'::show_name, 2, 'Nice views and attentive staff', NULL, 'Season 2'),
  ('028b9c9f-6f45-5661-9296-94559309774f'::uuid, 'the_layover'::show_name, 1, NULL, NULL, 'Season 1'),
  ('0290087e-6647-5f59-82b6-d1377131c98d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The speciality is devian. The lamb is specially raised as free-range in highlands in the east.', 'Restaurants and Bars'),
  ('02d49e8a-9566-5359-9a75-40bfa157999f'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Other Activities'),
  ('02f54841-e97a-553f-af67-f1d6a0bb81bb'::uuid, 'the_layover'::show_name, 2, 'Punk shows', NULL, 'Season 2'),
  ('03250768-2be3-5d84-966e-32a6a2db94d3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Lots of food stands. Tony met with a local food blogger Josh Suh and ate claypot rice', 'Food markets'),
  ('03574827-7bb6-5e05-ba43-1f948f0e3ffe'::uuid, 'the_layover'::show_name, 2, 'Deep fried fish, cajun boil', NULL, 'Season 2'),
  ('036d61d7-805c-5365-b1c9-36a3f0a759e5'::uuid, 'the_layover'::show_name, 1, 'Wontons and noodles', NULL, 'Season 1'),
  ('037269a1-24d9-5928-a056-e4640983ffe2'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony ate sabodet (sausage made from pig’s head, tongue, and beef) with Chef Georges Reynon and Chef Daniel Boulud.', 'Season 3'),
  ('038d5d21-442d-5670-9db3-9b7ac6481699'::uuid, 'the_layover'::show_name, 2, NULL, 'Fast fry style restaurant. Bamboo shoot, egg noodles, sea snails, fried oysters, crispy cod filet, 3-cup chicken (classic Taiwanese dish)', 'Season 2'),
  ('038fc74f-6e53-54f5-a990-9e1c06043f7b'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with filmmaker Tony Buba to have drinks and discuss the economy of Braddock''s blue collar neighborhood.', 'Season 10'),
  ('03c1f15f-27f4-5096-80ac-09c5f42fec26'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony went with the chefs to watch the Montreal Canadiens play the Carolina Hurricanes at the stadium', 'Season 1'),
  ('03ced693-9562-5c92-b671-56fa661bf394'::uuid, 'the_layover'::show_name, 2, 'Dumplings', NULL, 'Season 2'),
  ('04110495-001b-5c0d-8850-c3afce427426'::uuid, 'the_layover'::show_name, 2, 'German food and beer', NULL, 'Season 2'),
  ('047faac0-f4b6-5cca-9dab-9d2e588bddcc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This area on the edge of Port-au-Prince has a market with a lot of street food available. Laloo (a leafy green veggie with bits of crab, okra, and peppers), rice & beans, pork & chicken in Creole sauce with picklese (a spicy slaw).', 'Restaurants and Bars'),
  ('0481e74f-36dd-5211-8958-f3bded325489'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony met with a group at this place. They discussed "txokos" or "private and historically all-male gastronomical societies, though that gender rule has changed with the times." The menu for the evening: "diced raw tuna, grilled prawns with green sauce" to start, then "for the main, fried hake cooked with txakoli and steamed clams."', 'Season 9'),
  ('049e2119-8444-5da7-85c2-ce63412b3c75'::uuid, 'a_cooks_tour'::show_name, NULL, 'Tete de veau (Veal sweetbreads, cheeks, etc)', NULL, 'Disc 3: Europe'),
  ('04b2ff2f-16c5-5940-87d8-c275c69d8b14'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony ate iftar (meal at sundown when fasting for Ramadan has broken) with the Rasdien family. Malaysian family, they prepare panang curry with beef, a chicken pie, traditional ramadan shake.', 'Season 2'),
  ('04f55150-8005-5d12-9081-f70f94a00eda'::uuid, 'no_reservations'::show_name, NULL, 'Restaurant people after work bar', NULL, 'Restaurants and Bars'),
  ('052022f3-b945-5fc2-b8fb-d8e4322d6428'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony had a meal with Laila El-Haddad and her family. They ate maqluba (a traditional Palestinian dish made of layers of fried eggplant, tomato, potatoes, caramelized onions, and chicken, sautéed then simmered in a broth with nutmeg, cinnamon, cardamom, and rice). They traveled just outside Gaza City to a gathering place for elders where they had fatit ’ajir (roasted baby watermelon, eggplant, tomatoes, squash, chiles, and olive oil) served with unleavened bread.', 'Season 2'),
  ('0534ac34-f035-575b-b49d-4968e9ed4511'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Michelin starred restaurant. Seared tuna with borlotti bean puree; turbot confit with fresh asparagus; clams; spaghetti di gragnano with mussels, calamari, sea urchin, bottarga, shrimp; gnocchi with lardo, fresh fava beans, black truffle. Tableside prepared roast duck.', 'Restaurants and Bars'),
  ('057a9623-c6d6-5436-9c94-334197ad9fbd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This is the hotel Tony always stayed in. He signed a copy of Kitchen Confidential and put it in his room. It''s an author hotel', 'Lodging'),
  ('05976f0d-ce0c-5964-b1f7-d7b4fb411ca8'::uuid, 'no_reservations'::show_name, NULL, 'Italian bakery. Cannollis/Sfogiatelle', NULL, 'Restaurants and Bars'),
  ('05ae5ea3-7799-5cbe-a6b7-8d01c16a875a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony stopped by this small bar next to the restaurant and had small plates', 'Restaurants and Bars'),
  ('05c218a9-cda7-558a-a444-337e35cf4723'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A tiny bar where Tony had more drinks and did shots', 'Restaurants and Bars'),
  ('0623d392-0727-5888-90c1-650ba9d5aef3'::uuid, 'no_reservations'::show_name, NULL, 'Mutton bones cooked in a sweet and spicy sauce. It''s messy.', NULL, 'Restaurants and Bars'),
  ('0654087e-9287-5782-98d2-161bb5553ba4'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony had curried goat, samosas, tandoori chicken, fish curry with chilis in this area called Little Bangladesh', 'Season 1'),
  ('06644e19-af9b-5add-a078-48f221ed390c'::uuid, 'no_reservations'::show_name, NULL, 'Traditional Czech restaurant', NULL, 'Restaurants and Bars'),
  ('0692aac0-5c95-5581-9b02-d40de5ea4f28'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Not sure if this restaurant is still here. Tony and Eric met with Fuchsia Dunlop, a James Beard award-winning writer and cook who specializes in Chinese cuisine. They had "lily buds scented with rosebuds, thinly sliced beef shank with chili oil, tea tree mushrooms blanched and lightly stir-fried, prawns served cold with homemade noodles dressed with natural vegetable extracts, noodles hand-cut with duck-egg yolks, braised sea cucumber."', 'Season 8'),
  ('069d1db0-3614-5a1f-85a6-b7ed20404176'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Commercial artery/walkway for pedestrians that runs through downtown Santiago', 'Sightseeing'),
  ('06a1fca7-d22b-5d06-a237-488e9d125c4e'::uuid, 'a_cooks_tour'::show_name, NULL, 'Snow cone with condensed milk and fruit syrups', NULL, 'Disc 1: United States'),
  ('06ee3f7e-c09d-5e41-86f5-b66495dcd52c'::uuid, 'no_reservations'::show_name, NULL, 'Fish market', NULL, 'Food markets'),
  ('070423f6-a893-561b-bd5e-d97134fd4480'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony was invited to the crew meal for the vineyard workers cooking real authentic Mexican food', 'Sightseeing'),
  ('070f5c0a-3d3c-5f11-8520-919ca2396b5e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Cicchetto - sort of like tapas or pinchos. A bar that serves these is called a Bacari.', 'Restaurants and Bars'),
  ('0736c547-d6b3-51b3-843f-a3fdfe1a7c83'::uuid, 'the_layover'::show_name, 2, 'Skeet shoot', NULL, 'Season 2'),
  ('076221de-48c9-5dce-bbe5-f432ee0341b7'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had veal saltimbocca with Bruce Cameron Elliott and a pal from the Old Town Ale House whose nickname is Buzzkill. They discussed the Cubs and White Sox rivalry. His dining companions had scallops in pesto cream sauce and squid ink pasta with shrimp.', 'Season 7'),
  ('079a0108-214a-56de-9628-311706cbb6cd'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony ate the Senegal national dish with some locals. The national dish is called ceebu jen (meaning rice with fish). The fish they used was "Senegalese grouper, scored and stuffed with a mixture of garlic, parsley, and peppers, then slow simmered in a hearty tomato broth, infused by a funkatizing goodness brought by fermented conch and salt fish, served over rice and vegetables."', 'Season 7'),
  ('07d05b08-a2c3-5b3b-8244-1c12fbf2dfa2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tom Kitchin''s restaurant: French techniques with Scottish ingredients', 'Restaurants and Bars'),
  ('082dd037-e621-57f4-bfd0-e9e5035cf428'::uuid, 'the_layover'::show_name, 1, 'Pasta', NULL, 'Season 1'),
  ('082e854d-86b0-5c98-a02e-d9fe405c0927'::uuid, 'no_reservations'::show_name, NULL, 'Restaurant specializing in maple syrup', NULL, 'Restaurants and Bars'),
  ('082f968a-0ffc-55a5-8cce-cf1ecf15e9c1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went hunting in the mountains near here. They did not catch anything but his host''s family made dinner with venison for him.', 'Other Activities'),
  ('0839b442-f9f9-5681-a063-9efddcb70ca4'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony ate here with Paul Rimple, Tbilisi bureau chief for Culinary Backstreets. They had "salad with orange, almonds, and honey; grilled lamb ribs with pomegranate sauce; slices of fried eggplant wrapped around a walnut filling; chkmeruli, chicken slow-baked in an oven and then simmered in garlic and milk."', 'Season 7'),
  ('0849552b-9dc5-5cc9-b951-8a8c48585bb8'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('0849afa7-6364-59dd-93fc-731f77cbc5e0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The market near the citadel is "a dizzying maze of alleys and vendors" where you can buy everything from guns to food. Tony had tea at this shop', 'Food markets'),
  ('0849e7c1-dcba-5dcc-8845-de165f5b1add'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony had a dream to travel on the Congo River. He cooked some coq au vin on the boat. Later he and crew were stuck here due to technical issues with transportation', 'Season 1'),
  ('08901205-3971-5147-b369-c9a03d1ce4a6'::uuid, 'the_layover'::show_name, 1, '$25 to ride the tallest ferris wheel in the world', NULL, 'Season 1'),
  ('08c0d9bb-56bc-5850-aac0-5a9bdb354cf6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Fergus Henderson''s restaurant. It was new when Tony visited. Roasted bone marrow with bread and sea salt. Stewed pig''s head with bacon', 'Restaurants and Bars'),
  ('090d3ce9-e101-59c5-a8d3-a6b15b78a69b'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had a meal with Josmar Trujillo, a writer and activist. They did not say what they had but it involved rice and beans and some kind of grilled meat.', 'Season 9'),
  ('093313f3-53f0-58ac-907f-0277b5780ecd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'All you can eat for less than a dollar. Thali style vegetarian food.', 'Restaurants and Bars'),
  ('09371401-c3fd-5007-aa5f-fc59fbb3b6fe'::uuid, 'parts_unknown'::show_name, 7, NULL, '"A hangout for Cologne''s artist community since the first World War." Tony ate sauerbraten (pot roast of horse meat) with chef René Stessl', 'Season 7'),
  ('096f116e-6a94-59fa-b659-1085c4ee8af4'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Author Daniel Woodrell lives here, one of Tony''s favorite authors. His buddy made some squirrel pot pie, venison steaks.', 'Other Activities'),
  ('097776b5-9f5f-5dc8-b33e-84ed8bba0474'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony and Eric had drinks at this bar with a local filmmaker & sports writer, Gilles Rof', 'Season 6'),
  ('099490d9-debe-5486-8d66-67a0d7b2cdf9'::uuid, 'a_cooks_tour'::show_name, NULL, 'Chao muc is squid soup', NULL, 'Disc 6: Asia'),
  ('09b01cd9-365d-5a37-8251-66f497c75308'::uuid, 'the_layover'::show_name, 1, 'Fresh fruit smoothies', NULL, 'Season 1'),
  ('09b5a297-cac4-5cf8-9011-14cabaff60de'::uuid, 'no_reservations'::show_name, NULL, 'Popular fried soup dumplings. Tofu Beef Noodle soup', NULL, 'Restaurants and Bars'),
  ('09bc9d99-fc66-56a4-98c1-522c9640ce25'::uuid, 'no_reservations'::show_name, NULL, NULL, '"Food for the gods" with boudin noir, "one of the very best things on earth"', 'Restaurants and Bars'),
  ('09e2ea3a-74c7-5d2e-a190-1af65f525ca5'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony met comedian Al Madrigal and editor of OC Weekly, Gustavo Arellano. They went to this place to get some taquitos, "rolled up, fried, smothered in avocado sauce, topped with chile guero, garlic, tomatillo, and cilantro." Also, a burrito with beans with machaca, spicy shredded beef, sauce, and cheese.', 'Season 9'),
  ('0a3f4a9e-298c-5bdc-a8a7-30265986242b'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony drank Guinness here at 8 am!', 'Disc 1: United States'),
  ('0a49f316-e80c-5b3b-a87b-b5a56bce59ad'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Known to locals as Bar do Gomes, this bar is located in what Tony calls the "most magical neighborhood" in Rio.', 'Restaurants and Bars'),
  ('0a4f5f7f-0380-5bde-ab07-7a7d2ee0d91a'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony visited this off road park of mud and machines (ATVs, motorbikes). On the menu: "frog legs, snapping-turtle patties, catfish (barbecued and fried), smoked bass."', 'Season 11'),
  ('0a5492ab-4169-5b06-bdd0-fcb251b39feb'::uuid, 'no_reservations'::show_name, NULL, NULL, '"The highest lookout point in Managua, it was once home to former dictator Somoza''s palace and personal prison grounds. A notorious site for political prisoners."', 'Sightseeing'),
  ('0a6379dd-c1e2-5b05-b149-27c80bb5777a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Two falafel shops owned by brothers who do not speak to each other, right next door to each other.', 'Restaurants and Bars'),
  ('0a6428f3-8348-5a75-9903-5362c81377c6'::uuid, 'the_layover'::show_name, 1, 'Korean food', NULL, 'Season 1'),
  ('0a89da00-0984-5e53-b271-768cde7b0bf7'::uuid, 'the_layover'::show_name, 1, 'Old school breakfast diner', NULL, 'Season 1'),
  ('0a8cfc58-3944-5225-91e7-547f33908a5d'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony visited Al Hill, who lives on the site of the 3.5 million sq ft auto plant that is no longer in use.', 'Season 2'),
  ('0a947c84-ff2a-57fa-b0d4-986acd4b2d17'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with the local band Keystone. They made him the national dish, adobo. They had adobo with pork and chicken.', 'Season 7'),
  ('0ac3562b-075c-54df-9435-4c5db9863c48'::uuid, 'no_reservations'::show_name, NULL, 'Ceviche restaurant', NULL, 'Restaurants and Bars'),
  ('0ad0a73b-2a0a-599b-8d7b-8481d70eaf8c'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony ate here with Chef Jet Tila, who said this place has the "best Thai food in Vegas by far." You MUST have northern Thai food here. Tony says DO NOT order the pad thai. They had nam prik (a composed room temperature salad); nam kao tod (a puffed crispy rice salad with preserved pork sausage); hung lay (pork curry braised with garlic and ginger); and Northern larb.', 'Season 3'),
  ('0ad95000-84bf-538e-83b4-1a5ee44f004d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A memorial garden to the slaves who were traded and sold on the island', 'Sightseeing'),
  ('0aec6ae1-abf1-5705-8f9d-2f9879321dc4'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Sightseeing'),
  ('0b02425a-4cdc-5db1-9980-9fafa6897458'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a meal with activist and journalist Tamara Chergoleishvili, founding director of Georgia’s Tabula Media. They had khinkali which Tony describes as “big, fat, juicy soup dumplings filled with spicy cumin-jacked minced beef in a hot, rich, potentially scalding broth”.', 'Season 7'),
  ('0b145f10-0a3b-5fd7-bd32-adc3eb7d3d67'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony stays here in this remote eco-resort. He goes on a boat and catches a huge pirarucu fish and the hotel staff cooks it for him over a grill with tomatoes, onions, and cilantro.', 'Lodging'),
  ('0b4ff436-8c52-5cd3-836e-026272bb115c'::uuid, 'no_reservations'::show_name, NULL, 'Diner; American/Asian. Egg creams', NULL, 'Restaurants and Bars'),
  ('0b66e993-2322-55a0-819f-622a32c08b3b'::uuid, 'parts_unknown'::show_name, 8, NULL, 'The day after the big party at Alison''s house, they went to get bloody marys and mimosas at this bowling alley with brunch food.', 'Season 8'),
  ('0b89e42c-a5f8-53a8-b636-e77add4f5ab3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Local chefs prepared a stuffed lamb for Tony and Zamir. They served it with potato salad with pork jowl and pickled onions, cider vinegar coleslaw, and cornbread.', 'Other Activities'),
  ('0bc42dbd-8194-5de6-b141-255781047767'::uuid, 'parts_unknown'::show_name, 1, NULL, '"Once one of the swankest department stores in Rangoon," says Tony. "Now people live here."', 'Season 1'),
  ('0bf14fde-c5f7-544a-ad89-7bc82bf86a12'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Very good soba noodle. Simple noodle dish served with a duck broth, pieces of duck, and scallion.', 'Disc 5: Australia and Japan'),
  ('0bfc0d9f-2f72-5e77-9b90-f98d07afb29b'::uuid, 'no_reservations'::show_name, NULL, 'Stuffed Crab and pork shank soup (called bulalo)', NULL, 'Restaurants and Bars'),
  ('0c42d608-3a02-5bc5-bffd-2fae60830898'::uuid, 'no_reservations'::show_name, NULL, NULL, 'El Bulli was once located here, closed in 2011. The famous restaurant of the Adria brothers. Jose Andres (who trained at El Bulli) met up with Tony to eat there.', 'Restaurants and Bars'),
  ('0c4e13aa-aacb-51b5-92ef-a6c8a5b74eaa'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony got his "I suspend judgment" tattoo here (Montaigne)', 'Season 1'),
  ('0c6eaa44-c762-59ad-a06f-99e1f1a2d9dc'::uuid, 'no_reservations'::show_name, NULL, NULL, '"I like a hotel with a past," says Tony. He had a drink in the hotel bar with writer Jim Harrison', 'Lodging'),
  ('0c82a95d-a965-5d89-9c6a-6a5e9a2edc0b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony talked with a retired spy and visited the museum', 'Other Activities'),
  ('0c8300b0-aa4a-5fed-84d8-baa364b684fe'::uuid, 'the_layover'::show_name, 2, 'Shrimp and grits with a bacon sauce', NULL, 'Season 2'),
  ('0c8f796c-673f-5c78-a67c-9ae48bb40a37'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Roy had an Aloha burger, Spam Little Big Bite sandwich, and Halo-Halo, which Tony described as an “oddly beautiful” dessert with sweet red beans, white beans, red and green jello, young white coconut, flan, ice cream, and shaved ice.', 'Season 1'),
  ('0cec51f9-6d6b-53c6-b63d-aff42a36484f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate at the MasterChef Croatia winner''s restaurant, which serves seafood that are usually seen as "trash fish" and fishermen would cook with it', 'Restaurants and Bars'),
  ('0d1338e8-c5ab-5457-8de1-2343d5dab00d'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a street food dish called ndambe, a spread of spicy lentils on a baguette. You buy the baguette from this bakery, then go to the woman on the street who has the lentils to spread on it.', 'Season 7'),
  ('0d3c75e5-2028-5647-a5e6-d2b7048e1a55'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony ate at a jerk stand called Piggy''s in this town. Unfortunately it burned down in 2019', 'Season 4'),
  ('0d4622dc-0412-5ea8-abc3-d0f3ac8c8d87'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Grilled octopus, sea urchin, fried cuttlefish, sheep milk cheese', 'Restaurants and Bars'),
  ('0d4e5b03-2168-539e-91e9-136bff287717'::uuid, 'no_reservations'::show_name, NULL, 'Crab', NULL, 'Restaurants and Bars'),
  ('0d84afa5-a1e7-5d23-89c4-48c0cade0da0'::uuid, 'the_layover'::show_name, 2, NULL, 'Old bank building made over into a modern space. Lobby bar has mixologists.', 'Season 2'),
  ('0d85781e-7526-5f5a-bce1-04d0d62bad40'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony and Darren had yak butter tea. Tony tried braised pork, pork-bone soup, pepper soup, and rice. Darren tried betelnut which he said made him feel high.', 'Season 11'),
  ('0dbd0b35-8591-5a20-9326-1fdf9f3a233e'::uuid, 'the_layover'::show_name, 2, NULL, 'Where Tony stays', 'Season 2'),
  ('0de53f0b-0c77-5103-9661-5aa5751b93b7'::uuid, 'the_layover'::show_name, 2, 'Fried foods', NULL, 'Season 2'),
  ('0e2460a1-dbee-553e-9cb1-875ada3e689e'::uuid, 'no_reservations'::show_name, NULL, 'Huge fish market', NULL, 'Food markets'),
  ('0e4caada-743c-558d-bba4-38755be21fdb'::uuid, 'parts_unknown'::show_name, 2, NULL, 'This place has been around for over 90 years. Open 24 hours. The Coney dog has chili, cheese, onions, and mustard atop a hot dog.', 'Season 2'),
  ('0e66cbfb-597f-545e-87e2-8ca8c2fd0c72'::uuid, 'the_layover'::show_name, 1, 'Old World Greek food', NULL, 'Season 1'),
  ('0e6a7b65-e347-5c13-b5b4-819a3268bc2c'::uuid, 'no_reservations'::show_name, NULL, NULL, '100 year old market selling fruits, veggies, meat, fish. Tony and Zamir shopped there for a picnic. Tony bought the good caviar, which he implies is sturgeon caviar from Caspian Sea which is illegal.', 'Food markets'),
  ('0e7dafe1-26ed-50cb-ba7e-897e13145c05'::uuid, 'a_cooks_tour'::show_name, NULL, 'Meat market.', NULL, 'Disc 3: Europe'),
  ('0ede760f-6196-5e05-a384-41a25e07b337'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Dodol garut, a rice candy popular in Indonesia. Tony went on a factory tour and watched workers make the candy by hand', 'Sightseeing'),
  ('0ee738df-13f6-57f9-9fe0-7205615f82f0'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Former site of Gadhafi''s palace, destroyed by rebels in 2011. They were told to leave while they were filming this scene.', 'Season 1'),
  ('0f1ee1ae-559d-54c6-bf05-d15d962d3469'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Meal on a family farm with a collection of chefs. They had "smoked pig''s head with vegetables and chilies, native green beans called andu prepared with bacon and farofa" (toasted cassava flour). Also, "chicken in brown sauce baked in a clay pot, finished with the blood of chickens fresh killed this morning, served with pequi rice, farofa, and of course, cachaca."', 'Season 8'),
  ('0f573e1e-b0cf-5b36-a788-cb8ecc2241e3'::uuid, 'the_layover'::show_name, 2, 'Luxury hotel', NULL, 'Season 2'),
  ('0f5bc73a-3f05-500b-9888-96c5c20a48f2'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony went to The Blue Room to watch singer-songwriter Margo Price record directly to acetate at Jack White''s studio.', 'Season 8'),
  ('0f5bde48-72a0-5729-ad3f-ec45e011703f'::uuid, 'no_reservations'::show_name, NULL, 'Seafood spot with 20 different kinds of oysters', NULL, 'Restaurants and Bars'),
  ('0f70d0b3-39bf-521a-87bb-3160ac2174f3'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had apricot vodka, and trout wrapped and baked in lavash', 'Season 11'),
  ('0f7911f9-b246-5531-8880-a3f167c31b99'::uuid, 'the_layover'::show_name, 1, NULL, 'Food truck court! Tony ate at Sakaya Kitchen: short rib chunk cheesy spicy tater tots, and ginger brussel sprouts, and crackling herb duck sandwich.The Frita Cuban sandwich from Grillmaster food truck: Sausage and pork patty.', 'Season 1'),
  ('0f7c6223-c6d3-5ae0-9d7c-0c64a28be437'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony met with his old friend Dinh Hoang Linh and had grilled eel with lemongrass, green chili, and pepper. And lobster', 'Season 4'),
  ('0f825a44-7c13-532b-bf8e-72c8972c6843'::uuid, 'the_layover'::show_name, 2, 'The Chicago famous sandwich: Italian Beef', NULL, 'Season 2'),
  ('0f9e51e0-b5b4-5f6e-921f-950fb854b323'::uuid, 'the_layover'::show_name, 2, 'Modern Spanish food and bar', NULL, 'Season 2'),
  ('0fb04346-8cd7-5395-b9d1-f10cf4b71672'::uuid, 'no_reservations'::show_name, NULL, NULL, '"A weirdly wonderful place" built by Quakers in 1870 by Alfred and Albert Smiley (twins). "Strange, but fabulous," Tony says', 'Lodging'),
  ('0fdff966-5eda-518e-b24b-c06ba5e847fb'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They went to see the "Free Stamp" sculpture', 'Other Activities'),
  ('0ff1747b-dd84-5a9e-a805-252ee9d498ff'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Restaurant Tony worked at before and during the filming of the show. Permanently closed now.', 'Disc 1: United States'),
  ('0ff1747b-dd84-5a9e-a805-252ee9d498ff'::uuid, 'no_reservations'::show_name, NULL, NULL, 'On this episode, Tony visited the restaurant he worked at when he wrote Kitchen Confidential to work the line. (Now closed). He revisited in the season 6 "Techniques Special" and "Holiday Special" (season 7). On the "Holiday Special" Carlos made him a plate of choucroute which includes sauerkraut, veal sausage, frankfurter (French version of salami), potato, beer, smoked pork loin, pork belly, blood sausage, and bacon.', 'Restaurants and Bars'),
  ('0ff3bb97-58d7-5880-ba26-9b9fa8e1a2ac'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Not sure if this is the park where they surfed, but close enough. And it was cold.', 'Other Activities'),
  ('1039ab97-52b6-554e-833a-3bab483fb880'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony went on a helicopter ride with pilot Ryan Skorecki, who flies scientists around the continent to remote areas. He pointed out Mount Lister from the sky.', 'Season 9'),
  ('10423d51-8db1-5980-81d2-d358f129181a'::uuid, 'no_reservations'::show_name, NULL, 'Bar and probably the only place to eat in town', NULL, 'Restaurants and Bars'),
  ('105c37d7-c458-5a50-8c0d-f6d996d2f6b7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met with a local band to try food from this fishing store turned restaurant that serves canned seafood from the area.', 'Restaurants and Bars'),
  ('10973ca6-1a08-5363-81ce-e9fa790d3354'::uuid, 'the_layover'::show_name, 1, 'Burgers and beer', NULL, 'Season 1'),
  ('10c0d106-a246-58d7-994a-2bbbd961a027'::uuid, 'no_reservations'::show_name, NULL, 'One of Italy''s oldest restaurants. Pizza, sandwiches, bread.', NULL, 'Restaurants and Bars'),
  ('10c4472a-4004-55eb-ade7-0ea2f714c19b'::uuid, 'no_reservations'::show_name, NULL, 'Spanish seafood with Chinese influence', NULL, 'Restaurants and Bars'),
  ('10cf08b4-e7c3-533b-a4c4-69b924984b33'::uuid, 'the_layover'::show_name, 1, 'Morbid taxidermy gift shop', NULL, 'Season 1'),
  ('10d6a49e-4509-5b6c-b2f9-176cab1d178f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Chef April Broomfield met with Tony at her house (not at this location) to cook a proper English holiday meal. They cooked a duck and some savory pie with veal shank, pig trotter, garlic, chanterelle mushrooms, swiss chard.', 'Restaurants and Bars'),
  ('10ea5dd5-0b64-5f0f-bf99-fe49b623a4a6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went to a backyard boil at a chef''s house in this area known for its crawfish. There was also roast corn hash with tasso, venison, stuffed wild wood ducks. The next day, he attended a boucherie, which is a pig slaughter where teams of people quickly work on processing different parts of the pig to make products such as andouille sausage, boudin, ribs, cracklings, and more.', 'Other Activities'),
  ('11075417-ceae-5dc9-b123-1305b4cb053b'::uuid, 'no_reservations'::show_name, NULL, 'Martinis', NULL, 'Restaurants and Bars'),
  ('110fc0a3-2a5c-57d3-95d7-48452de90575'::uuid, 'the_layover'::show_name, 2, 'Gastropub', NULL, 'Season 2'),
  ('113de364-0272-5609-a685-f441671a859d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Zamir went by himself (with a cameraman) to this weird museum', 'Sightseeing'),
  ('117c7633-aa4d-596f-826b-a8dcd1189b90'::uuid, 'the_layover'::show_name, 2, 'Mountain experience. Suburb south of the city.', NULL, 'Season 2'),
  ('11b756e0-2500-5182-a9e4-7a5c39c14b08'::uuid, 'the_layover'::show_name, 1, 'Sausage, cheese, beer', NULL, 'Season 1'),
  ('11be29e9-e456-57fb-a0b0-ce2da47f1d69'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('11c044d5-9a4e-5c37-9a3b-86c3b465ab05'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Also known as "Cussing Noodles" due to the owner yelling at people, but is Tony''s friend Ha Pham''s favorite place to get bún chin zou, or as Tony describes, "a glorious steaming bowl of rice noodles with spicy chilies, a rich hearty porky broth with pig''s knuckles and snout. It''s the only item on the menu and it''s good!"', 'Season 8'),
  ('11fbd326-246d-5ae6-aa34-2a63a98d9f96'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony and Chris had lunch here and talked about their childhoods on the beach. They had clams in drawn butter, which he says no matter where in the world he ate them, it reminds him of this spot. They also had fried clams and fries.', 'Season 5'),
  ('11fe218c-2f78-5865-9d2d-618cbbec3c78'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had seafood here', 'Restaurants and Bars'),
  ('11fef83a-7c64-53a4-8819-4f78630a863e'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Deep in the jungle, this contemporary art museum built by an eccentric visionary.', 'Season 8'),
  ('12508b30-ce6f-51c6-b242-38cf54d54db9'::uuid, 'the_layover'::show_name, 1, 'Chicken Tikka Masala', NULL, 'Season 1'),
  ('125a43ab-b293-5572-b65f-42a77b72c06b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Restaurants where chefs go. Tony ate there with Eric Ripert and Scott Bryan.', 'Restaurants and Bars'),
  ('1289741a-5647-5478-ab19-eb86ab7f3351'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had drinks with Shina Peller, owner of Club Quilox, (a music venue) and Banky Wellington, record label owner', 'Season 10'),
  ('1292d460-606c-55bc-8960-0b089e531194'::uuid, 'no_reservations'::show_name, NULL, 'Cheesemakers', NULL, 'Food markets'),
  ('12a3b935-98f6-54ee-8977-495082cd8fbd'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony returned to the small village of Kuching nearly a decade since his last visit. “When I first went up this river, I was sick with love—the bad kind, the fist around your heart kind. I ran far, but there was no escaping it. It followed me up river, all the way. That was 10 long years ago. … Yet here I am again, heading up to that same longhouse in the jungle.”', 'Season 6'),
  ('12a81eae-a631-5bbf-b414-5e08f6e1e398'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with journalist Mark Navales to have drinks at this bar.', 'Season 7'),
  ('132f7241-aa15-5b04-a598-3a133d1bc953'::uuid, 'no_reservations'::show_name, NULL, 'Ingredients grown in garden or locally, and cocktails', NULL, 'Restaurants and Bars'),
  ('135ef566-c3f2-5e5f-aebd-f973a8d09296'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went shopping for hunting clothes', 'Other Activities'),
  ('13731b83-2de2-581e-bd67-aa180d64d495'::uuid, 'no_reservations'::show_name, NULL, 'Seafood restaurant', NULL, 'Restaurants and Bars'),
  ('1383e89d-fecd-5a73-894c-8f175fb342b5'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Seafood cooked on the beach in this small town. Fishermen bring in fresh catch and cook it for you. They had a huge lobster and a crab, Puerto Nuevo style. They chop it lengthwise, fry it and serve with beans & rice.', 'Other Activities'),
  ('13b94a05-5db4-5605-a90a-0f5ad6b08dd1'::uuid, 'the_layover'::show_name, 2, NULL, 'Tony''s chef friend Donald Lake, who he ate with on the show, owns this restaurant. Cajun food. Muffaletta is amazing.', 'Season 2'),
  ('13bf9233-8b6c-56f7-ab1e-a8a2d287dbaf'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony took a boat out to this island, where he ate lots of seafood like crab cooked in coconut milk, fried calamari, giant crayfish, and other fish.', 'Sightseeing'),
  ('13cce447-f812-596a-9d32-d937b83e9983'::uuid, 'parts_unknown'::show_name, 9, NULL, 'A catering business run by women whose profits go to funding children''s education in rural areas. They cooked a meal of "kabuli laham, slow cooked goat in a rice pilaf scented with star anise. Musanif djaj, a local specialty, are pan seared dumplings stuffed with chicken, pepper, ginger, turmeric, and onions. And of course there''s Omani bread with honey."', 'Season 9'),
  ('13f275ef-e5fd-59e4-8fee-6a3d348f9155'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had extremely fresh ceviche at this fish market', 'Restaurants and Bars'),
  ('14080d4f-042b-5d78-bc96-4026fc0b3990'::uuid, 'the_layover'::show_name, 2, 'Impressionist art gallery', NULL, 'Season 2'),
  ('14552721-bb64-52fe-8ae8-707a5e15a7ee'::uuid, 'parts_unknown'::show_name, 4, NULL, 'America''s oldest gay bar (built in 1798). Tony had drinks here.', 'Season 4'),
  ('14806531-4238-5a3d-9e87-2a4bc83225ed'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony went with a group of chefs to a place up near the lake to eat some hearty cod stew, various terrines (duck, rabbit, guinea hen, boar), jellied foie gras, fire-roasted moose shoulder and leg, ribs braised with red wine, local boletus, and chanterelle mushrooms.', 'Season 11'),
  ('149bbeaa-12ad-5101-b5a5-7c3bef7785e9'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony ate smokes (smoked-sausage sandwich) and ears (pig’s ear sandwiches), both served with housemade hot sauce and coleslaw; hot tamales.', 'Season 3'),
  ('14a71cbd-8c2c-5cb4-a021-79e8ae1ae1d1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Not sure if this is the correct address. Morimoto buys his knives from Inotada Knife Productions in Sakai City.', 'Other Activities'),
  ('14d96812-4761-5582-a108-af35be07e74c'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with a career server named Mario and had drinks and snacks.', 'Season 7'),
  ('150563cb-19a4-53a7-94a7-9ff1b72724e6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony has Vietnamese coffee and crepes, which are made with rice flour and coconut milk (banh xao), served with shrimp, pork, saffron, and bean sprouts.', 'Restaurants and Bars'),
  ('155d9127-c045-5e37-a033-286801a1428b'::uuid, 'a_cooks_tour'::show_name, NULL, 'Cajun/Creole', NULL, 'Disc 1: United States'),
  ('157d5e6d-952f-5aff-9abd-248ad29cb0d5'::uuid, 'parts_unknown'::show_name, 9, NULL, '"I love that word, corniche. I love any city with a corniche," said Tony.', 'Season 9'),
  ('1593aebe-3b0e-5434-83c2-ef73b460c1ce'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Former site of Mutfak Dili Ev Yemekleri, where Tony had some traditional food.', 'Season 6'),
  ('15aac213-5c73-564e-8b7e-f8ff4763a295'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Chef Olivier Roellinger''s bakery specializing with salted butter caramels, and sand cookies', 'Restaurants and Bars'),
  ('15b43088-d594-5be2-b50a-e1b2d59761b7'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Sightseeing'),
  ('15cf7fda-8176-53c6-91ea-375bd7de2e53'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Former site of Ivan Ramen, a restaurant that has since closed. The owner opened a spot in New York by the same name.', 'Restaurants and Bars'),
  ('161f07ed-c35d-547a-9380-bbc3a2985b6c'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had beer with Brooke Davis, demolition driver, and Chris Quenzler Jr., mechanic', 'Season 10'),
  ('163dece0-b00e-5f74-abde-85e733c587d4'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met with EDM DJ Jason Lima to talk about Vegas nightlife, which he admitted he is too old to understand.', 'Season 3'),
  ('1649e7da-817a-561b-ba65-3164cae7b4f3'::uuid, 'a_cooks_tour'::show_name, NULL, 'Beer and a hot dog', NULL, 'Disc 1: United States'),
  ('1701964f-58f9-5d87-bcb2-8a1196f380b2'::uuid, 'the_layover'::show_name, 1, 'Grilled sandwiches with cheese', NULL, 'Season 1'),
  ('171de22e-ea56-5310-884e-6c8153771789'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a beer here with the owner of the bar. The owner also creates X-rated drawings of famous people and hangs them on the wall, including political figures, athletes, actors', 'Season 7'),
  ('171de22e-ea56-5310-884e-6c8153771789'::uuid, 'the_layover'::show_name, 2, 'Dive bar with obscene paintings', NULL, 'Season 2'),
  ('1740ce3d-e474-58f0-a371-6c936b478ab0'::uuid, 'no_reservations'::show_name, NULL, 'Farm with dairy, meat, produce', NULL, 'Other Activities'),
  ('17924044-fa3d-587f-91c7-d53dd935887a'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with President Obama (while he was in office) to have bún chả. It was Obama''s first visit to Vietnam, and it reminded him of his childhood visits to Indonesia. They shared cold beers and bún chả, a traditional Vietnamese soup of grilled pork belly, pork patties, and noodles served in a broth of vinegar, sugar, fish sauce and served with chilies. Obama told a story about a city in Indonesia called Puncak where he would eat at a roadside restaurant overlooking the tea fields, with a river running through the restaurant. You could pick a fish and they''d fry it and serve it with a bed of rice. Obama said it was a simple meal but his favorite.', 'Season 8'),
  ('17a862d1-38a7-5737-9e2b-d2518daf3e88'::uuid, 'no_reservations'::show_name, NULL, 'Exploring the swamps', NULL, 'Sightseeing'),
  ('17d3909a-877d-56c9-b690-c7b592896b04'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had biscuits with gravy and fried eggs with journalist Nick Mullins and documentarian Elaine McMillion Sheldon.', 'Season 11'),
  ('181556f0-f01c-5553-9363-fe18a7029289'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and his guide had pisco sours.', 'Restaurants and Bars'),
  ('1831811f-b8bb-57ae-a55b-8efbcfb74c09'::uuid, 'no_reservations'::show_name, NULL, NULL, '"Sachertorte, a staple for the Viennese coffee and pastry culture."', 'Restaurants and Bars'),
  ('183c477d-cf1d-56ad-811c-dc338ce87d18'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They happened to be there on the day of a bull fighting event, where the streets are filled with festival goers and food stands. They ate some tacos. Tony said he was not a fan of the cruelty of the bullfighting but recognized it is tradition', 'Sightseeing'),
  ('1859793e-a8a0-53cd-b77f-864e2d39558c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited the El Bulli lab where Adrian tests out ideas for the restaurant', 'Other Activities'),
  ('185affd4-cf80-5734-b361-aa4a6d8d968a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Zamir and Tony had a night cap here with some bourbon.', 'Restaurants and Bars'),
  ('18b24290-0ad1-5740-b2cf-b70b0b97bb59'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Small restaurant. Tony had Masa de cerdo (pork) and pork cutlet served with yucca, rice, and beans', 'Restaurants and Bars'),
  ('18c0f446-18f8-5ffd-9940-f4d51a556d3c'::uuid, 'no_reservations'::show_name, NULL, 'Hot dogs', NULL, 'Restaurants and Bars'),
  ('18db88eb-cc12-576b-b91e-d43ba6f1751a'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony and Darren Aronofsky visited this restaurant where Tony ate pork and Darren (a vegetarian) had veggies and beans.', 'Season 5'),
  ('18e51de7-d42c-5d4f-936c-71b5405f9db1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had chopped liver on rye with a cream soda, coleslaw.', 'Restaurants and Bars'),
  ('18f8ef21-e790-5db5-bc7a-ceaad018e7cd'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony met Chef Juan Pablo Mayorga in this town in La Guajira. They ate Frichi, a traditional dish from the Wayuu people, includes the offal of the goat. They then rode ATVs.', 'Season 1'),
  ('1906fb09-fcd6-562d-8755-f352b304ba83'::uuid, 'no_reservations'::show_name, NULL, 'Chinese dish called Steamed Milk Pudding', NULL, 'Restaurants and Bars'),
  ('1924a963-7c31-5d58-9d27-4ed896bebf32'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony ate at the restaurant in this hotel with Ellen Allien, famous Berlin DJ. They had sausage made from chicken, pig’s feet, and sage with smoked potatoes and apple; braised beef shoulder served with root vegetables, potatoes, horseradish, and kale.', 'Season 11'),
  ('1962389a-bd21-5617-8baa-1dc0ef37e23a'::uuid, 'the_layover'::show_name, 2, 'Bakery and cafe', NULL, 'Season 2'),
  ('1965c9fe-2de9-5f45-b1dc-9285d094b69e'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Chef Alejandro Ruiz Olmedo and Tony visited this Central Market where they ate barbacoa tacos, consommé, and tlayudas (perhaps best described as a Oaxacan pizza).', 'Season 3'),
  ('199b5dcc-053c-5bec-85ae-d071f5b3175d'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony described this area as "unlike anyplace I''ve ever been in Japan." Masa''s good friend and pottery mentor, Haruo Konishi has a family hideaway here. They made iwana (char) caught that day in a mountain stream, Hokkaido scallops, wild Japanese boar, grilled fukinoto, and soba noodles with duck, green onion, and dashi sauce.', 'Season 8'),
  ('19b1501f-a6ea-58b0-b078-079eeca12d0e'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Muffaletta and groceries. They deliver!', 'Disc 1: United States'),
  ('19d73aaf-0466-508b-a69c-30713bff7336'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Everyone tells Tony he needs to try doubles. "Doubles are a Caribbean take on the Indian chana bhatura, two floppy, tender pieces of soft, Indian-style bread loaded with a wet heap of curried chickpeas, pepper sauce, and mango."', 'Season 9'),
  ('19ddf9c6-f11b-5063-9b36-6c716fd42e02'::uuid, 'the_layover'::show_name, 1, 'Drive around a see the homes made to look like Venice', NULL, 'Season 1'),
  ('1a030a89-bdf5-58fc-80ed-9c301c8848f9'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A convent converted into a restaurant, only ingredients that are fresh and currently in season are served', 'Restaurants and Bars'),
  ('1a4bdf58-f982-5a58-a76d-4fbb2b75ea2f'::uuid, 'a_cooks_tour'::show_name, NULL, 'A shooting range with snacks', NULL, 'Disc 6: Asia'),
  ('1a5a4680-85d4-56f1-bee9-be6af02ac6e6'::uuid, 'no_reservations'::show_name, NULL, 'Chickpea curry', NULL, 'Restaurants and Bars'),
  ('1ac9ca8c-f98c-5fd5-98e8-37f724475a27'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They rode horseback to a mountain overlooking this town', 'Sightseeing'),
  ('1ac9fb06-7a90-5eda-8a0d-e4e2b409e72e'::uuid, 'no_reservations'::show_name, NULL, 'Sidewalk cafe', NULL, 'Restaurants and Bars'),
  ('1acedb91-620a-52d2-a8b7-48d7b4878725'::uuid, 'the_layover'::show_name, 2, NULL, 'Drink a Guinness here. Locals call this the Gravediggers Pub since its next to the cemetery. Great food.', 'Season 2'),
  ('1b39be00-645d-52c2-bc18-2c2edc3926e3'::uuid, 'the_layover'::show_name, 2, 'Modern take on the classic bistro', NULL, 'Season 2'),
  ('1b51e36e-ad06-577c-8cd2-3e1f3d0896bb'::uuid, 'no_reservations'::show_name, NULL, 'Hindu sacred place', NULL, 'Sightseeing'),
  ('1b8b9956-641f-51a9-88c0-72de14304442'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, NULL, 'Disc 1: United States'),
  ('1b8c7786-09d1-57cf-b4da-883fa950072a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Zamir visited this company town which is still radioactive. They were instructed not to touch anything.', 'Sightseeing'),
  ('1ba523c7-5e67-5d24-a64c-d70525674919'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Fast food that looks very similar to McDonalds except with items called Foxy Balls and Foxy Burger. They got Foxy Nuggets, Foxy Balls, Foxy Fries, and a Chicken bacon sandwich with an "assertive mustard sauce," Tony described.', 'Restaurants and Bars'),
  ('1bbfbf57-7364-5c70-b9da-49ecaab437d6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had tacos here', 'Restaurants and Bars'),
  ('1bd08669-8ea6-5c26-914b-2aaa017ddf33'::uuid, 'the_layover'::show_name, 1, NULL, 'Hawker food center. Have at least 3 meals at any one of these food centers! Indian, Malay, Chinese food.', 'Season 1'),
  ('1bd9b7e8-2f3a-5d97-a291-477d6ecfe69c'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony recommends the tartare and the pork belly', 'Season 1'),
  ('1be5bcd4-347b-5027-9ef9-72bc188e08c9'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Zach''s wife''s family invited Tony for dinner. Iberico ham, remojon granadino (eaten during holy week, it has salt cod, egg, black olives, oranges, and tomatoes dressed in olive oil), migas (sardines, chorizo, melons, and peppers)', 'Season 2'),
  ('1bedc766-d567-5279-84ba-ba3ff5f8b37d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went on a tour including the Oliver Crowell mural', 'Other Activities'),
  ('1c1116e3-4e5d-5810-a853-21b468147332'::uuid, 'the_layover'::show_name, 2, 'Live music of all kinds', NULL, 'Season 2'),
  ('1c198767-157f-55f3-b330-3c9006f84ebd'::uuid, 'the_layover'::show_name, 2, 'Southern food', NULL, 'Season 2'),
  ('1c36d158-497f-597b-a93d-950b4759c803'::uuid, 'parts_unknown'::show_name, 3, 'Former location of Lamar Lounge, a whole hog barbecue place.', NULL, 'Season 3'),
  ('1c5e9eca-22f3-5c2c-9614-d4acf74b18eb'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Open since the 1800s. Guestbooks have sketches from famous artists like Matisse. Simple, classic, traditional Italian foods. Cooked over a wood fire and lots of seafood. The seafood risotto is spectacular', 'Restaurants and Bars'),
  ('1c777a70-09fc-56ac-b081-85bee6ac4b25'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony watched ritual bathing on the river, went to a flower market, and watched wrestling', 'Sightseeing'),
  ('1c918ccb-4556-58ae-b09a-7ca63e5e62e1'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony, Nacho, and Diego went to this drive through to have skirt steak and ribeye, french fries, blood sausages, and beer..', 'Season 11'),
  ('1cc98163-3c23-5fa8-86b7-594a9c2241bb'::uuid, 'no_reservations'::show_name, NULL, '800 year old meat market', NULL, 'Food markets'),
  ('1d24e6b3-52b6-55cd-8639-10b68dd845d6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Former site of Sushi Sebo, a sushi restaurant that shipped a majority of its fish from Japan, closed now', 'Restaurants and Bars'),
  ('1da67c98-2eed-5e21-9e17-1f136fa62e8c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Cured fat of the pig made in the Apennine mountains. Where Dante came to write.', 'Food markets'),
  ('1da9de03-59f3-5f9f-a83f-d9cd06441430'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met with Claudio Madureiro and Marília Hughes Guerreiro Costa, at a streetside cafe/bar on a big music and party night in the storied neighborhood of Pelo.', 'Season 3'),
  ('1daffe3e-3579-5f30-a305-1ebff600b9b0'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony had a meal with Chef Yasuda, they had kushiage (fried skewers of shrimp and basil, lotus fruit, octopus, and quail eggs) and okonomiyaki (egg-batter pancake stuffed with squid). Yasuda lives near here and loves this place.', 'Season 2'),
  ('1db66d35-0d8b-53fe-af19-106425d9c1d6'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony visited Christopher Gibbs'' house (antiques dealer and expat) for a garden dinner party with other expats.', 'Season 1'),
  ('1dbe40a9-87b7-5c12-a12b-fd77f7d175ad'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had a meal at Anton Newcombe''s studio (frontman of the Brian Jonestown Massacre) and friends. The had roasted lamb, sweet potatoes, and homemade schnapps.', 'Season 11'),
  ('1ddb9719-4b73-564a-b46a-4254245ff357'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony taught a lesson at the Culinary institute', 'Sightseeing'),
  ('1e2bca98-8ecb-59d3-9b22-3af9a6e233a4'::uuid, 'a_cooks_tour'::show_name, NULL, 'Fresh produce, meats, pickled veggies and fruits', NULL, 'Disc 4: Morocco & Russia'),
  ('1e4b8440-1f0a-548e-9bb2-cfc72d0aa4ff'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony met with Debbie Harry and Chris Stein, members of the band Blondie', 'Season 12'),
  ('1e4d9bf7-42d6-5a67-9ae2-d65eb1cf5840'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Clams, cockles, and other fresh seafood that the owner cans and sells. Expensive!', 'Restaurants and Bars'),
  ('1e5b58ee-896a-5838-b992-d07604d8d723'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony attended a meet and greet here for Cook it Raw elite chefs like Rene Redzepi, Albert Adria, Claude Bosi, etc.', 'Restaurants and Bars'),
  ('1ea01790-7a79-51f3-abc8-cec8e0c100f6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'There is (was?) a bar in this area called Bully''s Bar, can''t find it on the map anymore. A local bar, people told Tony it was in a "bad part of town" but he went anyway and said everyone was lovely', 'Restaurants and Bars'),
  ('1ea4dac8-e639-5fc1-9908-97cc465ec272'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had lunch with Eric Ripert and 2 Parisian chefs', 'Restaurants and Bars'),
  ('1ebf4953-4e1c-5bcd-95ed-8f675090527d'::uuid, 'a_cooks_tour'::show_name, NULL, 'Haggis.', NULL, 'Disc 3: Europe'),
  ('1ecdb654-a376-5290-af61-8218553a2260'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Former site of "The Rub BBQ" where Tony had brisket', 'Restaurants and Bars'),
  ('1ed7478e-c4be-5dc5-9815-ee048c2eaf71'::uuid, 'parts_unknown'::show_name, 2, NULL, 'There used to be a boxing gym in Toshima called Yurakura Gym, but I could not find it on the map.', 'Season 2'),
  ('1efb29f3-ae35-527b-9298-45a35e6bd66c'::uuid, 'no_reservations'::show_name, NULL, 'Bacalao, shrimp with coconut rice', NULL, 'Restaurants and Bars'),
  ('1f1759c4-317c-54a3-92e9-06fdbf417dea'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony rode around on a jet ski here, the best surfing place in the world', 'Other Activities'),
  ('1f62139a-8c99-52c7-ae8b-9483d1d34a24'::uuid, 'the_layover'::show_name, 1, 'Korean cold noodle soup', NULL, 'Season 1'),
  ('1f73b0da-c37f-5383-8deb-bf87d96be17f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They had drunken BBQ and chili dogs.', 'Restaurants and Bars'),
  ('1f891409-7630-53eb-9e2d-a0fe7277668d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Local chef making "small, meticulously prepared plates, meant to be shared." Parmesan beer fritters; chilled soup of asparagus and shallots; pickled oyster mushrooms; soft scrambled eggs with grilled broccoli, goat feta, and pine nuts; shrimp with fried heads served over garlic rice; foie gras grilled and served with macerated strawberries; goat neck with carrot and artichoke; chicken fried egg with sweetbreads; brisket; grilled chicken breast', 'Restaurants and Bars'),
  ('1f942948-59cc-5119-9e55-8212f9719f0a'::uuid, 'the_layover'::show_name, 1, 'Specialty food shops, cheese, cured meats', NULL, 'Season 1'),
  ('1fc68936-8c80-574a-8c00-071e2aae6e6a'::uuid, 'the_layover'::show_name, 2, 'Bar with late night food', NULL, 'Season 2'),
  ('1fcea4ef-0898-5ef3-bfc9-c68760aa9238'::uuid, 'no_reservations'::show_name, NULL, 'Cafe. Coffee and baguette or croissant.', NULL, 'Restaurants and Bars'),
  ('1fcfe414-8865-5140-bbf1-9f2c03741705'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with Miami bass pioneer, Uncle Luke. They had fish and grits.', 'Season 5'),
  ('1fe71a83-d413-5993-96ae-cdbf7f49e17f'::uuid, 'the_layover'::show_name, 1, 'Tiki drinks', NULL, 'Season 1'),
  ('1ff5a912-7760-53a1-85cb-2747905ac71f'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and Kamau rode on the Mad Max bus, which is basically a party on a bus. Afterward they ate goat''s head soup and drank beer.', 'Season 12'),
  ('2037cad8-7a1c-5734-ae4a-729f9e460734'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Located in a large public market in the neighborhood of Tepito, which is known to be a rough area to live in. Tony and hosts had migas: Cracked ham bones stewed with garlic, onion, cascabel chiles, and epazote; thickened with stale bread and served with tortillas.', 'Season 3'),
  ('20aa000e-18e1-5a28-a786-ceaa928c5b01'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Famous chef in Brazil. Bahian food: Crab salad, Redfish wrapped in banana leaf. seafood coconut stew (Moqueca)', 'Disc 2: Mexico and The Americas'),
  ('20bd34fb-37c1-5c3a-a4bd-3abede1ecb76'::uuid, 'the_layover'::show_name, 2, 'Great wines and fancy food', NULL, 'Season 2'),
  ('20d91af3-b3ca-5553-be01-9c4040da6ed2'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with his old friend Dinh Hoang Linh, his former Foreign Affairs Ministry minder. "Bia Hảirefers to the roadside joints where locals gather to enjoy keg dispensed, freshly brewed draft beer', 'Season 8'),
  ('20fa1ace-44ca-521d-bef5-881fe6329e64'::uuid, 'the_layover'::show_name, 1, 'Bar with pinball and hot dogs.', NULL, 'Season 1'),
  ('20fb398b-5d59-53d9-ba5c-3095af59fae7'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony was extremely excited to eat at this restaurant, called Thomas Keller "the top of his game" and best chef at that time. Tony eats with Michael Ruhlman, Eric Ripert, and Scott Bryan (who owned Veritas, which was one of Tony''s favorite NY restaurants)', 'Disc 1: United States'),
  ('20fb398b-5d59-53d9-ba5c-3095af59fae7'::uuid, 'no_reservations'::show_name, NULL, 'Thomas Keller demonstrates how to perfectly roast a chicken', NULL, 'Restaurants and Bars'),
  ('20fba5a9-8406-5a34-a3ec-7eba5e490325'::uuid, 'the_layover'::show_name, 1, 'Meat-centric restaurant', NULL, 'Season 1'),
  ('21223847-cd0d-5346-8df2-fd6ddcdf0ef9'::uuid, 'a_cooks_tour'::show_name, NULL, 'Traditional English breakfast', NULL, 'Disc 3: Europe'),
  ('2154a740-3d2e-570d-9f93-a944b5af2518'::uuid, 'no_reservations'::show_name, NULL, NULL, '3 bodybuilder brothers make noodles at this restaurant at night', 'Restaurants and Bars'),
  ('21a3d96a-208e-5434-89b7-f783f3b7fb21'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony ate at a BBQ kiosk in the city where he had goat stew.', 'Season 1'),
  ('21c1cdd2-5d7d-5f00-97eb-aab5caeea5ca'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A food court full of stands. Tony and guide had fish head curry.', 'Food markets'),
  ('21d67659-dd1f-59a6-9ef4-96fff3bffdf7'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Not sure if this still exists, but this address was the Thu Vien Biblioteque Cafe where Tony drank snake wine and ate lots of French-inspired Vietnamese food.', 'Disc 6: Asia'),
  ('21e8eab1-d762-5855-9967-93a7fd7090ce'::uuid, 'no_reservations'::show_name, NULL, 'Expat bar', NULL, 'Restaurants and Bars'),
  ('21f6c350-b66c-5229-b176-e6129a7e5192'::uuid, 'the_layover'::show_name, 1, 'Fine dining', NULL, 'Season 1'),
  ('2210f8db-b491-5aa9-915f-989b1243dd41'::uuid, 'the_layover'::show_name, 1, '18 miles of books', NULL, 'Season 1'),
  ('2236c8c8-4011-5240-946d-66b242b68492'::uuid, 'no_reservations'::show_name, NULL, 'Salt & pepper crab', NULL, 'Restaurants and Bars'),
  ('224b246e-ad95-5737-bb83-571db29c3279'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had a dish called Dizi, named after the vessel it is cooked in', 'Season 4'),
  ('224d8d09-d237-5d55-970d-b0416b6e2143'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Anise seed liquor, red and white table wines. Food at the restaurant changes seasonally. Tony ate potato salad with parsley, olive oil, and nuts; Lebanese spaghetti (served with yogurt); cabbage salad; grilled eggplant, tomato, and haloumi, sheep''s milk cheese, labneh.', 'Restaurants and Bars'),
  ('22559588-3c8a-5b51-96ff-a33937da3753'::uuid, 'no_reservations'::show_name, NULL, 'Horumonyaki - grilled pork and beef organs', NULL, 'Restaurants and Bars'),
  ('22570f9d-8fcd-5517-8785-0b2c01e8b041'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Somewhere on this street is the Alpha Haitai Social & Athletic Club. Chinese gunpowder tea served here, where intellectuals meet and play scrabble!', 'Other Activities'),
  ('225c8355-150f-5fde-a964-351848f50db5'::uuid, 'parts_unknown'::show_name, 5, '"Broasted" chicken shawarma', NULL, 'Season 5'),
  ('2268c8f1-14f0-5bc8-bba3-3db3ed1a5ae0'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('229d3de2-cbd9-5ee1-a1c7-afb2090c7a1e'::uuid, 'the_layover'::show_name, 1, 'Trippy art', NULL, 'Season 1'),
  ('2309084f-cf82-5b2c-9242-c7ac0384b35a'::uuid, 'a_cooks_tour'::show_name, NULL, 'Boat tour on a swamp', NULL, 'Disc 1: United States'),
  ('231d3552-e833-5964-9f54-51829bb929df'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony paid respects to Mom Gow by visiting her ashes in this Buddhist temple', 'Other Activities'),
  ('233218a0-511b-5941-a808-4ee31cc97da7'::uuid, 'the_layover'::show_name, 1, NULL, 'Used bookstore. On the show it was still St. Mark''s Bookshop, "Oddball, off the wall, hipster obscure stuff"', 'Season 1'),
  ('233c4d8f-da3e-5e3f-865b-d29dff02e899'::uuid, 'parts_unknown'::show_name, 4, NULL, '"Classic, homestyle Shanghai meals," Tony described of this restaurant that is a favorite of Yao Minji, chief feature reporter for SHINE. No menu, no waiting list. Tony had you bao xia (wok-fried shrimp); hong shao rou (braised pork belly); yan du xian (clay pot soup with bean curd stock, pork belly, tofu, and bamboo)', 'Season 4'),
  ('234b3d31-10c9-58d5-bebf-02076cd66320'::uuid, 'no_reservations'::show_name, NULL, '"One of the most beautiful butcher shops in the world"', NULL, 'Food markets'),
  ('236bb951-98c6-5189-8cd9-5b937f4ecace'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony also stopped here on the way to the airport to pick up a muffuletta sandwich.', 'Restaurants and Bars'),
  ('2380c67e-69dd-5392-9b1a-a764b51b264d'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Opened in 1941. Tony had a Delta dinner of Doe’s famous salad, hot tamales, fries, shrimp, and porterhouse steaks.', 'Season 3'),
  ('23afd895-7319-50d0-824e-7746295206e6'::uuid, 'parts_unknown'::show_name, 4, NULL, 'At this public beach, this food stand sells ackee, banana, and salt cod.', 'Season 4'),
  ('23b298a4-b475-5d03-a2ee-e430777f4c40'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony and Darren visited this place about an hour outside of the city. They visited a town in this area that specialzes in Phallus Handicraft and bought a few phallic art pieces (wooden penis)', 'Season 11'),
  ('23c114f2-b97a-5106-b0c2-d1225952586e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'On his way to the airport, Tony stopped here for a "house special" which includes jungle juice, island citrus, 190 proof vodka and rum.', 'Restaurants and Bars'),
  ('23c63385-c322-52da-a4f5-f6092d9df9bd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a gin & tonic with a priest', 'Restaurants and Bars'),
  ('23d9e12a-d207-5fca-aa96-01fd42bd48f3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Where the pina colada was invented. (Tony talked crap about it)', 'Restaurants and Bars'),
  ('2433c957-aaea-5ca4-ba2f-c1604b17e44d'::uuid, 'parts_unknown'::show_name, 4, NULL, '"Idyllic natural setting and good plumbing? Pretty much paradise," Tony describes.', 'Season 4'),
  ('2461af93-4a8e-5b0c-bb88-2ae865a1f98d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A tiny restaurant specializing in Catalonian food. He ate with the chefs, including: escudella (a boiled dish made during the holidays with beef shank, poultry, turnips, carrots, chickpeas, pig ear, blood sausage, cornbread, cabbage, meatballs called pelota), as well as a brothy soup with galettes with shell pasta, and a canalon (leftover meat from escudella cooked into a new dish with pasta and cheese)', 'Restaurants and Bars'),
  ('24694a03-11b9-5692-88c8-c0da77747b4d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'In the relatively affluent area of Haiti, which was less damaged by the earthquake, Tony ate Creole food with some locals.', 'Restaurants and Bars'),
  ('247bff76-bb05-5b1b-88c4-fdd4355704b5'::uuid, 'no_reservations'::show_name, NULL, NULL, '120 store complex with Vietnamese cuisine. Restaurants, food stands, produce', 'Food markets'),
  ('24885b2b-17d6-5f80-a4c7-18c71aed8991'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had a famous goose dish, served with broth made from chicken and ginger, rice, and a salad', 'Season 5'),
  ('249d686d-d1e9-57bf-82dd-4a2b73c9403f'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony, Fred, and Dave threw axes and had a cheese plate, an assortment of patés, and pickled pork tongue.', 'Season 11'),
  ('24a2cd86-d056-5c14-9349-1dff3a523544'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony went diving with a fisherman for some octopus off the coast of Moloka''i, which they hunted with the spear.', 'Season 5'),
  ('24afa6bd-b18b-5839-8fd9-01c08679f9f3'::uuid, 'no_reservations'::show_name, NULL, 'Tae Kwon Do school', NULL, 'Other Activities'),
  ('25255d18-2d00-5d6a-84a7-3eed98d1f5dc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Swiss settlement. Tony says, "I''m frightened of the Swiss" and felt uncomfortable', 'Sightseeing'),
  ('252a8090-e722-539c-8293-2f21d67ec292'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Xabier Agote, Shipwright and founder of the Basque Maritime Museum, is working here to built a 16th century style Basque galleon.', 'Season 9'),
  ('253db738-1f6c-5230-a8f7-200184ea169b'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Could not find this restaurant on the map. Tony had dorado, rice, beans, plantains, and rum.', 'Season 6'),
  ('257ed597-15ba-5764-8ded-c1af4a840d43'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A restaurant with a vineyard attached. Blood sausage, head cheese, bread with schmaltz and onion. Goose liver and onions. Pheasant breast wrapped in speck (proscuitto) and dumplings.', 'Restaurants and Bars'),
  ('258c68c8-d23a-502b-a9c1-9c6dc5d9b5e8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The Ainu people were indigenous to Japan, much like the Native Americans in the US.', 'Sightseeing'),
  ('25ea38d1-0126-58d5-aa4f-5dfaf3e53d38'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony and rocker Anton Newcombe had a dinner of brined pork knuckle served alongside sauerkraut and boiled potatoes, schnitzel with sautéed seasonal vegetables and creamed mushrooms. And a large beer.', 'Season 11'),
  ('25f5799d-a386-55f5-aa93-009ea4215c5c'::uuid, 'a_cooks_tour'::show_name, NULL, 'Self explanatory.', NULL, 'Disc 3: Europe'),
  ('25f85c9c-515e-53c1-86b1-b9346498754c'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony went here with Dean Fertita (guitarist and keyboard player for Queens of the Stone Age, musician with the Dead Weather). "Cryotherapy, the latest in muscle recovery treatments," explains Tony. Liquid nitrogen chills down the pod to -300 degrees which causes your body to kickstart anti-inflammatory proteins.', 'Season 8'),
  ('26313744-13a9-5990-892d-86b2ac2010ab'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Roast goose and pig. Tony said the goose was "worth flying to Hong Kong for"', 'Restaurants and Bars'),
  ('26a194bc-c26a-5ac1-9490-58cba842cc17'::uuid, 'no_reservations'::show_name, NULL, 'Baseball sports bar with sushi', NULL, 'Restaurants and Bars'),
  ('26ae31fa-eb87-5759-96eb-4ad7d05ef6b0'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('26d3de11-b8ce-5ac5-b5ac-929fdc06e8f5'::uuid, 'parts_unknown'::show_name, 8, NULL, 'A boteco, or neighborhood restaurant that serves beer. Tony met with Eduardo Maya, “self-taught gastronome,” and Luiz Otavio, a beverage tycoon who specializes in cachaça at Cachaça Vale Verde. They had "ox tongue cooked with basil, mint, and pepper" and "feijão tropeiro: beans, manioc flour smoked in cured meats" and fresh eggs.', 'Season 8'),
  ('26da00b6-c975-5bc5-8adb-8799cb300d7d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and his wife Ottavia ate here with one of the cameraman. Antipasti; tagliolini with garlic, chiles, and pork ragout; oxtail; tripe.', 'Restaurants and Bars'),
  ('26e115cc-fac6-55e0-b896-8f681bacfebb'::uuid, 'no_reservations'::show_name, NULL, 'Pork centric belly warming foods to warm you up. And beer', NULL, 'Restaurants and Bars'),
  ('271d0cf7-9ce4-58ab-8cee-74322cfc12cd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Chicken & waffles obviously. And Stymie''s Choice: chicken liver, grits, gravy, fried eggs.', 'Restaurants and Bars'),
  ('2776ceae-2b3a-5a9e-af5d-ba77e28eefb2'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony visited the Wagenia tribe which live in this region. He had steamed tigerfish limboke: steamed in a banana leaf.', 'Season 1'),
  ('2788ff82-1f95-5665-ad86-b8bc994078ab'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony tasted wine at this winery that has the same altitude as the Tuscan region. The owner''s wife cooked a 12-course meal for them (although it is not a restaurant)', 'Other Activities'),
  ('27895ab3-b112-5106-86a3-97c8b34eca05'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A seafood market where you can buy ingredients and someone will cook it for you. They had pinakbet, shrimp adobo, and coconut chili crab', 'Food markets'),
  ('280f55be-d785-55dd-908c-32c6a2094fd8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony finally got his huge seafood tower!', 'Restaurants and Bars'),
  ('281405de-7414-5102-9879-38bbc8f0da40'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('2828f204-9af6-50c9-985c-124e0b702f64'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony visited this small New England town to talk about heroin and opiate use.', 'Season 4'),
  ('2829fbf6-7fd2-5c15-8932-37068fd8b85d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a "happy pizza" which included "powerful herbs"', 'Restaurants and Bars'),
  ('28503185-0af4-5183-a3fe-45027dc31a95'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony met with workers from this organization tasked with finding unexploded objects left behind by American forces during the Secret War and safely blowing them up. Only 0.5% of the country has been cleared of unexploded devices. Kids and adults have been maimed and dismembered by these bombs strewn about the countryside.', 'Season 9'),
  ('286006ac-61b7-5662-ac8f-d4c44cb2d87d'::uuid, 'parts_unknown'::show_name, 7, NULL, 'The chef, Gia Rokashvili, uses local ingredients and serves the food with local wines. Tony had boiled beets in wild plum sauce, freshly foraged mushrooms with chili pepper, mint, and tarragon; baby lamb stewed with cumin, cooked with wild rice; fresh tonis puri, bread made in a tandoor-like clay oven. He ate with Keti Bochorishvili, former Deputy Minister of Economy and Sustainable Development, and Tamuna Gvaberidze, gallery owner.', 'Season 7'),
  ('288aaba5-b92b-54ff-9a95-4470203568fc'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony had dinner here after the disastrous "fishing" expedition. It''s his birthday and he doesn''t remember any of the meal because he drank so much. Tomaso and his wife (locals) had the meal together. They ate white olives, bread, olive oil, abalone served raw in the shell, baby sardines called neonata with citrus and salt, octopus, tuna tartare, cuttlefish crudo, pasta alfino querta (a true Sicilian classic made with fennel, pine nuts, saffron, and anchovy. Served with anchovy curing in chestnuts and salt for days, then lightly fried in oil.', 'Season 2'),
  ('28a8e5b1-9e67-520a-b805-aba23dde314c'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony discussed the history of Butte as a union town with former congresswoman, Amanda Curtis', 'Season 7'),
  ('28ccd760-36f7-594a-af42-8ad5617d5628'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tyree Guyton created this "delightfully loony outdoor community art project that began in 1986 and now attracts 35,000 visitors per year from around the world."', 'Season 2'),
  ('28e0d284-63e6-5077-99a7-937affda836d'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony took a boat up the river to see New Bordeaux. While on the boat, they ate grilled dorado fish topped with a mango salsa and catfish', 'Season 4'),
  ('28e8ae69-a9b6-52e8-9096-25dae99906ea'::uuid, 'the_layover'::show_name, 2, 'Obscene history tour', NULL, 'Season 2'),
  ('290ad5b7-41f2-5212-a255-3b579d8fcfd1'::uuid, 'the_layover'::show_name, 2, 'Large market selling wares and food', NULL, 'Season 2'),
  ('290adf47-fbef-5daa-9ad7-753f720aaff2'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'He moved since the episode aired. This is the new location. Serves ribs and other Caribbean BBQ', 'Disc 2: Mexico and The Americas'),
  ('2914e9b9-24a4-58b6-ad2a-077ed7a060a6'::uuid, 'the_layover'::show_name, 2, NULL, 'Kurdish Sandwich shop; rolled flatbread sandwiches with grilled meats', 'Season 2'),
  ('2934477f-30ea-50bd-82eb-210acea32049'::uuid, 'the_layover'::show_name, 1, 'Cappuccinos (only in the morning) and cornetto', NULL, 'Season 1'),
  ('29c7bb4c-8c50-55a1-91d7-13b6eefc3f2b'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Former site of restaurant called Cococo. Tony and Zamir had a meal with Sergey Shnurov and Matilda Shnurova, co-owners of Cococo.', 'Season 3'),
  ('29e60eec-c7d8-5c41-b351-bdb59cbea927'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They ate soup for breakfast (Khao Pia). It has chicken, duck, and pork with Vietnamese noodles.', 'Food markets'),
  ('2a0f3d1e-a0ef-5d97-8a05-45006c48ebf9'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Old style restaurant. Lots of tableside service including caesar salad, beef tartare, and shrimp cocktail. David McMillian had the filet mignon, Fred had the Scampi Newberg, Tony had the Dover Sole', 'Season 1'),
  ('2a14c424-9da3-5f3a-b7d0-1341ce43c31b'::uuid, 'no_reservations'::show_name, NULL, 'Hanshin Tigers baseball game', NULL, 'Sightseeing'),
  ('2a26cddf-2abd-5bac-976c-53fc34bbda19'::uuid, 'no_reservations'::show_name, NULL, 'Estate at the base of the Carpathian mountains', NULL, 'Sightseeing'),
  ('2a4d04b9-af94-5146-9b3f-9a21cf6a793b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met with Alice Cooper and ate a "Randy Johnson Big Unit" which is a humongous hot dog with chili and cheese', 'Restaurants and Bars'),
  ('2a7b1f34-b294-5a41-936f-5bef9366b8df'::uuid, 'parts_unknown'::show_name, 8, NULL, 'The rural town where Masa grew up. Tony and Masa visited his family (mom and daughter). His mother made motsuni, "a slow simmered stew of pork tripe, konnyaku, daikon, green onions, and miso," sashimi with freshly grated wasabi, uni, and otoro (tuna).', 'Season 8'),
  ('2a7cc4b2-ca20-5114-afb6-9f1cedcd3704'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony met with photographer Cherie Nutting and went to this outdoor food market. Tony bought fresh goat cheese wrapped in palm leaves and some flatbread for breakfast.', 'Season 1'),
  ('2a8a4282-708b-579a-8e39-44b3e8ba3f2d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony picked up food supplies here for a boat trip', 'Food markets'),
  ('2adf8843-4746-558b-ad80-c662377e5b38'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony ate with a family on a local farm, including the Aegan governor. They had stuffed peppers, slow-cooked rooster, rabbit in a wine sauce, and potatoes.', 'Season 7'),
  ('2aea703d-7c01-5fe1-9e95-d60a1ebed1b0'::uuid, 'no_reservations'::show_name, NULL, 'Very high end shopping', NULL, 'Food markets'),
  ('2af81bb2-6a0d-5a69-b42a-a1d6533cd043'::uuid, 'no_reservations'::show_name, NULL, 'Spa', NULL, 'Other Activities'),
  ('2b25a5cb-d2c6-53fc-add2-672b3a571463'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony met with food writer Mary Taylor Simeti, food writer, for lunch. They had panelli (fritter made from chickpeas), caponata (sweet and sour eggplant), spaghetti al nero di seppia (spaghetti in cuttlefish ink), casarecce al pescespada (pasta with swordfish, eggplant, and tomatoes)', 'Season 2'),
  ('2b3255b8-ce11-5ea8-9d5c-c74ba86ca2f5'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had rice and gravy, fried fish, ribs, and smothered stuffed turkey wings with journalist Herman Fuselier, Creole cowboy Dave Lemelle, musician and business owner Sid Williams.', 'Season 11'),
  ('2b3bb49b-d97c-5a5d-879c-63b7fe0c5dcc'::uuid, 'the_layover'::show_name, 2, 'Neighborhood with burger joints, drinks, shopping, etc.', NULL, 'Season 2'),
  ('2b476a8b-ca49-50d8-9df4-471422449a5b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'German sausages, headcheese, pork in aspic. Beer served in a boot. Tony had the crispy pork shank', 'Restaurants and Bars'),
  ('2b7b4d5f-540f-5ebd-976e-97367857ad6b'::uuid, 'the_layover'::show_name, 2, 'Food market', NULL, 'Season 2'),
  ('2b9ad1d9-58d1-52e5-87b3-3ba03e860b50'::uuid, 'no_reservations'::show_name, NULL, 'Crispy pork belly, tamarind baby back ribs', NULL, 'Restaurants and Bars'),
  ('2bdd58c9-8010-5d97-b0cb-0dc1ffce9023'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('2bfd26ca-4973-5b70-b7b4-3c7a25048701'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Not open to the public. Tony wanted to find out what the sumo fighters eat.', 'Disc 5: Australia and Japan'),
  ('2c41f9a4-1e17-5459-966a-2274eb4c8fbe'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony met with Hemms and his friend, attorney, and community organizer, Ali Najmi. They had thentuk, which is a hand torn noodle soup with chilies and ginger. Also, shaptra or chili-fried beef made of thinly sliced beef cooked with chili oil, soy, and Sichuan peppercorns; and sha momo, or steamed beef dumplings.', 'Season 9'),
  ('2c4d6d79-2ff1-584a-bbae-acbb6c52609a'::uuid, 'no_reservations'::show_name, NULL, 'Red beans & rice, and the famous fried chicken', NULL, 'Restaurants and Bars'),
  ('2c727109-43f5-5ea2-8b5a-f0b77fa207da'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Somewhere in this neighborhood, Tony had a breakfast of sfinz, a donut with an egg on top.', 'Season 1'),
  ('2cb5e7ab-a558-5b02-935f-8ee26efa05d5'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony ate beaver at Chef Martin Picard''s home.', 'Season 1'),
  ('2cc33450-ca09-53f3-a903-e6dd91bbbe17'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Typical Chilean favorites: Abalone, razor clams with cheese, fried conger eel, a seafood stew called mariscal.', 'Restaurants and Bars'),
  ('2cd42c7e-cc11-5355-8fd9-2c66155c6c10'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony ate with rapper Djily Bagdad. They ate dibi, roasted meat served on paper with grilled onions and mustard.', 'Season 7'),
  ('2d384f22-dd39-5196-8da8-8cb2627e5e4f'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony came here to have some roast pig', 'Disc 3: Europe'),
  ('2d501c99-cc82-5faf-8652-5a087b1d86e7'::uuid, 'the_layover'::show_name, 2, NULL, 'Large food market, ethnic ingredients; eat a beef dumpling from the stand', 'Season 2'),
  ('2d5db2ef-87f5-5c21-9716-86f6ce3182ae'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('2d860842-4a7b-5541-9625-ae04f5ae4fec'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Eric visited this museum of pre-Columbian Peruvian artifacts. While there, they went to the erotic gallery and looked at erotic pottery.', 'Season 1'),
  ('2d935bb1-d543-51cf-a7ab-ebb4f68e9158'::uuid, 'no_reservations'::show_name, NULL, 'Wrestling', NULL, 'Other Activities'),
  ('2da53e36-a5af-5297-9186-8f0f65262a11'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had Dai Pai Dong, which is a food hall dedicated to street food', 'Restaurants and Bars'),
  ('2da53e36-a5af-5297-9186-8f0f65262a11'::uuid, 'the_layover'::show_name, 1, NULL, 'Eat everything, but do not miss the black squid ink pasta. And DO make a reservation.', 'Season 1'),
  ('2ddd7864-f64a-5fa7-98da-621e29773f41'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This is Chef Morimoto''s flagship restaurant. He prepared monkfish many different ways for Tony.', 'Restaurants and Bars'),
  ('2de867ea-48c6-5036-83c4-22156197efba'::uuid, 'the_layover'::show_name, 1, 'There is a permanent wave here so people surf!', NULL, 'Season 1'),
  ('2df6e339-6547-5c51-b74c-462c3356024f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Japanese flavors with hot dogs. Nori with daikon and teriyaki hot dog.', 'Restaurants and Bars'),
  ('2e235c85-15d6-53eb-adf1-f09183e0752c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony called this restaurant Tatchaninmis. Tony and Zamir drank several bottles of vodka and ate seafood here.', 'Restaurants and Bars'),
  ('2e4d964b-c090-504f-ba24-10ee09b8b1aa'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony met again with John Birdsall, author, to have Indian food. Chef Preeti Mistry described the dishes to them and discussed Indian food in America. They ate Manchurian cauliflower which Preeti described as “vegetable candy”, bhel puri (puffed-rice dish), chili paneer, yogurt-marinated chicken curry served on rice, Indian Scotch egg (the Scotch egg was invented in India).', 'Season 6'),
  ('2e77601c-746b-57ff-a364-505f43678d8a'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony said this was the greatest show he''s ever seen, better than Jimi Hendrix, Janis Joplin, and David Bowie live. He saw the show called Robot Wars.', 'Season 2'),
  ('2e951b3d-662b-5baa-b72a-18e7ac57017b'::uuid, 'no_reservations'::show_name, NULL, 'Ham, egg, and cheese crepes', NULL, 'Restaurants and Bars'),
  ('2e9f191d-e9c8-5f00-b3c9-c7d73c453ffe'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Fresh ingredients from the market, world famous for her soups', 'Restaurants and Bars'),
  ('2eb0c651-0285-53a0-ab47-65c90ef59873'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Grilled meats. Tony and the Bishop visited after the church service', 'Restaurants and Bars'),
  ('2ec44a01-6922-51b0-a467-f6360e90182b'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony and Zamir met up at this bar on the top floor of the Radisson to drink chacha, a traditional Georgian moonshine', 'Season 7'),
  ('2ec7cf47-7df0-5919-9245-4a21e7051991'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met up with Zamir and ate Astrakhan caviar, salted cucumber with honey, Baltic sprat with beetroot, muksun (white fish with maldon salt), and vodka (of course)', 'Season 3'),
  ('2ecca1d7-ee42-5ca7-83cf-85d26ac2e042'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony called this place El Vaquero. A soured milk yogurt drink is supposed to be a hangover cure. Nacatamales is corn masa inside plantain leaves filled with pork, tomato, and herbs. Tony said it was the best meal he ate so far in the trip.', 'Restaurants and Bars'),
  ('2f5105c2-f962-5ca7-88b1-121a98c06766'::uuid, 'the_layover'::show_name, 2, 'Pork sliders', NULL, 'Season 2'),
  ('2f8f42f9-ddc1-5d5d-a2ca-34bc1196135c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate his worst meal ever with the Kalahari bushmen: wild boar anus.', 'Sightseeing'),
  ('2f98c13d-c9c9-51ba-8641-bef0c45f6035'::uuid, 'the_layover'::show_name, 2, 'Jazz music', NULL, 'Season 2'),
  ('2fb23673-8fbb-5958-a4e1-8f4991d450e6'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a meal on a boat with some fishermen. They had octopus, grilled salatouri (skate), marinated anchovies, grilled rofos (grouper), and mashed fava beans.', 'Season 7'),
  ('2fea7e9c-769b-50f9-842f-dc5dedc8aa9b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Traditional Austrian food. Meatballs with gravy and potatoes; tafelspitz (Austrian version of pot au feu with boiled beef shoulder); pan roasted goose breast with quince and red cabbage; beuschel mit serviettenknoedel (cream stew of veal hearts, lungs, liver, and dumplings.', 'Restaurants and Bars'),
  ('2ff4f5ba-1c10-525e-8894-c5376a7bc4e0'::uuid, 'no_reservations'::show_name, NULL, 'Margherita pizza', NULL, 'Restaurants and Bars'),
  ('2ff71545-0298-54f7-aef1-f3a8c9238b5a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Unpretentious bar, Tony''s favorite in Scotland', 'Restaurants and Bars'),
  ('2ffd4f2f-0307-5f27-93a5-ce5cde587f64'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Not sure if this is the correct location. Tony said the beach was called "Coeur. de Cassazione" but I could not find this on the map. He ate with Pierre Thiam, a renowned chef and cookbook author. They had yassa, made with a local fish called ciof, "cooked simply on the bone, wrapped in foil, and steamed over the fire, served with a mignonette style sauce with onions; grilled mussels, sea urchin."', 'Season 7'),
  ('304c90b5-3e30-5be2-838d-53f78abfcfe3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony spent time on the beach while his brother did sightseeing', 'Other Activities'),
  ('30a7992a-02d9-5a94-8dcf-616987a33c9e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony shot rifles', 'Other Activities'),
  ('30c2abc9-8b50-5747-8fea-26df79b913cd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Molecular gastronomy in a "hospital chic" themed restaurant. You are seated in a wheelchair. Weird.', 'Restaurants and Bars'),
  ('30c67ba8-20f4-51a0-982e-56e712c8419e'::uuid, 'the_layover'::show_name, 1, 'Oldest flea market in Singapore', NULL, 'Season 1'),
  ('30cdd607-425f-54a6-957c-fa7a1a5ef59a'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Serving beer and pork products since 1862. Tony met with Heinz and his friend Judith drank alt (a dark beer) and ate pickled eggs, cabbage and mettwurst, and spicy pork goulash with rye bread.', 'Season 7'),
  ('30d3adc0-9421-5e97-b72f-a6225ca6c2bf'::uuid, 'no_reservations'::show_name, NULL, 'Daoist Temple', NULL, 'Sightseeing'),
  ('310cf0bd-cfbe-56a7-8257-40c8f4b96dde'::uuid, 'a_cooks_tour'::show_name, NULL, 'Meat pies', NULL, 'Disc 5: Australia and Japan'),
  ('31262fbe-9d51-578d-b519-7f73557c2940'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('31312a63-0348-5f30-a25c-c7ab2ff3511a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Outdoor eating area with traditional foods served like tapas.', 'Restaurants and Bars'),
  ('317f8c84-070c-5a51-8d0e-e4a95d765ef6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony traveled by boat to Ban Xang Hai', 'Sightseeing'),
  ('3196adea-5cff-5f21-942a-329049ff87a9'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had goat curry, stewed oxtail, rice, peas, collards, mac ’n’ cheese.', 'Season 4'),
  ('319b80c3-8d83-5ce7-9fb9-ab5b28f0c6f0'::uuid, 'the_layover'::show_name, 2, 'Sardine sandwiches and other pub fare', NULL, 'Season 2'),
  ('319d0da6-2c9b-5568-a0b8-48f1baface12'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Much to Tony''s horror, his business friends decided to go to this karaoke bar', 'Season 5'),
  ('31e54ee5-9ba3-5d01-9d73-f5b1f2525fce'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Antique shop Tony visited and bought a mortar & pestle style tool from the Gond tribe in Mali for $300.', 'Season 1'),
  ('3232baf0-915e-56e7-8f3f-787169d066db'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('3245988c-c5c0-53d8-8201-309defdf45f4'::uuid, 'no_reservations'::show_name, NULL, 'Bread and pastry bakery', NULL, 'Restaurants and Bars'),
  ('3247dd0b-3758-5ac4-b68b-b8e82ce19aff'::uuid, 'no_reservations'::show_name, NULL, '"The Happiest Place on Earth"', NULL, 'Restaurants and Bars'),
  ('3267b4b8-6c38-56bb-8068-04e3fe79053a'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony loves Yasuda in NYC, and wanted to find out why the chef, whom the restaurant is named for, would suddenly move back to Tokyo. Yasuda said that Japan is the origin of sushi, so he wanted to return to where it was created. Yasuda is also a karate master.', 'Season 2'),
  ('32738f16-7be7-54f0-810e-da4a4fc38eb4'::uuid, 'no_reservations'::show_name, NULL, 'Criollo restaurant', NULL, 'Restaurants and Bars'),
  ('32cfb16b-4765-514c-b877-a9e8faa1cbe7'::uuid, 'no_reservations'::show_name, NULL, 'Spa treatments', NULL, 'Other Activities'),
  ('32f9d5c1-9a24-5b3c-8c4e-9f2a74b77b1f'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had a meal with a local poet on Princes Islands', 'Season 6'),
  ('32fc5211-94cf-56d9-acd4-eb83d621f006'::uuid, 'no_reservations'::show_name, NULL, 'Ampitheater', NULL, 'Sightseeing'),
  ('33767355-65d7-5b38-aae6-378c609c35ba'::uuid, 'the_layover'::show_name, 2, 'Cheese, meats, breads, open until midnight', NULL, 'Season 2'),
  ('339cd62d-409b-5112-88f9-0617f78d389e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Postcolonial elite. Tony describes it as "the last remnants of long-gone empires." They drank coconut liquor', 'Restaurants and Bars'),
  ('33a3de51-414d-54fa-9b2c-87db78640654'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Wisconsin beer cheese soup; crispy egg mollet with curry potato salad, crème fraiche, and caviar; foie gras french toast, bone marrow', 'Restaurants and Bars'),
  ('33d461a4-15ad-557f-ba50-1c1e193e8880'::uuid, 'no_reservations'::show_name, NULL, 'Drunk late night burgers.', NULL, 'Restaurants and Bars'),
  ('341f153c-7c8e-5260-a2f9-e51c9f661583'::uuid, 'the_layover'::show_name, 1, 'Beer garden inside Eataly', NULL, 'Season 1'),
  ('34234aa2-957c-584f-b295-c5df0bbc0ad4'::uuid, 'the_layover'::show_name, 1, NULL, 'Gator or rattlesnake. Wok seared beef. Deep fried quail. Tamarind seafood soup.', 'Season 1'),
  ('342fdecd-4704-57c1-b7f6-350a95460417'::uuid, 'no_reservations'::show_name, NULL, 'Mercado Egido, a fresh produce market', NULL, 'Food markets'),
  ('34652902-3e62-529a-a5d9-387f3e51bf42'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had music manager Danny Fields and had pierogies.', 'Season 12'),
  ('34e8de42-b782-538b-98b5-b371833a9e30'::uuid, 'the_layover'::show_name, 2, 'Pastel de Bacalhau', NULL, 'Season 2'),
  ('34ec388f-1db4-5932-ad1d-7e6428e6df39'::uuid, 'parts_unknown'::show_name, 10, NULL, '"This is our Central Park," Dharshan Munidasa says (a chef and TV personality). Tony and Dharshan had street food here.', 'Season 10'),
  ('35166639-a67a-517d-a4c8-f925d72c31c7'::uuid, 'the_layover'::show_name, 2, NULL, '16 flavors of daiquiris. Tony had the "special" which has 190 proof alcohol, orange juice, and pineapple juice', 'Season 2'),
