  ('353683a9-3bad-578d-b4fb-e31b38fce3ba'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Seasonal produce fresh food market. Tony''s hosts shop for ingredients to make a dish called ghapama.', 'Season 11'),
  ('359cb958-d25f-5acc-aafe-1d0a38710899'::uuid, 'parts_unknown'::show_name, 2, NULL, 'In Sacromonte, a neighborhood made of cave structures. Tony watched a an jeurga "informal, intimate, and spontaneous performance"', 'Season 2'),
  ('35a81f04-7b1a-573f-b45c-63f42121088a'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Philippe visited the palace ruins and admired the structures', 'Season 1'),
  ('35b28055-fffc-566b-ba71-02dbd1314ffa'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony played a video game in this PC video game cafe', 'Season 5'),
  ('35bb87dc-ac1b-5eb1-b756-cef84325cd90'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony met with chefs Fred Morin and Dave McMillan. They had a fried bologna cube and Newfoundland‘s very own Screech Rum.', 'Season 11'),
