  ('35ea79a2-b90d-5bd8-8938-0fae41d5b38d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Ice cream soda shop with sandwiches. Tony had a lime rickey and a tuna melt. His companion was Famous Fat Dave who does food tours around NYC. Dave had an egg cream and a tuna sandwich', 'Restaurants and Bars'),
  ('362a95e9-5e55-51cd-aec8-a34ef17ccb26'::uuid, 'the_layover'::show_name, 1, 'Old world, British colonial style hotel', NULL, 'Season 1'),
  ('36321dd9-4867-59f9-8e72-bf73bff05bac'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with Crow indian Kennard Real Bird, who ranches horses in the same location where General Custer "had the worst day of his life." There is also Indian relay racing, a dangerous sport involving jumping from moving horses.', 'Season 7'),
  ('36323708-5e26-5e47-8363-6c2421ddab51'::uuid, 'the_layover'::show_name, 2, 'Indonesian food. Beef rendang.', NULL, 'Season 2'),
