  ('36b8f189-ccba-5cef-920e-619421f02cc8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited Marta Minujin, a pop artist who created a model of the famous obelisk, a huge edible model made out of panettone', 'Sightseeing'),
  ('3717719e-b2b1-5da5-a9f5-b49a0111b4cf'::uuid, 'no_reservations'::show_name, NULL, NULL, '"A village of fishermen, seekers, and refugees" on government land only accessible by sand ferries. They went to a small dive bar where a blind man had a pet penguin named Pancho.', 'Sightseeing'),
  ('3730ce2e-eead-5010-89e9-4358754c45d6'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with Syrian immigrant Sakher Al Mohamad to talk about the unrest Cologne faced when middle eastern terrorists attacked Cologne residents on New Year''s Eve 2015.', 'Season 7'),
  ('37320f7a-3382-5df2-a1d4-70a666c93929'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony met with his friend and author Laurie Woolever, who co-wrote his cookbook Appetites with him. They bet on some horses and ate Jamaican beef patties.', 'Season 9'),
  ('37409d40-584f-5116-8d24-cd891b8732e9'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Andy and Tony ate Pad kee mao (drunken noodles) here, a spicy dish that has no noodles for some reason. They also ate kra pao gai (Thai basil chicken), pad cha talay (seafood stirfry).', 'Season 3'),
  ('374ce4c9-d6fd-50ff-b1d5-b4655210ac25'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Site of the original open food markets in Paris (now a park square)', 'Sightseeing'),
  ('3753d15b-4ed3-5bd6-9e3a-5315e7af5e06'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This was a restaurant called Queareparaenamorarte. It is closed now.', 'Restaurants and Bars'),
  ('375e82fb-2d9b-5a4d-91ac-0f7ab283db2e'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and José Andrés had cider, sea urchin, spider crab, percebes (gooseneck barnacles)', 'Season 12'),
  ('377ea118-9c32-5794-8c1e-82ece0069fa1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had BBQ here with The Black Keys', 'Restaurants and Bars'),
  ('37f1427c-b001-55b7-9813-a854c2cb8c03'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('3831668c-9102-5a1c-8f4c-4b14529a55a7'::uuid, 'the_layover'::show_name, 2, 'Reasonable rates', NULL, 'Season 2'),
  ('383738ab-caef-586e-a74a-6c45fb9f7784'::uuid, 'a_cooks_tour'::show_name, NULL, 'Culinary school', NULL, 'Disc 3: Europe'),
  ('38431e76-1ada-57dc-b3cb-444c84a341ea'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony said he felt old here but liked tasting the mezcal', 'Restaurants and Bars'),
  ('384862ca-1097-5089-814b-96af3d0f87d9'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('386275a9-f7dc-52ec-8907-4c4e133317de'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had piri piri chicken here. It is a spicy grilled chicken basted with piri piri chili sauce (piri piri peppers, lime, peanut oil, minced garlic, tomato).', 'Restaurants and Bars'),
  ('38880da0-cb0c-54ba-9365-11340401a51f'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Fish n chips; they ate lots of deep fried things here', 'Disc 3: Europe'),
  ('38880da0-cb0c-54ba-9365-11340401a51f'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had fish and chips (haddock), covered in shredded cheese and curry sauce; deep fried haggis with curry sauce', 'Season 5'),
  ('38a10c4d-63c8-5fb0-b04f-8bb17fab42d8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had Cacio e Pepe here', 'Restaurants and Bars'),
  ('38cd4f5d-478d-554c-8410-a120cf2f2e48'::uuid, 'the_layover'::show_name, 2, 'Fish and fruit market', NULL, 'Season 2'),
  ('38fba273-7364-5e5d-b7fc-fdbb4ed07d53'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony tried horse meat here. They grilled it outside on the street. Tony enjoyed it.', 'Season 2'),
  ('390dde18-a3d7-53ef-aee5-c690403414c4'::uuid, 'parts_unknown'::show_name, 4, NULL, 'One of the only Jewish delis in the Bronx. Tony had hot pastrami, chopped liver on toast, potato pancakes with applesauce, pickles, Dr. Brown’s Cel-Ray (celery-flavored soda).', 'Season 4'),
  ('390ed189-3c98-5d0f-a021-5cfe36d7fca4'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Handmade pastry traditionally eaten for breakfast. It''s a phyllo dough filled with a kind of salty ricotta style cheese', 'Restaurants and Bars'),
  ('39201f47-8122-5e59-86a4-818e00860557'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony always had a bowl of laksa when he visited Malaysia. This dish has rice noodles, herbs, red onion, fish broth, chili', 'Restaurants and Bars'),
  ('392566fd-1d2a-5147-9e06-6de1d2dc3743'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had northern Indian food here.', 'Season 11'),
  ('392eeae4-4db0-566b-a004-df8cc2d9237e'::uuid, 'the_layover'::show_name, 1, 'Cocktails and snacks', NULL, 'Season 1'),
  ('395914ae-b303-5976-9348-b94ab4766d91'::uuid, 'the_layover'::show_name, 1, 'Sauteed chicken/prawns', NULL, 'Season 1'),
  ('39b06481-f97f-55e5-b772-dda9eda617ff'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony visited the duck farm', 'Disc 3: Europe'),
  ('39b32a3b-a2d8-58cd-a3ad-c02d0c661d2d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited during the Songkhram Festival, a renewal or cleansing festival where everyone throws water on each other. It is very hot so this can be enjoyable, although messy.', 'Sightseeing'),
  ('39c4af71-e402-5537-9694-e2e09e5e089e'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Eric visited this restaurant where the chef uses a wok to cook. They had octopus and flounder ceviche; tiradito of flounder with pecan, lime, ají limo chili peppers, and sesame oil.', 'Season 1'),
  ('39cd7cce-da80-58d7-9e17-f28f761ad71c'::uuid, 'the_layover'::show_name, 2, 'Oysters', NULL, 'Season 2'),
  ('39f4f804-63ef-57bf-83c2-2a6ed9b73e01'::uuid, 'parts_unknown'::show_name, 3, NULL, 'The Zapotec ruins are here. Tony and his guide drank mescal here.', 'Season 3'),
  ('3a7fe0b7-0c40-5a49-bd21-a90bfd424d79'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had a meal at Rainer Judd''s house (President of the Judd Foundation). They had blue corn tortillas, menudo, sopapillas, queso fresco with chiles, tamales', 'Season 12'),
  ('3ab7bf45-e5d4-57d2-a667-77c8bd8189a6'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony visited the Palestinian side, referred to as the West Bank or the Samaria, Palestine, or Judea.', 'Season 2'),
  ('3af2f30a-0ea8-539e-af6c-587ba95d8f5d'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony tried port and assorted cheeses, bread, pumpkin jam.', 'Season 9'),
  ('3b3a6eb3-407f-56f9-9ca2-0bd63a12c335'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony hopped the border to Italy because he craved pasta in the Aoeste Valley. They had gnocchi with beet root fondue, ravioli with tomato sauce, creamy polenta with braised beef. Tony, Eric, and host played feur lane, a game where "you try to hit that tiny polished stone with that stick as far as you can."', 'Season 10'),
  ('3b4ae574-e45e-5877-9d46-35a6966d61d3'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony and Andy had deep fried chicken and fish, Thai chili dip nam prik noom, Thai pork sausage', 'Season 3'),
  ('3b4f403c-d8c3-5925-85a7-404b6973982a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They launched a boat near here to fish for octopus. Tony seemed miserable and cold with his "inappropriate footwear." The crew members then prepared the freshly caught octopus and they ate it with some cold beer.', 'Other Activities'),
  ('3b5a16ac-e70b-508b-af8f-535ff90990a8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited Chef Brian Polcyn here where he teaches charcuterie and other cooking classes', 'Other Activities'),
  ('3b79607d-5af6-5619-a518-bfd1b5b4912d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Cassava and plantain cooked slowly in banana leaves with marinated beef with garlic, onions, tomato, and bitter orange, layered with green onions and red peppers.', 'Restaurants and Bars'),
  ('3b976c36-7d9e-5bc7-b9e8-407c244395df'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and his brother head into the interior, the country. Met the Anrich family, who live on a ranch called Estancia los Morteros. They eat many things including an armadillo caught by the son', 'Other Activities'),
  ('3ba231e7-7193-5a96-a8fd-faa107cf49a9'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony watched as a diver/chef jumped off the cliff and harvested sea urchin. They ate it fresh out of the ocean.', 'Other Activities'),
  ('3bcb572b-96b4-5fbd-8f7e-17f17b695ff0'::uuid, 'no_reservations'::show_name, NULL, 'Thai market', NULL, 'Food markets'),
  ('3bd99a85-49ef-579a-9111-01bfbff5a9be'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony visited when it was still just a food truck. He got the Salty Pimp.', 'Season 1'),
  ('3be0637a-3d99-566b-acb2-a6122687c190'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Writer Yotam Ottolenghi took Tony to East Jerusalem, where Palestinians live. They had falafel from a street vendor', 'Season 2'),
  ('3be0e02b-909a-552d-bb9a-6ba8b8da53df'::uuid, 'the_layover'::show_name, 1, NULL, 'Best airport in the world. Fern garden, shopping, great food, rooftop pool, bars', 'Season 1'),
