  ('3c1fb8dd-6391-5642-83cc-0e13abc07790'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Not sure if this is the exact pulqueria is (where they serve pulque, an alcoholic cactus sap drink) and some sort of Mexican moonshine', 'Restaurants and Bars'),
  ('3c4f55ad-038f-5b57-904d-bebf1227856f'::uuid, 'no_reservations'::show_name, NULL, 'Wine and cheese', NULL, 'Restaurants and Bars'),
