  ('3c5d92cd-4152-5347-8400-7cf76c3505f4'::uuid, 'the_layover'::show_name, 2, 'Maple buttermilk donuts and coffee', NULL, 'Season 2'),
  ('3c688123-b14e-5be7-877c-cd32a831753c'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony did a guest chef spot at this French restaurant. Tony did a guest chef spot at this French restaurant. Classic bistro style food.', 'Disc 1: United States'),
  ('3c89fb27-c168-55a8-a479-e03ff6734857'::uuid, 'the_layover'::show_name, 1, NULL, 'Colombian hot dog: topped with mozzarella and various sauces, and topped with crushed potato sticks', 'Season 1'),
  ('3d029a81-0da3-59c5-9220-ac51505a00b5'::uuid, 'no_reservations'::show_name, NULL, 'Spicy Sichuan food', NULL, 'Restaurants and Bars'),
  ('3d3d6305-fffa-52ab-b3b4-a1c2e2159583'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Chef Rene Redzepi met with Tony to eat here. Spinach with codfish sperm.', 'Restaurants and Bars'),
  ('3d485871-a5a2-5999-8521-cccea9fd4907'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A rotating cast of cooks provide regional foods from the artisanal market. Labneh, Armenian meat pie, artichoke and fava bean salad, fuul.', 'Restaurants and Bars'),
  ('3d4b7fc4-ec6a-588e-89d3-2d249335efaa'::uuid, 'the_layover'::show_name, 2, 'Bar for journalists and chefs', NULL, 'Season 2'),
  ('3d90028a-4782-58d1-bf9b-a3a3e6ef27e8'::uuid, 'the_layover'::show_name, 1, 'Beer', NULL, 'Season 1'),
  ('3d916a96-92b4-5e6d-8bf9-bed43acda49b'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony visited this training program where people are taught coding and software engineering.', 'Season 10'),
  ('3d9a3038-b676-55bc-b22e-16540aae22f2'::uuid, 'no_reservations'::show_name, NULL, 'Glacier climbing', NULL, 'Sightseeing'),
  ('3dab1bb1-f1d8-5cfd-bdb0-a5ecd1d07252'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Zamir visited this site where the nuclear disaster happened', 'Sightseeing'),
  ('3dc09f18-117f-5b6f-af4e-560ba08ffbbf'::uuid, 'no_reservations'::show_name, NULL, NULL, 'I am not sure if this is the exact location where David Chang introduced Tony to this convenience store, which he later wrote about several times in his future visits to Japan. It is a chain of stores, and both David and Tony loved the egg salad sandwich and the chicken nuggets here.', 'Restaurants and Bars'),
  ('3dfcc5bf-c9fd-5c9a-91fe-a13ca939610a'::uuid, 'no_reservations'::show_name, NULL, 'Seafood, produce, meats, cheeses, etc.', NULL, 'Food markets'),
  ('3dfcc5bf-c9fd-5c9a-91fe-a13ca939610a'::uuid, 'the_layover'::show_name, 2, 'Famous market with the fish throwers and other vendors', NULL, 'Season 2'),
  ('3e0192cf-ac36-57db-b0ef-e96322c4c04c'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony is not a religious person, half Jewish and half Catholic, he felt uncomfortable here at the Wall.', 'Season 2'),
  ('3e0964b4-a7ca-587a-b279-6032c28f2dd9'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony went to this local''s only shooting club where they had a good old fashioned clam bake', 'Season 4'),
  ('3e2fda63-128d-5c92-bb5f-03c021e8e238'::uuid, 'the_layover'::show_name, 2, NULL, 'Northeast Brazilian food. Tony says put at top of your list', 'Season 2'),
  ('3e39ae76-1df6-57da-9d17-092354b51f29'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Popular local spot serving Cajun foods. Crab & shrimp with okra, stuffed turkey wings, catfish.', 'Restaurants and Bars'),
  ('3e520eb8-f1c5-58c6-ae88-872749f42fb2'::uuid, 'the_layover'::show_name, 2, NULL, 'One of the most famous temples in Taiwan, celebrates Buddhist, Taoist, and folk deities.', 'Season 2'),
  ('3e70465c-4777-51fd-a11d-65f1ff33bf80'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony had a meal with Philippe Lajaunie, restaurateur, former owner of Brasserie Les Halles. They had chicken necks and cold beer.', 'Season 1'),
  ('3e8e2b59-59b3-5f01-8545-d99ba9940529'::uuid, 'the_layover'::show_name, 2, 'Snacks and beer', NULL, 'Season 2'),
  ('3ec60242-9d10-5717-97c2-630f8773f3ed'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Open since 1932, Tony had the "special,” a beef bologna and salami sandwich with mustard heated on a sandwich press, an egg cream.', 'Season 1'),
  ('3ec9b9e8-e67a-567e-9a9e-31c5c13b58ba'::uuid, 'no_reservations'::show_name, NULL, 'Fast food - fried chicken with garlic sauce', NULL, 'Restaurants and Bars'),
  ('3ed7fc08-75e6-5d87-8203-a972241d3c72'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony met up with W. Kamau Bell in the capital city. They had a lunch of grilled tilapia, ugali, Tusker beer. Tony also had beers with Njeri Gikera, owner of ChilliMango clothing store; Melissa Mbugua, managing partner at MNM Consulting Africa; and Bell at another local place.', 'Season 12'),
  ('3edb3519-27da-5c33-b925-10befc65e35c'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony ate here with food critic Jay Rayner. Tony describes how highly he regards this restaurant, "The food that I yearn for is food that I react to in an entirely emotional way. I''m looking for a suspension of logic and reason. This is something that I got here from the beginning." They had "roast bone marrow with parsley and caper salad, sourdough made here" along with "pickled calves'' tripe with radish, shaved carrot, and watercress; skate poached in court-bouillon, with fennel in green sauce of fresh parsley, herbs, and anchovies; pan seared kidney in savory sauce served on toast; pig’s head and potato pie."', 'Season 8'),
  ('3ee3330f-5592-5528-845c-5c8199313598'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Encebollado, a yellowfin tuna specialty of the region, a fish stew. Tony describes the place as, "A simple food stall in a nondescript corner in Downtown Guayaquil."', 'Restaurants and Bars'),
  ('3f050ce4-7c87-5cfa-a4d8-55ff9054d68e'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('3f2a1153-9d6f-52cf-8352-d89b9feb51be'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had fish & chips with Dale Jarvis, Intangible Cultural Heritage Development Officer for the Heritage Foundation of Newfoundland and Labrador.', 'Season 11'),
  ('3f30a78c-f45e-5082-8275-290d2487e39b'::uuid, 'no_reservations'::show_name, NULL, 'Sustainable, seasonal local and made from scratch meals.', NULL, 'Restaurants and Bars'),
  ('3f3f02e2-3edb-5635-91e7-bc9703c9614e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had lunch at a place called Barraca Nordestina. This is in the wrong location though. He was in the Rochinha favela when he ate chicken feet, black eyed peas, and veggies.', 'Restaurants and Bars'),
  ('3f637ae6-8d07-54f3-aee6-fec4304235fd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Modern tapas. Foie gras with a sweet crispy pineapple topping; homemade veal sausage topped with housemade ketchup, cheese sauce, and crispy fried onions; gabas al ajillo (shrimp pounded thin and served with roe); chicken wings marinated in lime, honey, soy', 'Restaurants and Bars'),
  ('3f64c949-a58b-55da-b9e7-6ab5eeeb0c95'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony met with hip hop pioneer Fab 5 Freddy', 'Season 12'),
  ('3f6b1724-2d62-511d-80d7-76e9261ee200'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate tripe soup. His guide had a fish stew with plantains (casuela).', 'Restaurants and Bars'),
  ('3f6f1522-21c4-5a8c-ac90-cc2528364460'::uuid, 'the_layover'::show_name, 1, 'Tacos', NULL, 'Season 1'),
  ('3f716f93-ba22-59db-9b53-c6f21ff81371'::uuid, 'a_cooks_tour'::show_name, NULL, 'The only hotel in the town', NULL, 'Disc 5: Australia and Japan'),
  ('3f814187-0354-5133-b30c-df5b6e177961'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Josh from Queens of the Stone Age went to this swap meet. They bought some things and ate at the Sky Cafe.', 'Other Activities'),
  ('3fa34029-723e-591e-955f-4209d1e0381a'::uuid, 'a_cooks_tour'::show_name, NULL, 'Creole homecooking. Jambalaya', NULL, 'Disc 1: United States'),
  ('3fa433f1-0ccb-5f8d-b639-67198a4d223c'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'They trekked out to the desert and roasted a whole lamb in the sand.', 'Disc 4: Morocco & Russia'),
  ('40129f2a-273f-557d-93f7-a972059c0e29'::uuid, 'the_layover'::show_name, 1, NULL, '"If you want huge and strange and wonderful," Tony says of this hotel. It has a 23,000 sq ft swimming pool', 'Season 1'),
  ('401da8ae-6c94-5997-a062-6b3969398d13'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony called it Manhattan''s "last dive bar"', 'Restaurants and Bars'),
  ('4033e0f6-6239-5da4-bc86-82f372f08f84'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A monastery with a public vegetarian restaurant where monks cook.', 'Restaurants and Bars'),
  ('40535076-07d0-5c23-a3d2-c260a45281d1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They ate hot dogs from Dick''s Dogs hot dog boat as they sailed down the river. Then they ate crabs they caught in the river.', 'Restaurants and Bars'),
  ('408bf5ae-e74e-5352-a35b-dd33448ae137'::uuid, 'the_layover'::show_name, 1, NULL, 'Cruise down Ocean Dr and view the Art Deco architecture, "straight out of Grand Theft Auto"', 'Season 1'),
  ('40b1fa97-9497-562f-9036-9471bf4f63ea'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony visited this old cemetery to see if he could find his great great great great grandfather''s grave. He did not find it but historians said it might have been overbuilt. While in Paraguay he learned that his ancestor came into the country as a hat maker but also sold fireworks, which could have been made into weapons.', 'Season 4'),
  ('40b6cfd3-ae78-57bd-a9f5-eb9ff43fae9e'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony visited this small village town at the base of the Rif mountains and had dinner family style with Bachir Attar, leader of The Master Musicians of Jajouka and his family. Braywine (handformed dough filled with seasoned beef, baked until golden, then crisped in oil); chicken tagine; a wild mountain spinach dish with garlic, cilantro, hot and black peppers, lemon, and olive oil; dessert of fruit and mint tea.', 'Season 1'),
  ('410ad378-2844-5824-86a5-1bc3a19c079f'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and David Choe had Wang mandu king dumplings (with pork and kimchi inside), mandu dumplings (smaller with thinner dumping skins), and sweet dumplings.', 'Season 1'),
  ('410fc8a1-1585-56da-8950-bd78544f4d53'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Arm wrestling tournament. Hunting gear is appropriate wear for this bar.', 'Restaurants and Bars'),
  ('411b510b-2960-5d19-acee-d1ea0827282f'::uuid, 'the_layover'::show_name, 1, 'Take a ferry to one of the surrounding islands', NULL, 'Season 1'),
  ('411b7124-b938-505c-a644-7e6ca2109e97'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony trained here every morning while he was filming this episode. He trains at the sister school in NYC, and planned this entire episode just so he could train here.', 'Season 6'),
  ('4123574f-35d7-545a-9f0f-519a9993e920'::uuid, 'the_layover'::show_name, 1, 'Fish and chips', NULL, 'Season 1'),
  ('41543d20-c487-5418-86fb-1d1525c0eae1'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('41553e17-645c-568a-af12-b22eb1f6394a'::uuid, 'no_reservations'::show_name, NULL, 'Specialize in Macanese food.', NULL, 'Restaurants and Bars'),
  ('416a19f3-9c60-54c4-8f22-e73443425a04'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Food market with tons of produce. They had empanadas.', 'Food markets'),
  ('41907d75-1cc7-5cdb-ae8a-f1fa2857d42e'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('41b22ccc-5cd4-58fc-ba4f-731053bd82fc'::uuid, 'the_layover'::show_name, 1, NULL, 'One of the oldest taverns in Montreal. Moules frites and great cocktails', 'Season 1'),
