  ('42465f9d-929d-5008-a647-7bef70c7bf03'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Philippe traveled on a train through the Burmese country to Bagan. They bought snacks from locals at the train station. The train ride was very bumpy.', 'Season 1'),
  ('426a3aa9-0313-58a1-869c-6af96943c4fa'::uuid, 'no_reservations'::show_name, NULL, 'Street market every month.', NULL, 'Food markets'),
  ('427e69b1-6291-5c2e-9dde-71ff06be0b64'::uuid, 'no_reservations'::show_name, NULL, 'Oysters and beer.', NULL, 'Restaurants and Bars'),
