  ('429a7d07-56db-5ef2-80d5-b20340eb3957'::uuid, 'the_layover'::show_name, 2, 'Architecture boat tour', NULL, 'Season 2'),
  ('429ea771-62f1-5d8a-82b0-ab8629edb544'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went to El Calafate and took a tour to the glacier.', 'Sightseeing'),
  ('42ceacc2-f1e3-5d3e-9797-6881bdf21e54'::uuid, 'parts_unknown'::show_name, 8, NULL, 'America''s most expensive restaurant, it costs around $600 per person. It is run by Masa Takayama, America''s most respected sushi chef. Tony traveled Japan with Masa.', 'Season 8'),
  ('42ceacc2-f1e3-5d3e-9797-6881bdf21e54'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony gives his sushi recommendations. Yasuda or Masa.', 'Season 1'),
  ('42d431d7-cac0-546e-a383-f9a36d4956db'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony plays hockey', 'Other Activities'),
  ('42dee535-babf-5b2e-8077-05bce37c33bd'::uuid, 'parts_unknown'::show_name, 4, NULL, 'John Yingling owns this place and helped to mentor Tony in his young days when he was not yet a chef. Tony used to sleep on top of the walk-in at Espiritus'' old location.', 'Season 4'),
  ('432d3ff2-0178-5de0-81d2-37049ca795f4'::uuid, 'no_reservations'::show_name, NULL, 'Street cart serving different sausages and hot dogs', NULL, 'Restaurants and Bars'),
  ('435df1a1-971f-5ae1-a670-a3a997ea7b84'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Generations old family BBQ spot. He ate there with Michael Symon', 'Restaurants and Bars'),
  ('43671125-c307-5890-b80f-ef5e05d0bd10'::uuid, 'the_layover'::show_name, 2, 'Market and eateries', NULL, 'Season 2'),
  ('43880ade-2263-5d26-8dac-643e4a92f9bc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony called this place CF Market. They had Pork Mee: Hokkien Chinese noodles, Penang style; Balitlong (sea snails)', 'Restaurants and Bars'),
  ('43d23601-4f00-58eb-a96e-112f0e203942'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met with famous Brazilian artist, Belo Borba in this public market. They ate a fish that can kill you if not prepared properly, served in a spicy stew.', 'Season 3'),
  ('43e815ce-440f-53af-9bcd-231f284bb920'::uuid, 'the_layover'::show_name, 1, 'Gelato', NULL, 'Season 1'),
  ('43ef4627-e77f-5988-aaa7-3378aed62d55'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony crashed a Quinceañera held here and talked with the owners about the "quince" culture in the Houston area.', 'Season 8'),
  ('43f0a580-15b6-54a3-9abf-3c6e13c82cd8'::uuid, 'no_reservations'::show_name, NULL, 'Beloved institution in DC that serves chili dogs', NULL, 'Restaurants and Bars'),
  ('43fe6cc7-9ee9-5485-9a39-ad8df4d26ad3'::uuid, 'the_layover'::show_name, 2, NULL, 'Dumpling house. Phat Rice with short ribs and pork belly. Ramen.', 'Season 2'),
