  ('44234e87-ee40-5bdc-b429-c1a8d6bf4e98'::uuid, 'the_layover'::show_name, 2, 'Mortadella sandwich is famous', NULL, 'Season 2'),
  ('444f3f05-3018-54bf-87c5-d651b25d6f56'::uuid, 'the_layover'::show_name, 2, 'Creative sandwiches', NULL, 'Season 2'),
  ('447af583-36a9-565d-b42a-91eda5139e5d'::uuid, 'parts_unknown'::show_name, 10, NULL, 'While skiing in the French Alps, Tony and Eric Ripert stopped here. They had pan-seared foie gras, seared veal loin with a wild mushroom sauce and vegetable medley, a cheese course.', 'Season 10'),
  ('4497efe1-5d07-56ce-a6d5-b7fbe9f3fd1a'::uuid, 'the_layover'::show_name, 1, 'Bar that opens at 6 am. Charles Bukowski frequented this bar', NULL, 'Season 1'),
  ('44af098e-6739-5cf1-8ab7-fa1985d47e5f'::uuid, 'the_layover'::show_name, 2, 'Legendary Pork Chop sandwich', NULL, 'Season 2'),
  ('44b40be1-f24a-594e-9600-5aeb5d66e200'::uuid, 'the_layover'::show_name, 2, 'Kitchen supplies', NULL, 'Season 2'),
  ('44b892ae-97c3-5093-9586-d9c800066317'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and the punk band ate barbecue at this stand in the night market.', 'Season 1'),
