  ('462817e6-597c-5b04-8f6d-c4501ceadff5'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony scubadived with 350 lb gray nurse sharks.', 'Other Activities'),
  ('46299f37-d100-5907-949b-f1a0dd1387a2'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had beer, kielbasa, sauerkraut, pierogies, and mac & cheese with wrestlers Brittany Baker and Adam Cole', 'Season 10'),
