  ('4665928e-c221-5f1a-a470-de73bba8ce8b'::uuid, 'the_layover'::show_name, 2, 'Porchetta sandwiches', NULL, 'Season 2'),
  ('466cc274-6094-5ea0-b05b-80d625585458'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony went to a restaurant from Vilmos'' childhood, where they ate this fish chowder called halászlé made from pike from the river and seasoned with paprika and other spices.', 'Season 5'),
  ('46708cd1-9b10-5290-9a47-4f635af0db5d'::uuid, 'the_layover'::show_name, 2, 'Soul food - may be closed now?', NULL, 'Season 2'),
