  ('46870394-09b4-5c78-96c1-3ec9fa3404f3'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony did some mining with miners.', 'Season 7'),
  ('46950654-9388-53d3-bae6-0a67395e91c5'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Clam chowder, fried clams, fried shrimp, lobster, onion rings, fried haddock, etc. Lobster rolls.', 'Restaurants and Bars'),
  ('46af475b-2376-56cd-b575-d3537fa19e75'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony met with Hector Abad, a writer. They ate tamales with chicken and pork belly.', 'Season 1'),
  ('46e0acaa-62f1-5c39-8c31-3edaa4ce966d'::uuid, 'the_layover'::show_name, 2, 'Dan dan noodles. Very spicy', NULL, 'Season 2'),
  ('46fa9044-02f4-534d-a92b-da0de5cc034f'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony watched as kids skating, fireworks being set off, motorcycles drove around as people celebrated the Prophet Mohammed''s birthday and freedom after 50 years of oppression.', 'Season 1'),
  ('471fe7dd-d113-593f-8568-1d1b7f46bcea'::uuid, 'the_layover'::show_name, 2, 'Bistro', NULL, 'Season 2'),
  ('47642ce8-c3cb-5feb-823e-f84e015952a9'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A market on the river has fruits, vegetables, and fish found in this area', 'Food markets'),
  ('47beea2e-0ce2-5f79-8ff3-fdc4d87833f1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had pinchos and Chacoli (a local sparkling wine that is very light and low in alcohol)', 'Restaurants and Bars'),
  ('47ddfcd0-bc89-520c-9c59-4561414845cf'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with therapist Marianna and had parrilla, a traditional Argentine meal called achuras, including kidney, chorizo, morcilla.', 'Season 7'),
  ('4800601d-2577-52e6-903e-d6adac12ef18'::uuid, 'the_layover'::show_name, 2, NULL, 'Shaved ice with mango. This isn''t the exact location but Tony says visit any shaved ice place, they are ubiquitous in Taiwan.', 'Season 2'),
  ('4822c44f-068e-5826-b0c1-459b1f63241b'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('48343ecd-a155-5dee-9ce8-2fc0d8137dbf'::uuid, 'the_layover'::show_name, 2, 'Public executions used to happen here', NULL, 'Season 2'),
  ('4851f104-2047-5f96-b110-40b155902a1a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Russian restaurant. Pelmeni - a meat ravioli served with broth. Braised rabbit stew.', 'Restaurants and Bars'),
  ('48917d16-d709-5172-b3e1-7ee497d0d03f'::uuid, 'the_layover'::show_name, 2, NULL, 'Honors a general that is an important figure in Taiwanese history', 'Season 2'),
  ('48beffde-6e94-5219-b1e7-30cdcb18efc3'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony camped out, ate kangaroo barbecued on the fire.', 'Disc 5: Australia and Japan'),
  ('48ebf237-a72d-5444-aeb9-8bbcc35dd8fc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Banana leaf curry. Steamed rice with a variety of curry dishes and side dishes placed on banana leaf.', 'Restaurants and Bars'),
  ('48eef643-85c3-558d-9d4b-ad014dc71841'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Fine dining. The chef of this restaurant cooked a whole pig for him (he also owns Cochon).', 'Restaurants and Bars'),
  ('48eef643-85c3-558d-9d4b-ad014dc71841'::uuid, 'the_layover'::show_name, 2, NULL, 'Tony''s chef friend Donald Lake, who he ate with on the show, owns this restaurant. This is his flagship.', 'Season 2'),
  ('48f73cef-a686-5952-a505-e8ddcd87b1f5'::uuid, 'the_layover'::show_name, 1, 'Indonesian food', NULL, 'Season 1'),
  ('49408f37-a8a7-53a1-a961-77a97002dd1d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony tries cuy, which is a local specialty made from roasted guinea pig', 'Restaurants and Bars'),
  ('4944b8ac-09d5-501a-943e-800f6e696fa4'::uuid, 'the_layover'::show_name, 1, 'Quintessential Roman food', NULL, 'Season 1'),
  ('495e4a3c-530d-55df-b059-bd9524857508'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony visited this coastal town, which was an important site to raise the support of revolution for equal rights. A family cooked a meal for him. Coconut rice, freshly caught tasi fish, simmer with garlic and lime, topped with umngqusho (a fresh salad of chopped tomato, eggplant, cucumber, potato), and another fish which is a type of mackeral, marinated in lime and garlic and fried. Served with various breads, cassava, and rice.', 'Season 4'),
  ('49755293-745f-5abc-9986-ad0ceb91adb6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Family style breakfast. Huevos rancheros, beans, tortitas, stews, chicharron', 'Restaurants and Bars'),
  ('49cf6c93-ab4c-526e-a682-fed01a2811ed'::uuid, 'the_layover'::show_name, 1, 'Park overlooking the canal', NULL, 'Season 1'),
  ('49f06acb-ad17-5bf0-8d31-a5abedca83a1'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had drinks at this bar with the owner of this saloon.', 'Season 12'),
  ('4a2ce7f7-040d-5f64-880f-15983ca2a101'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Former site of this restaurant, which translated to Friends'' Corner.', 'Season 8'),
  ('4a326213-5dc6-5cd0-b045-5387d7173a10'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had drinks with an ex-cop named Alex Salazar that admits he crossed lines and did bad things when he was a street cop.', 'Season 9'),
  ('4a8fc701-54ea-5892-8e19-e019f3836ff2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Winery featuring Carmenère wine (local). There was a rodeo on site and dinner of beef, pork, and chicken.', 'Other Activities'),
  ('4a96e9fb-9eca-56dc-aa11-d4aff2126ea1'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Nibiki Restaurant. They serve fugu here, a fish that can kill you if not cooked properly.', 'Disc 5: Australia and Japan'),
  ('4ab69788-5536-575b-9274-e8451ef57868'::uuid, 'parts_unknown'::show_name, 4, NULL, 'They had lunch by the lake after driving around looking at zebras, hyena, lions, giraffe, and elephants. There was pesto pasta and brownies involved.', 'Season 4'),
  ('4ac06652-730c-5438-a5ce-2489c598fcfa'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Originally called the French Culinary Institute (during this taping), Tony visited Dave Arnold to ask what would Jesus eat for the Holiday Special episode.', 'Other Activities'),
  ('4b227b72-7b59-5815-b85d-b0f0cee077e6'::uuid, 'parts_unknown'::show_name, 9, NULL, 'For great Chinese food in Flushing. Tony met with chefs Josh Smookler and Cosme Aguilar. They had galbi, or "short ribs marinated in soy, garlic, and sesame oil, then grilled." and gam ja tang, a soup made from pork neck bones.', 'Season 9'),
  ('4b3b27ba-9402-5b4f-8701-8ed2623ee831'::uuid, 'the_layover'::show_name, 1, 'Secret bar', NULL, 'Season 1'),
  ('4b42ee34-94fe-560b-8502-b172509f48a8'::uuid, 'the_layover'::show_name, 2, 'Hotel overlooking Pike Place Market', NULL, 'Season 2'),
  ('4b7d11f2-e24c-5435-b937-42cf024bbc75'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Somewhere between Angkor Wat and this port city, Tony stopped at a roadside restaurant which served freshly made spring rolls and noodles.', 'Restaurants and Bars'),
  ('4b82cb0d-71f1-5753-a29a-9b7c52ed3d30'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Fancy Mexican restaurant by Chef Ray Garcia. Chicharron cooked souvide, slow cooked lamb-neck tamales with oyster mushrooms and queso oaxaca, Okinawan sweet potato filled with pork, topped with piloncillo syrup with bread with foie gras and piloncillo.', 'Season 9'),
  ('4b8666c3-03c8-5f6f-aa39-6f7d6b129f43'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Chef VJ Dennis cooked some gullah classics here at Mosquito Beach on James Island, home of Ashley Green. They had local blue crab, garlic shrimp, softshell crabs & conch in a peanut stew with sauteed Carolina squash and zucchini', 'Season 6'),
  ('4bb31861-99c3-56f3-8c1e-8e11f7bc0070'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate at a street food stand outside this building. Fish, quail, lentils.', 'Restaurants and Bars'),
  ('4c26ac8f-5ebe-5c2f-8812-d8bef211b88e'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Toby Rodriguez hosted a crawfish boil here. They also ate jambalaya.', 'Season 11'),
  ('4c28d6f0-ea87-5c1f-a2d6-f4686fee8b59'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Modena Balsamic Vinegar. They had lunch in the attached restaurant: chicken thighs braised in lambrusco; spare ribs slow cooked in white wine with cippolini onions; frittata. All served with droplets of the vinegar', 'Other Activities'),
  ('4c7f169b-af7f-50e8-a9be-03b6d7904743'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A nomiya, which is a tiny bar where late shift workers go out after work', 'Restaurants and Bars'),
  ('4c8ce825-b35a-5f4d-a1d2-f479729040d2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Michael Symon''s restaurant. Tony and Marky Ramon ate there', 'Restaurants and Bars'),
  ('4ce8dcc5-c275-5670-889d-02e569c50fe2'::uuid, 'the_layover'::show_name, 2, 'Record store', NULL, 'Season 2'),
  ('4ce8e86d-8dcd-5e19-9b55-4c12c55f0e28'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Sister restaurant to Joe Beef. Tony met with the chefs and ate Pakistani food by Chef Omar. "Butter chicken crab; little eggplants braised with anar seeds, pomegranate; mushrooms; rabbit korma; fingerlings with fenugreek and fennel; donkey nahari; goat biryani; and more.', 'Season 1'),
  ('4d008974-3a4c-5d99-835c-86f870c605d2'::uuid, 'no_reservations'::show_name, NULL, 'Indian food', NULL, 'Restaurants and Bars'),
  ('4d0394d5-90ff-5d1b-9b4c-69b172659517'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Before the meal, the chef brought them to this basilica where he talked about the perfection of the architecture.', 'Sightseeing'),
  ('4d153aeb-dc55-5e82-b4a1-ede0c1d92552'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony visited this high school when it was called Robert E. Lee Senior High School. It is the most ethnically diverse school in Houston, with 80% of students speaking a language other than English as their first language.', 'Season 8'),
  ('4d2bf560-dbf1-5ebd-ac5f-c7d9e0c32132'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Madam Gao was Tony''s good friend. She owned the restaurant.', 'Disc 6: Asia'),
  ('4d2bf560-dbf1-5ebd-ac5f-c7d9e0c32132'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony''s friend Mom Gow had passed away by the time he visited. "Even the colors seem more muted now. The atmosphere different."', 'Restaurants and Bars'),
  ('4d3b5cd7-dcd2-5411-a5c4-31eddcc104ed'::uuid, 'parts_unknown'::show_name, 4, NULL, '"An entire ecosystem within an ecosystem" Tony said of this volcano crater. He had breakfast at his hotel overlooking the crater lake.', 'Season 4'),
  ('4dbdade0-df9c-54b2-9420-15100fa27c3d'::uuid, 'the_layover'::show_name, 1, NULL, '3 generations of one family run this place. Tony recommends the boiled fish and grits served with johnny cakes', 'Season 1'),
  ('4ddbc170-d075-5e74-aafa-adc057d5f608'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony tried making pastries here', 'Restaurants and Bars'),
  ('4ddfacfa-c70d-5f36-9b53-bcedfb8e26a4'::uuid, 'parts_unknown'::show_name, 11, NULL, 'A 100-year old noodle shop. Tony had beef brisket noodles with wontons, cinematographer Chris Doyle had choy noodle soup.', 'Season 11'),
  ('4ddfc9fe-49e6-553a-850a-c1d87c0ef54a'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony has ddukboki (spicy rice cakes), japchae (sweet-potato noodles), and soondae (blood sausage)', 'Season 5'),
  ('4de756a2-3c99-5a1e-a7ef-b9710d3656e8'::uuid, 'no_reservations'::show_name, NULL, 'Rugby', NULL, 'Other Activities'),
  ('4dfdaae3-6ea7-575e-aaa6-efadbe1f9bb0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went to this resort just as it opened, so there were very few people around. He did some skiing on the icy mountain.', 'Other Activities'),
  ('4e020136-a437-5a34-9274-63fa44770922'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited this area that had been devastated from a tsunami', 'Other Activities'),
  ('4e0fcb77-a558-516c-8f5c-04ff8572d0aa'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Alvin Leung''s famous and very strange modern cuisine. Tony called him the "Ferren Adria" of Hong Kong', 'Restaurants and Bars'),
  ('4e2fe7f4-ba3e-581a-8655-5bc27867d2f0'::uuid, 'no_reservations'::show_name, NULL, 'Watch expert noodlemakers make noodles!', NULL, 'Restaurants and Bars'),
  ('4e400ac2-0389-5710-8910-4d8a675fcfbe'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a medley of foie gras prepared many different ways. Chef Bonanno was trained at the French Laundry.', 'Restaurants and Bars'),
  ('4e7d9f00-7756-5a81-89ea-197be9a9e400'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony had a meal with Toshio Maeda, the manga illustrator credited with inventing tentacle porn. They ate katsuo no tataki (seared bonito with daikon, fresh greens, sprouts, and ponzu) and tomato nabe (a hot pot of meat and vegetables favored by sumo wrestlers).', 'Season 2'),
  ('4e8f871e-abf4-50a7-8a8b-06ff642ffa44'::uuid, 'parts_unknown'::show_name, 2, NULL, 'A little place for tapas. Tony went with Zach and Fuen. They had salmon with tomato, caviar', 'Season 2'),
  ('4eb30202-3272-5e5f-a39e-537f403b2bf7'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony met with culinary writer Ma Thanegi. They had pig’s-head salad with Kaffir lime leaf, long-bean salad with sesame and fish sauce, pennywort-leaf salad, a salad of Indian-style samosa.', 'Season 1'),
  ('4ecff673-a23c-5fe2-ba17-c2749218b559'::uuid, 'the_layover'::show_name, 2, 'Pork vermicelli soup', NULL, 'Season 2'),
  ('4eee8cc2-a26e-5a34-9095-99a5cdb5f5aa'::uuid, 'no_reservations'::show_name, NULL, 'Spa', NULL, 'Other Activities'),
  ('4ef2cf26-07a1-530e-ba23-20b02add14d2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony''s continuous search for "meat in tube form" leads him to this sausage stand. It''s a fast food place, so his chef friend is surprised how much he likes it.', 'Restaurants and Bars'),
  ('4f04b60f-c425-5ed6-a3da-58f66f11a548'::uuid, 'the_layover'::show_name, 2, 'Classic brasserie. Seafood tower and expensive wine.', NULL, 'Season 2'),
  ('4f10af93-9a5a-56df-a408-4ee3eaf616ab'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Very strange velvet art; Tony wanted to buy the Mr. T portrait', 'Other Activities'),
  ('4f3ad1a0-fff7-5bd2-99f2-3385e4c94c72'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony described Cambodian food as light on meat, heavy on vegetables, fruits, and seafood. Visited many food stands.', 'Disc 6: Asia'),
  ('4f3ad1a0-fff7-5bd2-99f2-3385e4c94c72'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony got a haircut on the street where the guy shaved it closer than Tony would have liked.', 'Other Activities'),
  ('4f6a48b1-eb77-5798-b189-4c08d190f533'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony bought some fly fishing gear', 'Other Activities'),
  ('4f8b5177-1f2d-5994-a702-8efd322a5b20'::uuid, 'parts_unknown'::show_name, 3, NULL, 'One of the nation''s greatest culinary schools, started by Paul Bocuse. Tony and Daniel Boulud tried the poulet en vessie (chicken cooked inside a pig’s bladder).', 'Season 3'),
  ('4f8c549f-beff-5219-9163-360ca0fda205'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Modern take on traditional Portuguese dishes. They tried deep-fried codfish tripe; game pie with truffles, rabbit, and São Jorge cheese; horse heart and other offal; and cabrito (milk-fed young goat) served on rice mixed with the goat liver and tongue, mushroom, onion, and chicken.', 'Restaurants and Bars'),
  ('4fe56daf-b3a1-5676-9c89-c3ee148499fd'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Used to be Chicama. Closed now. Tony had ceviche and a mojito', 'Disc 1: United States'),
  ('502ce989-1e0a-58b5-97fe-37081be8dedd'::uuid, 'parts_unknown'::show_name, 2, NULL, '"Definition of a hole in the wall," says Tony.', 'Season 2'),
  ('506bd4dc-c406-5c2f-b95d-38851144a8c2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Actor Michael K. Williams accompanied Tony to this Bahamian food place in Crown Heights', 'Restaurants and Bars'),
  ('50987594-aef0-5829-84e6-05e8f07e2883'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony sailed along the coastline and visited Shipwreck Beach. They grilled octopus and made a seafood stew', 'Sightseeing'),
  ('50b2b481-3d9e-5dd1-9844-d8a04d72abff'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony drank beer and caipirinhas and ate a grilled pork chimichurri sandwich on the Ipanema beach while his wife is training for a Brazilian Jiu Jitsu competition', 'Restaurants and Bars'),
  ('50b397ac-34c8-58b7-aea3-514716c55fac'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Seeing this building makes you understand why the revolution happened', 'Disc 4: Morocco & Russia'),
  ('50ccb461-c5f6-5cd4-8eeb-77f41a6018b0'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a meal with Maurizio Arca, a Sardinian-German. They had wine, antipasti (carpaccio, tomatoes with pepper and parmesan, grilled zucchini, mortadella), spaghetti with white clam sauce', 'Season 7'),
  ('5106cc63-447c-5ae5-9c08-a035923aca65'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Site of Dona Anastasia''s blue corn quesadillas stuffed with various fillings. It''s a food stand on the corner.', 'Restaurants and Bars'),
  ('512c6679-0c5e-55b1-acf8-604d698a4061'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Over 125 years old, it was the nicest cafe in the world at the time it was built where artists and writers gathered. Nowadays, they have lots of foie gras on the menu. Tony had the pork throttle stew.', 'Season 5'),
  ('512d5160-2fea-56d2-9229-970d88852251'::uuid, 'no_reservations'::show_name, NULL, 'Scott Conant demonstrates how to make red sauce and pasta', NULL, 'Restaurants and Bars'),
  ('512e6ea0-9707-55f2-9b26-0683f96492d8'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Agri tourismo - a working farm, hotel, restaurant. Produces olive oil. On his last day in Sicily, he had a meal here made from ingredients on the farm: penne with sundried tomatoes and zucchini; a rabbit dish; agridolce greens', 'Season 2'),
  ('5131828f-b39d-5f00-b462-a8f1d2abdfca'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Translates to "The German Fountain," a 60-year old institution serving the "lomito" which is a pile of pork and avocado.', 'Restaurants and Bars'),
  ('51343356-9f34-5a1e-bdd9-db35654b1617'::uuid, 'no_reservations'::show_name, NULL, 'A very long line for this brisket/ribs/sausage spot.', NULL, 'Restaurants and Bars'),
  ('515676e3-c42e-5bec-aef8-18b85c32d80f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Paul Wilson, head chef at the time of this shooting, cooked wagyu beef on a grill', 'Restaurants and Bars'),
  ('516e9568-00af-5469-bbab-cc953d13ccb8'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with a group of women chefs to eat at this restaurant, including Bruna Martins, who owns the restaurant. Bruna only hires women to work there. They had "turkey neck, braised with butter and garlic, served with white beans, topped with kale and pork belly... ox hump pot-roast, served with mashed potatoes and farofa." While there, they had a scare when a drunk man in a stolen car was seen with a gun. The cameraman and producer dove on top of Tony to protect him, to which he said, "you know, you''re NOT the secret service!"', 'Season 8'),
  ('517bb390-d782-52d0-a581-456ad0dcae90'::uuid, 'the_layover'::show_name, 2, 'Dim sum', NULL, 'Season 2'),
  ('51b5c0e1-7e89-51fe-b8f4-adca2a9d5fe5'::uuid, 'the_layover'::show_name, 2, NULL, 'An institution. Everyone goes there. Fried Chicken, Shrimp Clemenceau, Jambalaya, Red Beans, and Rice.', 'Season 2'),
  ('51e2365e-f293-5ca2-a090-011808b4bbd4'::uuid, 'the_layover'::show_name, 2, NULL, 'National dish of Brazil. Rice, kale, rib, beans, sausage, beef. Peasant food.', 'Season 2'),
  ('51e44110-7163-5153-9cab-b809e06bbe57'::uuid, 'the_layover'::show_name, 2, 'Ethnic food stands', NULL, 'Season 2'),
  ('51ee81e7-d83d-5dce-b183-26f673875c07'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Formerly a Russian restaurant, Tony and Zamir ate a whole roast pig, blintzes with caviar, and more.', 'Restaurants and Bars'),
  ('51f0ad15-d175-517c-8d1a-b0d9eea46d00'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Restaurant known for their couscous. Tony had the royale, which is served with veggies, merguez sausage, chicken, chickpeas, lamb, and meatballs.', 'Season 6'),
  ('51f94c32-154e-5c72-a748-b3f33df150f8'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with an economics expert to talk about the financial ecosystem of this marketplace. Young people learn to take apart and fix phones for a living.', 'Season 10'),
  ('51fc2e64-cb00-55db-9842-0e337af53628'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had "racks of pork rib, grilled hearts of escarole and turnips, a sauce made from the pork drippings, and four types of sausage" with Chefs Justin Severeno and Sonja Finn.', 'Season 10'),
  ('520c94e8-55df-5915-9241-284edc052a1e'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Cocktail bar with a mixologist. Upstairs there is a restaurant called Catbird Seat. Tony had a drink here before he ate a meal at the restaurant.', 'Season 8'),
  ('523d5037-04d9-5482-9c3a-585563629376'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony says the cheesesteaks here are better than Philly, but it''s not a typical cheesesteak. It''s on a round kaiser poppyseed roll with steak, fried onions, and American cheese', 'Season 5'),
  ('527008de-9f5e-5a9f-8f1a-ef90c8b98232'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A 1000 year old dish of rice, pasta, black lentils, chickpeas, and fried onions. Served with a tomato cumin hot sauce and a vinegar/garlic sauce to drizzle.', 'Restaurants and Bars'),
  ('52e3632c-b694-5324-9fc6-4fcfc54ec458'::uuid, 'the_layover'::show_name, 1, 'Korean fried chicken and beer', NULL, 'Season 1'),
  ('531a079b-2f0a-502d-9620-5a6598d16e90'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony ate a Balkan burger here. It is a flattened ground beef patty with tons of cheese and your choice of toppings. There is a rooftop with a view where you can sit and eat.', 'Season 2'),
  ('5320fb78-befe-543d-8cb0-0d95fdd2df5f'::uuid, 'no_reservations'::show_name, NULL, 'Tamale on a hot dog covered in chili', NULL, 'Other Activities'),
  ('53383afb-3392-54a6-97c0-6c9534acae1f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Bucharest style meal. They had a whole suckling pig. Tony hated the themed Imperialist atmosphere but loved the food', 'Restaurants and Bars'),
  ('5341c585-a3b7-58ca-96a2-7e4ec988ffab'::uuid, 'the_layover'::show_name, 2, NULL, 'Tony''s chef friend Donald Lake, who he ate with on the show, owns this restaurant. Cajun Southern homestyle food', 'Season 2'),
  ('535d9849-dc59-594b-82c7-189568bf45ec'::uuid, 'parts_unknown'::show_name, 6, NULL, 'A feeder team for the NY Yankees, Tony met with Bill Murray who is an owner of the team, to watch a game', 'Season 6'),
  ('5389da44-0328-5ed1-b34c-807358780063'::uuid, 'parts_unknown'::show_name, 5, 'Korean BBQ with a group of Korean businessmen', NULL, 'Season 5'),
  ('53925b10-adfc-5157-8649-d358f7c628c1'::uuid, 'no_reservations'::show_name, NULL, 'Girly drinks', NULL, 'Restaurants and Bars'),
  ('53a52186-0269-5ba1-8ae2-3e7e67feebf6'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Out in the middle of the country, Sean Brock brought Tony to this traditional whole hog pit barbecue, a place that has been in business for over 40 years. They do burn barrel barbecue that requires tending to all night long.', 'Season 6'),
  ('53c51fc3-5508-57a8-bbcb-09e7f8f786f0'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with His Royal Highness, Alhaji Musa Muhammadu Dogonkadai, Sarkin Hausawan Agege. They had masa (griddle cakes made from sticky rice, sugar, potash—a mineral-rich salt), fura (millet and milk compote), danwake (bean-flour dumplings served with tomatoes), moringa salad, kuli-kuli powder (ground peanut).', 'Season 10'),
  ('53d5ea57-690f-5a59-a33b-41a58e9ce51e'::uuid, 'parts_unknown'::show_name, 6, NULL, 'A two-Michelin starred restaurant. They had veggie burger, beet rose with yogurt and rose petal ice (signature dish), California sturgeon caviar, egg yolk poached in smoked oil, wild king salmon wrapped in yuba with charred cabbage in wild ginger sauce, beef tenderloin, black sesame mocha bun with strawberry kumquat.', 'Season 6'),
  ('540714ee-7674-5059-b4dc-ff6825141ea1'::uuid, 'no_reservations'::show_name, NULL, 'Fancy cocktails at one of the best bars in Tokyo, in Shibuya', NULL, 'Restaurants and Bars'),
  ('540927e6-419a-596d-9b96-3f97948ad49a'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with Jamie Hince, "half the creative alliance that makes up the band The Kills." This is Jamie''s "favorite local joint for Caribbean food"', 'Season 8'),
  ('5426fa2c-6a6c-5539-b9d8-b0c59392b658'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Also known as the "Burning Lake" although it is on a river, not a lake. There are clay offerings and incense burning.', 'Season 11'),
  ('543dc5fd-faaa-5881-ba88-2aaa0e993712'::uuid, 'no_reservations'::show_name, NULL, NULL, 'In the wine country, the chef raises his own sheep to serve at the restaurant', 'Restaurants and Bars'),
  ('546dbf61-860e-5289-b727-e374928832b7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Restauranteur Con Christopoulos owns this place across from the Parliament. They grilled shrimp and meats.', 'Restaurants and Bars'),
  ('54773d9b-775c-5c3b-bcd6-6919b745106d'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had fried sardines, Tripe Porto-style, and wine.', 'Season 9'),
  ('547b792d-5765-51d2-8a32-acddd2054022'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Local seafood known for their fresh marinated fish, fried. And soup.', 'Restaurants and Bars'),
  ('548ce505-dbed-5f38-8131-75583dc33aa6'::uuid, 'no_reservations'::show_name, NULL, 'Famous for the Madrid Callos (tripe)', NULL, 'Restaurants and Bars'),
  ('54b21e10-d59d-53e3-b2f8-bd42138af7ee'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had halo halo, which translates to "mix mix." It is an "icy, milky, technicolor concoction of sundry sweet mung beans, candied fruits, and gelatins." Also has banana, condensed milk, and sweet young coconut.', 'Season 7'),
  ('54bd9162-8be8-51a5-9e02-990948bf7264'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Donut truck. Fried chicken donuts, Jalapeno donuts, all kinds of weird topping donuts', 'Restaurants and Bars'),
  ('551b13ce-789c-59c2-a319-0213fbab9b20'::uuid, 'parts_unknown'::show_name, 5, NULL, NULL, 'Season 5'),
  ('551c8da2-9786-5be2-8ba9-0ccd8ffbcdf4'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with Darren Aronofsky here to begin their journey', 'Season 5'),
  ('5556e7fb-40af-5ff7-a4d0-8e6e8774ed3a'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony met with chef Marcus Samuelsson and his wife Maya. They had beyaynetu, a platter of various stews including goman (sauteed greens), shiro wat (chickpea stew), tikil gomen (sauteed white cabbage); all served with injera bread.', 'Season 6'),
  ('555f1433-708f-5ef7-b118-45a3bd594232'::uuid, 'no_reservations'::show_name, NULL, 'Fish heads!', NULL, 'Restaurants and Bars'),
  ('55b0df7f-7348-5cd7-9276-a9a6a3493fe1'::uuid, 'the_layover'::show_name, 1, 'Old Italian Classics', NULL, 'Season 1'),
  ('55baa9f2-e5ef-5f26-b005-8a6af08f9415'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had sauteed chicken gizzards with green bananas, codfish fritters, carne guisada, and mofongo with the band Fiel a la Vega.', 'Season 10'),
  ('55bdadfa-d760-5f05-9547-e5bc691f48cb'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with a rapper named Chino to talk about this radio station that hosts all types of musicians.', 'Season 5'),
  ('55c3e866-1e3b-5c1e-87c2-05e223bdf077'::uuid, 'no_reservations'::show_name, NULL, NULL, 'One menu, prix fixe, the chef is the only one who cooks. The chef trained at Gramercy Tavern in NYC', 'Restaurants and Bars'),
  ('55d5cce2-2351-5af3-87e4-95526b1ee3a5'::uuid, 'the_layover'::show_name, 2, 'Hard to find bar, it''s behind the dim sum stand', NULL, 'Season 2'),
  ('55e38078-b32d-5f0e-8729-1a9f290e64e2'::uuid, 'parts_unknown'::show_name, 9, NULL, 'A taco truck serving carne asada, the slow grilled marinated beef classic served as a burrito with rice and beans, or simply on a tortilla as a taco. Tacos lengua, beef tongue braised with garlic and onions. And tacos al pastor, stacked guajillo chili rubbed pork shoulder slices with your choice of toppings."', 'Season 9'),
  ('55e63501-3dc7-5ab3-94e1-ad24746b1af3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony hunted reindeer', 'Other Activities'),
  ('55fc1b24-3877-5536-acd0-a2336aec0747'::uuid, 'parts_unknown'::show_name, 4, NULL, 'The best food in Iran is made at people''s houses. Tony''s host cooked him a huge meal in her house. They had chicken cream soup, Fesenjan (a stew of fried chicken, onion, ground walnuts, pomegranate, dried apricot, tomato paste), Mahia Halva (tilapia), Ghemieh (beans and meat), Tahdig (crispy rice).', 'Season 4'),
  ('55fdd823-4bf4-5d49-a8d1-39f3c37b7718'::uuid, 'no_reservations'::show_name, NULL, NULL, 'After shopping at the fish market, Chef Henrique Sa Pessoa makes Tony a meal. Mackerel, pork with sweet potato purée served over bok choy, a semi-salted cod called Bacalhau with chickpea purée.', 'Restaurants and Bars'),
  ('55ff028f-896f-5043-b8fb-e5f833ce1fbe'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Shrimp n grits are good. Tony had "The Big Nasty," which is a biscuit topped with fried chicken, cheddar, and sausage gravy. Also the buttermilk pie.', 'Restaurants and Bars'),
  ('56857f7c-ecc2-550b-b397-9cc3d49e3b3a'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony visited this liquor store to pick up some alcohol.', 'Season 2'),
  ('568e5467-9ab6-5535-b0e7-b60d98dffe31'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Roy Choi visited this place that Roy said was one of his favorites. They serve a soup called Soon Dubu, described by Tony as "a fiery, tongue-searing, ass-burning tofu soup that will make you forget every bad thing you ever thought about tofu."', 'Season 1'),
  ('569e10c4-055a-542a-9dfd-f7b8418c9e82'::uuid, 'the_layover'::show_name, 1, 'Burlesque bar', NULL, 'Season 1'),
  ('569e9f5c-bfb7-5982-80ed-e4192cafde00'::uuid, 'no_reservations'::show_name, NULL, NULL, 'After visiting on a tugboat pulling large ships into dock, they had a meal at this trattoria on an outside patio table. Tony called it "Trattoria Borghi" so it may have changed ownership', 'Restaurants and Bars'),
  ('56a39b33-df52-5c6d-a285-f154eb934d4e'::uuid, 'the_layover'::show_name, 2, NULL, 'Lots to look at but Tony came to look at the jade sculptures', 'Season 2'),
  ('5700a15d-318d-5025-86f9-139b277b885b'::uuid, 'the_layover'::show_name, 2, 'Wine bar with creative food', NULL, 'Season 2'),
  ('573d4297-04e7-5dec-b15b-6b8e0a5bb6c5'::uuid, 'the_layover'::show_name, 1, 'Best pastrami', NULL, 'Season 1'),
  ('5743a1f2-eb02-523a-b7f1-2fd713f6e4f5'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Vineyard. The chef in the vineyard''s kitchen made tagliatelle. They ate it outside with a Sangiovese made at the vineyard.', 'Food markets'),
  ('57790363-511c-551a-a507-5e4a18b4e640'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Former site of a fortress built to protect the city from marauding Swedes, it was taken over by Bolshevik rebels.', 'Season 3'),
  ('577ff0c1-c52b-58cd-992b-53bfc2987649'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had fish, a meze of hummus and salads, Laziza nonalcoholic beer.', 'Season 5'),
  ('579550a5-79b4-56f7-99be-e91d3b7bc5eb'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony had prawn curry here and cringed at the local cultural norm of making kissing noises to call a waiter over.', 'Season 1'),
  ('57a948c1-dba8-5d29-ae16-3202c7b2ed67'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('57fc9f7d-a025-5cee-8545-89abc92e5f81'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony watched local musician Youssou N’Dour perform at this restaurant. They also ate beef mafe served with rice, a stew thickened with ground peanuts. Tony says, "there are similar preparations throughout West Africa, but the Senegalese version is particularly great."', 'Season 7'),
  ('58044b92-2674-5001-9b67-f2c59a688cad'::uuid, 'the_layover'::show_name, 1, 'Park-like walkway down the west side of the city', NULL, 'Season 1'),
  ('580a0dc1-e8b7-59e7-8da3-a9116315d151'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Ludo''s mentor is chef at this restaurant. Tony and Ludo ate, escargot, Beef bourguignon, cheese', 'Restaurants and Bars'),
  ('581c9443-275a-55a5-a566-0841599760e4'::uuid, 'a_cooks_tour'::show_name, NULL, 'French market with meats and cheeses.', NULL, 'Disc 2: Mexico and The Americas'),
  ('5823cdbe-265e-5b3b-a1fe-03ec4267c98b'::uuid, 'no_reservations'::show_name, NULL, 'Arguably the best al pastor tacos in the city', NULL, 'Restaurants and Bars'),
  ('5832b0ca-ea3f-54ba-9bda-acdae08ba1e6'::uuid, 'parts_unknown'::show_name, 10, NULL, 'A cave city that predates the Greek and Roman empires. Tony visited the city with Asia Argento. It used to be where the outcasts were sent, until Hollywood came to make movies. Now there are tourists and AirBnBs.', 'Season 10'),
  ('583f7987-aae5-56b9-a534-e86d00496d7c'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony ate at Boi Tran’s home and gallery with Boi Tran, painter; Nguyen Qui Duc; Hương Lan, writer and food blogger; art collector Jean-François Hubert, and Philippe Damas. They had bird’s nest soup, made of swallow’s nests and served with crabmeat, crab roe, red onion, pepper, and seasoned steamed lotus seeds; lobster with red onion, ginger, lemongrass, and chiles, cooked and presented in a bowl with lime leaves and the stock poured over it', 'Season 4'),
  ('5850eff3-1cb7-50f9-a068-63aa12886a2c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Toddy is an alcoholic drink, but Tony was not a fan. He was a fan of the food served here. Known for their fish head curry. He also tried steamed pearl spot fish curry (local fish), and crab masala.', 'Restaurants and Bars'),
  ('585f3b6d-a649-5375-a61e-62af6b67b2c0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony shopped here for palm nuts, hot chilis, snails', 'Food markets'),
  ('586177ef-dec4-550b-890f-c0d66809295d'::uuid, 'the_layover'::show_name, 2, 'Portuguese food', NULL, 'Season 2'),
  ('5895da1c-17d0-5745-9d1f-6259541b7d13'::uuid, 'the_layover'::show_name, 2, 'Open air street art museum', NULL, 'Season 2'),
  ('5897771c-25b4-5325-a090-7bbf54d62a92'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had cachorros here, made of toasted bread, fresh pork sausage, cheese, and a spicy sauce. And fries', 'Season 9'),
  ('589fddc5-dbd1-5843-ae47-984d3e29b9b5'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('589fddc5-dbd1-5843-ae47-984d3e29b9b5'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony sat with the chef and ate roast beef, poached egg, chicken rendang.', 'Season 6'),
  ('58dbb69d-39a7-5970-88f9-99ab0a10fe28'::uuid, 'no_reservations'::show_name, NULL, 'Cheap burgers', NULL, 'Restaurants and Bars'),
  ('58df8eeb-9167-52a3-9ea7-56728e2232cd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Breakfast of coffee and pao na chapa, or grilled bread served with butter, Tony calls it "the local answer to bagel with a schmear"', 'Restaurants and Bars'),
  ('58ffe73a-9dc7-5255-a079-4f21176c4491'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Chivito sandwich, you pick your toppings. It is ENORMOUS. Tony ate here with his brother', 'Restaurants and Bars'),
  ('59197af4-51dd-5014-a266-f710b011321b'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Food markets'),
  ('591f2aeb-2a81-5960-8320-d1778c3db910'::uuid, 'no_reservations'::show_name, NULL, NULL, '"The man knows fish," Tony says of the chef.', 'Restaurants and Bars'),
  ('592a18ff-9da2-5566-a2f1-bf847ac45125'::uuid, 'the_layover'::show_name, 1, 'English Breakfast', NULL, 'Season 1'),
  ('5961e174-bd1c-51e7-be33-fe1768fa1a41'::uuid, 'a_cooks_tour'::show_name, NULL, 'Nouveau Basque food', NULL, 'Disc 3: Europe'),
  ('5961e174-bd1c-51e7-be33-fe1768fa1a41'::uuid, 'no_reservations'::show_name, NULL, NULL, 'One of Tony''s favorite restaurants in the world. Tony said this restaurant made him feel like he was home.', 'Restaurants and Bars'),
  ('5961e174-bd1c-51e7-be33-fe1768fa1a41'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony sat with the Arzaks, who, he considers family. "The food is innovative, wildly creative, forward thinking, but always, ALWAYS Basque. Marinated prawns on lemongrass and mint with beetroot and crunchy krill, roast pigeon with mastic and potato... grilled hake jowls with teff seeds and almonds served in a bamboo leaf... grilled monkfish with a pecan paste and hieroglyphics of pumpkin and sweet pea... white tuna with green melon and a jackfruit sauce... squid with walnut-ginger paste, psyllium sauce with black tomato."', 'Season 9'),
  ('59a06c1a-b7aa-5c22-9541-ad5df592de80'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony visited Aida Refugee camp and had a meal at the martyr center.', 'Season 2'),
  ('59c4b0c2-b283-50ed-973e-a82b6371c9c4'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony met with Himanshu Suri, rapper and member of the Swet Shop Boys hip hop group, who is also known as Heems. They had an assortment of dumplings at this restaurant, which is now permanently closed.', 'Season 9'),
  ('59d802c2-51de-5a40-a185-cc8a906ed21d'::uuid, 'the_layover'::show_name, 1, 'STROOPWAFEL!', NULL, 'Season 1'),
  ('59eca2a5-668c-5278-9916-cdbf603578a6'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony went hunting with a guide and stand-up comedian Joe Rogan. They cooked bird they shot over a fire, with a conservationist and a journalist from Field & Stream.', 'Season 7'),
  ('59f8fa2c-ae6f-593f-9a7f-e0ba87209286'::uuid, 'no_reservations'::show_name, NULL, 'Drink tea', NULL, 'Restaurants and Bars'),
  ('5a14e2d8-3f25-500b-abb6-6a11d62ff20a'::uuid, 'parts_unknown'::show_name, 8, NULL, 'A traditional Mexican and Tex-Mex restaurant. Tony ate Machaca Nortena ("marinated beef that''s been pounded, rubbed with spices, then dried and shredded") and Migas (eggs mixed with fried and chopped corn tortillas).', 'Season 8'),
  ('5a1c8a03-59f6-5442-875d-3c1b9b4eb674'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony and Chef Michelle Bernstein had a HUGE burger here called the Doralzuela (beef patty with ham, egg, six varieties of sauce, crispy potatoes, and cheese)', 'Season 5'),
  ('5a2738ea-0cfa-59d5-beb7-ff529f640b5a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Chef Morimoto ate soba noodles here. They have been making soba noodles by hand here since 1789', 'Restaurants and Bars'),
  ('5a386465-8634-5f27-a726-f5af54141d15'::uuid, 'parts_unknown'::show_name, 3, NULL, '"Here the colonials created England in miniature," Tony says of this hill town.', 'Season 3'),
  ('5a54eca2-ab34-5501-bd68-96d91a5c4103'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went back to Le Chef, where he ate on his last visit (when Beirut was bombed). They had hummus with pine nuts and ground beef, eggplant with tomatoes, chickpeas, and onions. Fun story he told on this episode: The airport got bombed so after he finally got home taking a ship back to NYC, his girlfriend Ottavia met him when the boat docked and they conceived their daughter.', 'Restaurants and Bars'),
  ('5a587636-4cbc-57f1-95a4-390577d19666'::uuid, 'no_reservations'::show_name, NULL, NULL, 'In business since 1893, held by the same family for generations. Classic Italian-American food', 'Restaurants and Bars'),
  ('5a99dc60-0f6a-53c8-87db-49d8303dac52'::uuid, 'the_layover'::show_name, 2, NULL, 'Oyster bar and casual restaurant. Fried oysters with cilantro aioli. Prawn crudo.', 'Season 2'),
  ('5ad5c613-5578-5676-b367-b220d8503d10'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Polish traditional food. Chicken paprikash, stuffed cabbage, bratwurst, pierogies', 'Restaurants and Bars'),
  ('5b1ff93e-537f-52cb-b4eb-27482cca0cce'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Not sure if this is the same Zum Tor. On the show it was a "gentlemen''s club" where men gather, drink and, play games. They played Okey, a Turkish game with numbered tiles', 'Other Activities'),
  ('5b4635a9-e56b-54d0-bd80-d7d78740b3c5'::uuid, 'no_reservations'::show_name, NULL, 'Cow ranch', NULL, 'Other Activities'),
  ('5b4d61f1-6544-5127-919c-92206aa76f28'::uuid, 'no_reservations'::show_name, NULL, 'Anthony gave a talk here at a food and wine convention', NULL, 'Sightseeing'),
  ('5b5a5feb-7b37-5462-b889-06e3125ca99d'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met with Xena Robrek, an openly gay artist and filmmaker, and Darya Tarasova, a local fixer and translator at this club to have drinks.', 'Season 3'),
  ('5b8bf350-840b-5d82-9c68-bc741e4056ef'::uuid, 'the_layover'::show_name, 2, 'Beer hall style restaurant', NULL, 'Season 2'),
  ('5ba02121-52ae-5d3c-a3e5-cc26e27b47fc'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony visited this fire department to eat with the firefighters. They made crabcakes, broccoli salad, and steak.', 'Season 2'),
  ('5bc202f6-b21e-535e-b181-5aca7baebe01'::uuid, 'no_reservations'::show_name, NULL, 'Diner', NULL, 'Restaurants and Bars'),
  ('5bc202f6-b21e-535e-b181-5aca7baebe01'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony calls this his "happy place" because his father used to bring him here in the 50s. He ate a cheeseburger, fries, and a ripper hotdog', 'Season 5'),
  ('5bc53db3-6c23-529d-bd5e-2c97f5cb7891'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Chef Ivan ate this restaurant that serves grilled eel.', 'Restaurants and Bars'),
  ('5bc704cf-bc31-54c5-9b78-e769fb65a7bb'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Malaysian food: BBQ fish with onion/chili sauce, beef rendang, fried saltfish, beef liver, oxtail soup, stewed jackfruit', 'Disc 6: Asia'),
  ('5c0caea4-b9ca-5529-8a94-bb8005df46d1'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had bagels with Kembra Pfahler, filmmaker and performance artist', 'Season 12'),
  ('5c287a31-9f55-5e6f-9b01-7e0681b786ea'::uuid, 'the_layover'::show_name, 1, 'Korean food', NULL, 'Season 1'),
  ('5c3fda2e-4b96-5ef2-884b-340b1d802a18'::uuid, 'no_reservations'::show_name, NULL, 'The master Akihiro Matsuosa grills meats', NULL, 'Restaurants and Bars'),
  ('5c4efc03-eb2b-596d-97f0-91641a79f05a'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony and Darren Aronofsky ate momos (dumplings) here. Could not find the restaurant on a map.', 'Season 11'),
  ('5c65c364-d425-5d62-b73a-dc45bea59f47'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony met with local chef Sean Brock to have beer, Jägermeister, Brock’s 1991 Stitzel-Weller bourbon', 'Season 6'),
  ('5c808251-a238-531f-a135-855768812ded'::uuid, 'no_reservations'::show_name, NULL, 'Swedish traditional foods', NULL, 'Restaurants and Bars'),
  ('5c8a1414-e6c9-571b-b6d0-8f5f6a832220'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had beers here', 'Restaurants and Bars'),
  ('5c8c0f84-989f-5911-9eba-518748d7cb67'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They went to food street in Chinatown. They had chicken balls and pancit palabok', 'Food markets'),
  ('5c8e1eb3-f38c-5878-bf7c-077f6116888b'::uuid, 'parts_unknown'::show_name, 9, NULL, '"Serves specialties from the city of Tlacolula de Matamoros in Oaxaca, Mexico," says Tony. He visited this place with UCLA Chicano Studies professor, Raul Hinojosa-Ojeda. They had black mole and barbacoa.', 'Season 9'),
  ('5cb2d7e5-42b6-582a-8cea-6792d2442066'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The birthplace of Ikebana (the art of flower arranging). Tony learned how to make a flower arrangement', 'Other Activities'),
  ('5cc6ae3a-eeb8-590f-bc01-68f041bbe55b'::uuid, 'no_reservations'::show_name, NULL, 'Jacques does a demo making an omelet.', NULL, 'Restaurants and Bars'),
  ('5d08ebdc-e801-59ce-b79a-e0a31e0d03a9'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony and Eric had some fantastic charcuterie at a patio table outside of this charcuterie shop', 'Season 6'),
  ('5d666e63-2485-5f7b-a2ee-cf779ce367e8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'I am not sure if this is the village that Tony visited, but he said he was with the Makua people, which are in this area. He called the village Buahle, but I could not find it on a map. Tony ate stewed goat, banana curry, and cassava, among other traditional foods', 'Sightseeing'),
  ('5de13aab-144d-5396-a229-0647b9c7e26a'::uuid, 'the_layover'::show_name, 2, 'Dive bar', NULL, 'Season 2'),
  ('5debed52-4816-52fb-af1b-85fba370f197'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Other Activities'),
  ('5df410e6-a91d-5fcc-a25f-2f1b40de8ecf'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had beers at this bar that opened in the 1920s.', 'Season 7'),
  ('5dfef2a6-552a-51b3-b697-79e58d677bae'::uuid, 'the_layover'::show_name, 2, 'Old school Southern food. Chicken fried steak', NULL, 'Season 2'),
  ('5e005d3f-7ee1-5768-8a87-60bc5ea05f3f'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony''s favorite hot dog. He hated the Upper East Side then; he ended up moving there. He still loved the hot dogs.', 'Disc 1: United States'),
  ('5e005d3f-7ee1-5768-8a87-60bc5ea05f3f'::uuid, 'the_layover'::show_name, 1, 'Best hot dogs', NULL, 'Season 1'),
  ('5e03cb23-4444-5a96-9722-d121035ca8c0'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had tabbouleh, kofta with yogurt sauce and cranberries, stuffed grape leaves, kibbeh.', 'Season 5'),
  ('5e073cc3-5782-569e-98a6-2fcbab7111d8'::uuid, 'no_reservations'::show_name, NULL, 'Korean food.', NULL, 'Restaurants and Bars'),
  ('5e078474-86c7-5828-b1d6-44562069fa88'::uuid, 'the_layover'::show_name, 1, 'Bar', NULL, 'Season 1'),
  ('5e078924-84cb-5161-8b63-8dc3de9d9939'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had a francesinha (a sandwich made of sliced bread, steak, sausage, linguiça, cooked in a sauce of beer, port wine, spice, tomato, and a lot of cheese melted on top).', 'Season 9'),
  ('5e30de1e-103a-5adf-85b4-850c31b39092'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had a meal with Richie Nakano, a chef. They ordered the Presidential Platter, which is a sampler platter of brisket, hog, jalapeño and cheddar sausage, frankaroni (macaroni around a hot dog), ribs, chicken, beans, potato salad, coleslaw, bread, fries.', 'Season 6'),
  ('5e627ba9-1b9d-51e0-9d9c-d854e291804e'::uuid, 'no_reservations'::show_name, NULL, 'Blanquette de veau (veal stew), rum baba (dessert), WINE', NULL, 'Restaurants and Bars'),
  ('5e7e18f4-c1ce-54c1-90e8-6d4f325cd928'::uuid, 'no_reservations'::show_name, NULL, 'The chef, Master Tatsui Rai, makes the noodles by hand.', NULL, 'Restaurants and Bars'),
  ('5ea2fdf9-391c-5b37-8a98-cb409745eedb'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('5ea94ebd-7248-5878-a691-def377a49ca3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Fresh produce and food stands. Tony had a pork tamale with red chile.', 'Food markets'),
  ('5ef3cc73-966e-5a8c-a9cd-9f18d978750e'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had a traditional fisherman’s breakfast, and a Steel Bottom (one part rum, four parts beer).', 'Season 4'),
  ('5f237c15-42bd-5f4a-b627-081c19b10694'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Specializes in smoked and cured fish. Started as a pushcart business in the 1800s', 'Restaurants and Bars'),
  ('5f2b66a2-b83f-5360-bdd8-14e73dc04ce8'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('5f3631e4-0edd-50f5-b27a-9a2fd33922bb'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with retired Seattle homicide detective Mike Ciesynski to discuss serial killers. They ordered food from North Star Diner: crab, bacon, and melted cheese sandwich', 'Season 10'),
  ('5f404672-fda7-5873-b091-f6f380bcc6d1'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with chef Leo Paixão, who trained under Joel Robuchon and now runs Glouton. They tried all sorts of fruits and veggies only found in Brazil.', 'Season 8'),
  ('5f58907d-d9a2-5717-956a-6ed0d99db0fd'::uuid, 'the_layover'::show_name, 2, NULL, 'A park where Tony was frightened by a mime', 'Season 2'),
  ('5f6daf78-862e-5ef9-8032-75b9654b031b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Seasonal soups, housemade sausages, stuffed cabbage, potato dumplings, roast duck with applesauce, latkes stuffed with mushrooms', 'Restaurants and Bars'),
  ('5f6f74e7-a6aa-5672-9eea-656da168e8e5'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with chef and entrepreneur Pedro Álvarez Cortez at this crab shack. They had crab, coconut arepas, and beer.', 'Season 10'),
  ('5fba7d4e-59fe-51a0-b632-a75cc752bf11'::uuid, 'the_layover'::show_name, 2, 'Late night lounge with music and local beers. And food.', NULL, 'Season 2'),
  ('5fceb1b5-72d7-5368-87d9-2dc7aefac17a'::uuid, 'the_layover'::show_name, 2, NULL, 'Food truck serving burgers. They have a couple brick & mortar locations too', 'Season 2'),
  ('5fe03aa7-b118-5e3b-9ca6-e2eb822e4db6'::uuid, 'the_layover'::show_name, 2, 'Live music in the day time', NULL, 'Season 2'),
  ('604959b3-1106-5b4e-8268-d1056a04a8a9'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('6078101d-c102-52d7-92b1-62a6d7f2bc5f'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony and Darren got to see golden lemurs. There are only 500 alive in the world. Tony then watched the village people butcher a cow while Darren took photos and relaxed by a stream.', 'Season 5'),
  ('60897ef6-633d-515a-b94a-50acd64e228e'::uuid, 'the_layover'::show_name, 1, 'Lunch only', NULL, 'Season 1'),
  ('60b1b61a-b089-5bf0-95bd-cae6ff271655'::uuid, 'no_reservations'::show_name, NULL, 'Strip Club', NULL, 'Other Activities'),
  ('60b5e742-911b-5e1f-b484-f48c8941aee9'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and Chef José Andrés at this plaza café. They had arvejas (green peas) with ham, croquette, mussels, steak topped with blue cheese', 'Season 12'),
  ('60cd4f29-5608-5ed2-95d4-29f3b4e96f24'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Roy Choi viewed Koreatown from the roof of this building, and talked about the 1992 Rodney King riots that took place below.', 'Season 1'),
  ('60cf889d-143b-5b81-a8df-ad5fba3dfca9'::uuid, 'the_layover'::show_name, 1, 'Weird macaroni tomato egg dish; silk stocking tea', NULL, 'Season 1'),
  ('60e5f1e9-fa36-51db-8f7e-03630752eeb9'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Eric ate at this sichuan restaurant, and Eric said the spice was "challenging" They had pickled chicken feet, la zi ji (spicy chicken), mapo tofu (Tony''s favorite), tong jiao yu (Sichuan green-peppercorn fish)', 'Season 8'),
  ('60ef2250-b323-5479-8de1-b5bd5e9342ea'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony visited during this Buddhist event that marks the end of Buddhist lent. There is a fire lantern festival, the symbolic casting away of one''s sins. Tony watched a boat race on the Mekong River.', 'Season 9'),
  ('611a6178-428b-5af3-8c1b-b3bafc86cc2f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Seafood Restaurant on the beach. Fried, Steamed, Brown Stew, or Festival Style.', 'Restaurants and Bars'),
  ('61217214-2758-5fe0-9d75-0ff18e0d9bf2'::uuid, 'parts_unknown'::show_name, 7, NULL, '"One of the city''s older, more traditional joints" Tony said. Tony and Zamir are both hungover from the previous evening''s shenanigans. They had a hangover cure, khashi which Zamir explained is made of beef broth from bones and joints. Tony did not think it worked. He did enjoy the chashushuli, "a stew of slow-cooked veal with onion and tomato, heavily seasoned with coriander, fennel, garlic, and chilies."', 'Season 7'),
  ('61305d6d-8789-5472-b21e-98f7c1a388e0'::uuid, 'the_layover'::show_name, 1, 'Beer', NULL, 'Season 1'),
  ('61321ac7-fbda-594f-905e-1d56b15478bc'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony and Zamir went to this strip club after they lost money at gambling.', 'Season 7'),
  ('61485a1b-2b2f-5604-aa79-7aee8ab49e1d'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had sushi with Hugo Cancio, a Cuban born entrepreneur', 'Season 6'),
  ('614bf31c-f119-58d3-a2f2-9ae72631cf7a'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony tried a local drink called Gammel Dansk (Danish bitters)', 'Season 2'),
  ('61528f0d-f3a7-59a4-b890-d68ecc724a70'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with former bouncer defense expert Mark Davies at his close combat knife defense center', 'Season 5'),
  ('6165da67-6373-567e-a476-bf05c20a3d2c'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony and Xabier had Rock prawn (head and body cooked separately—head grilled and body served semi-ceviche), grilled squid with onion-green pepper sauce, cocochas (hake fish jowls or chins), and grilled turbot (this is the dish people travel to this restaurant to try)', 'Season 9'),
  ('61749313-51e6-5ebb-a977-103a7686a1b7'::uuid, 'the_layover'::show_name, 2, 'Architecture', NULL, 'Season 2'),
  ('61a0d7d9-abe4-5d69-824c-5d3e3123bc6b'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony ate with a group. They had lots of oysters; flash-fried whole local smelt served with pepperoncini sambal aioli; local dungeness crab, chilled and cooked with pickled ginger sauce.', 'Season 10'),
  ('61b57f01-b1ed-507b-96cf-3cbc23b5002d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony''s guide Carlos lives in the Azores and his wife makes a Portuguese feast called Terresmos de vinha de alhos, "basically a panorama of delicious pork products, blood sausage, boiled sweet potatoes, and red peppers', 'Other Activities'),
  ('61c0ff78-b4d0-53b4-97fa-ed320a4d92a8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tamale dogs with various spicy toppings. Also a drink called The Suicide.', 'Restaurants and Bars'),
  ('61ca965f-907a-58bd-872e-99c9eb893a57'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a meal with Sadir Varaket, Melanie Chan, and Tanya Andoor. They had fried oyster omelets and fried prawns with chili paste; bak chor mi, a fish ball noodle soup; and beef satay.', 'Season 10'),
  ('620d8179-8e24-5f98-a21c-d96a576f377f'::uuid, 'the_layover'::show_name, 1, 'Meat Pies', NULL, 'Season 1'),
  ('6217b3f5-bd62-591b-b0af-b18cdb983b3f'::uuid, 'the_layover'::show_name, 2, NULL, 'Catch your own shrimp and they cook it for you', 'Season 2'),
  ('622caa29-299f-5cfa-9023-ebd6b6b1b99d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'He makes Beecher''s Flagship Cheese and sells others', 'Food markets'),
  ('62315ffc-2e2f-5afe-bc7e-878958e532ec'::uuid, 'the_layover'::show_name, 1, 'Award winning chowders at the airport', NULL, 'Season 1'),
  ('629b69b2-1e67-5022-9c2a-707dd7b49bc2'::uuid, 'the_layover'::show_name, 1, 'Seafood', NULL, 'Season 1'),
  ('62be5abf-b63e-50f1-8d5e-c7fd40fe4775'::uuid, 'no_reservations'::show_name, NULL, 'Chesapeake Bay crabs', NULL, 'Restaurants and Bars'),
  ('62de11df-9441-5025-85c5-d7d477d43c55'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a homecooked meal with Carlos'' huge family. Homemade everything, with Tony''s favorites being the tamales and the mole poblano.', 'Sightseeing'),
  ('62e39231-282a-5025-8fa4-0bf612194093'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony bought a Frito Pie and a soda', 'Season 2'),
  ('630242ee-434b-5477-96ca-1af6b105b9a7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited a home here where he was served many authentic Sri Lankan dishes, including the spiciest dish in Sri Lanka, crab curry', 'Other Activities'),
  ('63156314-fe09-5da0-b44a-e76b71eb2632'::uuid, 'the_layover'::show_name, 1, 'Seattle style hot dog. Has cream cheese for some reason.', NULL, 'Season 1'),
  ('6334853f-23ca-59a6-953a-40a2ae8151c3'::uuid, 'no_reservations'::show_name, NULL, NULL, '"Sushi is first about the rice." Chef Yasuda had been doing it for 32 years at the filming of this episode.', 'Restaurants and Bars'),
  ('6334853f-23ca-59a6-953a-40a2ae8151c3'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony gives his sushi recommendations. Yasuda or Masa.', 'Season 1'),
  ('6337c6cb-78d2-5e94-a885-33f790d9e22c'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony had a meal with artist Anthony Bondi at this breakfast and lunch spot.', 'Season 3'),
  ('6358e6dc-bafe-508f-86d8-95c63a74fd4d'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony ate health food with his punk hero Iggy Pop', 'Season 5'),
  ('639c75c2-2575-550f-a1db-846d688aad24'::uuid, 'the_layover'::show_name, 1, 'Wontons, noodles', NULL, 'Season 1'),
  ('63b12209-d665-54c7-9f8c-3bfb61775494'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met with Alexander Lebedev, businessman and owner of opposition newspaper Novaya Gazeta, at his home. They had fresh potato chips and Scottish salmon with cherry-tree sawdust.', 'Season 3'),
  ('63e6f7a3-bef1-53ae-96a5-c78de8db0e26'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A man-made island made of conch shells with a bar and cocktails', 'Restaurants and Bars'),
  ('641c8fa6-66d4-5ce5-9ecc-266a5abf7813'::uuid, 'the_layover'::show_name, 2, NULL, 'Tony recommended the Black Hoof, but the restaurant is closed now. This is the chef''s new restaurant', 'Season 2'),
  ('642a0164-2192-5ccb-9138-8c4e8035eddd'::uuid, 'parts_unknown'::show_name, 5, NULL, 'A market in Little Haiti with a 4-seat cafe selling cow foot soup.', 'Season 5'),
  ('6461ffaf-f2f3-56f3-8ea7-bf0081365a8e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony was invited to a neighborhood birthday party here where he had sancocho, a stew with chicken, beef, yucca, plantains, sliced avocado.', 'Other Activities'),
  ('64711630-e42a-57d3-9ce0-a364f56f790a'::uuid, 'the_layover'::show_name, 1, 'Indian food. Spices are ground fresh here.', NULL, 'Season 1'),
  ('647d9800-24e5-5904-8e51-6c4c9264335c'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony ate worms and ant eggs. Would not do it again.', 'Disc 2: Mexico and The Americas'),
  ('64c3abc5-9fb4-5e22-bc0c-f66431703cdb'::uuid, 'a_cooks_tour'::show_name, NULL, 'Live jazz bar', NULL, 'Disc 1: United States'),
  ('64cbf6cc-1db4-5486-b6d4-ce6890d0ff6c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a pork stew and listened to folk music', 'Restaurants and Bars'),
  ('64d38cef-f615-535a-b4f6-a585e74cbfbb'::uuid, 'the_layover'::show_name, 2, 'Laidback area with great restaurants.', NULL, 'Season 2'),
  ('64e80327-a18a-5a0f-8677-b0ee08265bc7'::uuid, 'no_reservations'::show_name, NULL, 'Large food market', NULL, 'Food markets'),
  ('64ecece9-50ae-5490-a376-416146c486f3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Jackie Chan''s stunt team helped Tony learn some martial arts stunts. Then they ate Poon Choi: a large bowl layered with vegetables, prawns, fish, mushrooms, pork, and chicken. A thousand year old dish', 'Other Activities'),
  ('65178aa4-ee41-5599-aa3a-9b0713df6c2f'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony ate Iberico ham and bean soup with roasted garlic; nitro almond cup, a frozen shell made from a puree of Marcona almonds, filled with almond milk espuma and finished with Andalusian caviar; mussels, olives with an escabeche “air;” truffle egg, a gelee of truffles formed into an egg shape with an actual yolk suspended in the center; crispy chicken skin escabeche; salt-roasted foie gras and clementine sauce; secreto de cerdo en papillote.', 'Season 3'),
  ('6521005e-5eb9-5e4f-8ff0-2deac832962d'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony had the deluxe: sausage made with bacon and garlic, homemade mustard, onions pickled in beer.', 'Season 2'),
  ('653513b6-c2b7-50ee-86fc-0e5da2256b72'::uuid, 'no_reservations'::show_name, NULL, 'Restaurant with local seasonal ingredients, and a hotel', NULL, 'Restaurants and Bars'),
  ('6547423f-c8b0-52ed-a77e-aab6f4c49e42'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Naxos style pork called rosto in a small village in the mountains.', 'Season 7'),
  ('6560c752-9292-5057-8f23-3761e420348f'::uuid, 'the_layover'::show_name, 1, NULL, 'Fred Morin and Dave McMillan''s restaurant (Tony''s good friends)', 'Season 1'),
  ('65881a00-05fe-51e6-a023-461a052ffd82'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, NULL, 'Disc 2: Mexico and The Americas'),
  ('659372e2-999c-5d3b-a0cc-2814f8086405'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This used to be TB''s Bar & Grill, where Tony had chips & salsa and beer', 'Restaurants and Bars'),
  ('65a39eb2-2542-5d6e-ae01-b53bc1021547'::uuid, 'the_layover'::show_name, 1, NULL, 'Changi Village Hawker Centre, this food stall has egg, chicken or fish and rice, sambal, coconut rice.', 'Season 1'),
  ('664afebd-4948-5e12-ab96-a6fb5c496a02'::uuid, 'the_layover'::show_name, 1, 'Seafood stew, roasted lobster, cioppino', NULL, 'Season 1'),
  ('668b24e2-dda1-502c-969e-7709e4dc74a2'::uuid, 'the_layover'::show_name, 2, NULL, 'More affordable option; rooftop lounge, underground performance space, good food', 'Season 2'),
  ('66946a4f-6146-5707-920f-89772dbb559e'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had a meal with some locals: oxtail soup; stewed liver and heart with tomato, onions, and fresh herbs; sheep’s head.', 'Season 11'),
  ('66961ff6-bd09-5018-bc66-f4ec5c6e05ff'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony was not a fan of the hot spring he said smelled "like a wet fart"', 'Other Activities'),
  ('66d9773d-8d46-5e1c-8cab-3bd811a24ede'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Best meat pies. Tony said this is a must visit whenever in Sydney', 'Disc 5: Australia and Japan'),
  ('66db8484-3e42-5a39-83cf-7a3671a4a7e8'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony and Andy Ricker visited this small but popular restaurant. They had grilled pig tail, Northern Thai herbal pork sausage, pig''s brain, and pig''s blood soup.', 'Season 3'),
  ('66f94b9e-4410-5294-a38a-ee865d933af5'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had lunch with Toby Rodriguez and Marc Savoy, a musician and Cajun-style accordion builder, and his family. They had whiskey, gumbo, and beer.', 'Season 11'),
  ('67073219-970c-525e-b0f8-04854454017b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Known for their pork leg (pernil). A drink called the tornado has wine and frozen pineapple juice', 'Restaurants and Bars'),
  ('676eeef4-a24c-5a5f-9a60-cddcd573e971'::uuid, 'the_layover'::show_name, 1, 'Also called New Discovery, cheap beer and a great view', NULL, 'Season 1'),
  ('67919aa3-d9a3-5e26-b9d4-624d6156d7f2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went to the Hall of Fame with Tommy, the drummer from his favorite band, The Ramones', 'Sightseeing'),
  ('67fc516c-fce9-5620-bc10-88ae67745dc9'::uuid, 'parts_unknown'::show_name, 1, NULL, 'The plane landed here in Miraflores, a jungle outpost in the southern province of Guaviare in the Amazon Forest Preserve. Tony talked with a guide there about the cocaine trade of the past.', 'Season 1'),
  ('6811da74-7238-58a8-add6-a4753165c342'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a heavy breakfast here although he was feeling very ill. Sambal and chili, rice.', 'Restaurants and Bars'),
  ('681b1652-f367-5cd4-8ed0-a2fe44a44e58'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Gorgeous seaside restaurant. Tony had beers, grilled shrimp, conch and cuttlefish salad', 'Restaurants and Bars'),
  ('68316809-1695-53ac-85fb-6700fefccfaa'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony won $3,000 at the Baccarat tables in the casino', 'Other Activities'),
  ('6858451d-12fc-5093-bbe9-59903bc47b71'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Food market, founded 100+ years ago. Staggering abundance of local produce, meat, fish', 'Food markets'),
  ('6899660b-b3f5-50f2-a5d8-39248e5ffcd9'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Sprawling indoor market of produce, meat, fish, dairy. Tony and his chef friend Paul ate bratwurst for breakfast', 'Food markets'),
  ('689c2b4f-82a3-5d49-8398-7d795ad4c78b'::uuid, 'no_reservations'::show_name, NULL, 'Roast duck', NULL, 'Restaurants and Bars'),
  ('68c5a421-6997-5c39-883b-5b1854eb9737'::uuid, 'the_layover'::show_name, 1, NULL, 'Dutch baby. Cross between a souffle and a pancake. Crispy on outside, soft in the middle', 'Season 1'),
  ('68ec70cb-3f39-57b4-8bdc-3743c766c20c'::uuid, 'no_reservations'::show_name, NULL, '"Fountain of shame"', NULL, 'Sightseeing'),
  ('68f7235c-5afe-58d2-b294-4c4045bf655c'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Lodging'),
  ('68f7235c-5afe-58d2-b294-4c4045bf655c'::uuid, 'the_layover'::show_name, 1, NULL, 'This is where Tony stayed when he visited Miami', 'Season 1'),
  ('69036360-cba6-5bb7-b6fd-16fa14bba408'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a meal here with the chef.', 'Season 10'),
  ('6942abe6-139d-5226-9461-d3695da225dd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony''s friend Nico invited him to eat at his family home in Marina di Pisa. They cooked a bunch of fresh seafood.', 'Other Activities'),
  ('695177de-bce3-50d9-8eeb-552adf37aa8a'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony said it had always been his dream to eat here. Paul Bocuse is considered the father of modern French cuisine. They ate soupe aux truffes noires V.G.E. (black-truffle soup named after former French President Valéry Giscard d’Estaing); loup en croûte feuilletée (sea bass in pastry crust); choron (béarnaise or hollandaise sauce made with tomato purée); pot-au-feu (French beef stew); lièvre à la royale (roasted hare).', 'Season 3'),
  ('69528e89-b95e-5a81-9201-8bc939f26ab9'::uuid, 'the_layover'::show_name, 1, 'Food trucks!', NULL, 'Season 1'),
  ('695d65d1-a2da-557e-969f-1ecffd187340'::uuid, 'no_reservations'::show_name, NULL, 'Steakhouse heaven. And more martinis.', NULL, 'Restaurants and Bars'),
  ('69707fa3-0a68-503b-b7b6-624c2566c697'::uuid, 'a_cooks_tour'::show_name, NULL, 'Fancy. But amazing.', NULL, 'Disc 5: Australia and Japan'),
  ('69c86780-7460-583b-b69c-4fbb2af19d98'::uuid, 'no_reservations'::show_name, NULL, 'So much offal', NULL, 'Restaurants and Bars'),
  ('69f58f7a-3b8f-530c-bf59-1f3dbaa2188f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony lost money betting on horses here', 'Other Activities'),
  ('6a0e7a96-f30b-5f88-b6b1-13b6ff6b6ad3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Grilled pit beef with tiger sauce (horseradish mayo) served on rye or a kaiser roll.', 'Restaurants and Bars'),
  ('6a3dd8b4-05be-5bc8-931c-b5d2193aea82'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited this favela where he was tricked into trying a "natural Viagra" by his guide.', 'Food markets'),
  ('6a472dcb-0c58-5afa-9851-4ed72fff9e8b'::uuid, 'no_reservations'::show_name, NULL, 'Seafood', NULL, 'Restaurants and Bars'),
  ('6a599d7d-75a6-5002-b073-0a0a7590c2d3'::uuid, 'no_reservations'::show_name, NULL, 'Local wines and petiscos (Portuguese tapas)', NULL, 'Restaurants and Bars'),
  ('6a64c342-1a8d-5390-b142-bbf5e3498f12'::uuid, 'no_reservations'::show_name, NULL, 'Former site of Incanto, Chris Cosentino''s restaurant', NULL, 'Restaurants and Bars'),
  ('6a7ffb91-a085-5702-beeb-6544c8321ac1'::uuid, 'no_reservations'::show_name, NULL, 'Maple bacon donut bar; chocolate, oreos, and peanut butter', NULL, 'Restaurants and Bars'),
  ('6ab5d11e-8c8e-50d6-86a4-551af370f50c'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony called this the "Sikh equivalent of the Vatican." He attended a festival called a gurpurab where feet are cleansed and people of all religions all take part in a simple meal', 'Season 3'),
  ('6b034d58-8016-57e7-b8ec-9fcc0697b96e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Completo hot dog: a 12 inch hot dog covered with sauerkraut, tomatoes, guacamole, topped with mayo.', 'Restaurants and Bars'),
  ('6b25d15b-be22-55c1-bb4a-5c154aea5f8a'::uuid, 'parts_unknown'::show_name, 2, NULL, 'The second oldest amusement park in the world. Tony and Rene visited and rode on the ferris wheel.', 'Season 2'),
  ('6b5a8f5c-732d-59f8-8e20-14b286565214'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Palestinian children from the Aida Refugee Camp participate in a theater production here', 'Season 2'),
  ('6b97f3e0-92bb-5263-92ff-f098a2ea8ecf'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and Kamau met with Masai chief Jonathan Kip and Masai elder Lela Kinyaga to have a meal in a Masai village. They had cow’s blood mixed with milk, grilled meat, and rice.', 'Season 12'),
  ('6ba0a549-beaa-5ff2-8ecb-5327718f9270'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Lebanese food. Lamb brains, softshell prawns. Tony''s favorite thing he ate in Melbourne: barbecue quail and lamb ribs. He liked the quail so much he ordered a second plate.', 'Restaurants and Bars'),
  ('6bc68072-c687-5876-aba4-cf4025dbb76f'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony tried yak hide sautéed with garlic, tomato, and peppercorns with Darren Aronofsky and environmentalist Dasho Benji Dorji', 'Season 11'),
  ('6bd39ce1-820b-5693-94b2-f6e9cf68120c'::uuid, 'no_reservations'::show_name, NULL, 'Lots of food stands with lots of parillas (grilled meats)', NULL, 'Food markets'),
  ('6c32386b-dd7f-52c5-9e71-20bf55177e79'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony and Andy both got sak yant tattoos (traditional Thai tattoos)', 'Season 3'),
  ('6c45b7ed-3c4a-5a97-b7fb-8a4ed1b5a858'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This used to be Chadwicks, where Tony had beers and burgers with a former US spy', 'Restaurants and Bars'),
  ('6c48fc45-c551-5f1a-bc77-24dec9fb75e5'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Somewhere in Tripoli, Tony ate at a place called Uncle Kentucky (or Kentaki) Fried Chicken. Could not find it on any maps.', 'Season 1'),
  ('6c4c4adc-1f8a-594b-8084-b3f10640c8fb'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony bought cowboy boots here', 'Other Activities'),
  ('6c91e8fe-76a5-5858-9861-70e364362f12'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony had some Guinness.', 'Season 8'),
  ('6cb6a9d3-b7a4-5222-9c7f-4ebd1d75d03f'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Breakfast. Tony ate the smoked sturgeon platter.', 'Disc 1: United States'),
  ('6cb6a9d3-b7a4-5222-9c7f-4ebd1d75d03f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a platter delivered with Nova Scotia salmon, whitefish salad, smoked sturgeon, capers, and assorted fixings.', 'Restaurants and Bars'),
  ('6cbe1623-a6a6-5061-b314-e712718c930e'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had dinner with the comedian couple. He ate spaghetti with meatballs. Tony says he is not a fan of Trump and says he looks ridiculous.', 'Season 5'),
  ('6cc44719-83cb-5a22-840e-b87353294826'::uuid, 'no_reservations'::show_name, NULL, 'Former site of Boulud''s fresh sausage place, DBGB', NULL, 'Restaurants and Bars'),
  ('6d825c32-10fe-5b11-9216-738492d40236'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony and DJ Les had fried chicken, greens, mieliepap, beets, and coleslaw.', 'Season 2'),
  ('6e273de4-6202-589f-af15-84ea1174e057'::uuid, 'parts_unknown'::show_name, 6, NULL, 'A mini market. Tony is obsessed with the egg salad sandwich. In the behind the scenes episode in season 12, the crew explained that the location they shot at ran out of egg salad sandwiches and there was a mad rush to find one at nearby Lawson stores.', 'Season 6'),
  ('6e48676b-abc0-5916-adb5-4244c90b1432'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Creole tasting plate , seafood andouille gumbo, country fried chicken with cassoulet', 'Restaurants and Bars'),
  ('6e6496bf-62c8-572e-947d-2dbd66076a78'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had drinks with Hermes Ayala, freelance journalist for outlets including Vice and HuffPost; Laura Moscoso, journalist specializing in data visualization and multimedia.', 'Season 10'),
  ('6e6b01e6-4db3-539d-9d5a-1a599bc1ad40'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had a fish coconut stew in this park.', 'Season 4'),
  ('6e82f730-57ec-53e6-aa71-6ccd4627aee5'::uuid, 'no_reservations'::show_name, NULL, 'BBQ catfish, burnt ends', NULL, 'Restaurants and Bars'),
  ('6ea1c1f3-c509-516d-a78c-b8677ec05dee'::uuid, 'the_layover'::show_name, 2, 'Meats, cheeses', NULL, 'Season 2'),
  ('6ec28db2-8e6d-5faf-bfbe-90656da4b455'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Seafood. Tony ate a dish with turtle and turtle eggs, coconut milk, garlic, rosemary', 'Restaurants and Bars'),
  ('6ec99fbc-51d0-59cf-90ce-d173d8971ac9'::uuid, 'the_layover'::show_name, 2, 'Rock shows', NULL, 'Season 2'),
  ('6ef04062-5fac-5c26-81bc-6b60733bf3a0'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('6f08909e-96b2-5b2e-8509-ff8fe19ed0e8'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Iconic dish of Punjab. "A perfect little flavor bomb of wheat dough pressed against the side of a very, very hot clay oven, slathered with butter and served with a chickpea curry on the side."', 'Season 3'),
  ('6f2b1e61-d599-5d30-b058-d8c03be8c7dc'::uuid, 'no_reservations'::show_name, NULL, 'Old Red Hook bar.', NULL, 'Restaurants and Bars'),
  ('6f3c8d51-2a93-50da-a733-b1ecc45d8749'::uuid, 'no_reservations'::show_name, NULL, 'French dips', NULL, 'Restaurants and Bars'),
  ('6f3c8d51-2a93-50da-a733-b1ecc45d8749'::uuid, 'the_layover'::show_name, 1, 'French dip, cake donuts. Cafeteria style restaurant', NULL, 'Season 1'),
  ('6fa1b7d7-ab03-5d93-a352-9c5e65da9bee'::uuid, 'a_cooks_tour'::show_name, NULL, '"A candy colored nightmare"', NULL, 'Disc 1: United States'),
  ('6faf061e-09a7-5ce7-aa9b-7a6bfcac5faa'::uuid, 'the_layover'::show_name, 1, 'Mediterranean dishes using fresh, local ingredients', NULL, 'Season 1'),
  ('6fc212b9-99af-56d5-ae06-22c6c3bce8f1'::uuid, 'no_reservations'::show_name, NULL, 'Simple classics done well.', NULL, 'Restaurants and Bars'),
  ('6fca4199-de3b-5ed6-94d2-556a75190b45'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Specialty is roast chicken in orange sauce with rice and black beans', 'Restaurants and Bars'),
  ('70363a75-00b2-5251-bda6-4d93b27d6864'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Sustainable restaurant using ingredients grown/raised on site. The chef trained at Mugaritz, a world-class restaurant in the Basques.', 'Restaurants and Bars'),
  ('7056f197-a6d9-58a1-98fb-7826afaf1425'::uuid, 'a_cooks_tour'::show_name, NULL, 'Gaufre waffles', NULL, 'Disc 3: Europe'),
  ('70893b54-0d01-520a-bc3c-8f782fff4fdd'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony ate here with Bobby Seale, co-founder of the Black Panther Party. They ate skillet-fried chicken, rice and peas, greens', 'Season 6'),
  ('709d7b23-d139-504d-9458-3c2a76bbe32e'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony had the special salad with Italian vinaigrette, steak, shrimp, onion rings, and pompano (a huge Delta fish).', 'Season 3'),
  ('70a9016d-163a-58bf-9e27-bad5fbb3f22f'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('70b4c122-d7f2-5dd1-b2cd-0127d0a830e3'::uuid, 'no_reservations'::show_name, NULL, 'Guinness and meat pies', NULL, 'Restaurants and Bars'),
  ('70ca0ab1-1b64-57c1-9f7d-0fba0d881802'::uuid, 'no_reservations'::show_name, NULL, 'Meat shop selling offal.', NULL, 'Food markets'),
  ('70d22346-45f1-5461-b860-985aae34dcd3'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony and friends ate a feast of empanadas with corn and shredded, slow-cooked beef; goat cheese and spinach croquettes; fried fish; provoleta (bubbling cheese that “puffs up and inflates on the plate”); whole roasted suckling wild boar; whole roasted fish; beef milanesa covered in tomato sauce, ham, and shredded cheese.', 'Season 11'),
  ('7140a94f-ffc3-5055-bdcb-62fe2da8b5ef'::uuid, 'the_layover'::show_name, 2, 'Traditional fine dining (michelin star)', NULL, 'Season 2'),
  ('7151116b-9561-500f-a230-84bbad06cf3f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Late night dish called kottu roti. It is made of diced veggies, eggs, curry sauce, and chopped roti chopped together.', 'Restaurants and Bars'),
  ('7169dc86-95bf-557e-adb8-4fc630709b3f'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and Kamau visited this conservancy to view the animals. They saw a giraffe, termite mounds, zebras, an ostrich, an elephant, a rhino, and some lions. They then had a breakfast of scrambled eggs and toast with Mike Watson, CEO of the conservancy; Faith Riunga, education officer of the conservancy; Wanjiku Kinuthia, communications officer of the conservancy; Tom Lalampaa, CEO of Northern Rangelands Trust', 'Season 12'),
  ('71878a1f-b2ad-5382-ba83-071b64359be5'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('71cd984b-329b-5d2c-806f-fc7d0b405d6c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a huge fish taco, oysters, crack pie, and beer.', 'Restaurants and Bars'),
  ('71e2df86-5029-541a-b681-4c2023d6e1e8'::uuid, 'a_cooks_tour'::show_name, NULL, 'Fresh produce', NULL, 'Disc 1: United States'),
  ('71e32741-445e-5791-b30d-d504ee94b159'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony and a group of chefs had fried bologna which Tony called "awesome," fried clam strips, liver and onions, pan-fried cod tongues, Jiggs dinner, french fries.', 'Season 11'),
  ('71ef0247-1782-519c-baa6-9685ab830fb7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Location of the Sausage Shoppe. Permanently closed in 2018 (the owners retired), Tony visited to watch them make sausage', 'Food markets'),
  ('72528244-b8ef-5949-b5f5-4f198386ff26'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A man named Kushil opened up his home after the flooding from the tsunami and this evolved into an entire network of services including a medical center, a preschool, a business & services center, and recreational facilities free for everyone to use. They also feed Tony red rice, yellow lentil curry, claypot simmered tuna, jackfruit curry, and coconut sambal during the visit', 'Other Activities'),
  ('7256767d-247b-5fcf-a380-3da100593e46'::uuid, 'parts_unknown'::show_name, 4, 'The second largest public square in the world', NULL, 'Season 4'),
  ('7262f61b-d910-56af-8e16-7a13d00d9417'::uuid, 'parts_unknown'::show_name, 8, NULL, '20-seat restaurant with a menu that changes nightly. They ate risotto with sunflower seeds instead of rice, topped with fermented sunchokes and garnished with sunflower sprouts; linguini with sea urchin and chili flakes, made with Japanese ingredients—wakame bucatini, yuzukoshō to represent the chili flakes, scallops dried and smoked and grated over the top; macaron and cookie.', 'Season 8'),
  ('7266c789-7e71-5d0b-84f8-290e894efdf3'::uuid, 'no_reservations'::show_name, NULL, 'Night food market with lots of street food', NULL, 'Restaurants and Bars'),
  ('7277f153-2508-5719-8757-f906ae0b6253'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Restaurant serving tagine. Tony had fresh olives; roasted walnuts; warm bread; tagine with baby shark, calamari, and monkfish with fresh mountain spinach; shark kebabs; strawberries, pine nuts, and honey', 'Season 1'),
  ('728cc276-3da0-5dcc-9587-c958960e89ba'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had a Jersey sandwich with sliced ham, salami, pepperoni, provolone, tomato, onions, shredded lettuce, roasted peppers, and oil & vinegar.', 'Season 5'),
  ('729dac0c-0f9f-56af-bd17-984b84624b6a'::uuid, 'the_layover'::show_name, 2, 'Swing bands and jazz bands', NULL, 'Season 2'),
  ('72b6b5d1-ea8f-594d-9514-b4fd27562fbb'::uuid, 'the_layover'::show_name, 1, NULL, 'Haitian food. Specialty is Griot which is a fried pork shoulder served with sweet plantains and salad.', 'Season 1'),
  ('72c52073-eab0-5905-9384-5c1fbeeba58f'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had bún bò Huế (bone broth with lemongrass), fermented shrimp paste with rice noodles, tender beef shank, crabmeat dumplings, pig’s foot; huyết (blood cake)', 'Season 4'),
  ('730d3eff-6e5a-5c7c-87e9-76ada51fa220'::uuid, 'the_layover'::show_name, 2, 'Arais sandwiches', NULL, 'Season 2'),
  ('731e6d40-ce3f-5853-b604-96ef5ab02a07'::uuid, 'the_layover'::show_name, 2, 'Cakes, fruit, jams, breads', NULL, 'Season 2'),
  ('7341ba41-61ba-5718-8ab6-809016224dc8'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had pig-tail soup and rum drinks.', 'Season 4'),
  ('73eb7da6-28dd-5756-8511-affdbe1b87e1'::uuid, 'no_reservations'::show_name, NULL, 'Pickled veggies', NULL, 'Food markets'),
  ('73ec11d1-74a2-5eaa-bfc1-e942a1565e9f'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, NULL, 'Disc 4: Morocco & Russia'),
  ('7405dc75-9ed6-5445-8956-5e39e1f4f446'::uuid, 'the_layover'::show_name, 2, NULL, 'Freshly caught shrimp and crabs. The place Tony ate at got flooded in a hurricane. This is the closest thing.', 'Season 2'),
  ('740a8f5d-fded-5f0a-85db-239b6959f356'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony bought a cleaver here. The neighborhood is a restaurant supply area.', 'Season 1'),
  ('741cb586-7375-5ff3-91ca-a7016c5a1d58'::uuid, 'no_reservations'::show_name, NULL, 'Yakitori, or Japanese BBQ, mostly chicken.', NULL, 'Restaurants and Bars'),
  ('74274903-4027-53b0-8c02-a7d9da046e09'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony came to this soccer club to drink beer and eat chorizo with Chef Soledad Nardelli, and watch kitchen staff of 2 rival restaurants play soccer at 1 am', 'Season 7'),
  ('7458cc7b-61a5-57cc-81ec-ba754ffeaae1'::uuid, 'no_reservations'::show_name, NULL, 'Classic Russian restaurant. With vodka.', NULL, 'Restaurants and Bars'),
  ('7467e2c9-a1ab-5fda-a61a-23d9c7b0b204'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had a carne asada burrito with activist Sandro Canovas', 'Season 12'),
  ('7478937d-4648-5977-b18a-9bf18a357a29'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Big pot of soup that you add things to: shrimp, chicken, veggies. This is what sumo fighters eat.', 'Disc 5: Australia and Japan'),
  ('749166b5-38cb-5333-9cb5-f9321ef818fc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went to the Kris Kringle market in front of the palace. He had a spezialpunsch and goulash from a stand called Wiener Spiralkartoffel', 'Restaurants and Bars'),
  ('74b86975-d3b3-55d1-9840-9ca540e6c3be'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony came here to eat his favorite Filipino street food, which he describes as "possibly the best thing you can ever eat with a cold beer." The dish he is talking about is sisig, a sizzling dish of pig face with a runny egg on top.', 'Season 7'),
  ('74d5adb9-61d4-560e-a4f6-ee5d14ad5b24'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Former site of Kihachi, a Japanese restaurant by retired chef Mike Kimura.', 'Restaurants and Bars'),
  ('74d5d1b8-dbe1-5da9-8721-d5fff9a99fb4'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony, along with chefs Fred Morin and David McMillian, traveled by train to Quebec City. The chefs brought along a gourmet meal including foie gras and truffles.', 'Season 1'),
  ('74d94703-8f75-5b19-81cd-6e3f85ba9f9f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited artists making art in the Tent City, as well as a mass grave that was created after the earthquake. He also met up with actor Sean Penn, who is doing humanitarian work while living in a tent there. They ate chicken pies filled with spicy chicken, picklese, and tomato and deep fried.', 'Other Activities'),
  ('74dbd21f-2371-5b7e-83bf-2bfaeb8a8f02'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Delicious banh mi with liver pate, cucumbers, fresh basil, and a crispy fried egg', 'Restaurants and Bars'),
  ('74f789f8-3ab2-5f88-bd20-b530add18fef'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Fishermen bar. They also ate Wellfleet oysters.', 'Season 4'),
  ('74f9a583-bb9b-5647-84ff-0b5b3d986504'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met Andy Ricker (Pok Pok restaurants) in a small village in this region.', 'Season 3'),
  ('7508c1be-acea-5a62-a9a8-6747156897c2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited a farm where he fed a baby lamb by bottle.', 'Restaurants and Bars'),
  ('7544e418-32b3-590b-89eb-8c953d4f9384'::uuid, 'no_reservations'::show_name, NULL, 'Active volcano!', NULL, 'Sightseeing'),
  ('75642a31-1424-5715-aebd-d0c754d759d9'::uuid, 'no_reservations'::show_name, NULL, 'Fresh fish, outdoor produce market', NULL, 'Food markets'),
  ('757078e6-793e-57e6-822d-5830826d1981'::uuid, 'the_layover'::show_name, 2, 'Local ingredients', NULL, 'Season 2'),
  ('757ab81b-544f-5245-a8dc-2d2c4f6d726b'::uuid, 'the_layover'::show_name, 1, 'Tacos and burritos. The chorizo breakfast burrito is special', NULL, 'Season 1'),
  ('757c09b0-ae16-5c9a-8837-359287c5095a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Meat, meat, and more meat. Tony and Ottavia ate at this churrascaria.', 'Restaurants and Bars'),
  ('75b816fd-ec94-56bd-ada7-ee3adad2ae3a'::uuid, 'the_layover'::show_name, 2, 'Breakfast dishes, crepes, cakes', NULL, 'Season 2'),
  ('7602756f-43ea-5aed-a4d9-a94b01e50dc3'::uuid, 'the_layover'::show_name, 2, 'Retro diner with eggs and hashbrowns', NULL, 'Season 2'),
  ('760b3077-6284-5e1d-a672-6aeebd235d3a'::uuid, 'parts_unknown'::show_name, 7, 'New site of chef Tekuna Gachechiladze''s restaurant.', NULL, 'Season 7'),
  ('76216db1-2ed0-5e13-92a6-5869623e56ba'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony took a bus through the desert out to Jaisalmer, a walled city known as The Golden City. Was a major trade route point in the past', 'Other Activities'),
  ('76376af6-2383-5ce8-843c-eb24d2cec689'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony met with a band called On the Tropica to play tejo, a game involving "alcohol and explosives." They also ate a Colombian picada, "a huge selection of fried pork, pork rib, steak, cassava, potatoes, and deep fried plantain."', 'Season 1'),
  ('7672b511-c9b0-584e-a8ea-2d40032329f6'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'He called the pastrami burrito dog "strange" and said it shattered his newly found appreciation of California', 'Disc 1: United States'),
  ('76771a95-f86f-5bcb-8fd1-5877d6158059'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Ultra exclusive 18-seat restaurant. 3 Michelin stars. 26 courses.', 'Restaurants and Bars'),
  ('769cf859-41cd-5916-ba74-1f1129e4e25c'::uuid, 'no_reservations'::show_name, NULL, 'Stew with lots of offal', NULL, 'Restaurants and Bars'),
  ('76b630ed-75f6-51d9-a5c1-49c0160b2903'::uuid, 'parts_unknown'::show_name, 3, NULL, 'The home of writer William Faulkner. Tony visited this house with Jack Pendarvis (animated series creator of Adventure Time).', 'Season 3'),
  ('76fb4a25-0394-5b54-82c7-995dacb9e521'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met with a journalist here where Congress meets.', 'Sightseeing'),
  ('7710be08-845d-5e3e-828d-5ca53bdfdcc9'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate at a restaurant called Elitsa Rini. Could not find it so I guess it closed', 'Restaurants and Bars'),
  ('7717ea0a-55ee-50ec-9d82-ada04c47098b'::uuid, 'the_layover'::show_name, 1, 'Art gallery', NULL, 'Season 1'),
  ('77206576-72a5-5579-b09e-345ddc6b21a3'::uuid, 'the_layover'::show_name, 2, 'A hostel', NULL, 'Season 2'),
  ('773fd4c5-3d1d-5957-903b-ea175e110e23'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Beach restaurant where Tony and his brother ate fire roasted prawns and sauteed octopus', 'Restaurants and Bars'),
  ('773fd4c5-3d1d-5957-903b-ea175e110e23'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony ate with the owners of this place. They had whole fish baked in salt, rib-eye steak, flank steak, suckling pig.', 'Season 11'),
  ('77baac79-c0fb-5b5f-84b0-7fdeb3a608b8'::uuid, 'parts_unknown'::show_name, 1, NULL, 'The restaurant name means "Everything''s Cool" in local slang. They had razor clams, a cream of haddock roe, Coqui St. Jacques, terrine of foie gras, head cheese with cassis mustard, truffled sweetbreads, goose hearts persillade, salt cod.', 'Season 1'),
  ('77c9d3f6-b1af-5337-aec5-4fdaa6cad52e'::uuid, 'the_layover'::show_name, 1, 'Open area with view of Colosseum', NULL, 'Season 1'),
  ('782190a5-41d6-54e6-8f9b-d88b0001ff4a'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('783d9b97-0604-57fc-a137-1dd4c79c5700'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony skeptically went to an ashram named Sunil.', 'Other Activities'),
  ('784b05b9-1754-5641-8919-2deb3a83dec1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate here with Steve Plotniki who is a food writer, who says this restaurant is like San Sebastian, Spain, but in NYC.', 'Restaurants and Bars'),
  ('786c43b8-90c9-5627-9a65-bef5d297d665'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Large fish market where Tony and Chef Henrique Sa Pessoa visited. They also have produce, cheese, and meat.', 'Food markets'),
  ('78c73d3c-82ca-580c-afe3-065137f5cf1a'::uuid, 'the_layover'::show_name, 2, 'Seasonal/local food', NULL, 'Season 2'),
  ('78cd62f2-60f7-5316-906e-ab38873f6fc6'::uuid, 'the_layover'::show_name, 2, 'Street art gallery', NULL, 'Season 2'),
  ('798cde7f-0bbf-5a18-9aa3-9df37a548371'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had xiao long bao (soup dumplings), fried pork chop with brown sauce with Professor Zhou Lin, Dean at Shanghai Jiao Tong University', 'Season 4'),
  ('7a032a77-0825-562c-b82c-6e6ecf77c780'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony dropped off a package for the sushi chef named Alfredo at Laredo Sushi Roll. Alfredo''s mother cooked them Mexican food', 'Restaurants and Bars'),
  ('7a11c231-96cd-5f6e-bece-b9acf6ab579f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went to a tiny remote island called Monkey Beach with lots of macaques. They grilled some fish they bought at a floating seafood market. The island is only accessible by boat.', 'Other Activities'),
  ('7a12ca5b-2820-5890-b0f9-78a05aa43836'::uuid, 'the_layover'::show_name, 1, 'French Bistro', NULL, 'Season 1'),
  ('7a5d3def-7a96-5f14-8418-324e08ae5b37'::uuid, 'the_layover'::show_name, 1, 'Southern Indian food', NULL, 'Season 1'),
  ('7a789f56-0845-5007-96c2-e2d58fdbd2f8'::uuid, 'no_reservations'::show_name, NULL, NULL, '"Japanese drunk food fusion" is how Tony described this food truck.', 'Restaurants and Bars'),
  ('7a7cafb6-d763-5f9e-8a6f-60f8cb1bf124'::uuid, 'parts_unknown'::show_name, 3, NULL, 'For breakfast, Tony had Khao soi (curry coconut milk noodle soup), som tam (green papaya salad), Thai iced tea.', 'Season 3'),
  ('7a92258d-abfd-53f8-bceb-5cd0e4ffc2de'::uuid, 'no_reservations'::show_name, NULL, NULL, 'World famous restauranteur Francis Mallmann has a restaurant here. They eat at a big bonfire: salt crusted pork, pumpkin, fried bread (torta frita), veggies cooked in hot stone, and a pascualina which is a tart with pastry and eggs', 'Restaurants and Bars'),
  ('7ab070ac-709a-5b01-97fa-9c93198f0279'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Home of the Industriales. It was a dream of Tony''s to watch a baseball game in Cuba.', 'Other Activities'),
  ('7ab6530e-ed64-5efb-b63f-b94db09c4602'::uuid, 'no_reservations'::show_name, NULL, 'Fancy restaurant with a Michelin star', NULL, 'Restaurants and Bars'),
  ('7ad39c92-fc9c-576e-8a00-44d03e35e396'::uuid, 'parts_unknown'::show_name, 1, NULL, 'The staging area for Tony and Eric''s visit to the mountains to find cacao for their company making chocolate bars.', 'Season 1'),
  ('7aed8ff1-127e-5cf3-b312-01261d5859b4'::uuid, 'parts_unknown'::show_name, 4, NULL, 'A symbol of national pride, the tallest building. Tony visited the observation deck. During the shoot, a huge sandstorm rolled through the area, causing parts of the building to fly off. This was all captured on film.', 'Season 4'),
  ('7b685577-78b2-55c4-9fc1-e3d8a380a6ce'::uuid, 'no_reservations'::show_name, NULL, NULL, '"Wonderfully sadomasochistic play between pleasure and pain; between the scorching searing bite of the dried red Sichuan pepper and the cooling more floral relief of the Sichuan flower petal"', 'Restaurants and Bars'),
  ('7b7bfbdf-e1f4-5b12-a4a4-ec96b5990e90'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This place is in the specialist category - grill master in the Basque. Voted 3rd best restaurant in the world. This place is in the specialist category - grill master in the Basque. Voted 3rd best restaurant in the world. Tony said he had one of the best meals of his life here, definitely unlike anything he''d ever eaten.', 'Restaurants and Bars'),
  ('7b7bfbdf-e1f4-5b12-a4a4-ec96b5990e90'::uuid, 'parts_unknown'::show_name, 9, NULL, '"In every way, extraordinary" says Tony. He had lunch with his old friend Virginia Irizar, who runs a restaurant, and whose dad showed him San Sebastian for the first time. The chef of Etxebarri, Victor Arguinzoniz, makes everything himself from local ingredients. Tony had chorizo "served over a tiny little grill still smoking and infusing it with scent and flavor, grilled razor clams, beluga caviar... grilled and heaped over almond paste... perfectly cooked prawns. Line caught squid, grilled and served in its own ink. And king hell Galician beef chop, grilled."', 'Season 9'),
  ('7b9f8263-8f25-523a-8911-44cf272a37c5'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Eric Ripert met with Maurice Guillot, Eric''s mentor at this butcher/cheese shop. They bought beef tenderloin to make steak au poivre, tomme de chevre, and saucisson.', 'Season 10'),
  ('7ba9fedf-6e88-5c8c-b701-68bad56dbcf5'::uuid, 'a_cooks_tour'::show_name, NULL, 'Casual Japanese barbecued meats served with beer and sake.', NULL, 'Disc 5: Australia and Japan'),
  ('7bb9444b-d5e1-514a-9d0b-daa40f3a173c'::uuid, 'parts_unknown'::show_name, 1, NULL, 'They stopped to get a liver sandwich at a stand on the way to this spot. Leptis Magna, "arguably the most intact remains of a Roman city in the world."', 'Season 1'),
  ('7bc5f63e-76fa-5d33-b2ba-32a6d329758f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a very untraditional miso ramen that included butter and corn.', 'Restaurants and Bars'),
  ('7bd21db1-d9b9-5686-9c11-efcbf3dedd7d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate grilled meats from a food stand right outside this market.', 'Food markets'),
  ('7be2a864-e470-56cb-a36b-ca3f23274d34'::uuid, 'no_reservations'::show_name, NULL, NULL, 'French Creole food. "A legend, an institution, immortal," says Tony.', 'Restaurants and Bars'),
  ('7c0ab4c1-0918-55a2-b993-f3ca8cdf6a73'::uuid, 'no_reservations'::show_name, NULL, 'Open air food market', NULL, 'Food markets'),
  ('7c72e619-ecd0-5ad7-b960-7fe9716a72b6'::uuid, 'the_layover'::show_name, 1, 'Soup with Foie gras, blood sausage', NULL, 'Season 1'),
  ('7c796c86-cc55-5fd9-ac52-5c3c394c984e'::uuid, 'the_layover'::show_name, 1, 'Diner style. More comfort foods', NULL, 'Season 1'),
  ('7c9ab17c-4a40-524d-a72d-9198af2e8b1d'::uuid, 'parts_unknown'::show_name, 4, NULL, '"Old school, Puerto Rican goodness," Tony said of this place which serves cuchifritos (deep-fried pig parts), morcilla (blood sausage), plantains, rice and beans.', 'Season 4'),
  ('7cb4076b-1ab4-5f32-8d8f-72c6eceafc16'::uuid, 'no_reservations'::show_name, NULL, 'Butcher shop with charcuterie', NULL, 'Food markets'),
  ('7cc2bbf1-aad8-54f5-8654-998406ec1899'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This restaurant allowed Tony and his host to cook their fish they caught on the grill. They ate the fish on the boat along with some cheese and bread.', 'Other Activities'),
  ('7cd24ca2-caaf-57c0-ab42-74522fd65312'::uuid, 'no_reservations'::show_name, NULL, 'Old school Cantonese food', NULL, 'Restaurants and Bars'),
  ('7ce83200-cf02-5c72-93e2-c6272615f693'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had a meal with Mike Costello and Amy Dawson, chefs and owners of Lost Creek Farm.<br>They had desperation pie, pawpaw ice cream with candied wildflowers, buttermilk-poached trout with fresh-picked rhubarb, sweet-corn chowder, buttermilk-fried rabbit with fresh maple syrup, venison with a chicory-root rub, chanterelle mushrooms, and wild pears.', 'Season 11'),
  ('7d01ea62-e50d-5666-9adc-60d1591ce421'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony watched a comedy show featuring comedian couple Rich Vos and Bonnie McFarlane, then ate a meal with them.', 'Season 5'),
  ('7d213173-0ae7-5533-88dd-a5af2860040e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Nari ate Korean BBQ', 'Restaurants and Bars'),
  ('7d6271cd-f0c8-5a11-961a-a3aa33f7e493'::uuid, 'the_layover'::show_name, 2, 'Italian sandwiches', NULL, 'Season 2'),
  ('7db9d205-1f35-503b-af92-018c724cfd0d'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with musician, producer, and sound engineer Steve Albini. They had the famous breaded steak sandwich, which Tony said was "at least 4 pounds" and required lots of napkins.', 'Season 7'),
  ('7e107814-1709-5377-b850-60e53489dd81'::uuid, 'no_reservations'::show_name, NULL, 'The chef made tiny soft shell crabs caught that day', NULL, 'Restaurants and Bars'),
  ('7e1ba735-e253-513e-9533-ef86d480d06a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This used to be the Savoy Grill, but it closed now. Tony and Zamir had a meal here, in a place that used to feed both mobsters and politicians', 'Restaurants and Bars'),
  ('7e3876d3-02e3-5f1d-a111-305e5067441f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited during the Day of the Armed Forces, the day the country gained its independence from Portugal colonizers', 'Sightseeing'),
  ('7e5120d7-299d-523e-a315-d4ffeee8c215'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('7e8d5f75-0669-504d-ad0e-7b62d3b286d8'::uuid, 'no_reservations'::show_name, NULL, 'Bar with a mermaid tank', NULL, 'Restaurants and Bars'),
  ('7ea39304-4a65-53cf-916e-e68d6983169f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Pork chop bun, a Macanese specialty. It''s a pork chop on a fluffy bun.', 'Restaurants and Bars'),
  ('7efc423f-a520-5791-ae61-e18bf254fe9b'::uuid, 'no_reservations'::show_name, NULL, 'Poutine', NULL, 'Restaurants and Bars'),
  ('7f1fa699-e2f4-55da-aa74-f10331fdbe77'::uuid, 'no_reservations'::show_name, NULL, NULL, 'One of Tony''s favorite restaurants. Specialize in Foie Gras and pork', 'Restaurants and Bars'),
  ('7f3ac2d6-6307-510b-87c2-fad697f8befe'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Former site of Guns & Butter, where Tony ate with Charlie Leduff, a journalist, at a pop-up restaurant with Chef Craig Lieckfelt.', 'Season 2'),
  ('7f436ee0-f180-5575-855b-63f17acabdf6'::uuid, 'the_layover'::show_name, 1, NULL, NULL, 'Season 1'),
  ('7f67070b-3d4f-55a1-87ae-af6efc9389fe'::uuid, 'parts_unknown'::show_name, 3, 'A locals'' joint with live entertainment.', NULL, 'Season 3'),
  ('7f726912-dede-599f-af95-20f95e672638'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Chefs Michel and Cesar Troisgros carry on the family tradition of nouvelle cuisine. Tony had salmon in sorrel sauce, a dish that he says changed the world.', 'Season 3'),
  ('7fbdaccf-df93-53e4-a818-ba790ed94b87'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Known as the Khao Ka Moo Cowboy Hat Lady, where they ate Khao kha moo (stewed pork leg).', 'Season 3'),
  ('7fc23c61-67e6-52ec-92d4-eb3db05cfe52'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony cooked in the hotel restaurant. The airport was on fire and the there were bombs going off everywhere, but he felt relieved to be able to cook', 'Other Activities'),
  ('8000d933-b5b9-5fc5-90ec-63b3a05c76b4'::uuid, 'parts_unknown'::show_name, 2, 'Cafe con leche and a small breakfast like toast with tomato.', NULL, 'Season 2'),
  ('800d75cf-2d1d-572e-97b1-1611fddebe7f'::uuid, 'the_layover'::show_name, 2, NULL, 'Where Tony stayed', 'Season 2'),
  ('8056e2b7-606d-5938-9d61-df90720fe291'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'One of the many tapas places Tony ate at', 'Disc 1: United States'),
  ('8056ef90-fe11-59fd-b27c-546e17bb45be'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and José Andrés had a bowl of beans with sausage and some cider. After they ate, they played a game similar to bowling.', 'Season 12'),
  ('806dd0b0-5951-5ad5-bb3a-8242005c1b1c'::uuid, 'the_layover'::show_name, 1, 'Public park', NULL, 'Season 1'),
  ('8088e5df-14d6-54f3-a862-ff5a286c4cf7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had empanadas and longaniza with Dominican Republic', 'Restaurants and Bars'),
  ('809d6f33-2f99-5b6e-bfe9-c071881afc62'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Eric took a train out to Long Teng Dong Jie to eat a meal with Chen Zhong, a filmmaker.', 'Season 8'),
  ('80bd2d62-3d97-53e5-943e-2db5e13542a5'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Ryokan (traditional Japanese inn). Tony had a kaiseki meal with Chef Morimoto', 'Restaurants and Bars'),
  ('80ffa8a5-5f1f-5494-af2f-d6ba90540f92'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Fried things. Tony ate the testicles. And capirinhas.', 'Restaurants and Bars'),
  ('811b6aa7-e210-5635-867c-e73d949c5062'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony ate with Roy Choi and Roy Kim, the grandson of the founder of the restaurant. They had banchan, bulgogi, sliced ribeye, kimchi bokumbap (fried rice)', 'Season 1'),
  ('811cb956-a316-5c1f-9803-15e58362917c'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, NULL, 'Disc 4: Morocco & Russia'),
  ('81202529-fc20-505e-ab5a-cc4a68a4db59'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Time for more cheese. Tony and Eric had raclette and fondue here.', 'Season 10'),
  ('815ee28d-addf-553a-b058-35812d2a384b'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Other Activities'),
  ('81c34bd3-5320-5d1f-b5d4-4b847cf0d6df'::uuid, 'no_reservations'::show_name, NULL, 'Icelandic food', NULL, 'Restaurants and Bars'),
  ('820899c7-a322-5807-8040-dcf570156a4f'::uuid, 'the_layover'::show_name, 1, 'Cheesemonger', NULL, 'Season 1'),
  ('82151381-8128-5f55-a74b-364bbaf35113'::uuid, 'the_layover'::show_name, 1, 'Cash only. Ropa vieja and rice & beans', NULL, 'Season 1'),
  ('82456be7-f48b-508d-a469-4ad64b3f3365'::uuid, 'the_layover'::show_name, 1, 'Tea, cafes, Malay food, nightlife.', NULL, 'Season 1'),
  ('824c80a1-e3c4-56ce-8f3a-dfa776f64838'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Lake Trout = not from a lake and not a trout. It''s a "trash fish" that is fried but tastes good. Sides of macaroni & cheese and greens. Also cheap', 'Restaurants and Bars'),
  ('8270e92f-4e2f-5548-86b7-aa7281c59344'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Some of the best preserved Roman ruins in the world. The town was once called Heliopolis, City of the Sun. They worshipped the Goddess of Love,Venus.', 'Sightseeing'),
  ('828e267d-a885-554b-a24b-ada8c31b64f3'::uuid, 'no_reservations'::show_name, NULL, 'Polish traditional foods. Pierogi, Kielbasa', NULL, 'Restaurants and Bars'),
  ('828fba56-752d-5bd7-9343-b0492149eff7'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Not sure if this location still exists, the CNN site says it is on Saya San Road, but not showing up on the map. Tony met with San Zarni Bo and had fermented tea leaf salad, which is served with peanuts, lime, and chilies.', 'Season 1'),
  ('82a05ea2-1b6c-5dd4-a168-fb9be2693ddc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Zamir and Tony ordered bourbon, short ribs, lamb ribs, spare ribs.', 'Restaurants and Bars'),
  ('82a2a5b6-5d7f-54dd-8bff-2c86d7f183cf'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony and Zamir took the luxury Grand Express train from Moscow to St. Petersburg. Aboard the train, they had blini with caviar and cold pickled herring, and vodka.', 'Season 3'),
  ('82d8d1e8-a7a7-56d3-a2de-01aec51a63da'::uuid, 'no_reservations'::show_name, NULL, 'Old school NY steakhouse, since 1885', NULL, 'Restaurants and Bars'),
  ('82e368ce-d27e-5171-a2c4-03f9bfa0c844'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had a rib eye steak and margaritas with Roger D. Hodge, deputy editor at The Intercept and author of Texas Blood', 'Season 12'),
  ('8350e152-545f-589e-b58b-5b3d71ab90eb'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony, Eric, and Gilles Rof (local sports writer) played foosball here', 'Season 6'),
  ('8386c47c-c407-522c-8f5c-67fc262b6406'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Run by a woman who has cooked for nearly every important political figure. No longer open to the public. Some dishes include: Carne de Monte (iguana) and bull nuts.', 'Restaurants and Bars'),
  ('83977e7b-e643-5392-abfe-fa263897562d'::uuid, 'the_layover'::show_name, 2, NULL, 'Hakka cuisine from Southern China. The specialty is the "stinky tofu" (which Tony did not like)', 'Season 2'),
  ('8399fc46-0f2e-55e9-b7ac-71160b0cac9f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Omo Tuo: (pounded rice balls served with palm or groundnut soup.)', 'Restaurants and Bars'),
  ('83af8228-e775-5394-b14e-7abd651e5861'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Bill Buford called this "a very male tradition," called the Franc Machon. They ate Blanquette de Veau (slowly stewed neck and shoulder of veal with mushrooms served over rice); bread, Beaujolais wine.', 'Season 3'),
  ('83ca30ed-04bf-5a14-b17f-707d4bb9f9c6'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had a free-range chicken stew with rice called Pitu de Caleya.', 'Season 12'),
  ('83d28005-098a-55cd-9ab9-e4f4d07e071a'::uuid, 'parts_unknown'::show_name, 5, NULL, 'A huge and beautiful thermal bathhouse Tony went to with Vilmos Zsigmond, a cinematographer who worked on movies like Close Encounters of the Third Kind. (He died in 2016.)', 'Season 5'),
  ('83d2b993-ae3a-5d76-af94-7fe01b32a554'::uuid, 'the_layover'::show_name, 1, 'Bar', NULL, 'Season 1'),
  ('83df8a7c-e035-5cfb-a586-519709ea017b'::uuid, 'the_layover'::show_name, 2, 'Meats, cheeses, dried fruits, nuts, etc.', NULL, 'Season 2'),
  ('83efb747-3c97-550c-b6d0-b2e75a8aa6c7'::uuid, 'the_layover'::show_name, 2, 'Korean food', NULL, 'Season 2'),
  ('843f3609-150a-57e0-a6d2-48303ed4ce9d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had beer and bifana, a sandwich with thin slices of marinated pork, with mustard and chili oil.', 'Restaurants and Bars'),
  ('849a7d52-3e15-5612-a45c-6ee569d37a8b'::uuid, 'the_layover'::show_name, 2, 'Stylish and reasonably priced. Musicians stay here', NULL, 'Season 2'),
  ('849b1c24-2b3a-5115-a1d1-7b872520d04e'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony met with Frank Künster, legendary Berlin bouncer. They had pork schnitzel with brown gravy and boulette (pork meatballs). They discussed the nightclub scene in Berlin.', 'Season 11'),
  ('84afb19e-b91e-53bb-8e84-9b919a21126e'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a meal with the family who runs this restaurant. They had pig trotters with black vinegar (and ginger, fried chilies, and asam), Hainan mixed vegetables (cabbage and glass noodles stir fried with bean curd, black mushrooms, pig skin, and shrimp).', 'Season 10'),
  ('84b2d610-e2ba-5b31-95f9-6dec859d68f1'::uuid, 'no_reservations'::show_name, NULL, 'Very high end restaurant', NULL, 'Food markets'),
  ('84c6c500-a9f2-590b-806a-c1b2e91c2345'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony ate pretzel-crusted swordfish over lump crab meat with Vicki Gold Levy, a local historian. She had pan seared scallops.', 'Season 5'),
  ('84d66e99-b3ab-5d38-b798-b0e82206861b'::uuid, 'parts_unknown'::show_name, 2, NULL, 'On the edge of this town, Tony visited an all-women racing team', 'Season 2'),
  ('84e2d31d-ccea-5e42-8adc-3821ca61b746'::uuid, 'the_layover'::show_name, 2, 'Fresh juices and breakfast sandwiches', NULL, 'Season 2'),
  ('84f809e6-03a4-5de3-a11a-335f31592422'::uuid, 'no_reservations'::show_name, NULL, NULL, '"The dish I crave above all others," Tony says of pho. This episode was a clip show showing "food porn" examples.', 'Restaurants and Bars'),
  ('853e1228-371b-53a9-9497-4a44f31926ac'::uuid, 'no_reservations'::show_name, NULL, 'Cabaret dancing', NULL, 'Other Activities'),
  ('8557dc26-7ddb-5bb6-ae2e-95b0b762dca4'::uuid, 'the_layover'::show_name, 2, 'Meat filled dumpling/pies', NULL, 'Season 2'),
  ('856357b9-5913-56cc-8d3a-f434c6e48f65'::uuid, 'a_cooks_tour'::show_name, NULL, 'Pastele de Pescado', NULL, 'Disc 3: Europe'),
  ('85b6a07f-a683-59cb-8993-684fb5ce46cd'::uuid, 'no_reservations'::show_name, NULL, 'These seafood guys made lobster in the warehouse', NULL, 'Restaurants and Bars'),
  ('85dafb20-1f51-5bdc-b81c-8291ea408c57'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony''s first big break: working as a line cook at this Italian/seafood restaurant. Tony''s favorite is the veal marsala.', 'Disc 1: United States'),
  ('86199da1-c2d3-5e8d-b14a-142108c86957'::uuid, 'the_layover'::show_name, 1, 'Morbid death tour', NULL, 'Season 1'),
  ('861ce88b-b77c-5491-85e6-efe5fc54d1b0'::uuid, 'the_layover'::show_name, 1, 'Coffee', NULL, 'Season 1'),
  ('8652f23d-b5f3-52ec-a254-78bd85747dbc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went on a boat to see mollusk alley, where mussels are harvested the old fashioned way. There are also oysters.', 'Other Activities'),
  ('869beb9e-8518-5422-849a-c15515ceee62'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had roasted pig here.', 'Season 12'),
  ('86f56c54-c9f6-543e-bc3b-1d64559c30ca'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with documentary film producers Billy Corben and Alfred Spellman to have stone crab claws.', 'Season 5'),
  ('870ae067-853e-5be5-9712-0ca70ed44ec1'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Sightseeing'),
  ('87263c16-95ef-5dd5-a141-dfb32dd0485f'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony camped out here in the desert and ate a meal with locals. They cooked the meal on the fire.', 'Season 9'),
  ('8733c398-5ecb-5882-bbc4-fd8b4c2fb9f2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony stayed at this resort in an area nicknamed Patagonia, a mythical land of giants. There is a 5-star restaurant on site that serves ingredients from the property. Steak a la pobre, potatoes, quail eggs, Conger eel from a local fisherman, and a Chilean version of polenta made from corn grown on the premises called chuchoca', 'Lodging'),
  ('874345ef-18cf-5145-a25e-c499dc1f5b63'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony went to the beach', 'Disc 2: Mexico and The Americas'),
  ('875018c2-47d6-56bf-a69f-2b81791803c7'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Dylan prime is closed. Tony drank martinis there.', 'Disc 1: United States'),
  ('8766ccec-3020-51df-ade0-cc5e7aad8d3a'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony ate at local''s home, she is a journalist for Havana Times. They had pork marinated in garlic, onion, and sour orange, served with rice.', 'Season 6'),
  ('87a1ebb9-475f-5f87-b7c9-375c5ea8b305'::uuid, 'no_reservations'::show_name, NULL, 'Pasty. Meat and potatoes in a dough and covered in gravy.', NULL, 'Restaurants and Bars'),
  ('87ae276b-7210-5376-aa5c-0690d4f7d86a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited a local men''s bar called Cafe Astoria in this town, but it doesn''t seem to be open anymore', 'Restaurants and Bars'),
  ('87d85306-17b0-5739-ac82-afdbbc60854e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Zamir visit Zamir''s hometown. They went to a restaurant Tony called Salashihk which I could not find on the map', 'Sightseeing'),
  ('87f2cf77-7ccf-593b-9dfe-3aa5a38f5b45'::uuid, 'no_reservations'::show_name, NULL, 'Squid fishing!', NULL, 'Sightseeing'),
  ('8800b55f-c4fc-5f72-ae40-aacea9e74fc1'::uuid, 'no_reservations'::show_name, NULL, 'Fresh seafood close to the source.', NULL, 'Food markets'),
  ('8811aa9a-8508-58ed-b965-efe0439e7d54'::uuid, 'the_layover'::show_name, 2, NULL, 'This used to be the Yuan Xu Yuan teahouse he visited. Now Closed.', 'Season 2'),
  ('8813de72-959c-5a99-9d5d-7fd8681d5d57'::uuid, 'no_reservations'::show_name, NULL, 'Cupping and acupuncture', NULL, 'Sightseeing'),
  ('88199263-c7ad-5b4b-9dee-965752862a0f'::uuid, 'no_reservations'::show_name, NULL, 'Melon and prosciutto', NULL, 'Restaurants and Bars'),
  ('882d6f4a-368c-51e5-8b62-2fe3a3ae1a7d'::uuid, 'parts_unknown'::show_name, 1, NULL, 'A cafe serving hashish. "There is one particular cafe in the heart of the kasbah that''s drawn in foreign dignitaries, rock stars, aristocrats, and artists since it opened its doors in 1943," Tony explained. Afterward they went directly across the street to a vendor selling spanish omelets filled with potatoes, eggs, ketchup, and mayonnaise.', 'Season 1'),
  ('88362cde-5220-5b3e-9747-195a53812412'::uuid, 'no_reservations'::show_name, NULL, 'Double cheeseburger, chili cheese fries, and a beer', NULL, 'Restaurants and Bars'),
  ('883d1083-4f78-5381-b5f9-c6756f8eebd8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'He quotes "Heat" by Bill Buford, who calls this place "a museum of Tuscan cooking"', 'Food markets'),
  ('88583e75-4757-51aa-a93a-76abe45aec89'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Very old market selling meats, produce, cheese, and other local goods. The market is best known for its seafood.', 'Season 2'),
  ('886353f2-f5d7-502c-9b34-c6b4d6c6b01b'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Masa ate fresh seafood at this market. They had sea urchin, kanogani (snow crab), grilled eel livers, and giant oysters "as big as freakin'' clown shoes"', 'Season 8'),
  ('88637275-19c0-570a-9305-2a260dd3ebe2'::uuid, 'the_layover'::show_name, 2, NULL, 'Tacos. Tony says get the lengua taco', 'Season 2'),
  ('8896bb85-5442-53b2-a9cb-580f3e071dfe'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met at this bustling food market with NPR West Africa correspondent Ofeibea Quist-Arcton.', 'Season 7'),
  ('88995fb5-4984-5579-88e5-23224b4c6d14'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony tried the legendary Spaghetti Red., a plate of spaghetti with pickles, onions, and parmesan.', 'Restaurants and Bars'),
  ('88b702d9-99e0-5e32-85f3-12ecc3e7a9da'::uuid, 'no_reservations'::show_name, NULL, 'Casual, friendly Parisian cuisine', NULL, 'Restaurants and Bars'),
  ('88e4bd9c-c428-58bd-b7fd-abdcb79f7d45'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Michael had housemade proscuitto, ficattola (fried bread), a local cheese, tortelli, gnocchi, and steak', 'Restaurants and Bars'),
  ('89214467-1f1a-5e2a-aac6-6db82c1613ec'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony ate here with chef Tekuna Gachechiladze, who is trying to modernize Georgian cuisine. I have also mapped the current location of this restaurant.', 'Season 7'),
  ('892fb096-7d63-5818-a829-a3a9b5b4660e'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had a boudin ball (a type of local sausage) stuffed with pepper jack cheese, cracklings, and Budweiser beer with chef Toby Rodriguez', 'Season 11'),
  ('89bc55e4-bb03-5578-8048-54e2078679c7'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had a meal with Questlove here. They had deviled eggs; fried green tomatoes with pork belly; chocolate chip pancakes with bourbon maple syrup, banana compote, and peanut butter; fried chicken with chilled watermelon; cheddar-cheese waffles; and shrimp and grits', 'Season 5'),
  ('89e0c975-4ab9-5220-8456-0dab898fc175'::uuid, 'parts_unknown'::show_name, 4, NULL, 'A food market with food stands, known as the largest and most popular food market. Tony ate a catfish soup, gnocchi and stew, sopa de Paraguayan.', 'Season 4'),
  ('89e40f99-e4bc-59e0-91ca-ca9a96c382b3'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Leon met with Ivo Faria, the “godfather” of mineiro cuisine at this restaurant inside the Mercado Central. They had beer, liver with jiló (a veggie like eggplant, only green and only edible when ripe).', 'Season 8'),
  ('89eef75e-2a2b-5564-b747-b264cad44ddd'::uuid, 'no_reservations'::show_name, NULL, NULL, '"He was a cranky pederast and a syphilitic" Bourdain said of Gaugin', 'Sightseeing'),
  ('89f57a10-a422-55cf-b205-6d3e10761943'::uuid, 'no_reservations'::show_name, NULL, 'Gin & tonics and snacks', NULL, 'Restaurants and Bars'),
  ('89fdf599-7ef4-50ef-8796-5ad356ea497e'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony tried the blood sausage with braised red cabbage and pickles.', 'Season 5'),
  ('8a013368-dc09-5ce7-a3eb-d401693319ce'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony ate classic Southern soul-food buffet of collard greens, fried okra, mac ’n’ cheese, lima beans, red beans, neck bones, rice and gravy, a piece of fried chicken.', 'Season 3'),
  ('8a2464f9-b4ec-5e27-80d5-76b7b35d076c'::uuid, 'parts_unknown'::show_name, 8, NULL, 'By the end of this meal of painfully spicy Sichuan hot pot (dog tail; tripe, or “thousand-layer stomach”; tofu skin, seaweed, various meats and fishes, intestines), Eric said he couldn''t think anymore (because of the spice). Tony enjoyed the meal and watching Eric squirm.', 'Season 8'),
  ('8a41b85f-9ea5-5140-aaa1-acd4519b564b'::uuid, 'the_layover'::show_name, 2, NULL, 'Crowded but one of the best markets in the city with tons of food stands. Try the rice pot sticker soup and oyster omelet. Also the Ba Wan (pork, shiitake, garlic, soy.', 'Season 2'),
  ('8a5284bb-f095-5ae9-bb9f-54460bdc3595'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony went to this weed dispensary to buy some pot, since it is legal in the state of Washington', 'Season 10'),
  ('8a5d838e-af90-5bde-a47a-62f4281fc6a3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Coffee con Piernes - beautiful women in tight outfits serve you coffee', 'Restaurants and Bars'),
  ('8a6fb329-5bc9-5eff-afcf-03a9fbc3bf47'::uuid, 'no_reservations'::show_name, NULL, 'Culatello is made here, made from pork butt.', NULL, 'Other Activities'),
  ('8a7499dd-7b11-5f7d-8f18-da7885069f32'::uuid, 'no_reservations'::show_name, NULL, 'Tiki bar', NULL, 'Restaurants and Bars'),
  ('8acf3958-daaa-5577-93fd-60b436bc78eb'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'One of the last czars or Russia, Alexander II, was blown up at this very spot by a terrorist group', 'Disc 4: Morocco & Russia'),
  ('8ad51ab7-7602-5c74-8c18-09007ba6abba'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with activist "Pocho" to have a feast of Sancocho, a beef stew with yuca, plantains; fresh-caught grouper and red snapper.', 'Season 10'),
  ('8ad9f01a-c7d5-5571-88e6-1410ce031f01'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had lunch here with a famous Portuguese musician. They sampled peixihos da horta (tempura green beans), morcela (blood sausage), pig trotters with cilantro, a golden egg dish with cepes (mushroom) and cheese, and a hazelnut dessert.', 'Restaurants and Bars'),
  ('8b27fedc-3af2-5c23-b15c-eb5a3407c6e5'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony played candlepin bowling, where the ball is smaller and the pins are much thinner and harder to knock down.', 'Other Activities'),
  ('8b64633e-2ecd-53d0-bdbe-1b902c8a5c38'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony met with musician and actor Lydia Lunch. They had seafood.', 'Season 12'),
  ('8b76f063-e307-571e-a4d4-a61aacdede18'::uuid, 'parts_unknown'::show_name, 10, NULL, 'One of Tony''s favorite things to eat in Singapore is char kway teow. "Ordinarily this is a breakfast," Tony explains. "I eat it every time I''m in Singapore." It is made of crispy lard bits, cockles, shrimp paste, and noodles.', 'Season 10'),
  ('8b90150b-d74d-5ca6-ae83-4aa2a9a32365'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony visited this small village in northern Laos. The villagers cooked him chicken and veggies.', 'Season 9'),
  ('8bc4afcf-5a95-57ff-b96c-bbd86d94ba5e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'In search for a cheese-filled sausage (kasekreiner), Tony and friends stopped at this hot dog stand', 'Restaurants and Bars'),
  ('8bce6a31-39b9-5bf3-b4a9-449babbfd412'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Ludo Lefebvre and Tony went there to visit Ludo''s mom in his childhood home.', 'Other Activities'),
  ('8bf8fc9f-5b37-56ec-9f0f-47b6bb5fbd20'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate isan style chicken and green papaya salad, which he described as so hot, "I think my pubes just caught on fire."', 'Restaurants and Bars'),
  ('8c2d2d6e-69a9-5248-84dc-f44ec319adf6'::uuid, 'the_layover'::show_name, 1, NULL, 'Curried fish fritters. Pad Krapow: pork with basil garlic and chiles.', 'Season 1'),
  ('8c49a4fd-ed3a-5629-9bdf-7493be0d67d5'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('8c555dca-f9d4-5b58-a92a-b6d1436ccc71'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Garlic crab, oysters, and crab cakes. And a crazy blue drink named The Obama', 'Restaurants and Bars'),
  ('8c8561b7-9c73-5e8d-8f93-ecd596cb77a3'::uuid, 'a_cooks_tour'::show_name, NULL, 'Traditional Moroccan feast', NULL, 'Disc 4: Morocco & Russia'),
  ('8c9e405d-9788-5c04-a976-6b6b4e423b15'::uuid, 'the_layover'::show_name, 1, 'Salted Pickled Herring', NULL, 'Season 1'),
  ('8cc9a70e-5d30-536c-bdb3-0ee117d97691'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony went to a men-only coffeehouse called Yahzakem Coffee where people smoked hookah and drank local coffee.', 'Season 1'),
  ('8cd04fae-8523-5b0c-a9ac-bb18d77a7710'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had a home cooked meal made by Fiona Cullinane here with A.A. Gill, a restaurant critic. They had roasted grouse with bacon and bread sauce, and served with watercress, parsnips, and beetroot. The next day they went hunting and shot a deer, then had a meal of venison seared in duck fat and served with a pan sauce of red wine, butter, and currant jelly.', 'Season 5'),
  ('8cec61e4-5bd0-5408-a5bc-828454600d68'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony stayed with his guide at this 18th century fort palace (where the guide worked)', 'Lodging'),
  ('8cfecd17-3b8b-5236-97e1-e044730f5392'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Legendary improv comedy theater where John Belushi, Gilda Radner, and others got their start.', 'Season 7'),
  ('8d013a87-c274-57cc-a58e-e231bb80ca8d'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Masa''s brother Kazuo had a restaurant in Nasushiobara called Sugimura. Could not find it on the map. They had "kimoyaki, eel liver dipped in a sauce of sake, soy, and mirin, and grilled low and slow over charcoal... insanely delicious custard of eel and egg, jacked with bean curd, bonito broth, and kelp... hitsumabushi, eel steamed, dressed, and grilled, over rice."', 'Season 8'),
  ('8d5dbf52-77e3-558d-a478-a79446139f45'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony ate Padang food: fried lungs, intestine goulash, beef rendang.', 'Season 12'),
  ('8d680c2a-e41b-58a3-9cfc-c3d9083ae144'::uuid, 'no_reservations'::show_name, NULL, 'Fancy food at Thomas Keller''s Vegas restaurant', NULL, 'Restaurants and Bars'),
  ('8da70352-a0eb-51fa-9afc-bc37e74ccf79'::uuid, 'no_reservations'::show_name, NULL, 'Food stand serving ginger and pork sausage', NULL, 'Restaurants and Bars'),
  ('8daed258-9cd2-501a-b21d-5deb561101f7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They had micheladas and seafood. "Pescado empapelado (grilled and seasoned red snapper heaped with vegetables). Brochettes of bacon wrapped shrimp stuffed with crabmeat."', 'Restaurants and Bars'),
  ('8df8d38d-7491-50d0-8f3a-20f7bd4be710'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony was hungover so Nigella cooked Eggs in Purgatory for him, bread toasted in beef fat, served with runny eggs and spicy chili tomato sauce.', 'Season 8'),
  ('8dff041b-6768-5141-9327-d43a6741b9ca'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met the owner of this musical venue', 'Season 10'),
  ('8e069501-eade-5e13-b663-d8985616e43f'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had a meal with 2 women heavy machine operators.', 'Season 9'),
  ('8e58c3b7-d0a7-596f-b9f0-eb2b403f2ed6'::uuid, 'no_reservations'::show_name, NULL, 'This bar serves Fried Sardines, seafood soup, and Pasteles', NULL, 'Restaurants and Bars'),
  ('8e623ee3-8e28-5212-9a81-302eb176eb33'::uuid, 'the_layover'::show_name, 2, 'Knife shop', NULL, 'Season 2'),
  ('8e6b1668-8de6-57cd-b1fe-c4eb08738daf'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('8e700a8c-cd6d-5db6-923d-3fc68cbe6e6b'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a meal at Chicago-based rapper Lupe Fiasco''s house with his extended family. His mother made macaroni and cheese, collard greens, and other soul food.', 'Season 7'),
  ('8e84d1f5-039b-5446-8944-053e7cf513fc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'English country classics. Croustade quails eggs with hollandaise sauce, roast venison, Omelet Arnold Bennet', 'Restaurants and Bars'),
  ('8e8e2ba7-d0ec-5c85-8308-f0fe7c734d59'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony tries the Howie Carr, named after the radio station host. It is a huge sandwich with corned beef and beef brisket. And pastrami knishes.', 'Restaurants and Bars'),
  ('8eb08b94-cbfb-51b8-9eef-14dfdcfb8ded'::uuid, 'the_layover'::show_name, 1, NULL, NULL, 'Season 1'),
  ('8edb0fcc-388f-5549-8420-fbac32301cda'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony had some snacks at this train station on his way to the Himalayas.', 'Season 3'),
  ('8ef66724-bbad-554c-a422-6e4fd37887bd'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony relaxed by the beach and had caipirinhas and fried cheese on a stick.', 'Season 3'),
  ('8f0112e2-199c-5ae0-bd46-7b4cb5752539'::uuid, 'parts_unknown'::show_name, 5, NULL, NULL, 'Season 5'),
  ('8f1068fd-b7dc-555c-b5ab-ba223425c636'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony visited this boxing gym to speak with boxer Jorge Lacierva', 'Season 3'),
  ('8f2eb95a-3281-5759-ba40-d2fa2143eb1f'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and José had lunch with the man who caught el campanu (the season’s first caught salmon) in 2014. They had bread, salami, cheese, olives, beer.', 'Season 12'),
  ('8f44d304-0a22-5193-bf23-5ecb49e62bcf'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony went to this cafeteria style restaurant with Jesse Boyce (songwriter/producer),and ordered a combo popular in Nashville called the "meat & three" which includes a meat dish and 3 sides. Tony chose fried chicken with okra, corn, and mashed potatoes.', 'Season 8'),
  ('8f469665-dabc-5a00-a3fd-f4f86e7d6b74'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The Izmailovo Market - a huge flea market. Also has food stands with grilled meats on a stick', 'Food markets'),
  ('8f479295-326b-5441-8f4f-863561d1f242'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and José had fresh caught grilled salmon with local moonshine. They laughed as they ate and drank outside at this place.', 'Season 12'),
  ('8f51ece7-bbb2-585a-9378-6ec97d3ecd7b'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with Thao Griffiths, the country director of the Vietnam Foundation. They ate Banh cuon, a dish of ground pork with wood ear mushroom in a thin rice noodle roll that is dipped in broth.', 'Season 8'),
  ('8f6917db-8402-546d-b88e-b3652560df97'::uuid, 'parts_unknown'::show_name, 4, NULL, '"Cape Cod of the Bronx." Tony had steamed clams, boiled striper, snow crab, beer.', 'Season 4'),
  ('8f993f77-cf9e-5388-839f-f84b78f7d6cd'::uuid, 'no_reservations'::show_name, NULL, 'Formerly Verre, by Gordon Ramsay (closed)', NULL, 'Restaurants and Bars'),
  ('8fbd4581-f354-59bd-92fa-3437f4b018bc'::uuid, 'no_reservations'::show_name, NULL, 'Shrine to the forest gods', NULL, 'Sightseeing'),
  ('8fced5cc-c220-5842-b0b0-be4a61afdfc7'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony ate a burger here', 'Disc 1: United States'),
  ('8fe19cc3-2c4c-53f0-ae03-217e73b7ff67'::uuid, 'the_layover'::show_name, 2, 'Novelty gift shop', NULL, 'Season 2'),
  ('8fe8a9ff-c43c-595a-bba3-314d021fca6b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Portuguese Restaurant serving grilled chorizo; clams with garlic, white wine, cilantro, malagueta peppers; grilled sardines; suckling pig', 'Restaurants and Bars'),
  ('8ff4e41f-e9d9-5e99-9c00-3ab56b4ff82a'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony''s friend the taxi driver recommended this restaurant. They had Işkembe çorbası (tripe soup).', 'Season 6'),
  ('8ff728d1-b3f0-5895-aecc-e44a2049f2b6'::uuid, 'no_reservations'::show_name, NULL, 'Traditional German food', NULL, 'Food markets'),
  ('900e8fe1-feeb-509d-8f07-175cb12e51ff'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony and his brother drove out to this shore town to relive old memories.', 'Season 5'),
  ('901a3ad4-0d07-5499-916a-5008548d2d07'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony visited this penguin colony of 2000 breeding pairs. He talked with marine ecologists Dr. David Ainley, who has been studying the colony for 20 years.', 'Season 9'),
  ('902b5bd9-aa6c-5a2c-86bb-e88c3dc63ae3'::uuid, 'a_cooks_tour'::show_name, NULL, 'Grilled meats', NULL, 'Disc 1: United States'),
  ('9033c7a4-7ba4-5377-bfb7-c67026ac933b'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Bean paste with shrimp and tomato, fried in spicy oil. Served with salsa.', 'Disc 2: Mexico and The Americas'),
  ('9033c7a4-7ba4-5377-bfb7-c67026ac933b'::uuid, 'parts_unknown'::show_name, 3, NULL, 'A food stand that always has a line. Tony had acarajé, "a falafel-like wad of crushed black-eyed peas, seasoned with brown brine shrimp and onions, deep-fried until crispy and golden, with chili spice in dendê oil"', 'Season 3'),
  ('9048e738-7cc9-5e74-a31d-e7259a227e87'::uuid, 'no_reservations'::show_name, NULL, 'Manchu style dinner - imperial cuisine of the Qing Dynasty', NULL, 'Restaurants and Bars'),
  ('904dc671-02dc-5af5-9989-53ae5c487cf1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'He visited Conchtown Cafe, which no longer exists', 'Sightseeing'),
  ('90502523-194e-5afa-a0a3-c4fe94855a3c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Coffee has been produced on this land for 2 centuries. There is a microclimate that is perfect for growing the coffee', 'Sightseeing'),
  ('9089c821-9429-54a9-b382-407c8523ef3e'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony and guide stopped to view this settlement and talked about the conflicts between Palestinians and Jews', 'Season 2'),
  ('908b78d3-ce25-582e-9712-b36efd93072d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The mecca for lovers of meat in tube form. Home of the famous Chicago red hot. Also fries cooked in duck fat. Locals love this place and it has won a lot of awards', 'Restaurants and Bars'),
  ('90b450a7-a615-56ff-a359-79f018015589'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Two members of the New Mexico UFO & paranormal forum, Norio and James, met Tony outside here to talk about America''s first rocketships.', 'Season 2'),
  ('90b7911e-741b-587c-91f0-26fbeb875220'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Local seafood cooked in Japanese recipes. Tempura fried zucchini blossoms stuffed with fresh scallops. Dungeness crab, daikon with pepper, mustard miso dressing, Japanese celery.', 'Restaurants and Bars'),
  ('90c24f25-19f4-5f75-9604-5330c5f9ef4f'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony had espresso and a bomba, a type of Italian donut, for breakfast.', 'Season 8'),
  ('90c4b474-6ffe-5c2e-83ad-c31ef4a15aff'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony ate by himself here, he had Chianti, prosciutto and artichoke hearts in olive oil, ravioli.', 'Season 8'),
  ('91388156-96a0-55fc-9e24-4b2ffdf4f3e5'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony went to a moraga (a beach barbecue) with chefs Juan Andres Moria and Rafael Luca, and friends. They had dried tuna on toast with spicy olive oil, fish, cheese, pate, grilled octopus, sea bream, pork tenderloin, and morcilla (blood sausage).', 'Season 2'),
  ('913a09e0-2974-558f-a10d-430137d68fb7'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('917febe0-49b9-56e5-a344-d68aa90d369d'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with KF Seetoh, his guide in Singapore, "the guru behind the Makansutra guides and an advocate for the kind of democratic, affordable, casual chaos of the hawker world." They had prawn mi from this stand.', 'Season 10'),
  ('918b32b8-6437-5390-9ae7-36054294c49e'::uuid, 'parts_unknown'::show_name, 9, NULL, '"During the Secret War, [this hotel] was the offices for USAID, America''s foreign aid mission," says Tony. He had lunch here with the hotel owner, Mama Vahn, who made the meal, "an elaborate spread of dishes whose recipes are left over from imperial times." They had lon song, a fish from the Mekong River, cooked with shallots, garlic, chili, coconut milk, and pork; river crab, fish with pork grilled in banana leaves, ginger sauce, pork skin, and sticky rice.', 'Season 9'),
  ('91cf6135-5af9-5730-a6e4-bae195439a1c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Michelin starred dim sum restaurant. Roasted chicken with honey lime sauce; dumplings in the shape of goldfish; Roasted pork belly; fish ball soup; crab claw steamed, served with ginger, white wine, egg white', 'Restaurants and Bars'),
  ('91d7bdd6-4cb1-5483-83cf-2111fbac7eb9'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony did an interview on a right-wing station here. The Friends of Eddie Coyle is Tony''s favorite crime novel, and this impresses the radio host.', 'Other Activities'),
  ('92038cea-1d07-541e-975f-b966b673da8c'::uuid, 'no_reservations'::show_name, NULL, 'Curry mixed rice', NULL, 'Restaurants and Bars'),
  ('9221a964-9590-56bb-8101-255cc00341ea'::uuid, 'no_reservations'::show_name, NULL, NULL, '"You can drink in the street in this country, like a civilized human being" Tony said to open this episode.', 'Restaurants and Bars'),
  ('922e1b72-be7a-589e-b07f-870aa6c91f40'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had more Persian food in someone''s home. They ate Boz Ghormeh (slow cooked lamb in yogurt, saffron, and egg yolks), sour cherry rice, koofteh tabrizi (a very large meatball with ground beef, onion, cooked rice, walnuts, dried apricots, boiled eggs, and barberries).', 'Season 4'),
  ('92377b89-7584-5799-93f3-fa96bb184d2f'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Old school diner specializing in many pies. Tony had corned beef and cabbage and raspberry cream pie.', 'Season 4'),
  ('92411ef3-80dc-520a-824f-75a17c518f0b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Spanish style restaurant, food like what Spaniards eat at home. Braised oxtail is the specialty', 'Restaurants and Bars'),
  ('926f1d10-f317-5c5a-8ef2-9daf04c96129'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Training facility that gives second chances to convicted felons out of prison. They take leftover ingredients from restaurants and hotels and make food for the needy', 'Other Activities'),
  ('9277a875-96ff-5ab2-a309-dfeda4fb1fc5'::uuid, 'the_layover'::show_name, 1, 'Fancy cocktails with fresh fruits', NULL, 'Season 1'),
  ('92925038-28b8-59e2-8702-40111f5dc33b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a martini at this fancy hotel on a lake', 'Restaurants and Bars'),
  ('92f1937c-511a-54dc-ae5f-553f8fc4c517'::uuid, 'no_reservations'::show_name, NULL, 'Every person buried there had a vice.', NULL, 'Sightseeing'),
  ('9321186c-22f7-5219-8b04-48eb3d99a275'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony ate lunch at this locals only place, with Majid, the owner of Boutique Majid. Tomatoes brushed with local olive oil, garlic, and coriander; beef liver kebabs grilled over charcoal; swordfish; orange roughy.', 'Season 1'),
  ('9327e541-b6e3-55c6-928e-14baf7685b57'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Other Activities'),
  ('933f52cd-debe-5d2e-a65c-3e98faf51e06'::uuid, 'no_reservations'::show_name, NULL, 'Currywurst and fries. It''s a very Berlin thing.', NULL, 'Restaurants and Bars'),
  ('934b9f4e-2d93-5d99-b51f-c2b85b913020'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited a boxing gym.', 'Other Activities'),
  ('936da26c-35db-5dbf-ae86-6e3012aceee8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'La vida tapa. Albert Adria is the chef. "Whimsical, theatrical; a carnival fairway-like feeling to its dining room," says Tony', 'Restaurants and Bars'),
  ('939a1ded-6e47-5258-8aff-9508abc24f03'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had another meal with a local, the nanny of one of the show''s directors, Erik Osterholm. She made kare kare, or oxtail soup. After living abroad for over 30 years, Aurora is finally back home living with her kids and grandchildren, although many still live abroad to send money home to support the family. They talked about the sacrifices Aurora and many other Filipinos make to send money for better lives for these poor families.', 'Season 7'),
  ('93d2c228-9f17-5221-af4e-f052734ccb5e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony stayed here for a week while visiting Haiti and said it seemed like a spooky fairy tale. He had a rum punch at the hotel bar. He also spoke with the owner of the hotel and they shared some fried shrimp fritters and conch in Creole sauce later in the episode', 'Lodging'),
  ('93d370e9-5354-5476-87a1-55ff6f0dd1a0'::uuid, 'the_layover'::show_name, 2, 'Handheld version of the Irish breakfast served here', NULL, 'Season 2'),
  ('93ecab3e-1c28-5714-8b58-83baa418aa61'::uuid, 'no_reservations'::show_name, NULL, 'local beer, local food, soup, buffalo wings of course!', NULL, 'Restaurants and Bars'),
  ('9411dabc-043f-5e2f-9740-8475dd53857c'::uuid, 'the_layover'::show_name, 2, 'Fried chicken', NULL, 'Season 2'),
  ('944dff8e-e042-5231-8c1a-567263eee555'::uuid, 'the_layover'::show_name, 2, NULL, 'Used and rare books. The name changed since the show. Formerly known as Cathach Books.', 'Season 2'),
  ('945f2cf2-4c5f-50d4-b77b-4f10bfe0a62b'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony ate at this Korean restaurant with John Cook and Todd Bishop, co-founders of tech news website GeekWire. They had: "cilantro noodles with yu choy, and thinly sliced flat iron steak; kimchi pancakes with braised pork belly and bean sprouts; marinated short rib rice bowl with house sambal daikon, kimchi, and egg; and short rib dumplings topped with pickled shallot and scallion salad."', 'Season 10'),
  ('9464a7cd-1e8e-5265-a1f0-f61df7547d3f'::uuid, 'the_layover'::show_name, 1, NULL, 'Crispy rice with chicken, mushroom, fish. String beans, lobster, crabs, clams.', 'Season 1'),
  ('9466cabc-fb0d-5ac4-bc18-c792d0229e77'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tapas. They specialize in local, wild mushrooms', 'Disc 3: Europe'),
  ('9466cabc-fb0d-5ac4-bc18-c792d0229e77'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony went on a poteo (bar crawl) with the famous chef Juan Mari Arzak and his daughter Elena. They ate a lot of pintxos and drank beer. They did not specify the places they visited except for this one, because this was Tony''s favorite place to get pintxos, and the first place someone brought him to when he first visited the Basque area. Iberico ham with mushrooms on toast, crab tartlets, seared wild mushrooms and foie gras with egg yolk (house specialty, and Tony''s favorite)', 'Season 9'),
  ('94758e25-3fe4-5f9d-b655-af1ef3f5c07f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Two falafel shops owned by brothers who do not speak to each other, right next door to each other.', 'Restaurants and Bars'),
  ('94836737-5ddc-56ab-80cb-522a51de5a5b'::uuid, 'the_layover'::show_name, 1, 'Films', NULL, 'Season 1'),
  ('948d2557-d335-55c8-b970-7d4e35f784a4'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('9490c7fc-05a1-5760-bca5-763cebed65bc'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony visited La Marquesas Ranch, the private bullring of star matador David Fandila. Tony tried it himself with a calf. They then ate bull stew with local herbs, onions, and potatoes; ham; homemade chorizo; Spanish cheese; bread with olive oil', 'Season 2'),
  ('94b46e50-ce5a-56be-94c8-72255033424a'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony got a tailor made gangsta suit made here', 'Season 1'),
  ('94b89ea8-1805-572e-827e-6ea3f8049dd9'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('94b8e8ac-7b3e-53c0-a7cc-d9186bbfb382'::uuid, 'the_layover'::show_name, 1, 'Fancy hotel', NULL, 'Season 1'),
  ('94cfecec-e4d1-50bc-ae05-3ac35ee5e95a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Genuine Tejano cuisine. Chicken mole; cabrita (goat), served with rice and beans', 'Restaurants and Bars'),
  ('94dfa5a9-97bf-5f9d-87eb-8c3e61cb44b8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Pastrami on rye with brown mustard, pickles. Tony has his with a cream soda.', 'Restaurants and Bars'),
  ('950e9b6f-1677-5a51-8560-ef809720bb29'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony hunts rabbits for dinner.', 'Disc 3: Europe'),
  ('95196e79-5070-5e3e-a530-627578689535'::uuid, 'parts_unknown'::show_name, 1, 'Former site of Roy Choi''s A-Frame restaurant.', NULL, 'Season 1'),
  ('9544c7e5-b4c7-5d6d-ae8a-2b68a98615b2'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony loves this local fast food joint, even though he said "I hate myself" as he was finishing his meal. He had Jolly Spaghetti (with hot dogs in it) and Chicken Joy with a brown sauce.', 'Season 7'),
  ('958eb549-b056-58be-a946-bc4da81ec7d9'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'The Bourdain brothers bought sausage and cheese for a picnic on the beach', 'Disc 3: Europe'),
  ('95a940d4-7d01-52eb-8b56-72e1cf47d6c0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A liquor store you can eat at. They have tortas! Tony had the Cubano which is huge and filled with chorizo, hot dog, ham, egg, cheese, mayo, jalapeno, and avocado.', 'Restaurants and Bars'),
  ('95de02c1-380c-5cc7-b23e-f3002406ab1b'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Now closed, Tony had a meal here with John Birdsall, a food writer.', 'Season 6'),
  ('96143715-eb91-5194-b7d2-8033f3c687c3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony got a tour of the stadium and walked the field', 'Sightseeing'),
  ('96521476-860a-5a89-8356-b4205f031d80'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Attached to Roberta''s, the chef here does a tasting menu that Tony tried with rapper Talib Kweli. Veal sweetbreads, trucidi with razor clams, and celtuce; raviolo with nduja and hyssop; crispy duck; steak with hearts of palm', 'Restaurants and Bars'),
  ('967a6244-2b9e-59fa-9500-d5fd845b249d'::uuid, 'the_layover'::show_name, 2, 'Coffee', NULL, 'Season 2'),
  ('97016348-3e9a-578b-bcba-b5d04f8c2732'::uuid, 'the_layover'::show_name, 2, 'Modern hotel', NULL, 'Season 2'),
  ('97089944-7771-532f-855c-c5caa6616c95'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went whitewater rafting on the Chama River', 'Other Activities'),
  ('9715a502-ff9c-5c6f-8f15-4f5c3e97906c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Zamir ate their khachapuri on the beach', 'Restaurants and Bars'),
  ('97262315-c6cf-5549-b0bd-9283e3d72fa7'::uuid, 'the_layover'::show_name, 2, 'Over 100 whiskeys', NULL, 'Season 2'),
  ('973c73d9-c071-52c5-ad78-55c98e2d12d8'::uuid, 'no_reservations'::show_name, NULL, 'Traditional Puerto Rican food', NULL, 'Restaurants and Bars'),
  ('9786cebd-1480-500c-9ba8-c3ddcd01da83'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The maharana cooked Tony a royal meal of goat curry', 'Other Activities'),
  ('97acf195-37e5-5f7f-bd93-d4213383471d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate at this truffle restaurant', 'Restaurants and Bars'),
  ('97cdc695-8b06-545a-a9e6-65c695245880'::uuid, 'the_layover'::show_name, 2, 'cocktails', NULL, 'Season 2'),
  ('97ed392e-8964-5f02-bf9e-41135bbcbda2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Sailed a boat through ''dragon footprints" which are craggy rocks along the edge of the coast', 'Sightseeing'),
  ('97eda892-b983-59b7-94e5-68f8680319b3'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had beef, fried chiles, and biscuits with the Means family on their ranch.', 'Season 12'),
  ('97f64e27-3226-50af-8620-67e37549f74b'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Eric stopped at a roadside stand in the Marañón canyon to have sopa de gallina, a Peruvian hen soup. After they went to the cacao plantation, they had dinner at Don Fortunato''s home: juane (rice dumplings with boiled egg, chicken, and achiote) and roasted cuy (guinea pig) in a cacao sauce', 'Season 1'),
  ('97f80eff-b6eb-5519-bfd4-037fdbe58b18'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with Melek Yaprak, aTurkish-German whose grandparents were among the first wave of Turkish immigrants in Cologne in this Turkish restaurant. They had Raki and mezze of "spicy mashed vegetables, tzatziki, hummus, beetroot and olive dip, fried eggplant, pastries with feta, meatballs with tomato sauce and mint"', 'Season 7'),
  ('981fd24e-10d7-5032-bb36-db9a9c00bde1'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony visited Chef Boulud''s childhood school in this town, where Chef Boulud explained the fresh, healthy meals students are given here. They had pumpkin soup, fish with couscous, cheese with chocolate and orange segments.', 'Season 3'),
  ('98424235-bc6e-5212-a2fb-8d66c2c6021b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Closed now, but this was Wylie Dufresne''s restaurant. This episode featured Bill Buford, Amy Sacco, Ted Allen, and Chris Wilson eating at the restaurant and talking about the restaurant biz.', 'Restaurants and Bars'),
  ('98aab782-5603-5b57-b35d-1b43d3e14853'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had an enormous platter of seafood consisting of "coastal shrimp, local oysters and crab, sea urchin, langoustine, gooseneck barnacles, whelks, and clams, and a salt-baked sea bass."', 'Season 9'),
  ('98e0f2c3-1518-5116-b935-c803e0da7c52'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went to a crab boil at a band''s house while in town for SXSW', 'Other Activities'),
  ('99170e3b-3ec7-576b-896c-6a057d1d7664'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony ate shark, lobster, shrimp, zebra, lots of veggies (Darren just had veggies) on the beach with some locals.', 'Season 5'),
  ('992d2e3c-a342-5604-a172-17741b4356d1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony filmed a short skit in this film studio', 'Other Activities'),
  ('996492f1-f3dd-548b-ba32-1a6260d0c130'::uuid, 'parts_unknown'::show_name, 12, 'steak with green onion, grilled corn, tortillas, beans', NULL, 'Season 12'),
  ('99a66a66-ee47-5b89-8ff8-1ec974b285bc'::uuid, 'no_reservations'::show_name, NULL, 'Fried meat fritters', NULL, 'Restaurants and Bars'),
  ('99c13033-c0ef-5e02-ae5b-5d1041037bb9'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had fried snapper here at a place with many street food stands.', 'Season 9'),
  ('99e44c5f-dff7-59f7-a57d-a65a96e7d109'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This is the parillas stand that Tony and his brother Chris ate at', 'Restaurants and Bars'),
  ('9a14c724-6755-579d-8044-79e2423f14e7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Steaks! Tony had the cowboy ribeye.', 'Restaurants and Bars'),
  ('9a2216e1-2dd7-59da-848c-e70d6b87e340'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony used to live in this neighborhood and come to this old school sausage store', 'Food markets'),
  ('9a4e5a07-bf8b-5046-87ad-c041b2aa83ec'::uuid, 'the_layover'::show_name, 1, 'Marijuana cafe', NULL, 'Season 1'),
  ('9a5239c0-7c59-5bf0-8e32-a1314e2fad73'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Sourcing ingredients from a roof garden, they make their own dough and serve craft beers.', 'Restaurants and Bars'),
  ('9a57c1f1-fbb0-5048-80c0-8a011dae9aa4'::uuid, 'the_layover'::show_name, 2, NULL, 'One of the last parts of Taipei with remnants of colonial Taiwan. Shopping.', 'Season 2'),
  ('9aa0a455-167e-58e0-a9e3-aa7c706904d6'::uuid, 'the_layover'::show_name, 2, NULL, 'Cheap but good food. Only prix fixe meals. Menu changes daily.', 'Season 2'),
  ('9acf52cc-d30b-5591-a704-5ce0d1fdad18'::uuid, 'the_layover'::show_name, 2, 'Try the Roast Beef Po''Boy', NULL, 'Season 2'),
  ('9af9c302-1ffb-5286-bc2d-386c26e46b3e'::uuid, 'parts_unknown'::show_name, 1, NULL, 'National Institute for Agronomic Study of the Belgian Congo is located here and Tony met with a man who works to save the library of thousands of books here.', 'Season 1'),
  ('9b24ab41-41d3-5e00-9487-91f6d4b5ef2e'::uuid, 'the_layover'::show_name, 2, 'Dive bar with games. No douches allowed', NULL, 'Season 2'),
  ('9b4b6e0d-7861-53d6-bfc1-f84d9a0f5a4f'::uuid, 'no_reservations'::show_name, NULL, 'Basque chef from Spain. Marmitako (seafood stew)', NULL, 'Restaurants and Bars'),
  ('9b6a264d-f4f5-5651-93af-4ccccd301b95'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with Heinz Grüne, beer expert, to have some kolsch, a style of pale ale created in Cologne. They ate a halve hahn, "Gouda cheese on rye" and Mettbrötchen, or raw minced pork on a roll. They also had himmel und erde (blood sausage, fried onions, mashed potatoes, applesauce), and cured pork', 'Season 7'),
  ('9b6a9d22-7c76-5bfd-a08b-40921aa253a3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had fresh seafood on the beach', 'Restaurants and Bars'),
  ('9b801944-f3e7-5517-8939-8aa05ef11ed3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Everyone told Tony he should do a sauna when he visited Finland. He did it while drinking beer and putting sausage on a grill. He also gets some treatment that causes you to bleed bad toxins out of your back. :/', 'Other Activities'),
  ('9ba444b7-5a79-550e-9a3b-d194da3ac741'::uuid, 'no_reservations'::show_name, NULL, 'Butter snails with chiles, freshwater crabs', NULL, 'Restaurants and Bars'),
  ('9bb8132f-78ae-56b5-bb39-f50c910075af'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony rode on the Sea Hunter, a sea scallop fishing vessel', 'Season 4'),
  ('9bd2171a-134f-5f61-82b6-95c1e8f5e844'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a meal on a boat to Vieques. They ate salted cod marinated in coconut milk and seared, root vegetables, escabeche, and avocado sala', 'Season 10'),
  ('9bf999ce-948f-5969-a33f-f1ad36e93ebb'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony headed out to this border agrarian town of only 9 families, to have a traditional supra. A supra is a Georgian feast. Tony ate with journalist Dima Bit-Suleiman, and Ushangi & Makvala Kokashvili. They had three varieties of khachapuri, a traditional cheese-filled bread, stuffed here with potato, beet leaves, or stewed cabbage; korma made from a roasted pig; homemade bread.', 'Season 7'),
  ('9c05bc90-711e-5ca7-82d2-4d31ddfdcba2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had traditional Laos whiskey (lao-lao) here in this town that translates to "Whiskey Village"', 'Sightseeing'),
  ('9c16b393-40ae-5199-973f-1cb3cd628b92'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had an oyster po’boy, crawfish étouffée, pecan pie, and beer.', 'Season 11'),
  ('9c2a24de-148a-5480-881b-2408fc0c32dc'::uuid, 'the_layover'::show_name, 2, 'Brunch everyday.', NULL, 'Season 2'),
  ('9c3ecca7-2200-5a6b-8b69-ed4d21b88444'::uuid, 'no_reservations'::show_name, NULL, 'French homestyle country cuisine', NULL, 'Restaurants and Bars'),
  ('9c5c3d3b-336a-5c21-9f20-3317e02c8541'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A century old market with fresh produce, seafood, locally made goods', 'Food markets'),
  ('9c876939-f268-588f-80da-5e2f6dc6b2a5'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony had his first fresh oyster out of the sea here, and he says it was life-changing', 'Disc 3: Europe'),
  ('9cd4cc9a-96ed-5936-b5d8-2dce201b32d6'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony got off the train here in Jaffna, a coastal city "as far North as you can go before you hit India."', 'Season 10'),
  ('9d405172-0abc-55f1-ab7c-ad7cc0d28c80'::uuid, 'the_layover'::show_name, 1, NULL, NULL, 'Season 1'),
  ('9d424c80-e1dc-563a-9aee-663dc2fed5dc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Whole families live in this old hotel, known as deslocados (the displaced). There are about 3,000 people living here', 'Sightseeing'),
  ('9d4b0b44-6c98-52b2-80c8-00010fb4eab6'::uuid, 'no_reservations'::show_name, NULL, 'Fish and chip shop', NULL, 'Restaurants and Bars'),
  ('9d524bd8-9f8a-5ac2-af20-95744f5ccf4a'::uuid, 'no_reservations'::show_name, NULL, 'Yoruba religious artifacts', NULL, 'Sightseeing'),
  ('9dda63f6-2088-5653-9760-c0b9e6259c57'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Home cooked Salvadoran meals. Tony ate here with Chef George Azar and friend Joe. They had tamales, pupusas, and shrimp with garlic butter.', 'Season 2'),
  ('9e0dfe9c-0ce0-5c97-9595-b1d715faf016'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went folk racing here in the snow in a VW Bug', 'Other Activities'),
  ('9e1c9315-2708-5747-898d-5d6c08d8da25'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Former location of L20, Laurent Gras'' seafood restaurant. Closed now', 'Restaurants and Bars'),
  ('9e27d045-bd8d-583d-b274-7342a3cf667c'::uuid, 'the_layover'::show_name, 2, 'Eat your pizza with a knife and fork for some reason', NULL, 'Season 2'),
  ('9e34637e-74a5-5175-8e17-739066ec9cdf'::uuid, 'the_layover'::show_name, 1, 'Coffee and marijuana cafe', NULL, 'Season 1'),
  ('9e374ea0-e93c-5e25-bd83-b6cf284ab6ca'::uuid, 'no_reservations'::show_name, NULL, NULL, 'German-style food and wines. This was his guide''s favorite place', 'Restaurants and Bars'),
  ('9e4bba48-d9ee-5248-aaf5-31be31740c38'::uuid, 'a_cooks_tour'::show_name, NULL, 'Fish stew', NULL, 'Disc 3: Europe'),
  ('9e5e8b79-bc1f-524c-a7d4-b2ffd275c547'::uuid, 'a_cooks_tour'::show_name, NULL, 'Tea in the hotel restaurant', NULL, 'Disc 6: Asia'),
  ('9e71fe1b-8756-5964-ae72-e15fb2ca8d1e'::uuid, 'the_layover'::show_name, 1, 'Beer', NULL, 'Season 1'),
  ('9e8bcc18-2276-526d-a1c2-480ecf700677'::uuid, 'parts_unknown'::show_name, 2, NULL, 'A mish mash of trinkets and souvenirs for sale, including Native American jewelry.', 'Season 2'),
  ('9e96c50e-8af9-516c-8518-39f5df67f01a'::uuid, 'the_layover'::show_name, 2, 'Hotel', NULL, 'Season 2'),
  ('9ea69037-740e-5818-b582-1ae9d5e89db7'::uuid, 'the_layover'::show_name, 2, 'Brasserie, the largest oyster house in Paris', NULL, 'Season 2'),
  ('9eb19876-6a5b-5d08-9f71-7d0e577bac02'::uuid, 'the_layover'::show_name, 1, NULL, 'Jon Jon Deragon (everything bagel with fried hot dog). Also got tater tots with nacho cheese dip. On the show there was a location on St. Marks next to Please Don''t Tell bar, but not on Google maps.', 'Season 1'),
  ('9ec11b05-ba34-5cc1-b2df-977c953cf8a7'::uuid, 'a_cooks_tour'::show_name, NULL, 'Churros and drinking chocolate', NULL, 'Disc 3: Europe'),
  ('9edcf9d2-2fe5-5d94-8cc1-02dca1ba9f57'::uuid, 'no_reservations'::show_name, NULL, 'Sushi', NULL, 'Restaurants and Bars'),
  ('9edf35dd-1196-5d2d-907d-7234fa87cfd4'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony had pan roasted mahi mahi in this local seafood restaurant', 'Season 5'),
  ('9ee64eb4-83ec-52f5-aa63-994aa55d692d'::uuid, 'parts_unknown'::show_name, 5, NULL, 'A sacred place in the community on Moloka''i, which is known as "The Friendly Place," but has a reputation for being unwelcoming to outsiders on other islands. They had slow roasted pig, grilled kala fish, mullet cooked lavalu style, octopus, poi, and freshwater clams from the mountains.', 'Season 5'),
  ('9eeae59e-38a3-5ee5-b336-1456d374bc6f'::uuid, 'no_reservations'::show_name, NULL, 'Hot dogs', NULL, 'Restaurants and Bars'),
  ('9ef46e9a-d7a8-5536-94e5-1904d1c80e5c'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Eric Ripert and mentor Maurice Guillot went to this wine & spirits store to purchase champagne, white burgundy, and cognac.', 'Season 10'),
  ('9f1ffc19-ef6e-5a95-befe-aeece9591c75'::uuid, 'no_reservations'::show_name, NULL, 'Authentic Greek food. Tripe soup, chickpeas', NULL, 'Restaurants and Bars'),
  ('9f27c8cf-f513-55e3-9875-97da474b79b4'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony visited a small town called Teotitlán del Valle and met Abigail Mendoza, a descendant from pre-Spanish Mexicans. She cooked a Chicken mole for him, using 35 kinds of chiles. The dish takes 2 weeks to prepare. She also made cow and pork brains cooked with chiles, tomatoes, and yerba santa.', 'Season 3'),
  ('9f538626-ca79-57ba-bb7e-26698f77d922'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and musician Harley Flanagan had a chocolate egg cream.', 'Season 12'),
  ('9f5b30bd-596a-548f-adf6-7d22778d5c48'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony had capirinhas, chorizo, and other snacks at this outdoor restaurant.', 'Season 3'),
  ('9f67990b-40f7-5032-af2c-7d9cc9f73d72'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, NULL, 'Disc 3: Europe'),
  ('9f738115-fe93-5f43-a540-597d9bcb7382'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Chef''s Claude Tayag home which is also a gallery, restaurant, and school. There are 4 kitchens. The chef prepared food in the outdoor kitchen.', 'Restaurants and Bars'),
