  ('a05eae90-ae66-545f-8a5e-d3a5fbadc289'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony spoke with street artist Yescka about revolutionary art.', 'Season 3'),
  ('a05f5397-f700-5410-95d6-31ac801c737d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Sonia Rican restaurant was here before; Closed now, Tony had mofongo there.', 'Restaurants and Bars'),
  ('a0692ca2-3a65-5267-a27c-6814afceaf58'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony watched bull sumo, or Tōgyū, while eating yakitori.', 'Season 6'),
