  ('a070ee75-1dfb-5099-9622-6b31ec14d3d5'::uuid, 'no_reservations'::show_name, NULL, 'Vineyard', NULL, 'Sightseeing'),
  ('a0b2dd8b-a831-5912-b524-f9f861ee9d9e'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had oxtail, curried goat, callaloo, rice and pigeon peas.', 'Season 4'),
  ('a0d1cc52-44ae-5148-b434-192d13a73f98'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a Manhattan, Negroni, and a Sidecar made by bartender Dale', 'Restaurants and Bars'),
  ('a1186d12-e3ee-5422-a142-7cadfaf8d024'::uuid, 'no_reservations'::show_name, NULL, 'A nice but discreet hotel in NYC', NULL, 'Lodging'),
  ('a1210768-91e5-5379-9d24-c3e822b631cc'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony ate at Chef Erica Connelly''s home with her family. She made lobster, coconut arepas, and conch salad.', 'Season 10'),
  ('a14d117d-eb2f-5a55-875b-603c35b2bf50'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate noodles for breakfast at a roadside stand in this town. He then took a lorry (a makeshift traincar made of stacked wood) and stopped at the Soys, a family on a rice farm living in a traditional stilt house. They cooked him chicken with shredded banana flowers, leben, and coriander. Sour beef stew with lemongrass, turmeric, fermented fish, and kantrop leaves. Sticky rice cooked in bamboo, and a dessert made from palm sugar.', 'Restaurants and Bars'),
  ('a1523e34-47b7-50f0-9ca4-9c1c654cd46d'::uuid, 'the_layover'::show_name, 1, 'Swanky dinner. Coat required.', NULL, 'Season 1'),
  ('a155e3b0-a0ef-5e5d-9414-3a7d0bc93488'::uuid, 'no_reservations'::show_name, NULL, 'Nachos were invented here', NULL, 'Restaurants and Bars'),
  ('a160e9f0-1926-5c3c-a0ea-9dae9765f7e2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Feather bowling: a Belgian feather bowling place with mussels and fries, and live music', 'Other Activities'),
  ('a174f80d-043a-5ba1-9fb8-15e51d42f60c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate Kibbeh, phyllo, Armenian cheese, spicy potatoes, meat & cheese filled pastries, hummus, stuffed grape leaves', 'Restaurants and Bars'),
  ('a192d8a5-4ed2-5482-874c-41ace0aa9157'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony visited Captain Bob who lives on a boat on this river.', 'Season 5'),
  ('a1b93aa2-7cce-568c-b5b1-7ddd8474f445'::uuid, 'the_layover'::show_name, 1, 'Whiskey and bitters emporium', NULL, 'Season 1'),
  ('a1bf5265-be7f-5667-aa6e-a4b3c154419a'::uuid, 'no_reservations'::show_name, NULL, 'The shiva festival is held here', NULL, 'Sightseeing'),
  ('a1e2177e-e9c0-5cd3-a561-d8225edbafab'::uuid, 'parts_unknown'::show_name, 4, NULL, '"Hacker turned entrepreneur Thomas Yao" met with Tony at this place, where they ate ziran paigu (cumin-rubbed ribs).', 'Season 4'),
  ('a2007a20-4eed-5dcd-ba1c-750c7d217230'::uuid, 'no_reservations'::show_name, NULL, 'Cuban food', NULL, 'Restaurants and Bars'),
  ('a2093294-6735-5988-9192-5286038f3c3e'::uuid, 'no_reservations'::show_name, NULL, 'Cheese shop', NULL, 'Food markets'),
  ('a2194d44-5674-5076-949f-a1bf465f9ac5'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The city center was reestablished once the drug cartels were driven out.', 'Sightseeing'),
  ('a223d41e-f52e-54e4-8ab0-db49e0dd7319'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went with a truffle hunting dog and its owner to find some white truffles in this mountain town. They then cooked with it.', 'Other Activities'),
  ('a23b6f6b-b883-5c0f-a5af-4fb46556e366'::uuid, 'the_layover'::show_name, 2, 'Pub', NULL, 'Season 2'),
  ('a25a623b-8135-5e76-a759-c9129d6dada0'::uuid, 'no_reservations'::show_name, NULL, 'A single prix fixe menu every day', NULL, 'Restaurants and Bars'),
  ('a2655ecf-9c9e-559e-976d-d46cc455a5af'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had pizza with the Hablan por la Espalda bandmates. They had pizza a caballo, or “a bizarro stoner hybrid topped with thin chickpea flatbread”', 'Season 11'),
  ('a26bc5a6-3776-565b-81f4-2d1500d4d104'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Used to be a soul food restaurant called The Harbor. Closed now', 'Disc 1: United States'),
  ('a27b745e-ac29-54fa-9e7e-793f235a0e08'::uuid, 'the_layover'::show_name, 1, NULL, 'High quality produce-driven dishes. Locally grown veggies from their farm on Vashon Island', 'Season 1'),
  ('a294b913-61f0-5355-9fac-328ebe6940fc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A liqueur made from morello cherries, ginjinha has been sold from this spot for 70 years', 'Restaurants and Bars'),
  ('a2be130a-69f6-5841-a830-8d8abd8bca08'::uuid, 'no_reservations'::show_name, NULL, 'Dim sum!', NULL, 'Restaurants and Bars'),
  ('a2ca9d18-b5cf-53c4-b16c-5c03df6c8585'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Traditional country style Russian food. Russian dumplings, potato pancakes, cabbage', 'Disc 4: Morocco & Russia'),
  ('a2edc0c3-038e-5e9a-98d5-c0371238fba9'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Asia went shopping here for a lunch her sister prepared for them. They bought fava beans, cheese, and other goodies.', 'Season 8'),
  ('a3253632-1fa5-5a39-9ec1-d349aae21f66'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony crashed a holiday party here, the Seven Continents Travel & Tours corporate Christmas party. They had lechon, a whole pig roast pork that is traditional during the holidays.', 'Season 7'),
  ('a33c7d70-e60e-59a7-b72f-a9f9037e3be8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A high end resort in quiet countryside, "where one lives, and eats, and meditates on a tree or the movement of water over rocks for a couple of days… you lose all sense of time." The innkeeper also served robatayaki', 'Sightseeing'),
  ('a376b4fe-2802-5778-883d-eb093dc9fe18'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited a home on this island. Octopus and octopus stew, pico wine, moray eel, locally raised potatoes, local tuna cooked on an open fire.', 'Other Activities'),
  ('a3dc371f-378b-542f-89d4-73867d4f0986'::uuid, 'no_reservations'::show_name, NULL, 'Fresh seafood, lots of shellfish', NULL, 'Restaurants and Bars'),
  ('a4121145-eed6-5b20-98d6-4531b55b22d3'::uuid, 'no_reservations'::show_name, NULL, 'This place is a 24-hour restaurant known for their dumplings', NULL, 'Restaurants and Bars'),
  ('a46a7b78-9322-5bcc-a54c-33b40ef899dc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate steamed shark head and chili crab.', 'Restaurants and Bars'),
  ('a47481b4-42e7-58e5-8ce4-54d0faa5a0dc'::uuid, 'the_layover'::show_name, 1, 'Pizza', NULL, 'Season 1'),
  ('a4a3b455-634d-5368-b39e-dfe4688f23f4'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony met with journalist Patrick Lagacé at this restaurant (closed in 2016). They discussed "pastagate" which is the scandal that happened when a restaurant got in trouble for using the word "pasta" which is Italian', 'Season 1'),
  ('a4b8cbbf-05cf-54bd-844a-ae98744a611f'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony went on a canoe tour on the Mississippi River.', 'Season 3'),
  ('a4be7ad4-d558-586f-8ee7-f543fdcb3f71'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony ate here with comedian Paul Jurewicz. They had beef tartare, roasted bone marrow, tete de cochon with blue cheese and celery relish, confit of beef tripe, slow roasted cauliflower with caramelized onions and lentils.', 'Season 7'),
  ('a4be7ad4-d558-586f-8ee7-f543fdcb3f71'::uuid, 'the_layover'::show_name, 2, 'Young and hip, affordable hotel, 38 whiskeys at the bar', NULL, 'Season 2'),
  ('a56aa804-6c46-5df3-8923-d0b943ca7cda'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had hatch chilies. He had a red and a green enchilada. He preferred the red. He said it was the best red enchilada he ever had', 'Restaurants and Bars'),
  ('a5922eb1-e8c4-526a-ad67-66338a5f0524'::uuid, 'the_layover'::show_name, 1, NULL, 'Inside the Carlyle Hotel. Super fancy but everyone should go once in their life.', 'Season 1'),
  ('a59461fd-7a19-54bc-994a-1daa94c8e7d6'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony and Zamir had a meal with Boris Nemtsov, one of the main critics of Putin, who served as an advisor under Yeltsin (he has since been assassinated in 2015, and this restaurant is now closed).', 'Season 3'),
  ('a59ea576-ca1f-52d6-a7e4-f55a9e001c66'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A chef Tony calls the pioneer that put Melbourne on the map as the food capital of Australia. Local snapper sashimi, lough oysters, yellowfin tuna with caramelized pork belly and watermelon, freshwater lobster.', 'Restaurants and Bars'),
  ('a5a345da-8d9d-562f-bc1f-420d5980869e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This is where the crew and Tony are staying but he raved about how great the food is in the hotel, and he normally hates hotel food', 'Lodging'),
  ('a5a345da-8d9d-562f-bc1f-420d5980869e'::uuid, 'the_layover'::show_name, 1, NULL, 'Fancy hotel where Bourdain stayed. They have street food inside the hotel.', 'Season 1'),
  ('a5adb60e-41d6-5277-b7a2-505822bf572d'::uuid, 'parts_unknown'::show_name, 9, NULL, 'A Nigerian restaurant in Jamaica Queens, with chef Blessing Osagiede running the place. Tony ate here with Sarah K. Khan, a food & culture writer, filmmaker, and photographer.', 'Season 9'),
  ('a5c4a0ae-877a-5edf-959c-83ae5e688c87'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This chicken joint is super popular. Rotisserie whole chickens roasted over charcoals. They use spices from Peru', 'Restaurants and Bars'),
  ('a6130d78-d1b9-5736-8119-4e31b890f90b'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had fish & chips with Astra Elane and Dustin Patterson, members of local band The Gods Themselves.', 'Season 10'),
  ('a6274c37-5015-5d79-82a0-b5a4f333280f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate street foods', 'Food markets'),
  ('a6369046-c644-51fc-b7a5-3514ad0e361d'::uuid, 'the_layover'::show_name, 2, 'Masters of the soup dumpling. This is a must try.', NULL, 'Season 2'),
  ('a6394c45-6e29-5f28-8c42-fe4d5332cf65'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited Ponce for the Fiesta of Immaculate Conception (held in December). Street food.', 'Sightseeing'),
  ('a63e63e5-7e63-5430-bf53-056f01b4d806'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony had a meal cooked by Zora Santos, "a practitioner of old school Afro-Mineira cuisine." They had angu (cornmeal and milk cooked for hours), ora pro nobis (a native green, filled with protein), pork ribs.', 'Season 8'),
  ('a6541967-9b38-579a-9bcd-922cc17fd9a1'::uuid, 'a_cooks_tour'::show_name, NULL, 'Tagawa Sushi', NULL, 'Disc 5: Australia and Japan'),
  ('a6621ab9-b43b-5348-8807-f8c2a56ddd15'::uuid, 'the_layover'::show_name, 2, 'Snakes', NULL, 'Season 2'),
  ('a6765bdb-cfbc-5128-b6f8-f6857e1b8b33'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony and Darren took a very old train to Manakara.', 'Season 5'),
  ('a68806db-5803-511b-baf8-bfac91112d07'::uuid, 'the_layover'::show_name, 2, 'Bowling, music, drinks', NULL, 'Season 2'),
  ('a6f64421-226e-5f70-858d-2ea2af309f12'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Lots of internal tourism for these crabs which is prized for being the best in China', 'Restaurants and Bars'),
  ('a6fdbc5f-7076-5b01-9ad1-8e1316b5ad03'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony''s local bar (at the time of filming season 2)', 'Restaurants and Bars'),
  ('a74a34d9-d657-5a72-baa2-88764e62deef'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony was made into a video game character', 'Other Activities'),
  ('a75a69c5-aabb-5e0a-bec8-8008e109aa94'::uuid, 'the_layover'::show_name, 1, 'Craft beers and wines. Laid back and mellow.', NULL, 'Season 1'),
  ('a7ab0446-9b2b-5807-89af-e12f194ef914'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Eric visited this restaurant run by Chef Pedro Escofino, highlighting Peruvian ingredients. They started with a lime cocktail with culantro; breadfruit with tuna and cashew sauce; scallops with wild almond and freshwater shrimp dashi; Inchcape soup made of ham, peanuts, and corn; patarashca (catfish wrapped in leaves and cooked on hot coals); paiche (a type of fish from the Amazon River) atop a palm fruit purée with a fermented yucca sauce and a chili pepper sauce made with nuts and ants. Eric did not like the ants.', 'Season 1'),
  ('a80500e7-564e-5e10-86b2-57b3c3bfd2dc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Roast pig located across a monument to Trujillo. They break down the pig with a machete.', 'Restaurants and Bars'),
  ('a80bc388-a4f6-5ae5-a61d-1ea301d52190'::uuid, 'parts_unknown'::show_name, 10, NULL, '"The oldest Peranakan restaurant in Singapore, predating independence." They had a Laotian dish called ikam asam nana, a sour fish curry with pineapple; itek sio, a duck braised in tamarind and coriander; and okra sautéed with sambal.', 'Season 10'),
  ('a8260344-0ebc-555a-a917-899070ba6426'::uuid, 'no_reservations'::show_name, NULL, 'Doner kebab in a pita.', NULL, 'Food markets'),
  ('a831e33a-8fe1-59b4-ab8c-14bed10a2a7e'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Bar #2 for Tony, Zach, and Fuen. They had mussels steamed in butter and olive oil.', 'Season 2'),
  ('a8662084-86a1-57e1-b060-9fe45e6a2385'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Hawker center. Stretch tea. A pocket of dough filled with minced lamb, onion, egg.', 'Disc 6: Asia'),
  ('a86cfe14-e8d4-5cff-983a-15baa3660d43'::uuid, 'no_reservations'::show_name, NULL, 'Laksa!', NULL, 'Restaurants and Bars'),
  ('a86cfe14-e8d4-5cff-983a-15baa3660d43'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony calls Sarawak laksa "a magical dish," it has chicken, prawn, coconut, chili, and noodles in a complex broth. “Best breakfast ever.”', 'Season 6'),
  ('a8768423-f3cf-5c61-a0a2-7c8c75564124'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony visited the Minneapolis location on the show, but it doesn''t appear to exist anymore', 'Disc 1: United States'),
  ('a879acfe-72c6-5b18-a9a6-ec3e7fb0ee3f'::uuid, 'parts_unknown'::show_name, 6, NULL, 'After a very long plane ride, Tony had char kway teow (dish made with rice noodles), spicy pork noodles, black pepper crab, beer.', 'Season 6'),
  ('a8cda4c9-8a73-5b48-94ba-30604eaaa379'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with legendary cookbook author Nigella Lawson to have some Scotch eggs, whitebait ("tiny baby herring lightly battered whole and fried, tossed with a little bit of lemon juice and salt"), fries, and Guinness.', 'Season 8'),
  ('a8e3316f-7513-5791-bcaa-c165957c4782'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony, Marcus, and Maya went to this small village where Maya grew up. They were served coffee. Later they had a feast where they barbecued 2 goats.', 'Season 6'),
  ('a902b257-71a0-53b7-bbe1-989d35b06a59'::uuid, 'the_layover'::show_name, 2, 'National dish of Taiwan: Beef Noodle soup', NULL, 'Season 2'),
  ('a90b0178-b7af-5d31-bf2a-39d45a679715'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('a9250565-7c8e-5ef3-8a3d-ae0b65ed912a'::uuid, 'no_reservations'::show_name, NULL, 'Public Sewer Museum', NULL, 'Other Activities'),
  ('a92c023c-7d35-5ec6-a4c3-ae78269d704b'::uuid, 'the_layover'::show_name, 2, '36 taps and 700 bottles', NULL, 'Season 2'),
  ('a92e21c2-41ed-5374-b31a-2a62b9346f7b'::uuid, 'the_layover'::show_name, 2, 'Watermelon cocktail!', NULL, 'Season 2'),
  ('a954a963-0dca-532d-ad17-c06446ba6b14'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met the owner, Mac Klein, who was 100 years old in 2014 (he died in 2016).', 'Season 5'),
  ('a954a963-0dca-532d-ad17-c06446ba6b14'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony always comes here after he gets a tattoo across the street. It is a dive bar.', 'Season 1'),
  ('a96b4025-ba11-5343-831c-ace09102d8ba'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had a beer with a Trump supporter to try to understand why they voted for him.', 'Season 11'),
  ('a96c37b8-28ca-5c69-adad-72e8bf71822a'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('a9801fa9-e4f5-566b-80bf-0fafb4586d6b'::uuid, 'a_cooks_tour'::show_name, NULL, 'Live poultry, food stalls, produce, other goods', NULL, 'Disc 6: Asia'),
  ('a9801fa9-e4f5-566b-80bf-0fafb4586d6b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Breakfast in the market: Hoi An noodles, slices of pork with pork skin, pickled garlic', 'Restaurants and Bars'),
  ('a982aaa6-a49f-5ee4-8079-a7fb945ce31d'::uuid, 'no_reservations'::show_name, NULL, 'All you can eat whole hog BBQ.', NULL, 'Restaurants and Bars'),
  ('a996b560-1940-5a67-b935-6e52779a6efc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had drinks here and played darts', 'Restaurants and Bars'),
  ('aa435ec5-5f6b-54e2-b075-e8d04f7c9f03'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This restaurant no longer exists, but it was a traditional Ecuadorian restaurant', 'Restaurants and Bars'),
  ('aa47837c-0851-520b-b955-16bc8e750586'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The restaurant where the chef made the chili oil typhoon crab', 'Restaurants and Bars'),
  ('aa797995-b53b-56a0-994b-22d42677dbc1'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony visited Mitchell''s BBQ which is now closed. This is the newer spot.', 'Disc 1: United States'),
  ('aa9f1d65-8272-50de-b162-fe5982fe1828'::uuid, 'parts_unknown'::show_name, 1, NULL, 'A large market, where Tony met with a guide to have some fresh carrot and orange juice. They also ate corn arepas. In the back corner of the fish market, they had Caldo de Costilla, a traditional breakfast soup from the Andean region, which has beef short ribs in a broth with potatoes and scallions.', 'Season 1'),
  ('aabb7b05-9624-5d82-8ea0-f6f802474eee'::uuid, 'no_reservations'::show_name, NULL, 'Truck stop restaurant with great food.', NULL, 'Restaurants and Bars'),
  ('aadbedf2-214b-56da-af55-cd6c42a3d526'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony had a meal with Abel Ferrara, film director known for Kings of New York and Bad Lieutenant, who now lives in Rome with his family. They had Roman pastas, snails, and artichokes.', 'Season 8'),
  ('ab1a99d4-0f0f-5211-a56e-ed7179a9cbc0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A restaurant many chefs meet at for after shift meals. Mud crab with ginger and shallots, batter fried lobster with Sichuan peppercorns.', 'Restaurants and Bars'),
  ('ab1f2f49-c111-50ab-984c-925197881544'::uuid, 'the_layover'::show_name, 2, 'Mediterranean food', NULL, 'Season 2'),
  ('ab55d965-b914-5897-96e1-b45413569dfc'::uuid, 'a_cooks_tour'::show_name, NULL, 'Chicken with Chinese herb broth, served with fried baguette', NULL, 'Disc 6: Asia'),
  ('ab707ff8-5d3b-50dd-971f-1ec83d0bb25d'::uuid, 'the_layover'::show_name, 2, 'Coffee', NULL, 'Season 2'),
  ('ab7169c2-6093-502c-a59a-84580a19b875'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Some kind of weird game with a donut puck and a mallet like croquet', 'Other Activities'),
  ('ab769a92-5d5f-5df8-853d-f294e07f9e97'::uuid, 'parts_unknown'::show_name, 2, NULL, 'A butcher that sells biltong, a salted dried meat. Afrikaner paraphernalia hangs in the shop, which bothered Tony. For restaurant, you can go to the meat counter and order cuts of meat with "monkey gland sauce" on the side (barbecue sauce).', 'Season 2'),
  ('abdf6573-332d-505e-ad8f-1760e27854ce'::uuid, 'the_layover'::show_name, 2, 'Graffiti art for miles', NULL, 'Season 2'),
  ('abf3fb2e-8f78-56cd-aac2-a998534d4acd'::uuid, 'no_reservations'::show_name, NULL, 'Goat offal prepared many ways. Sinigang was served', NULL, 'Restaurants and Bars'),
  ('ac03eca4-66b7-597c-ba5f-5e1dbcd6a5c8'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with rock star Mark Lanegan (from Queens of the Stone Age, and also the person who wrote the theme show of Parts Unknown). They had tapas and drinks.', 'Season 10'),
  ('ac171819-164b-5136-9f3e-6e3730f62cb7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony stayed here, the hotel is rumored to be haunted. Someone jumped off the roof and haunts all the rooms on the way down (all floors with rooms ending in "03")', 'Lodging'),
  ('ac2f2621-4452-5ad5-abac-ef9ece0a0724'::uuid, 'the_layover'::show_name, 2, 'Monument to explorers', NULL, 'Season 2'),
  ('ac31c176-7ba7-500d-bb3d-acde0094e3ab'::uuid, 'a_cooks_tour'::show_name, NULL, 'Traditional English cuisine', NULL, 'Disc 3: Europe'),
  ('ac31c176-7ba7-500d-bb3d-acde0094e3ab'::uuid, 'the_layover'::show_name, 1, NULL, 'One of Tony''s favorite restaurants in the world', 'Season 1'),
  ('ac548702-3cfa-555e-8717-3f19f5922b9c'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Coque Ossio, one of the most successful chefs in Peru, spends weekends in Pucusana, a small fishing village. His mom, Marisa Guiulfo, is like Peru''s Julia Child. They made food and pisco sours for Tony and Eric Ripert. Marisa opens the house every weekend for a large group to visit and eat.', 'Season 1'),
  ('ac66b773-3fec-5c26-bd6f-1e5a9095e436'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Zamir went to a restaurant on this street called Le Borsch. It is closed now, the place had 5 kinds of Borscht and Tony had the green borscht.', 'Restaurants and Bars'),
  ('ac68df7e-e153-5804-99cd-7b5304532a56'::uuid, 'the_layover'::show_name, 2, 'Tator tots and beer', NULL, 'Season 2'),
  ('ac6c3edf-1b7c-51d8-88fd-159efe2d7747'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony had drinks with poet and activist Javier Sicilia.', 'Season 3'),
  ('ac7aac3d-d771-5ffd-a74b-70f7a881c786'::uuid, 'the_layover'::show_name, 2, NULL, 'Hu Jiao Bing. Pork buns with peppers in a baked flour dough baked in a clay oven.', 'Season 2'),
  ('ac8f82b9-927d-5760-b6af-f37cdc37e2a0'::uuid, 'parts_unknown'::show_name, 2, NULL, 'A backyard BBQ serving soul food. Tony had smoked pork loaded collards and mac & cheese.', 'Season 2'),
  ('aca0c57e-bb3e-5674-abd5-d7a3cc3847a9'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony and author Curt Fukuda discussed how the Japanese internments during WWII while eating tempura and Japanese curry tonkatsu.', 'Season 6'),
  ('acab4019-e3cf-5615-9d65-20d975de6ea7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The crew are scolded by the guide for spooking the elephants, which is very dangerous.', 'Other Activities'),
  ('acb1f01f-f268-5ed5-a270-1fc4ce497d0e'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony ate at a small food stand near the Bagan Palace ruins and called it the best restaurant in the country so far. He had chicken curry and raved about all the small accompaniments served.', 'Season 1'),
  ('acc1e23d-67da-5ef0-8906-6fa3c8ac9824'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had beers here with Tech journalist Artur Papayan, developer Harut Martirosyan, and cybersecurity consultant Ruben Muradyan.', 'Season 11'),
  ('acc3c3f7-8c5a-54d6-a6a5-47ab0469b0c5'::uuid, 'the_layover'::show_name, 1, NULL, 'The world’s first Michelin-starred Peranakan restaurant, Candlenut takes a contemporary yet authentic approach to traditional Straits-Chinese cuisine', 'Season 1'),
  ('acce1888-510a-5e98-9148-e9045d31d1c1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A very special bookstore with endless shelves of books. Tony visited with Harvey Pekar, comic book writer of American Splendor fame', 'Other Activities'),
  ('acd2697e-2b91-5264-bf76-109adf4ab283'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with Masa''s high school friends and had a soak in the hot spring, then ate sukiyaki (meat slowly cooked, tableside, in a broth), Tochigi beef with maitake (type of mushroom), and home-brewed sake', 'Season 8'),
  ('acfdfeca-0bda-5098-b15e-0b24fc7fc9e7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony craved sea urchin and salmon roe.', 'Restaurants and Bars'),
  ('ad698b93-598f-5d08-b6d2-6487bc1b7121'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate here with Zamir and a food blogger. The blogger says this is the best place to get BBQ in the city. It was called Oklahoma Joe''s when they attended. Tony loves the ribs and burnt ends.', 'Restaurants and Bars'),
  ('ad6af49e-0c0e-57d5-8e63-690684acf825'::uuid, 'the_layover'::show_name, 2, 'Great selection of whiskeys', NULL, 'Season 2'),
  ('ad834620-1876-5d6f-846f-5244f50baf7a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'At 8 am, the men gather and eat charcuterie, bread, and cheese and drink red wine', 'Restaurants and Bars'),
  ('adb86c88-2ff7-5d3e-a1f6-4c5da24cecfa'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had shekla tibs, which are chunks of fried beef or lamb served in a clay pot with Ethiopian skateboarders and Marcus Samuelsson.', 'Season 6'),
  ('adf50918-8465-5710-9702-c70af845aa74'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had dinner with chef and owner Lucía Soria and Nacho. They had "homemade gnocchi with mushrooms and pumpkin; prawns with avocado, apple, and wasabi; beef tartare with quail egg."', 'Season 11'),
  ('ae53fdd6-2a74-59a2-952f-7aa25bd2f9eb'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony ate a burger', 'Disc 1: United States'),
  ('ae87d467-c996-54ef-b9f1-0e1fd958cd4e'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('ae97a529-9a49-51f3-a246-7b909c769360'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Roy Choi''s Korean taco truck. Tony had the Kogi short rib taco, a Korean barbecue short rib on corn tortilla with salsa roja, cilantro, and onion, slaw, and a chili soy vinaigrette.', 'Season 1'),
  ('ae97a529-9a49-51f3-a246-7b909c769360'::uuid, 'the_layover'::show_name, 1, 'Korean tacos', NULL, 'Season 1'),
  ('ae9d2d59-cd16-5179-94dc-b2732e6cd12c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Originally created for "shanghais" which were when men were kidnapped and sold to pirate ships to work', 'Sightseeing'),
  ('aec6867a-d2a9-5735-9c62-6fcc17044b86'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had spicy pepper soup with journalist Kadaria Ahmed', 'Season 10'),
  ('aecc0935-51fb-52fb-83ea-f61a2e12a20e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Open 5pm to 2am. Food market selling many different foods. Tony''s guide buys different ingredients from the street food vendors and assembles a plate with roast pork, spinach, beans, and rice.', 'Food markets'),
  ('aed3d0a2-243e-52f0-aa81-ba40c578922a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'In this episode about food obsessions, Tony met with Josh Ozersky (who died in 2015) to try the La Frieda black label burger. Ozersky was obsessed with beef.', 'Restaurants and Bars'),
  ('aed3d0a2-243e-52f0-aa81-ba40c578922a'::uuid, 'the_layover'::show_name, 1, 'Priciest burger in NYC', NULL, 'Season 1'),
  ('aeda545b-909e-5644-a5c3-78d46be3e988'::uuid, 'no_reservations'::show_name, NULL, 'Bun Cha (noodle dish with grilled meats)', NULL, 'Restaurants and Bars'),
  ('af2ccaf1-9f7b-5340-bbdb-97109cfcbcc4'::uuid, 'the_layover'::show_name, 1, 'Michelin starred modern dim sum restaurant.', NULL, 'Season 1'),
  ('af364a7d-0046-5945-a67c-e2e1721df084'::uuid, 'no_reservations'::show_name, NULL, 'Lunch counters and eateries across from the market.', NULL, 'Restaurants and Bars'),
  ('af3fe8dd-e0c1-5fab-a15c-940582455c33'::uuid, 'the_layover'::show_name, 1, 'Bar with pool tables', NULL, 'Season 1'),
  ('af503389-5f90-5664-bbac-3029d5b6523f'::uuid, 'a_cooks_tour'::show_name, NULL, 'Center of Moroccan cuisine', NULL, 'Disc 4: Morocco & Russia'),
  ('afadf944-2711-51d5-837d-70835a16d40f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Payan Especial: Pork with tomato, mustard, and cheese, heated in a sandwich press. A drink made with orange juice and condensed milk.', 'Restaurants and Bars'),
  ('b01ff974-93c9-5736-a56f-e9af141250a7'::uuid, 'the_layover'::show_name, 1, 'Halibut and avocado at the airport', NULL, 'Season 1'),
  ('b0419e29-8e0c-5c24-a5e6-5dc0cf250a3f'::uuid, 'no_reservations'::show_name, NULL, 'Roasted pork', NULL, 'Restaurants and Bars'),
  ('b080f90a-5f7b-5e20-a602-8a245be5a021'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Watched ram fights. Visited the snack bar and had some nasi goreng (Indonesian fried rice)', 'Other Activities'),
  ('b081a848-e8d2-5cbd-88e3-cc95e7631185'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony hung out with Joe Coleman, performance artist', 'Season 12'),
  ('b092bcfe-11e8-5623-82c0-ab91dd692455'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony visited this cooking lab and met with Nathan Myhrvold, author of a book Modernist Cuisine. They had baba au rhum in a jar, and a bagel.', 'Season 10'),
  ('b0c79373-3891-5aef-afab-e06257d4be6f'::uuid, 'a_cooks_tour'::show_name, NULL, 'Coffee and hookah', NULL, 'Disc 6: Asia'),
  ('b0d9b02d-422f-5d8e-9b2e-31c12ed11906'::uuid, 'no_reservations'::show_name, NULL, 'Avant garde restaurant. Part chef, part mad scientist.', NULL, 'Restaurants and Bars'),
  ('b0de7d29-c8fe-5239-ba90-481777137805'::uuid, 'the_layover'::show_name, 2, 'Swanky cocktail bar', NULL, 'Season 2'),
  ('b0e5f659-bf68-5aa5-ad49-2c684ddd87ca'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony, Marcus, and Maya had tej, a light alcoholic drink made of fermented barley and honey', 'Season 6'),
  ('b0e985d2-c3dc-5475-9d36-ad6af19a3cdb'::uuid, 'parts_unknown'::show_name, 10, NULL, '"More like a house party with food," than a restaurant, says Tony. They had chicken paprikash, lángos (Hungarian fried bread), kolbasz (Hungarian sausage), cucumber salad.', 'Season 10'),
  ('b10b6bef-5edd-524d-aa5a-661dcace2b51'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Local cheese shop. Tony''s chef friend made uvo raviolo.', 'Food markets'),
  ('b10d30fa-7f72-59c3-b65d-04664f6b3136'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony ate at this chef''s country home', 'Disc 5: Australia and Japan'),
  ('b16bc886-d37d-596b-a5b8-ebd03d31f639'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with the chef, Margo Henderson. They had wine, peas in their pods, radishes, vitello tonnato, Welsh lamb chops with lentils and green sauce.', 'Season 8'),
  ('b172da2a-f665-59d2-9fad-afbee88c18f6'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony visited during Tet, the celebration of the Lunar New Year. He ate at many stands that were put up to celebrate the end of a fast.', 'Disc 6: Asia'),
  ('b17dd08d-556f-5e75-bcc6-8ad351fc2074'::uuid, 'the_layover'::show_name, 1, 'Cheap supplies for the kitchen', NULL, 'Season 1'),
  ('b1890229-ced6-51dc-8920-7c0e649c3f31'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony tried the hottest version of Nashville Hot Chicken (and paid dearly for it later). He ate with Allison Mosshart of the band The Kills and her brother Matthew, a chef. He said he had a 12-hour "existentially awful experience" after eating the chicken.', 'Season 8'),
  ('b18b1478-70ad-5c84-9302-2cb3923c3633'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The name translates to "Where''s the little fat guy." Corvina, a local fish, is cooked in a creamy king crab salpicon', 'Restaurants and Bars'),
  ('b18d5e2d-b38c-5aea-8d30-f807151acde8'::uuid, 'the_layover'::show_name, 2, NULL, 'Red Hots are Tony''s favorite hot dog in the world', 'Season 2'),
  ('b1ae0a85-e21d-5332-8c2f-fb9a127b0533'::uuid, 'no_reservations'::show_name, NULL, 'Bar and hangover food. The chili is the specialty.', NULL, 'Restaurants and Bars'),
  ('b1d2cee8-3970-52ca-9aa9-8f2a7b8e871d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony was hungover from eating manicou stew (opossum stew) on the beach and drinking strong rum. He ate here the next morning: Caribbean Conch Curry, Souse soup', 'Restaurants and Bars'),
  ('b21ae1c3-c0ec-5c4b-a956-d784fe29d903'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony had a tuna bocadillo here: Spanish style sandwiches with tuna, veggies, and hard-cooked eggs, a healthy wad of mayo, and a crispy layer of french fries in the sandwich.', 'Season 1'),
  ('b23d9ca0-2236-5f7b-980a-1074d84f6f43'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony and Andy ate fried frog with crunchy fried garlic.', 'Season 3'),
  ('b27efbe1-de48-5af0-baec-fe1d045e40b5'::uuid, 'the_layover'::show_name, 1, 'Island with no cars. Only boats and bikes', NULL, 'Season 1'),
  ('b2a87ab5-62a4-5b78-9a41-fae0d61aee56'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They went here to find acai berries.', 'Other Activities'),
  ('b2ca0368-1f3e-5bac-8e0a-a484b3324c82'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony watched a soccer game at Mawilies Inn (could not find on the map) in Soweto, a suburb of Johannesburg. The town name derives from an abbreviation of Southwestern Township. They ate lamb''s head; mieliepap (sticky porridge made from maize); stewed beef, dumplings, stewed greens, carrots, beans, gravy.', 'Season 2'),
  ('b32a86f0-99cb-5d3e-a4d5-f1e987da7ea4'::uuid, 'no_reservations'::show_name, NULL, NULL, '"Street by day, food wonderland by night." Tony had Char Koay Teow, a fried rice stick with bean sprouts, chili, and prawns.', 'Food markets'),
  ('b33adba9-fdaf-5039-a203-9b60c4689056'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A local favorite. Modernizing traditional Portuguese food. They started with seafood: Barnacles, shrimp, crab, clams, they ended with the steak sandwich.', 'Restaurants and Bars'),
  ('b36f64ff-0328-553c-8503-9b7425ecd4cb'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony and his best friend Eric Ripert ate at this outdoor cafe.', 'Season 6'),
  ('b3723001-8f55-577c-a62f-21c636868b27'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had a meal with Miray Girt, who was born in Spanish Basque country but raised in France.They discussed the differences between French and Spanish Basque foods. They had "ventrèche de thon, or tuna belly with tomato carpaccio; pigeon, roasted and then flambéed, served with a terrine or pâté of the same bird."', 'Season 9'),
  ('b37d5277-e7ae-53fe-af40-cf90e3f8077d'::uuid, 'the_layover'::show_name, 2, '80s night; old movie theater turned into a performance space', NULL, 'Season 2'),
  ('b37da4a7-b0a6-5b4b-8729-c63e87ef81c0'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with a Hawaiian journalist, Daniel Ikaikaito. They had a plate lunch, a Hawaiian specialty of a protein with white rice and potato-mac salad. They ate theirs with chicken katsu, hamburger steak in “sinister” gravy, seared ahi with nori and sesame seed.', 'Season 5'),
  ('b38a753e-eb84-50d8-a93d-999948f06a5b'::uuid, 'no_reservations'::show_name, NULL, 'Sandboarding in the Namibian desert', NULL, 'Sightseeing'),
  ('b3ac0364-a08b-5608-a55e-a386dfebc69a'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony and the canoe guide stopped here to cook food on a fire.', 'Season 3'),
  ('b3bfb8ff-3820-544a-a9b9-1e8d1dd9a6b5'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had lunch at this local rice and curry joint with Kumar Lopez, CEO of Sri Lanka Press Institute, a news trade organization. They had chicken curry, spicy potatoes, beets, and rice.', 'Season 10'),
  ('b3dd1b58-bfc4-5b1c-9aae-9d5c7105c3c1'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony''s dinner guest, English teacher Bill Wang, says this is the best place to get wontons. Minced pork, bok choy, rice wine in a wonton dough, served with a mixture of soy sauce, vinegar, chili sauce, sesame oil, and peanut butter. "YOU NEED THIS," Tony exclaims.', 'Season 4'),
  ('b3f13a4b-6049-53e7-94c9-d0b708663811'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony met with Billy Wagner, co-owner of Nobelhart & Schmutzig at this movie house for currywurst and fries, doner kebab, sparkling wine, and red wine.', 'Season 11'),
  ('b40e865e-f455-5c7f-b5a8-54aa76265a0a'::uuid, 'no_reservations'::show_name, NULL, 'Oscar Wilde died here', NULL, 'Lodging'),
  ('b411a5c5-3828-5b33-9bf7-00885a228ca5'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony went horseback riding in this area near where Georgia O''Keeffe spent her last years. Bourdain helped with a red canyon cook-out.', 'Season 2'),
  ('b415e749-00e5-5e2d-8d53-7464118764c6'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a meal with the Hollingsworths, from the cannabis farm. They had Lebanese food here: "baharat spiced beef and lamb kabobs, fried cauliflower with tahini, a summer fatteh with local squash and charred tomatoes topped with sizzling brown butter and pine nuts; sweet and sour rice wrapped in grape leaves; hummus."', 'Season 10'),
  ('b440824a-d360-5c73-9ca7-a6b34b23ca92'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Martinis and cioppino. Also hangtown fry: oyster, eggs and bacon.', 'Restaurants and Bars'),
  ('b51049fd-1761-5684-8c1e-f71b3a3d792f'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Sightseeing'),
  ('b57273e0-d9df-5464-bb37-eb26999dab86'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Casual restaurant using local ingredients and growing herbs and veggies on site. "A woodburning oven is central to the rustic menu: flatbreads, slow roasted lamb, and grass fed beef."', 'Restaurants and Bars'),
  ('b5836697-dd02-5896-bdf7-008ce0b562f7'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony grabbed beer here after a shift at Les Halles.', 'Disc 1: United States'),
  ('b5836697-dd02-5896-bdf7-008ce0b562f7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had an after lunch rush drink here before he tackled dinner service', 'Restaurants and Bars'),
  ('b5a845b1-c259-52b3-9e0f-a979423717f7'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony went for dim sum with Janice Lau and Jason Cheung, members of Hong Kong punk band David Boring.', 'Season 11'),
  ('b5cf5509-2255-5cd0-a6ff-7912cc4c6c97'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Maple bacon latte. Also a radio station where Tony did an interview. Closed down now.', 'Restaurants and Bars'),
  ('b5ed1517-0a7c-5128-b2b2-76b5a160e367'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with Janey Godley, a comedian, and had Scottish oysters and lobster thermidor', 'Season 5'),
  ('b5ed5061-6f89-5565-9f97-c83ed58d6fe1'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony ate bear meat in a coal mine with miners.', 'Season 11'),
  ('b612b5bb-6863-5625-8dad-b513e6b39881'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Eric''s dream as a kid was to work as a park ranger, so they met with a lady named Sonia Popoff who does this for a living. "She''s who you call when things are really bad," says Tony. They rescue skiiers who injure themselves on the mountain.', 'Season 10'),
  ('b615fc97-3614-54b1-a4e9-19848fc5bb68'::uuid, 'the_layover'::show_name, 2, 'Irish music', NULL, 'Season 2'),
  ('b647407b-1fd1-5610-a6b6-7478608c8ca6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Lebanese food. Babaganoush, hummus, taboulleh, kibbe, fresh bread', 'Restaurants and Bars'),
  ('b65f6984-f86c-50ed-bfd9-eff7e21ac0ad'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony and Chef Biryong make budae jjigae on his TV show called Mukbang.', 'Season 5'),
  ('b66562a5-b012-501d-a48e-57ecfa2555c5'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony ate with Dr. Ravi Perumalpillai, his sister Jeeva Perumalpillai, and Punitham “aunty” Selvadura. The aunty made crab curry.', 'Season 10'),
  ('b669b6d0-4f35-565d-9985-3d8df2a71375'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony went to this small eatery with 2 chefs, Andrew Lay and Mark “Gooch” Noguchi. They ate miso soup, pigs feet soup, tripe, taco rice (taco toppings and an over-easy egg on top of rice, which is an Okinawan specialty).', 'Season 5'),
  ('b6800fb8-f775-5cdf-9c8c-196edd516b1c'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony visited this restaurant to have pounded yams, egusi soup, "a stew of goat meat, melon seeds, fish stock, and chilies."', 'Season 10'),
  ('b6ba1d8f-2ecd-5648-8df8-c431252a18f6'::uuid, 'no_reservations'::show_name, NULL, 'Gnocchi, cured meats. Sandwiches too.', NULL, 'Food markets'),
  ('b6ba1d8f-2ecd-5648-8df8-c431252a18f6'::uuid, 'the_layover'::show_name, 1, NULL, 'Porchetta, Meatball, Finocchiano. Come early because they sell out', 'Season 1'),
  ('b6bdecd7-1d41-5f5d-b262-4fdc6b220b53'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony took a helicopter to this beach where they had grilled lobster, rice and beans, fried sweet potatoes. For dessert, pina coladas served in a pineapple.', 'Other Activities'),
  ('b6cec648-235f-5fe3-b759-8992d0b30891'::uuid, 'the_layover'::show_name, 2, 'Burger place. There are a few locations', NULL, 'Season 2'),
  ('b6e19bc8-098d-5237-83f9-6756864783a7'::uuid, 'the_layover'::show_name, 1, 'Closed', NULL, 'Season 1'),
  ('b6e5f1fc-7ca1-5060-9168-ff44f7f466fe'::uuid, 'the_layover'::show_name, 1, NULL, 'Singaporean national dish: Chicken rice. Curry fish head stew, breaded pork cutlet', 'Season 1'),
  ('b715456c-e8e7-572e-b223-938ee2b72d47'::uuid, 'the_layover'::show_name, 1, 'Simple seasonal food', NULL, 'Season 1'),
  ('b7488f65-253b-5c30-a8ae-3938265a5f39'::uuid, 'a_cooks_tour'::show_name, NULL, 'Bar for chefs to wind down', NULL, 'Disc 1: United States'),
  ('b74d49c3-a26e-5543-9225-5150250974aa'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Not sure if this is the beach bar where Tony had some raki to start the day. It was a ocean side bar near where the boat dropped them off.', 'Season 7'),
  ('b7552172-0261-5ec9-a1c1-25410040b91c'::uuid, 'no_reservations'::show_name, NULL, 'Balaclava Naval museum where nuclear submarines were stored', NULL, 'Sightseeing'),
