  ('b8294dff-9db0-50c2-9239-df1e30da9d8c'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had drinks, horse meat and goat sashimi, pork belly, pickled pig’s ears, baked yam', 'Season 6'),
  ('b8311d9d-80db-5e71-978e-34494a48d885'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony visited this school. They talked about chopped cheese.', 'Season 4'),
  ('b834c1a5-cf28-5b55-b5bc-0809b7afb1a1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Danya ate an offal breakfast at a place called Abu Abdullah''s. Tony liked it more than she did.', 'Food markets'),
  ('b84aa6f0-cd3d-5e00-a87d-76c7b0adc34d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Zamir attended the Victory Day parade in Kiev', 'Sightseeing'),
  ('b85df6b6-dae1-5adf-b59f-a28896bf3362'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony met with Adolph Mongo, a political strategist, and had a vodka.', 'Season 2'),
  ('b86617bd-fb8a-57c9-9634-1baa291db4c1'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony stayed at this place where a maharaja once lived. He ate some of the food such as mulligatawny soup.', 'Season 3'),
  ('b8671a67-353f-582f-933a-c7f15c88d9fb'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and José Andrés had Cabrales (a type of blue cheese) at this cheese farm. José commented that the cheese had penicillin in it and Tony''s retort was, "I can feel my syphilis clearing already!"', 'Season 12'),
  ('b8870259-9be3-5921-8aa4-f3699fb3d636'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony camped out in the wilderness with Tigran Grigoryan, a war veteran and aspiring politician; Tatul Hakobyan, a journalist; Saro Saryan, an Armenian born in Azerbaijan who fled during the war. They had jingalov hats, or “lavash bread stuffed with greens and onions before being toasted atop a cast-iron sheet” and Armenian barbecue covered in fennel and fresh herbs', 'Season 11'),
  ('b89222e8-3ed3-5853-80c3-4887779a6065'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Sightseeing'),
  ('b8954950-03e4-5414-83d8-0f57586e62bb'::uuid, 'no_reservations'::show_name, NULL, 'Fresh fish market', NULL, 'Food markets'),
  ('b8c0b428-cf78-57e2-a20d-502bb3a05252'::uuid, 'parts_unknown'::show_name, 10, 'A marijuana farm that supplies some of the dispensaries', NULL, 'Season 10'),
  ('b8c278d8-78fa-53af-ad66-715613149f57'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited a temple in this small town', 'Sightseeing'),
  ('b9171a15-fe09-5acd-b8a2-ae9010e643dd'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had a beer with Loycent “Loy” Gordon, the owner of the tavern, and New York City Fire Department lieutenant. The movie "Goodfellas" filmed scenes in this bar.', 'Season 9'),
  ('b92bdc7c-9968-58bc-a770-b58e19b91e7c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a drink with a guy named Tony who is a nightlife promoter.', 'Restaurants and Bars'),
  ('b94edf4a-436c-52c3-aba9-673b931fe1ab'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Former site of Blaue Gans, an Austrian restaurant that closed in 2018.', 'Restaurants and Bars'),
  ('b96c3c00-25c1-55e1-a22d-e76c6b04174e'::uuid, 'no_reservations'::show_name, NULL, 'Fortune Teller', NULL, 'Other Activities'),
