  ('b9e48fe1-4878-5faf-a04c-30a780fd444d'::uuid, 'a_cooks_tour'::show_name, NULL, 'Bought beef for kefta and tagine to make', NULL, 'Disc 4: Morocco & Russia'),
  ('ba0954d7-8c6a-50d2-95c9-0dd5a1aff1a7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate at the Sicilian restaurant in the hotel. Caponata, bucatini with sardines. Fish, potatoes, fava, pistachio, tomato.', 'Restaurants and Bars'),
  ('ba0eac8f-38ca-5dbe-a7ec-8fb1ccb2ba2c'::uuid, 'the_layover'::show_name, 1, 'Bar', NULL, 'Season 1'),
  ('ba4dad87-4bee-5b81-a2f7-89594524510f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They had Guinness and beef barley soup', 'Restaurants and Bars'),
  ('ba881988-651d-5f07-98ee-6b2c03447d69'::uuid, 'the_layover'::show_name, 2, 'Getting your hair washed is like a spa treatment in Taiwan.', NULL, 'Season 2'),
  ('baaa39cd-342d-58f0-9e96-9e05de4927bc'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a meal with Francis Ford Coppola. They had lampascioni, or scored and fried hyacinth bulbs; braciole di cotenna, or stuffed pig skin rolls; lamb’s head casserole, fresh fruit, assorted wines.', 'Season 10'),
  ('bad92a39-3154-5e9b-b16d-cd61976081bf'::uuid, 'no_reservations'::show_name, NULL, NULL, 'High end Mexican regional cuisine. Very old recipes, reinvented.', 'Restaurants and Bars'),
  ('bb02e84d-87ce-5883-b594-3ed701ab43f1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Hotel where he started', 'Lodging'),
  ('bb16271e-ecfc-5650-aae9-ad702813642b'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony met with Singaporean- Malay entertainer and producer Najip Ali for Lontong (rice cake, coconut gravy, vegetables and hardboiled egg) and Mee Siam (fried rice noodles with chili paste, prawns, bean sprouts, and a spicy sweet and sour gravy, fried bean curd, and egg).', 'Season 10'),
  ('bb1dc085-036a-5551-93bb-2f33a665b1d4'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony met with a local punk band at this night market.', 'Season 1'),
  ('bb275c59-4757-5097-9b52-32576a2f8a05'::uuid, 'the_layover'::show_name, 2, 'Bar with great jazz music', NULL, 'Season 2'),
  ('bb3b8960-fd9d-5469-a233-5bc4f9c5a55b'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had street food at this huge market', 'Season 12'),
  ('bb4413e9-2e84-5449-a5fc-727279d03e37'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony visited this church in the Isfahan province', 'Season 4'),
  ('bb4afead-19cc-544d-a5e2-0b53e7e17e61'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Zamir ordered chicken and ribs (the platter is called The Flying Pig) and Tony had the brisket sandwich', 'Restaurants and Bars'),
  ('bb57817d-8e72-56d7-a2f0-f7cf5a18d185'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony went to this writer/journalist bar where they had snacks and drinks', 'Season 3'),
  ('bb61614c-789e-5b61-9752-1316782df332'::uuid, 'the_layover'::show_name, 1, 'Seafood', NULL, 'Season 1'),
  ('bb670e11-52de-5003-bb25-d7e5dbf0fa35'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony ate at Ondine Restaurant, which is now closed. This is the current restaurant of the same chef, Donovan Cooke. Tony praised the food for using local ingredients.', 'Disc 5: Australia and Japan'),
  ('bba42d28-7e1c-59e4-bbb0-8ab2d013f696'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had lunch with journalist Carina Novarese. They had homemade sausage with roasted turnip and fermented vegetables, beet quiche.', 'Season 11'),
  ('bba8eb78-945c-5a0c-9f8b-e352d6a981ce'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate carbonara and amatriciana', 'Restaurants and Bars'),
  ('bbe31ae2-8e6b-544a-a0ed-304269e34036'::uuid, 'no_reservations'::show_name, NULL, NULL, 'It''s all about the crust, caramelized on the outside. Tony HATES deep dish pizza but said after eating this, he gets it.', 'Restaurants and Bars'),
  ('bc03485c-f730-5110-9e82-05c757484b2c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Another Bacari with a more modern feel. Tony enjoyed the sardines gratine.', 'Restaurants and Bars'),
  ('bc20b919-5a9c-52d0-b333-1da4f6436a4d'::uuid, 'the_layover'::show_name, 1, 'Columbian style arepas.', NULL, 'Season 1'),
  ('bc411975-04cd-5b1b-81c0-ee4edf42a085'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate with soldiers from the US Army who were stationed there. Tony had kebab.', 'Restaurants and Bars'),
  ('bc91192b-620c-5173-92f8-4f91e277c770'::uuid, 'the_layover'::show_name, 2, 'Urban park walkway', NULL, 'Season 2'),
  ('bd0b9d65-e887-5156-b524-3d4c312137f0'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony ate hard boiled eggs with painter John Lurie.', 'Season 12'),
  ('bd2c1425-e535-531b-b1ad-539c7ef88266'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony had drinks with Travis Link, manager of punk rock band Louna, and Rouben Kazariyan', 'Season 3'),
  ('bd302c69-8fa9-5cf8-be07-5b45e56d6c9a'::uuid, 'the_layover'::show_name, 2, NULL, 'Tony watched a form of tai chi that includes sparring (called pushing hands).', 'Season 2'),
  ('bd34b7c9-3960-5069-9489-13dee1ecef1f'::uuid, 'parts_unknown'::show_name, 4, NULL, 'The second oldest bowling alley in the US, where pin bowling is the game.', 'Season 4'),
  ('bd43009e-ce28-5d24-afeb-489b124df114'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Josh from Queens of the Stone Age had Yorkshire Pudding with creamed spinach. This restaurant has been around since 1966', 'Restaurants and Bars'),
  ('bd63db74-c994-5931-92f9-4416bfa80671'::uuid, 'no_reservations'::show_name, NULL, 'Roller derby', NULL, 'Other Activities'),
