  ('bda80409-0b13-5bd8-a0b3-8a8111b7e8d0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Rocco made lunch for Tony at his restaurant. A dish with 2 types of clams and pasta; octopus in a red sauce', 'Restaurants and Bars'),
  ('bddb0d6e-faa7-5c33-a48d-f68effb07860'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony met with another chef here to take a boat out on the water', 'Season 1'),
  ('be30e32e-e26b-5ada-93fc-4d3a76fe2480'::uuid, 'no_reservations'::show_name, NULL, 'Fresh fish market', NULL, 'Food markets'),
  ('be9740a9-3190-52cd-b4ac-f031c98e573f'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'On the show he visited Veritas, which is now closed (Scott Bryan''s restaurant). This is Scott''s new restaurant. Tony said Veritas was one of his favorite NY restaurants', 'Disc 1: United States'),
  ('bea1e48e-f5a7-54e8-9ac7-c98054f4f9d0'::uuid, 'parts_unknown'::show_name, 10, NULL, '"A special place at the bottom of the mountain," describes Tony. "croute with morilles, and cream, lots of cream....farcante: a big, heavy, albeit thoroughly delicious loaf of potato, bacon, dried fruit, and cream slowly steamed in a bain marie."', 'Season 10'),
  ('bec75d93-d7de-5777-9729-bb3d18bb6e68'::uuid, 'no_reservations'::show_name, NULL, 'Salted and grilled snakefish.', NULL, 'Food markets'),
  ('bf0fcad4-5fb2-5cf8-aae2-98209e712c62'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This was one of Tony''s favorites from his childhood', 'Restaurants and Bars'),
  ('bf16dfd0-0d39-5850-833b-540a1771c0c9'::uuid, 'the_layover'::show_name, 2, 'Ping pong and drinks.', NULL, 'Season 2'),
  ('bf16e9c8-8c8b-5a9c-b8d6-c1c6e8314d2d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Closed now, this was a restaurant called Carano Masakan Padang. Tony had a lunch here, served similar to tapas style with lots of rice. Beef rendang, stews. His cameraman knocked over a shelf holding all of the food for the day for the entire restaurant.', 'Restaurants and Bars'),
  ('bf2b396d-b394-50aa-9157-1841516f1343'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('bf4d1858-a2bb-5e14-96d3-b486033b7114'::uuid, 'the_layover'::show_name, 1, 'Seafood', NULL, 'Season 1'),
  ('bf680052-aea7-5151-8361-85202ed21e94'::uuid, 'the_layover'::show_name, 2, 'Breakfast', NULL, 'Season 2'),
  ('bf77fac2-17f7-567e-aa65-7c8717ecf287'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited the studio where Josh from Queens of the Stone Age made some songs for the show. Tony cooked some food: asparagus risotto with black truffle and pecorino. At the end of the episode, they return to the studio where Tony makes spaghetti pomodoro; Dave makes jalapeno cheese cornbread and collard greens; B.O.C. makes veggie wraps with a soy peanut dipping sauce; Josh makes a red cabbage salad with vinegar, cracked red pepper, and crumbled Roquefort dressing; Hutch makes pulled pork.', 'Other Activities'),
  ('bf85983f-1ac8-52a2-a415-f71c7934311a'::uuid, 'no_reservations'::show_name, NULL, 'Asian Market. Bubble tea and food court', NULL, 'Food markets'),
  ('bf89c08b-6b39-5e25-88ba-1bc3c8a7a93f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate here with Joel supervising the meal. Gazpacho; sole meuniere; Robuchon mashed potatoes', 'Restaurants and Bars'),
  ('bf91e230-6722-542b-8a3e-06bc5fac0b93'::uuid, 'the_layover'::show_name, 2, 'Sausage rolls', NULL, 'Season 2'),
  ('bfdaf3c5-0617-5c6f-b7f4-66f568c3e465'::uuid, 'parts_unknown'::show_name, 1, NULL, 'At the time of filming, this was a food truck, but has since been made into a brick & mortar establishment. Roy Choi took Tony there and he ate a Kimchi Spam Bowl.', 'Season 1'),
  ('c002ec22-fb2b-53d7-83dc-52fd8a454ee0'::uuid, 'a_cooks_tour'::show_name, NULL, 'The Bourdains used to play on this beach as kids', NULL, 'Disc 3: Europe'),
  ('c0139b2a-66c6-5bfd-9dab-e1e1fe61ed89'::uuid, 'the_layover'::show_name, 1, 'Cold mango drinks', NULL, 'Season 1'),
