  ('c051e75d-7686-583e-bef3-a77cdbf97939'::uuid, 'no_reservations'::show_name, NULL, 'Public market with fresh produce, street food', NULL, 'Food markets'),
  ('c06b3aa9-2c53-5ef5-b661-a808b96a6c14'::uuid, 'parts_unknown'::show_name, 8, NULL, 'The restaurant that Tony and Asia visited in Rome that Tony refused to disclose the name of.', 'Season 8'),
  ('c08c0047-b3fa-5ec4-89c8-272f7ad0d2fb'::uuid, 'a_cooks_tour'::show_name, NULL, 'Ice cream. Lots of Asian flavors', NULL, 'Disc 1: United States'),
  ('c125644b-48c1-507f-97d3-e6c4276d485c'::uuid, 'parts_unknown'::show_name, 12, NULL, 'A taco place in a gas station that is well loved by everyone, including chefs. Tony had barbacoa tacos with David Beebe, Presidio County Justice of the Peace and Marfa Public Radio DJ and Primo Carrasco, Marfa Public Radio DJ.', 'Season 12'),
  ('c14d6718-205a-57ae-8054-eda805966090'::uuid, 'no_reservations'::show_name, NULL, 'Pakistani restaurant with Punjabi food and naan', NULL, 'Restaurants and Bars'),
  ('c19e3125-9ed1-5b7e-a476-59b491833226'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tea shop where Tony had morning tea with U Thiha Saw, a journalist. They had the hot black tea with a dollop of sweetened condensed milk and a fish soup.', 'Season 1'),
  ('c1a5bd0f-b3b3-59f5-94e7-44b20116046c'::uuid, 'parts_unknown'::show_name, 9, NULL, 'One of the most oldest and legendary base camps. Everything comes in by helicopter. The manager at the camp is said to be the best cook on the continent. She made grilled pork tenderloin, grilled mahi sticks, shrimp marinated in chili sauce, homemade sourdough bread, roasted beet salad, edamame salad, roasted vegetables.', 'Season 9'),
  ('c1cd0518-eeea-50e9-8201-8f8542c6b537'::uuid, 'the_layover'::show_name, 2, 'Sake and katsu, udon.', NULL, 'Season 2'),
  ('c1d8c953-822b-56bf-9781-7bad49b4332e'::uuid, 'the_layover'::show_name, 2, 'People dive off the cliffs here', NULL, 'Season 2'),
  ('c215c497-66d7-57fe-9a76-e7c67b04a309'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Closed now. This was a restaurant in a rail car that Tony had a humongous sandwich from.', 'Restaurants and Bars'),
  ('c21c99b1-74b8-5de7-9fb1-1506df20f3a9'::uuid, 'the_layover'::show_name, 2, 'Dark cavern bar with punk bands', NULL, 'Season 2'),
  ('c26d1663-d0e4-5a5a-9eb3-95d01c4041ab'::uuid, 'the_layover'::show_name, 2, 'Art museum', NULL, 'Season 2'),
  ('c273f69a-78e9-55fa-ade1-b7edebba7de2'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had dinner with the McKinney family, “a typical expression of hard-scrabble Appalachian practicality,” combined with “Neapolitan roots”: spaghetti pizza, chicken stew with peas and onions, pumpkin pie cake.', 'Season 11'),
  ('c28c5612-93de-583e-af3f-6d9eb8742fee'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A floating market where Tony ate fried shrimp cakes and a mixed salad plate.', 'Food markets'),
  ('c2b33f92-8876-592f-8f40-424b8b0e9897'::uuid, 'the_layover'::show_name, 1, 'Dive bar', NULL, 'Season 1'),
  ('c2c00f97-5f1d-5865-aecf-3390286e219f'::uuid, 'the_layover'::show_name, 1, 'Independent Bookstore', NULL, 'Season 1'),
  ('c2e86497-37ce-56b2-8ff5-21d292da6614'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Masa watched a geiko perform at Fujinoya Tea House (could not find exact location on map).', 'Season 8'),
  ('c2e9788d-bd22-592b-80e4-ef35c8f90ac6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Traditional Swedish food; game birds - pheasant, goose, duck; seafood', 'Restaurants and Bars'),
  ('c2fc75dd-0968-5865-a48b-886a1b0c7d8a'::uuid, 'the_layover'::show_name, 2, 'Food truck for breakfast and lunch', NULL, 'Season 2'),
  ('c2fe79d8-914e-5d17-8251-d94010a2d5d8'::uuid, 'parts_unknown'::show_name, 3, NULL, '"Get used to eating a lot of vegetarian. India is one of the few places on Earth where, even for me, that''s not a burden," Tony says. He had chickpeas, saag, and lots of naan.', 'Season 3'),
  ('c3036940-809d-58d0-b207-24c19079b5da'::uuid, 'no_reservations'::show_name, NULL, NULL, 'HUGE steaks. Tony''s cameraman Jerry took on the 72 oz steak challenge.', 'Restaurants and Bars'),
  ('c322f61a-badc-55b8-b8d6-13ec5f7f8671'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a curried tiger and a ginger beer. It is a curry beef pie topped with "a heaping scoop of mashed potatoes, a volcano crater full of mushy peas, and an eruption of brown gravy.', 'Restaurants and Bars'),
  ('c3602a55-c34c-53c0-a049-2fbf76e2e4cf'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony did some hiking and participated in a water purification ceremony', 'Sightseeing'),
  ('c36b6af7-cc3a-5707-bc73-eeb49c549cc1'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with a group of women (Fama Diof, photographer; Umi Nador, journalist and TV presenter; Minyel Tal, entrepreneur) to discuss gender roles in a mostly Muslim country. They ate clams, sea urchins, and thiof fish.', 'Season 7'),
  ('c3b48d7b-7de3-58e6-91d0-4192185854c6'::uuid, 'parts_unknown'::show_name, 2, NULL, '"It feels like an alternate universe..." Tony says of this restaurant run by a couple, where the husband is Muslim and the wife is Jewish. He ate fried eggs with peppers from the garden; roasted tomatoes, okra, onions, and mint; grilled zucchini covered in fried yogurt sauce; fresh zucchini with mint and tiny sweet apricots', 'Season 2'),
  ('c3e881e8-44e9-5b04-8eea-c3ce096da9c7'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony and Andy had grilled pork intestine and drinks.', 'Season 3'),
  ('c41c91d3-03f4-513a-8f69-9a4b35cf2332'::uuid, 'no_reservations'::show_name, NULL, 'Get the mortadella sandwich. His favorite.', NULL, 'Food markets'),
  ('c42ef839-3b4e-5d9b-85b6-6bd1792aeb6b'::uuid, 'no_reservations'::show_name, NULL, 'Octopus, anchovy, cordula, fava beans, snails', NULL, 'Restaurants and Bars'),
  ('c46642f2-cb44-5bc5-a762-2f67402d0175'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony says the Maxwell Food Centre is the best hawker center, and this place has the best chicken rice in Singapore', 'Restaurants and Bars'),
  ('c46ab036-b8ea-5caf-8155-2f466ba420fa'::uuid, 'no_reservations'::show_name, NULL, 'Banh mi sandwiches', NULL, 'Restaurants and Bars'),
  ('c4bc37d4-dd23-53f2-add4-42c77bbb3873'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony visited this drug recovery center where people shared their stories.', 'Season 4'),
  ('c560ca35-7fd5-5431-8d7d-c036ecf8b705'::uuid, 'the_layover'::show_name, 2, NULL, 'Hot Spring resort. If you''ve got the dough, a decidedly posh level of Zen-like relaxation. Only 4 rooms so book way in advance.', 'Season 2'),
  ('c56cd1b8-f09c-5155-ad22-415988cdb439'::uuid, 'the_layover'::show_name, 2, 'Middle eastern food', NULL, 'Season 2'),
  ('c5bab428-0a0d-53e4-ab2c-9bcf97861b72'::uuid, 'no_reservations'::show_name, NULL, 'Kart racing', NULL, 'Other Activities'),
  ('c5dad52f-689f-5d2b-a16c-a5e7adc0ede0'::uuid, 'parts_unknown'::show_name, 2, NULL, 'The beach where they launched the boat to go "fishing" and then dropped dead fish, octopus, and shellfish into the water around Tony. He described his feelings on this experience saying he slid "quickly into a spiral of near hysterical depression." After this scene he gets really drunk.', 'Season 2'),
  ('c5eb696a-ca70-5e4d-b3c8-c055148663d4'::uuid, 'parts_unknown'::show_name, 1, NULL, '"On first inspection, this is an airplane boneyard, where unwanted props from Romancing the Stone corrode artfully. But in reality, this sleepy hangar is an important gateway to the more impenetrable parts of the country," Tony says.', 'Season 1'),
  ('c60ee0d0-862b-52d8-a849-a5d0fe6fd735'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Open very late into the night, this place serves mocotó, "the ultimate in broke-ass, drunk-ass peasant food. Slow-cooked cow’s foot and/ or other bits, tender and tasty, and believe me, one of my favorites, especially at this hour. We opt for the elite version, served with raw quail egg."', 'Season 8'),
  ('c6198f29-7246-5682-b33f-4fdc75eabcd5'::uuid, 'parts_unknown'::show_name, 9, NULL, 'On the helicopter ride, they also saw Mount Erebus, the southernmost active volcano on Earth.', 'Season 9'),
  ('c6246ddc-e7bc-55d7-a308-5a7c880a5056'::uuid, 'no_reservations'::show_name, NULL, 'Exotic ingredients with Caribbean flavors', NULL, 'Restaurants and Bars'),
  ('c63a546a-81ef-531f-bae5-3be09a410c79'::uuid, 'the_layover'::show_name, 2, 'Cocktails.', NULL, 'Season 2'),
  ('c65cb9fc-8f84-516b-827c-99ca862d61b1'::uuid, 'the_layover'::show_name, 1, 'Seafood market. Wear your rain boots!', NULL, 'Season 1'),
  ('c65fb5d4-1bdf-5ab8-86e3-02ca223eb9d8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony''s brother was a train nut as a kid. They visited this old train station in Montevideo', 'Sightseeing'),
  ('c683587e-01cf-5f69-b9fb-2f8ac87270c6'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony flew to this small town before heading into the Serengheti.', 'Season 4'),
  ('c6b41156-6303-5551-91bd-32f87f890335'::uuid, 'a_cooks_tour'::show_name, NULL, 'Many stands selling wares', NULL, 'Disc 4: Morocco & Russia'),
  ('c6c10b01-402d-5bda-a2f5-a193c35ba315'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met with Carlos, who took over his job as head chef at Les Halles. Breakfast with tequila. Food is free with drinks.', 'Restaurants and Bars'),
  ('c6c77066-7e1b-58ee-86b9-29aa5076427a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Miss Linda''s Yakamein food truck is parked here sometimes. Tony ate this concoction of noodles, beef, egg, and scallions from her truck.', 'Restaurants and Bars'),
  ('c6d82db5-0c5b-5545-aa73-c93e43863c5f'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony played bocce ball and had a picnic of sausage and peppers and got beat by a 103-year old.', 'Season 10'),
  ('c6d95f3c-90e8-54c5-971c-e51ac60a736c'::uuid, 'parts_unknown'::show_name, 8, NULL, '"Artist, author, icon, Ralph Steadman continues to make art every day. He was the visual expression of Hunter S. Thompson''s work." Tony met with Steadman at this restaurant/pub for lunch. "Runny egg wrapped in Parma ham and breadcrumbs, prawn cocktail, fish & chips with mushy peas, steak & stilton pie"', 'Season 8'),
  ('c737c61f-8c4d-5312-9c4c-f2b181fa9ca0'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with Tracey Gudwin (friend and former producer for No Reservations) and Anke Lönne, a resident of Cologne. They had schnitzel, which Bourdain describes as “surfboard-sized slabs of veal and pork filled with many wonderful things, dredged in breadcrumbs and fried in magical, magical deep fat.”', 'Season 7'),
  ('c7397b65-7da4-5b9f-a131-ced8a121d2ee'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony met with chef and musician Tomas Rueda, and they had crab salad, handmade pasta, stuffed with labneh cheese with a chorizo sauce; braised osso buco (with beef shank) over vegetables, wine and broth in a wood-fired oven.', 'Season 1'),
  ('c7469d6f-993f-5251-8abc-ddeb9e079aec'::uuid, 'the_layover'::show_name, 2, 'Artisanal food vendors', NULL, 'Season 2'),
  ('c78444b3-2c3d-5a78-b0ee-40d762525845'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony saw a gypsy band called Budapest Bar play and then ate with the musicians. They had chicken paprikash, whole perch roasted in bacon, stuffed cabbage filled with goose meat and slow-cooked, goulash.', 'Season 5'),
  ('c799aead-c36c-5718-96dc-f470856df60e'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Traditional kaiseki restaurant that dates back to 1890. Menu changes as seasonal ingredients become available. ""Preserved in a tightly wrapped bamboo leaf, intended to resemble a sword, sea bream served chimaki-style over rice slightly sweetened by vinegar, soy sauce, sugar, and sesame... Grilled rockfish made Horaku style, steamed in smoking wormwood. Bamboo shoots and wagyu beef prepared tableside with soy sauce and mirin. Today''s sashimi course is cod, salted and pressed between leaves of kelp for 2 hours, coated with sake-cured codfish roe. Next to it, flounder, its skin gently rubbed with grilled tomato the day before. Finally, a super luxurious clam hot pot: rice is steamed with clam and a bonito broth, then topped with plump torigai plum and manju clams, as well as creamy sea urchin and a Japanese broccolini blossom for good measure. Simple, perfect."', 'Season 8'),
  ('c7b4001b-a261-5b87-a3ca-5273f483eb6f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Beijing restaurant specializing in dishes made with cow and sheep stomach', 'Restaurants and Bars'),
  ('c8219c27-27b5-52a6-b99a-816b9e631eb1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony stayed here. In the open air restaurant, a man scares away the birds from eating guest''s breakfasts by shooting them with a slingshot', 'Lodging'),
  ('c82f5808-a0aa-52e6-81ea-1d07ab696640'::uuid, 'parts_unknown'::show_name, 11, NULL, 'This address was supposed to be a place called Grosz where Tony ate Weimar fare with Historian Brendan Nash; performance artist Le Pustra; and event manager, producer, and promoter Else Edelstahl. Could not find on map.', 'Season 11'),
  ('c85a64ae-6ade-51dc-826b-65617af8f79b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Choose your own fish and shrimp. Catch of the day is served with a spicy rub and coconut curry sauce', 'Restaurants and Bars'),
  ('c91bff19-f523-5e92-a5a6-baba0f7d7c62'::uuid, 'no_reservations'::show_name, NULL, NULL, 'One of the best restaurants in the country. They had octopus stewed in white wine and tomatoes. Slow cooked lamb with hand rolled pasta', 'Restaurants and Bars'),
  ('c92ccee3-e4b8-566e-8921-eafc447827c7'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had sheephead stew and bread at this cafe.', 'Season 4'),
  ('c9594cf9-a842-51b5-942d-65265728e3f5'::uuid, 'the_layover'::show_name, 2, NULL, 'One of the tallest buildings in the world. Check out the view.', 'Season 2'),
  ('c95ac3b6-db47-5bf5-98ca-2c072944628a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met a guide here that promised to take him to eat some pho.', 'Restaurants and Bars'),
  ('c97472bf-21ab-541c-8221-a55d7ac6d677'::uuid, 'a_cooks_tour'::show_name, NULL, 'A getaway for affluent Japanese.', NULL, 'Disc 5: Australia and Japan'),
  ('c97f8de2-be26-59a9-89c7-e346cbef2e27'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('c9d259a1-f32f-50b9-986c-23f6d91810a9'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony and Aisha Stoby, PhD candidate of Middle Eastern art, strolled through this market and talked about the culture of Oman.', 'Season 9'),
  ('c9d4fe78-2086-5685-a0d0-64723785e503'::uuid, 'a_cooks_tour'::show_name, NULL, 'Royal Cambodian meal', NULL, 'Disc 6: Asia'),
  ('ca1740dc-fb40-5468-a2c8-6337c6e6dd5b'::uuid, 'no_reservations'::show_name, NULL, 'Food stand market', NULL, 'Food markets'),
  ('ca27c106-cade-5405-9aa6-377ec97f65d0'::uuid, 'the_layover'::show_name, 1, 'Beer and cafe', NULL, 'Season 1'),
  ('ca3602da-b6e7-5908-a41f-c00bc66d023e'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Chef Sanza cooked for Tony: A Nigerian dish of egusi and beef (cooked with melon and pumpkin seeds) futu (crumbly cornmeal porridge); basmati rice with rose water; achar (pickled eggplant and mango); Congolese cassava; and falafel. Menu changes daily.', 'Season 2'),
  ('ca596b66-51a5-511c-9087-9b92a68a81a8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony was upset that this market he went to 10 years ago was now more commercialized. He went to a smaller local and less touristy market and had Ka Tiew, a noodle soup (they did not say where this was)', 'Food markets'),
  ('ca81b0e3-2adc-535d-b1ed-ba628cfeb1c7'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Nightclub, performance space, and art gallery highlighting artists and DJs from around the world.', 'Season 6'),
  ('ca85cc03-926d-53f2-9301-37a6d2290ee2'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had a meal with Roosevelt China Investments President Tim Tse. They had French oysters with champagne, New Zealand shrimp, Australian Wagyu beef', 'Season 4'),
  ('ca86fcc9-b30b-5adb-a4fd-dee0d3a0a92e'::uuid, 'no_reservations'::show_name, NULL, 'Hotel and restaurant that locals eat at', NULL, 'Lodging'),
  ('caa34262-9dc7-55fa-9a0e-0c1d6c332b11'::uuid, 'no_reservations'::show_name, NULL, 'Kofta, sausages, baba ganoush, salad', NULL, 'Restaurants and Bars'),
  ('cab44d43-06f0-5f90-a053-20d4b5d63c0f'::uuid, 'parts_unknown'::show_name, 9, NULL, 'This is a cart that sells mulitas, "not quite a taco, not a quesadilla. More of a taco sandwich. First the tortilla goes on the grill, then marinated meat, cheese, then another tortilla. Flip and serve."', 'Season 9'),
  ('cad517a2-b16c-55bd-85a0-09c17df03648'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Mega seafood market with food stands and tables. You pick your fish, chilis, ingredients, and how they cook it, they serve it to you.', 'Disc 6: Asia'),
  ('cae886d8-c94c-5e3d-a2f6-b1b262e5dba9'::uuid, 'no_reservations'::show_name, NULL, NULL, 'After their shoot was canceled when authorities did not want them filming street racing, Tony and his driver and friends went to a hamburger stand on the street for burgers and hot dogs.', 'Restaurants and Bars'),
  ('caf2efb8-50be-58d4-9b22-27f696623039'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had slow roasted suckling pig with ranch owner Apa Ramos. They also had gandinga, a stew made from pig heart, liver, and kidney.', 'Season 10'),
  ('cafb3220-eded-5f9a-b736-5479c8032d1d'::uuid, 'parts_unknown'::show_name, 1, NULL, 'The Cali version of ceviche: cooked shrimp, slathered in mayonnaise, ketchup, and Worcestershire sauce; rock mollusk with rice; steamed shrimp with green tomatoes; beer; sugar cane (viche), plantains.', 'Season 1'),
  ('cafebcf6-ad1c-5e30-9c60-21de0029b505'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Madame Kek took their food they bought at the market to an area along the beach with thatched huts under which they could eat.', 'Other Activities'),
  ('cb459a65-921d-5e60-ad0c-869dd2bc9613'::uuid, 'no_reservations'::show_name, NULL, 'Hot springs', NULL, 'Other Activities'),
  ('cb50001d-75e8-5826-becd-51fa5a33e842'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony visited Chef Rene Redzepi at this restaurant, which is known to many as "the best restaurant in the world." Tony came to Denmark solely to visit this restaurant.', 'Season 2'),
  ('cb9e8625-2025-5ba4-a930-995b6b8231d6'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Vendors on the beach: toasty cheese, shrimp on a skewer, quail egg, sugar cane.', 'Disc 2: Mexico and The Americas'),
  ('cbafc733-2e42-557f-822b-bd90167f8895'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Street foods galore! Tony had octopus and masala lobster with chili mango, grilled on a skewer. He also had Zanzibar pizza (beef, tomato, onion, cheese, egg, and mayo rolled up in a dough and fried)', 'Season 4'),
  ('cbe72bbf-25b5-5be1-ba27-e2b4edc954c5'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Other Activities'),
  ('cbf35205-026d-52fa-b84c-eeadc996c496'::uuid, 'the_layover'::show_name, 2, 'Pho', NULL, 'Season 2'),
  ('cc030533-1311-54a6-a3cb-0f2457d07c5d'::uuid, 'the_layover'::show_name, 1, 'Canadian pub', NULL, 'Season 1'),
  ('cc3116f7-57b0-5dcb-acf3-f6cdeeb3c8f2'::uuid, 'parts_unknown'::show_name, 11, NULL, '"Cheap, delicious food served from open air stalls." Tony met with chef Gazza Cheng and had drunken chicken, fish tripe, and egg-custard clay-pot dish with youtiao', 'Season 11'),
  ('cc38d004-366f-5e04-a39b-68c53dc1ae21'::uuid, 'no_reservations'::show_name, NULL, 'Thai boat noodles', NULL, 'Restaurants and Bars'),
  ('cc44cf9f-c407-52f7-bc3d-ed8d8b2ebfdf'::uuid, 'the_layover'::show_name, 1, 'The world''s 2nd most unhygienic tourist attraction', NULL, 'Season 1'),
  ('cc5a6319-aa21-50f4-9630-6c21fefac30f'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Take the 7 train and get off at Roosevelt Ave. to find lots of awesome food stands. One place sells Ecuadorian food right at the exit to the subway, such as hornado, or "roast pork with sublime crispy skin straight from Heaven, morcilla, or blood sausage with potato cakes." The cart is called La Esquina de la Caserita.', 'Season 9'),
  ('cc61cb21-7e9a-5d7e-9b6d-c7d3825cf7a7'::uuid, 'no_reservations'::show_name, NULL, 'Outdoor vegetarian restaurant', NULL, 'Restaurants and Bars'),
  ('cca6518e-ec8b-549f-88df-c6fbec697772'::uuid, 'no_reservations'::show_name, NULL, 'Trapani Salt Flats', NULL, 'Sightseeing'),
  ('ccbb6e30-bc10-52bc-ada3-83ea3b6e6fa4'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Kendo master Tadao Todo did a kendo demonstration for Tony', 'Other Activities'),
  ('ccc3faa8-7988-58c3-ab41-9c8b9698385e'::uuid, 'no_reservations'::show_name, NULL, 'Making Italian recipes from local NY ingredients', NULL, 'Restaurants and Bars'),
  ('ccd93423-8c38-56ff-8886-57985466a51e'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('ccd93423-8c38-56ff-8886-57985466a51e'::uuid, 'the_layover'::show_name, 1, 'Bagels are sweeter and crispier than NYC here', NULL, 'Season 1'),
  ('ccef8cd6-bf71-51c8-be2e-46cf2868edd4'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony visited Mariam Movsisyan’s grandmother’s family home. They had ghapama (traditional dish consisting of a baked pumpkin or squash stuffed with rice, nuts, raisins, and apricots), Armenian cheese and lavash, hummus.', 'Season 11'),
  ('cd08151d-0495-54b9-99a0-172117c1a673'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A mountain painted by an artist using thousands of gallons of paint', 'Sightseeing'),
  ('cd0a83a2-350a-5984-bd4b-fa8065a22a24'::uuid, 'the_layover'::show_name, 2, 'Ritz Carlton', NULL, 'Season 2'),
  ('cd1251f1-8ce8-509e-a79e-00303099211b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony brought Ruhlman here to torture him, because he knew he''d hate it, hahaha', 'Restaurants and Bars'),
  ('cd6d8ede-0a3b-5d21-beb6-7639dadaaa65'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony watched cover bands at this biker bar', 'Season 7'),
  ('cd7c5eb0-73b0-5605-9080-64da28fe0e56'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Asia visited this huge structure, which was built originally to be a symbol of fascism.', 'Season 8'),
  ('cd88183e-62d8-5ff8-808f-c68354d5dbf4'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony met with Pyinfamous, a local hip hop artist, to have drinks.', 'Season 3'),
  ('cda16428-6b27-5e52-b6a7-bbcf0a2f4667'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony visited his alma mater where he went to culinary school and learned classic French techniques', 'Disc 1: United States'),
  ('cda16428-6b27-5e52-b6a7-bbcf0a2f4667'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony returned to his alma mater with Mark Ruhlman', 'Other Activities'),
  ('cda3aa21-99b1-5abc-9710-3c61f9db8984'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Cured meats and cheeses in a food market called the Naschmarkt.', 'Food markets'),
  ('cdb657f0-1bda-5d98-b00f-1004f60a77b6'::uuid, 'a_cooks_tour'::show_name, NULL, 'Seafood restaurant', NULL, 'Disc 3: Europe'),
  ('cdf1fc4d-82e5-5172-861e-57905a0b07bf'::uuid, 'the_layover'::show_name, 2, 'Crab avocado breakfast sandwich', NULL, 'Season 2'),
  ('ce03ca68-8f56-5769-b6b6-497dde35efe6'::uuid, 'no_reservations'::show_name, NULL, 'Cuci Lampo - tailor', NULL, 'Other Activities'),
  ('ce0b6a7f-744b-5b42-bc35-63b96108dbc9'::uuid, 'no_reservations'::show_name, NULL, 'Modern Italian food with local ingredients', NULL, 'Restaurants and Bars'),
  ('ce0ffcd7-aed1-5e28-97b1-d7d4261b6688'::uuid, 'a_cooks_tour'::show_name, NULL, 'Steak frites', NULL, 'Disc 3: Europe'),
  ('ce4b2167-ba1a-51cb-9f9a-a8ef59420909'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony visited during the Madai Festival for the Tamil people who are praying to Kali, a Hindu goddess.', 'Season 10'),
  ('ce671be4-512b-57c1-9d30-bfcbd9823e31'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went boar hunting and then cooked it at the lodge where he was staying.', 'Lodging'),
  ('cec0484f-0777-531f-8710-1b6e7b90cde5'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had a duck curry made by his host.', 'Season 9'),
  ('cec09e45-1176-5f1b-b724-9dd55ef4c17d'::uuid, 'the_layover'::show_name, 1, NULL, NULL, 'Season 1'),
  ('ceec8d48-688d-53a3-91fe-5bf2cc1b2774'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had champagne and caviar', 'Restaurants and Bars'),
  ('cef12518-fe7d-5a20-8dae-90ea8cb92dbc'::uuid, 'no_reservations'::show_name, NULL, NULL, '"The sensible among you will avoid this activity at all costs," Tony says of the spelunking tour', 'Sightseeing'),
  ('cf33ec30-4e83-5e10-a564-cc49ea49110c'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('cf40313a-70d5-56ce-978d-7ad8ac07838e'::uuid, 'the_layover'::show_name, 2, 'Korean fried chicken', NULL, 'Season 2'),
  ('cfa2934c-3cd2-5f6f-bb9f-3b783e6e0213'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Sightseeing'),
  ('cfd123b8-ba31-5618-8711-4c9e1881a7c8'::uuid, 'the_layover'::show_name, 2, 'Charcuterie, Butcher shop, breadmaking', NULL, 'Season 2'),
  ('cfd4ddcf-c480-54cf-9291-aaf6158823da'::uuid, 'parts_unknown'::show_name, 2, NULL, '"A notoriously dangerous district" where Tony met with DJ Les.', 'Season 2'),
  ('cfe7464d-1200-534e-9ba2-a7a33e23ef23'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Former site of Bellman Bar? Tony met with film director and photographer Miron Zownir for cocktails here.', 'Season 11'),
  ('cff84a35-1562-5787-8135-1be5cbf5f58e'::uuid, 'a_cooks_tour'::show_name, NULL, 'Best ribs in Houston', NULL, 'Disc 1: United States'),
  ('cff84a35-1562-5787-8135-1be5cbf5f58e'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony had not been back in 15 years. He ordered "the torpedo-sized baked potato filled with cheddar cheese and chopped barbecue beef, and homemade link sausage. Slow cooked pork ribs, big ass beef ribs, and brisket."', 'Season 8'),
  ('d01132d8-21a4-5ed4-b500-47e7e44aaa9d'::uuid, 'the_layover'::show_name, 1, 'Drinks', NULL, 'Season 1'),
  ('d02ca623-ed37-57f6-a739-ab9503162191'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('d057c0ad-97e0-567f-86e5-7b46d0da856a'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Eric took Tony shopping in this market to find supplies for a shaman they will visit later in the episode.', 'Season 1'),
  ('d0850729-926b-50ab-8f22-4275cc365fd0'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and Kamau visited this area and met with comedian Mammito Eunice, musician Simon Okuku, and comedian Geoffrey Ochieng, members of Kibera Creative Arts.', 'Season 12'),
  ('d08fda52-5357-549e-ae72-06345d077876'::uuid, 'no_reservations'::show_name, NULL, 'Russian pies filled with potatoes, beef, or cabbage', NULL, 'Restaurants and Bars'),
  ('d0ba5d2c-1e51-5a9c-953f-c7daf5edfcad'::uuid, 'a_cooks_tour'::show_name, NULL, 'Permanently closed; it was a classic French restaurant.', NULL, 'Disc 1: United States'),
  ('d0c4965b-0cbe-5d2d-90ac-1d4712c19e33'::uuid, 'the_layover'::show_name, 2, NULL, 'Away from the French Quarter. Modern, boutique hotel. Locally owned with 18 studio loft apartments', 'Season 2'),
  ('d12ac1d9-74f9-56ba-b979-63a7354f34c3'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Cafeteria style restaurant where Tony ordered meatloaf and macaroni & cheese. He ate there with Bruce Cameron Elliott, who owns the Old Town Ale House. Bruce told Tony that he often saw Barack Obama having breakfast at this restaurant', 'Season 7'),
  ('d171b233-d094-51d7-952e-5f71105823bd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had another bowl of noodle soup here', 'Restaurants and Bars'),
  ('d1abcb1d-796e-55f5-8992-2244a999be4a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had Baja fish tacos; there is a condiment bar with different kinds of salsas, crema, guacamole, and other toppings', 'Restaurants and Bars'),
  ('d1b3cc19-c9c7-5244-9e05-dacc8854e8c4'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony was the only guest in this "expensive, luxurious" hotel. Tony had dinner with the owner of the hotel, one of the richest men in the world, local billionaire Michael Lee Chin.', 'Season 4'),
  ('d1d1dc0a-7ef9-5f09-8221-9b279020f485'::uuid, 'the_layover'::show_name, 1, 'Beer', NULL, 'Season 1'),
  ('d1d8a463-3727-58a8-a550-3c2a9170060a'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Unsure if this is the correct location. There was a scene on the show where Tony and Eric visited Mercado Central on Calle San Martin in the Marañón Canyon where they bought food to cook to feed their host, Don Elioberto, and his family. They made chicken and shrimp with peppers and onions, along with mashed potatoes and traditional Aztec hot chocolate. I could not find a Mercado Central on a street with this name on the map.', 'Season 1'),
  ('d1e9e4d1-9dc1-5c80-8e23-89e5a19ed1bb'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had breakfast here with Eric Ripert', 'Restaurants and Bars'),
  ('d2487f1d-19cd-5f54-9853-b560ff7adf46'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Bar #3 for the group. They ate cheese, fried smelts, picarones (fried pastry), chulatitas (baby lamb chops).', 'Season 2'),
  ('d24e4387-e70d-5dfd-b77d-9d4c56be3408'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a meal with John Fetterman, mayor of Braddock; Gisele Fetterman, who runs a nonprofit to help those in need in their community; Franco Harris, four-time Super Bowl champion; and Chef Kevin Sousa, restaurateur behind Superior Motors. They had Lake Erie walleye pike, new potatoes, fish cracklin, and fresh herbs; beef short ribs on milkweed buds and overwintered sunchoke chips; wine.', 'Season 10'),
  ('d2762a22-7c8b-531b-911c-9ad71a697e13'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited this small village at the edge of the country', 'Sightseeing'),
  ('d2913511-8a3b-5ddc-860d-a7263c99c9c7'::uuid, 'no_reservations'::show_name, NULL, 'Produce and meat', NULL, 'Food markets'),
  ('d296d11d-b467-5b6d-836f-97ae38426de6'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony visited this town during Thadingyut, the Full Moon festival celebrated by Buddhists at the end of October. He ate street food and watched the human-powered ferris wheels', 'Season 1'),
  ('d2a4cb63-a233-5df1-9b2a-0a05d36af802'::uuid, 'no_reservations'::show_name, NULL, 'Cuts of meat for every budget', NULL, 'Food markets'),
  ('d2ae9d8c-8989-57ea-867b-328634ff23eb'::uuid, 'a_cooks_tour'::show_name, NULL, 'Indian food. Fish head curry', NULL, 'Disc 6: Asia'),
  ('d2b845bb-8012-580a-b63f-930074825e8f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Jim Lahey, owner and baker. Obsessed with dough/bread. The restaurant on the show, called "Co." (short for Company) closed, but he is still making pizza at Sullivan Street Bakery''s Chelsea location.', 'Restaurants and Bars'),
  ('d2c442e2-5611-5468-be05-0cf79636947f'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had pickled beets, sweet potato salad, salami and cheese, side salad, pickled peppers, breadsticks, large scallops in white wine sauce, extra thick tenderloin of beef', 'Season 7'),
  ('d2c8878b-5c78-5f1a-b768-4ea688f045ba'::uuid, 'the_layover'::show_name, 1, 'Portuguese roast chicken.', NULL, 'Season 1'),
  ('d3218d12-59cb-5681-b875-bf8046b2c175'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony met with the record store owner to talk about the birth of hip hop in the Bronx.', 'Season 4'),
  ('d32bef40-a5d3-5641-80f8-8c7a8e7f7d13'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony went to Principal Jonathan Nguyen Trinh''s home to have lunch. They had tamales de gallina; fresh pupusas on the grill; a jellyfish, shrimp, and pork dish tossed with mint, peanuts, carrots, red onion, and dressed with fish sauce; mi quang: a Vietnamese noodle dish made with pork ribs, shrimp, and chilies; and “Viet-bayou style” crawdads steamed with sriracha, orange juice, and beer', 'Season 8'),
  ('d3370cc5-09fb-58d1-a573-eeab9e05803b'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Other Activities'),
  ('d33963db-468f-5fc0-889d-ff5956a44fac'::uuid, 'the_layover'::show_name, 1, 'Coffee', NULL, 'Season 1'),
  ('d34a9aa9-90e5-59c1-b195-0dc5d2d76e34'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The restaurant was not yet open yet when Tony visited, but the chef cooked for him', 'Restaurants and Bars'),
  ('d36bc7c1-633c-50f2-8a41-eb16f6976170'::uuid, 'no_reservations'::show_name, NULL, NULL, '100% Baja cuisine - local ingredients. Roasted tuna belly with daikon and kohlarbi, nasturtium; leg of lamb braised in black bean with swiss chard, carrot, radish, and turnip.', 'Restaurants and Bars'),
  ('d39661a6-64ac-53f0-82c0-bb3ee3467625'::uuid, 'the_layover'::show_name, 1, 'Wanderlust Hotel. Affordable/hipster', NULL, 'Season 1'),
  ('d39e81c5-fa8c-5e68-adba-4a8f13105b86'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They bought seafood here, then brought it to Esplanada Belinha to have it cooked. Clams steamed with garlic; prawns grilled and basted with butter with nshima (thick porridge made of ground maize).', 'Food markets'),
  ('d3cb5eab-08f3-547b-a366-0d895054dbda'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony had a meal here that started with a tower of maple desserts. It had a lot of courses which would be too many to list!', 'Season 1'),
  ('d3df1550-91ec-59b8-bc64-bf789c0cb753'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Ian Fleming''s cottage (British author known for creating the James Bond character). It is now a resort.', 'Season 4'),
  ('d3eacf2d-9824-5920-970b-9e97ef763bf9'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony witnessed the town get together to slaughter a pig and cook it for a feast.', 'Season 9'),
  ('d409912c-f7d1-51c1-b7cf-cfe8c6fb797c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Cured meats. Tony''s go-to salumeria in NYC', 'Restaurants and Bars'),
  ('d43d3486-57d1-54a7-bdbc-cc0f1741deba'::uuid, 'a_cooks_tour'::show_name, NULL, 'Healthy fresh vegetarian food, fresh juices', NULL, 'Disc 2: Mexico and The Americas'),
  ('d4838005-9092-5800-b1cf-b4c2a95dfc68'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had lunch with Mu Sochua, an ethnic Cambodian-Chinese member of Parliament.', 'Restaurants and Bars'),
  ('d484438c-c351-52a1-8727-6f49275e1386'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Traditional Nigerian foods such as ewedu (jute leaf) soup with crayfish, chilies, and locust beans; jollof rice (cooked in tomato sauce); goat; pounded yam.', 'Season 10'),
  ('d4ce6fb1-cd53-5a93-917d-d03f7f4a91b2'::uuid, 'the_layover'::show_name, 2, 'Bookstore owned by a British family for generations', NULL, 'Season 2'),
  ('d4e3861a-3fd3-5f8c-8f8f-37f6c25d731d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Many stands were closed when he visited this food market', 'Food markets'),
  ('d50e9763-4684-5783-aced-a87b11b6dfe3'::uuid, 'parts_unknown'::show_name, 5, NULL, '"A smoky, chilly working class joint," Tony describes of this restaurant. "A golden pancake, heaped with chicken livers, and covered, nay, drowned, with a rich, deeply satisfying sauce with bone marrow." He also tried the venison stew and the HUGE schnitzel this place is famous for.', 'Season 5'),
  ('d51aeec8-25c7-5e1c-b9d0-eab7c4996dd6'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a pasta dinner here with Asia Argento.', 'Season 10'),
  ('d5284fcf-7c55-5766-b3ad-97b492d289da'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This used to be the location of O Senhor Ramos, a Portuguese restaurant. Now closed.', 'Restaurants and Bars'),
  ('d52a7b70-b672-54de-b8c0-5ebe904f23e2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Closed now, but Tony tried lots of spam here when it was called Uptown Fountain', 'Restaurants and Bars'),
  ('d539efe6-8283-5925-bc8b-0c31e5368c78'::uuid, 'no_reservations'::show_name, NULL, 'Sake bar', NULL, 'Restaurants and Bars'),
  ('d54dc289-33c9-57c0-bde0-a3d3b80740c4'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Andy and Tony had their last meal at this place which serves hammered meat. The owner also presented a special dish to them, "a bitter soup with buffalo tendon spiked with bile," which Tony described as addicting.', 'Season 3'),
  ('d5829238-95cf-5387-bf69-6369c7245419'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had Pescado Frito at D''Wendy Sabor, one of the food stands on the beach', 'Restaurants and Bars'),
  ('d5b12578-4aa9-56f2-9cd3-bb01ad9e969d'::uuid, 'the_layover'::show_name, 1, 'Italian Japanese. Prawn & chili pizza, mango poke.', NULL, 'Season 1'),
  ('d5e64587-edb4-5a6e-ad89-67a491c1757e'::uuid, 'no_reservations'::show_name, NULL, 'Hawaiian hot dogs', NULL, 'Restaurants and Bars'),
  ('d5ed081e-0fae-57a9-b5f4-ae451fe6f9af'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met with Chef Michael White in this food market', 'Food markets'),
  ('d5f6710a-15e8-56c7-9f18-84d16fc65e74'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Former site of food stand called El Taco Rico, the best tacos in the area', 'Restaurants and Bars'),
  ('d5fe9c26-6650-514a-a7c6-04279f2db780'::uuid, 'parts_unknown'::show_name, 8, NULL, 'For Tony and Eric Ripert''s first place, they had dan dan tian shui mian.(spicy noodles) from this place.', 'Season 8'),
  ('d6027bef-8b0b-5510-8950-b881d9e8ed36'::uuid, 'no_reservations'::show_name, NULL, 'Italian gastronomy by Chef Michael White', NULL, 'Restaurants and Bars'),
  ('d604da48-60cb-5ead-bcb2-7baf7b414f42'::uuid, 'the_layover'::show_name, 2, 'Hosted the Beatles. Very "Twin Peaks"', NULL, 'Season 2'),
  ('d622baa5-b337-5cdc-bf32-3f22f61b64fc'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Can only have up to 3 toppings because the owner wants to showcase the good crust', 'Restaurants and Bars'),
  ('d64eb7df-e3f4-5c18-bdba-dbdfc36ae07c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They had biryani', 'Other Activities'),
  ('d671f5db-8b82-5718-80f8-27e7b834eafe'::uuid, 'parts_unknown'::show_name, 6, NULL, '"A private home turned restaurant serving very traditional Okinawan dishes," Tony describes.Tony had "tundaabun" or multiple bite-size portions served in a lacquered dish of "sliced squid; swordfish wrapped in seaweed and simmered in stock and fermented sake; dried sea snake, slow-simmered; burdock root wrapped in pork loin, slow-cooked in hot sauce; taro flash-fried and dressed with sugar and soy; pork shoulder dredged in black sesame, then steamed."', 'Season 6'),
  ('d68d4ef8-f316-5dde-9bda-d07e383e4436'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony and photojournalist Simon Go ordered Fried pork cutlet over rice with tomato sauce, soup with macaroni, spam and egg, French toast with peanut butter and condensed milk, pineapple bun.', 'Season 11'),
  ('d731eef7-5450-53b8-a7ae-2da3e588a353'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Some of the best fruits and vegetables are grown here due to the great soil. Tony raved about a tomato, "It''s nice to be reminded of how good a tomato can be" and "a near religious experience." They also drank Fragolina and sliced salami, good cheese, and crusty bread.', 'Other Activities'),
  ('d7398822-61b5-597b-8242-8b2f8d8b034f'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony had dinner of salmon marinated in pomegranate juice at a home in this town with Amichai Luria and Amiad Cohen', 'Season 2'),
  ('d7485fdd-f068-5930-9507-6e86bef27a6e'::uuid, 'the_layover'::show_name, 1, NULL, NULL, 'Season 1'),
  ('d754b795-620b-50a6-a585-1b2aa85892f0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'This was the former site of the east coast branch of the Pok Pok empire, but now closed.', 'Restaurants and Bars'),
  ('d793bc75-c508-5f04-b462-dd1c1f1a8462'::uuid, 'the_layover'::show_name, 1, 'Dirty history of Seattle.', NULL, 'Season 1'),
  ('d815183f-7ea6-57de-ae27-0c722ac768c9'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Resort where everyone gets a lakeside cottage. A man in a boat delivers a breakfast of rice pancakes with brown sugar and coconut milk in the morning.', 'Lodging'),
  ('d817b9f4-d84c-50ca-9ef1-87b66daeefc9'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Barakoda Restaurant, a seafood restaurant just outside of town on the Mediterranean. The menu is not printed, you select fish from the daily catch on ice and they cook it for you the way you specify. Tony ate fish, shrimp, and stuffed calamari', 'Season 1'),
  ('d8215a85-68f4-51d5-9272-0c6676414fd7'::uuid, 'no_reservations'::show_name, NULL, 'Caper farm', NULL, 'Sightseeing'),
  ('d842cc50-681f-50c9-8e8f-482869e84f5b'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a meal with Liza Fournier Cordova, a teacher. They had corn fritters with ham; plantain soup; pastel al caldero, or "pork marinated in bitter orange, taro root, green plantains, squash, and garbanzo beans, slow cooked"; morcilla (blood sausage).', 'Season 10'),
  ('d8579652-5e55-5eef-b787-11e320dd36ea'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had the famous sliders here', 'Season 4'),
  ('d8588c03-2af8-5d28-b939-c1ecbb0bf650'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony met with James Syhabout, a chef and restaurateur behind two-Michelin star restaurant Commis, in San Francisco. They had a bowl of khao piak sen, or Lao noodle soup, which is James'' first dish he seeks out once he gets off the plane. The dish includes crispy sliced pork, blood cake, meat broth.', 'Season 9'),
  ('d8812d19-151f-5083-9714-5225c8359792'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had chicharron, cabeza, and chorizo tacos.', 'Restaurants and Bars'),
  ('d8d2f68c-e5c5-5ca4-b53b-6cde7c0003d0'::uuid, 'the_layover'::show_name, 1, NULL, 'Palace of Juices. Also has other stands including fried plantains, arroz congri, and chicharrones. Roast pork sandwiches', 'Season 1'),
  ('d8fc6ed0-ef1c-51fd-9540-88319470801b'::uuid, 'a_cooks_tour'::show_name, NULL, 'Ice cream!', NULL, 'Disc 2: Mexico and The Americas'),
  ('d90d16de-e158-542d-ac4e-6a0c9356405b'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony ate with local chefs. They had a "clam bake with dungeness crab, spot prawns, corn, and potatoes, covered in kelp and steamed together under burlap."', 'Season 10'),
  ('d9205733-29a4-532d-81b2-3e56181d9792'::uuid, 'the_layover'::show_name, 1, 'Fancy', NULL, 'Season 1'),
  ('d92f37cc-c46d-50f5-9695-34e76463c116'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Market, depot, and food court. Tony and his friend Hector ate a platter of beef & onions with rice', 'Restaurants and Bars'),
  ('d947ef08-724d-5cee-89ba-9f9239624f72'::uuid, 'the_layover'::show_name, 1, NULL, NULL, 'Season 1'),
  ('d94d8daa-b41e-5b6f-8971-04ffa8c7452f'::uuid, 'no_reservations'::show_name, NULL, 'Thai bakery', NULL, 'Restaurants and Bars'),
  ('d975bf96-6590-56b0-a376-0f8b0c90bd7b'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Plant It Forward farmers Gertrude and Albert Lombo and Gimoule and Constant Ngouala hosted a meal with Tony and other friends. They had "slow-cooked stew of sausage, shrimp, dried mackerel, and Malabar spinach over fufu; then Texas beef brochettes marinated in chilies and cilantro and Maggi bouillon with a ratatouille made from produce grown right here."', 'Season 8'),
  ('d9885510-4241-590d-bda9-8271e8a7b011'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met up with David Chang again after the Cook it Raw competition and had yakitori.', 'Restaurants and Bars'),
  ('d9937d35-eba2-5bfc-900e-aeaf0c42c512'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony did a cheese tasting', 'Disc 1: United States'),
  ('d993a574-e542-5b52-ae5a-d7f3d67af776'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('d9c0423d-de7a-5a91-bd2c-5c153c602d93'::uuid, 'the_layover'::show_name, 1, 'Muscle cars and food', NULL, 'Season 1'),
  ('da0096e7-832c-543f-8229-28661303a066'::uuid, 'no_reservations'::show_name, NULL, NULL, 'African slaves worked on fields in this area and they created gullah culture. This restaurant serves traditional low country foods: frogmore stew and she crab soup made from Carolina blue crab. Frogmore stew is a boil with potatoes, corn, sausage, and shrimp.', 'Restaurants and Bars'),
  ('da57dd61-a917-5dc0-a0f0-f2e86a956373'::uuid, 'the_layover'::show_name, 2, 'Traditional Irish breakfast', NULL, 'Season 2'),
  ('da9c2c82-4543-55c5-aa4f-691fe3bc2d56'::uuid, 'no_reservations'::show_name, NULL, 'Dive bar', NULL, 'Restaurants and Bars'),
  ('dac65db5-1df7-5558-b02f-1cd0590d2896'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Chocolate factory of a famous chocolatier who is inspired by Gaudi', 'Other Activities'),
  ('dade4e82-bce3-5da1-b5b6-74c3fb6f7ac7'::uuid, 'no_reservations'::show_name, NULL, 'Dance club', NULL, 'Food markets'),
  ('dae41934-350f-5d93-8d1d-18eb0f3104b0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'For a big fat greasy sandwich, "a temple of big sandwich arts" which Tony also describes as "happiness"', 'Restaurants and Bars'),
  ('daea5da8-e7d8-5de3-9444-dfd3c10bf543'::uuid, 'the_layover'::show_name, 2, 'Ping pong bar', NULL, 'Season 2'),
  ('daec0356-19b2-58e0-80b8-1caa29a60fdf'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony had a family style meal with Presidio Mayor John Ferguson, his daughter Molly, her boyfriend, and the former mayor of Ojinaga', 'Season 12'),
  ('db38cf7e-5bfb-5449-a430-bf1e99493c5c'::uuid, 'the_layover'::show_name, 1, 'Ocean view restaurant', NULL, 'Season 1'),
  ('db7e993c-d0a7-5b2a-9a80-c68910a5bb57'::uuid, 'the_layover'::show_name, 1, 'Artsy gift shop', NULL, 'Season 1'),
  ('db8a1898-9865-5a35-91b0-6ffa765b7f21'::uuid, 'no_reservations'::show_name, NULL, 'Kitchen supply store', NULL, 'Other Activities'),
  ('dba5b25b-a21a-53f8-89e4-eccc53a40ec3'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony started this Vietnam journey at this bún ốc restaurant in Hanoi''s Old Quarter. Bún ốc is a snail noodle soup', 'Season 8'),
  ('dc3df4b9-02d8-598b-92c8-7b0c0ae85a72'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had grilled meats on a stick from a mobile food stand', 'Restaurants and Bars'),
  ('dc832e7b-1483-593b-8e7a-3c024144e5bd'::uuid, 'no_reservations'::show_name, NULL, 'Small plates restaurant', NULL, 'Restaurants and Bars'),
  ('dc8859e7-544d-51cd-8747-d8bb2db649ed'::uuid, 'the_layover'::show_name, 2, 'Every Friday night at The Kingpin. Tacos', NULL, 'Season 2'),
  ('dcb08900-ce4c-5966-9c69-07d15c66e2b7'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with the chef from Ox & Klee, Daniel Gottschlich and his friend Demetri to have grilled bratwurst with curry sauce.', 'Season 7'),
  ('dcbeb3c9-3662-52fa-9af1-3ba9c8b5a138'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Japanese Izakaya that is fancy and pricy, but casual. Tony met with Penn Jillette and ate sea urchin, tuna, Japanese river crab, hasaki sashimi, hasaki belly, juicy deep-fried chicken, hamachi belly, and fish collar', 'Season 3'),
  ('dcd6abc5-205a-5224-82d5-36c832ad6fe6'::uuid, 'no_reservations'::show_name, NULL, 'Ron Cooper makes mezcal here', NULL, 'Other Activities'),
  ('dd04d656-13ac-5c80-bbd5-84b53c1ea1b2'::uuid, 'the_layover'::show_name, 1, 'Pancakes that inspired a Beastie Boys song', NULL, 'Season 1'),
  ('dd12fcd5-994e-5d4a-80b8-3536898913fe'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony shops the farmers'' market with chef Olivier Roellinger', 'Food markets'),
  ('dd1d0c8f-7b56-56c9-9b42-5f86f8feea7b'::uuid, 'the_layover'::show_name, 2, 'Fish n chips. With curry sauce. The smoked cod is good', NULL, 'Season 2'),
  ('dd3170a4-f5d1-5b65-b22e-7eac0ff2b9cb'::uuid, 'no_reservations'::show_name, NULL, 'Oldest spice market in the Middle East', NULL, 'Food markets'),
  ('dd32f345-86ab-50ce-9be3-481b6342975b'::uuid, 'the_layover'::show_name, 1, 'Bumboat tour', NULL, 'Season 1'),
  ('dd56ffaf-6fcb-510e-a44f-d5162eae9399'::uuid, 'the_layover'::show_name, 2, 'Drive thru authentic tacos', NULL, 'Season 2'),
  ('dd74356a-9d18-573a-ae23-3a23af9cb2c9'::uuid, 'the_layover'::show_name, 2, 'Luxury hotel', NULL, 'Season 2'),
  ('dd7b15f3-a842-585c-94f9-d56f89eac018'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate chocolate', 'Restaurants and Bars'),
  ('dd8ada3f-abcd-57ee-877f-35dee9ec929c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Best chef in Montana, according to Tony. Buffalo, elk, and chicken gallantine, pork rilette. Braised whitefish stuffed with lightly smoked trout with a white butter sauce. Lavender rack of lamb with potatoes. Shortribs with morels. All local ingredients', 'Restaurants and Bars'),
  ('ddd6bab9-5a0f-5862-9e25-7c8fc40e4d27'::uuid, 'a_cooks_tour'::show_name, NULL, 'Oysters, crabs', NULL, 'Disc 1: United States'),
  ('ddd6bab9-5a0f-5862-9e25-7c8fc40e4d27'::uuid, 'parts_unknown'::show_name, 6, NULL, 'This was one of Tony''s regular stops when he visited San Francisco. He had crab and oysters.', 'Season 6'),
  ('ddd6bab9-5a0f-5862-9e25-7c8fc40e4d27'::uuid, 'the_layover'::show_name, 1, NULL, 'Seafood - one of Tony''s favorite SF restaurants', 'Season 1'),
  ('ddd7b16d-f4f4-5535-8a72-df197391074a'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Eric took a boat ride to see the largest stone buddha in the world, built in 713.', 'Season 8'),
  ('ddeb1193-8ec4-53aa-bdcd-e4848bf3429b'::uuid, 'no_reservations'::show_name, NULL, NULL, '"Lots of people, lots of food, lots of cats." A 24 hour food stand. The plate they got had fried chicken, fish roe, beef, shrimp, squid, veggies, sauces, rice.', 'Restaurants and Bars'),
  ('de058223-01d1-58f2-94b9-ac736103efa8'::uuid, 'no_reservations'::show_name, NULL, 'Rock concert', NULL, 'Other Activities'),
  ('de0b362a-f7c0-52fb-af91-4dba452b030c'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony ate at this restaurant with Eric Ripert and many women in the restaurant business, who discussed how it is to be a female chef in the male-dominated business.', 'Season 6'),
  ('de42fa46-868f-53ee-867c-30b3519c1b0d'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had a meal with Chef James Syhabuot and his friends/family. They had aw lahm, which is made with wood ear mushrooms, dill, pepper wood (a key ingredient infused into the dish, which imparts flavors of star anise and white pepper), two types of lahm made with buffalo (one raw, one cooked), and leuat paeng, a dish made from raw buffalo blood and herbs.', 'Season 9'),
  ('de917e09-273c-5b31-b93b-75a87126c6aa'::uuid, 'no_reservations'::show_name, NULL, 'Former site of Piccolo restaurant, closed in 2017', NULL, 'Restaurants and Bars'),
  ('de94dbf7-3978-5822-8af2-ba4532383ea8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Sheep and cattle farm. They hunted game and found white truffles', 'Sightseeing'),
  ('de9b7702-e750-5f06-bb0f-d2419ac8bcf4'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Chef Tandy Wilson made pizza for Tony and Dean Fertita (guitarist and keyboard player for Queens of the Stone Age, musician with the Dead Weather).', 'Season 8'),
  ('deb8b0ef-cce9-5e8f-a19d-241992ae0aff'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Grocery store. They shopped for Indian foods. Tony tried rambutan.', 'Disc 3: Europe'),
  ('debc9136-9f77-54e6-81ba-e5de1bbdb93a'::uuid, 'the_layover'::show_name, 1, 'Bao buns. Fried chicken and pork belly.', NULL, 'Season 1'),
  ('dee76cb6-7e5e-548d-a6e5-44c9b799ad99'::uuid, 'parts_unknown'::show_name, 1, NULL, 'The hotel where Tony and the crew stayed while in Tripoli.', 'Season 1'),
  ('df1185a5-42c7-5cef-9d8a-a31e6dddc7c4'::uuid, 'the_layover'::show_name, 1, 'Galleries and street art district.', NULL, 'Season 1'),
  ('df20fcac-3ead-5cb2-8844-728007dc8366'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a meal prepared by Meriko Gubeladze, a star chef at Tbilisi’s Black Lion Restaurant. They had spinach with walnuts and wild capers; pickled carrots; cheese curds with roasted hazelnuts and mint; roasted eggplant seasoned with coriander; kharcho, a stewed chicken cooked slow with ajika chili sauce, onions, marigold flower powder, and blue fenugreek, and cooked & served in a pumpkin.', 'Season 7'),
  ('df60b3ba-6785-5adb-b719-6a0efcd0741e'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony had camarones borrachos (Drunken Shrimp) with 3 MMA fighters: Gilbert Melendez, Nick Diaz, and Nate Diaz.', 'Season 9'),
  ('df6d17e7-2aec-5624-813b-9ede5135f260'::uuid, 'no_reservations'::show_name, NULL, 'Roast lamb in the country', NULL, 'Other Activities'),
  ('df7f51ee-4086-5cc3-b1a2-d407acdb82c5'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony ate here with Chef Stephanie Izard and Chef Peter Wong. They had pork dumplings in chili oil, mapo doufu, and fish hotpot.', 'Season 7'),
  ('df86d4cd-f8e0-5d40-9f84-72610d410482'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony visited this rail station that the Belgians built during their occupation of the Congo. About 200 volunteers still work at the station to keep it running. Tony took a ride on the train', 'Season 1'),
  ('df8f49cd-7181-5554-b1a4-426811951152'::uuid, 'the_layover'::show_name, 2, 'Great whiskeys and bourbons', NULL, 'Season 2'),
  ('dfb550a0-36da-5bc6-a45f-b8cce876866f'::uuid, 'the_layover'::show_name, 1, 'HUGE gift store', NULL, 'Season 1'),
  ('dfc91534-6886-5ece-8608-c6a7bf4dfc84'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('dfedbd1b-afcc-5e6c-bbf6-6894b443b26f'::uuid, 'the_layover'::show_name, 1, 'foodie books', NULL, 'Season 1'),
  ('dffe86ac-d216-5dee-8876-f93b2dacf84b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony stayed in this little town with his cameraman for the show. They did woodsman things like chop down trees and eat venison , rabbit, and bacon', 'Other Activities'),
  ('e016544c-9a59-5414-85fe-09a07dc4bf4d'::uuid, 'the_layover'::show_name, 2, 'Famous journalists eat here. Beer and burgers.', NULL, 'Season 2'),
  ('e0615f4a-c540-5fe1-86fc-658779c37806'::uuid, 'no_reservations'::show_name, NULL, NULL, 'A market made on top of an active railroad. They have to move and pause the market every time the train comes through.', 'Food markets'),
  ('e0aea1c2-3ee2-545c-9121-6e3d47378a68'::uuid, 'no_reservations'::show_name, NULL, 'Turkish tea, fried cheese, olives, assorted breads', NULL, 'Restaurants and Bars'),
  ('e0ba631b-1635-578e-960e-244ec301b140'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Sightseeing'),
  ('e0d75f55-60b8-5735-87eb-8aa8ddbcee26'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony took a boat ride aboard the Emeraude to this bay, one of Vietnam''s most visited destinations. "Hạ Long means ''where the dragon descends into the sea'' and legend says that this is where a great dragon charged, protecting Vietnam from foreign invaders."', 'Season 8'),
  ('e0f93f5a-381e-5f62-894a-d71c6ad0ee13'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony and Kamau went shoe shopping at this discount market', 'Season 12'),
  ('e10fa40c-04e4-5a7e-8191-b37315342d22'::uuid, 'the_layover'::show_name, 2, 'Oldest market in the city with food stands', NULL, 'Season 2'),
  ('e1531539-b818-5292-b05f-2e4787049313'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony stayed here', 'Disc 3: Europe'),
  ('e155c057-7a24-53f7-a9d2-bbf054ef0473'::uuid, 'no_reservations'::show_name, NULL, 'Oldest ferris wheel in existence.', NULL, 'Other Activities'),
  ('e1abc06e-a396-572b-a6ad-230cb1b39ed1'::uuid, 'the_layover'::show_name, 1, 'Best view of the city', NULL, 'Season 1'),
  ('e1ad0123-a909-5f96-aadb-0aebef3aed8a'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had drinks at the rooftop bar of this restaurant/hotel.', 'Season 6'),
  ('e1c2fac7-99d4-540c-9635-9c7682e49809'::uuid, 'the_layover'::show_name, 1, 'Pub with burgers and wild boar sloppy joes', NULL, 'Season 1'),
  ('e1dd8a08-c687-5bf6-a4cc-c2cd163335fa'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony took a diving tour to see a sunken ship that sunk in 1982.', 'Season 7'),
  ('e1e43c99-5e83-505c-8dd6-0cd6eb6bb907'::uuid, 'no_reservations'::show_name, NULL, 'Fancy schmancy', NULL, 'Restaurants and Bars'),
  ('e1eb702b-2da7-58a1-8bac-0786ddc944ab'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony ate in Chef Eduardo Garcia''s kitchen at this restaurant, one of the hottest places in Mexico. He ate abalone with chiles, lemon, and brown butter; confit of suckling pig, "topped with grandma’s salsa and served on a tortilla."', 'Season 3'),
  ('e1fad9da-ebc8-56e1-99a6-251c15e8b2b3'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony visited this flea market with Anton and his son Wolfgang. They purchased records at one stand.', 'Season 11'),
  ('e2141bf6-d257-5d8a-ac55-f5f22bb9e497'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Date farm with café, gift shop, and gardens. Tony had a date milkshake', 'Other Activities'),
  ('e2542c54-e5f3-515d-9626-c69325d6f92f'::uuid, 'a_cooks_tour'::show_name, NULL, 'Guinness.', NULL, 'Disc 3: Europe'),
  ('e25fbeb6-23bb-5151-a57b-ec8a2dec3204'::uuid, 'the_layover'::show_name, 1, 'PORK', NULL, 'Season 1'),
  ('e273d0ef-a4ab-598d-b110-53141aa916c4'::uuid, 'parts_unknown'::show_name, 11, NULL, '"This is what my soul needed,” Tony said as he ate braised lamb shank with rice pilaf; vegetable manti', 'Season 11'),
  ('e2805eac-7a47-5faa-aa7f-8fc03819761c'::uuid, 'the_layover'::show_name, 1, NULL, 'Hawker food center. Have at least 3 meals at any one of these food centers! Indian, Malay, Chinese food.', 'Season 1'),
  ('e28a228e-af27-5bff-a41c-50d84e479523'::uuid, 'no_reservations'::show_name, NULL, 'Sightseeing', NULL, 'Sightseeing'),
  ('e2ded8bb-653e-5619-9e7c-62ae3ce2dfad'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with former police chief John Carnochan and had lamb curry simmered in spicy tomato gravy and naan', 'Season 5'),
  ('e2e58e0d-38bb-5de8-9a30-5af7f5412763'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony went to a free range pig farm located in this national park. They cooked one of them, using the lungs and liver in a stew with garlic, chili pepper, red wine. They also make blood sausage and serve it with homemade cured meats, local cheese, and homemade wine.', 'Season 2'),
  ('e38928c7-a11c-559b-b6c1-e73b831b7824'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Seasonal restaurant; Tony had a dish that had fresh artichokes, fava, peas, and pancetta. Also a baby lamb dish, a salad with roman chicory and anchovy.', 'Restaurants and Bars'),
  ('e3bec8c6-bb2a-5a3f-b619-cebd74751047'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony spoke with the owner of this restaurant whose daughter was killed. They discussed both sides of the conflict.', 'Season 2'),
  ('e3cf91ab-e86a-5fb5-95c7-96dce362f767'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, '"Flavors of the forest" as in they serve all kinds of animals. Tony famously ate a still beating cobra heart here.', 'Disc 6: Asia'),
  ('e3ee9983-0e6c-5a7f-8675-b827a7247a29'::uuid, 'no_reservations'::show_name, NULL, 'Bobby Flay''s restaurant', NULL, 'Restaurants and Bars'),
  ('e4129238-1cd5-5a81-9b40-cbb473794ca1'::uuid, 'no_reservations'::show_name, NULL, 'Creative pizzas with housemade sausage', NULL, 'Restaurants and Bars'),
  ('e4303280-9818-58a5-ac99-f12026e94990'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Margaritas and beer, and a whole roast pig is cooked underground in a barbecue known as a matanza.', 'Season 2'),
  ('e4543889-6c1a-51ef-bc4a-a493096a4940'::uuid, 'a_cooks_tour'::show_name, NULL, 'Spring rolls, pho, Vietnamese iced coffee', NULL, 'Disc 1: United States'),
  ('e49298de-55b2-5e2e-aa6e-24eb3ede32c1'::uuid, 'the_layover'::show_name, 2, 'Poutine', NULL, 'Season 2'),
  ('e49702ae-90c1-5e48-96b8-d3cb173434b8'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony, Fred, and Dave went to this island to visit Maïté Legasse, home cook and director of Ma P’tite Cocotte. They had sea urchin pâté, stuffed squid over rice, braised halibut, local cheese, tart with local baked apples and blackberries.', 'Season 11'),
  ('e4db2d1e-4e5b-5a35-886f-577ebcce723a'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Cuban coffee and food. Tony met with chef Michelle Bernstein and had a medianoche sandwich (roast pork, ham, Swiss cheese, pickles, and mustard)', 'Season 5'),
  ('e50460f6-ec89-55b6-8228-2776ac56fbd1'::uuid, 'the_layover'::show_name, 2, 'Open air market', NULL, 'Season 2'),
  ('e54d615e-0a0a-5545-a097-40866bcaefcb'::uuid, 'parts_unknown'::show_name, 4, NULL, '"Ladies in orange vests cook and serve old school Paraguayan working class food to people from every walk of life," Tony explains. They ate empanadas de carna (beef, onion, and hard-cooked egg).', 'Season 4'),
  ('e56de1f3-ca2e-5996-aa06-6a048382414c'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Castillian food. Diego and Pepe (brothers) run this restaurant. modern twists on traditional dishes using hyper-local ingredients', 'Restaurants and Bars'),
  ('e5ede5e9-6682-5cd5-9282-9512612ae52a'::uuid, 'the_layover'::show_name, 2, 'Neo Retro Southern cooking', NULL, 'Season 2'),
  ('e63cb8ea-d64d-59cc-a11f-1108b4d29995'::uuid, 'the_layover'::show_name, 2, 'Rare whiskeys', NULL, 'Season 2'),
  ('e65cfe40-9733-50b0-8ae2-3a613eb961a5'::uuid, 'parts_unknown'::show_name, 6, NULL, 'One of Chef Sean Brock''s restaurants, Tony and Billy Murray had a meal here. "Husk directly addresses Southern culinary traditions using the best of modern techniques, but always, ALWAYS respecting the originals and who made them," Tony says. They had old country ham made from a pig brought over from Spain in the 1500s called asabal, and aged 3 years. They also had oyster pie (a pre-Civil war recipe), shrimp & grits, hoppin john with Carolina gold rice, grilled whiting, suckling pig, creamed corn, and cornbread.', 'Season 6'),
  ('e66fa9d0-5f4f-56d0-80f0-fdac5273a73f'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony shopped here to prep for a turkey hunt.', 'Season 6'),
  ('e672c1e4-ac7c-5093-95a1-8c1170d11a12'::uuid, 'no_reservations'::show_name, NULL, 'Fried meat fritters', NULL, 'Restaurants and Bars'),
  ('e68393db-ef0c-5ee7-931d-8b79f3ff5b49'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had lunch here: bánh xèo (rice-flour pancakes), steamed and topped with fried shallots and cassava paste and crumbled fried shrimp; bánh bột lọc (cassava or tapioca with pork and shrimp wrapped in a banana leaf); fried sticky-rice dumplings filled with shrimp', 'Season 4'),
  ('e6c371dd-d596-5299-ae1b-5ff819484717'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony''s handler is from Belfast, and owns this pub', 'Restaurants and Bars'),
  ('e6f63afe-c8d4-55d1-87dc-944943233e52'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met with Zamir and got some khachapuri, a fried bread with cheese inside.', 'Restaurants and Bars'),
  ('e769fc08-5557-588d-adb6-bff0923b898b'::uuid, 'no_reservations'::show_name, NULL, 'Teaching kitchen cooking downhome classic Southern food', NULL, 'Restaurants and Bars'),
  ('e777d211-0e4e-5779-b095-bb4d32ea9346'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited this small town in Turkey where they are celebrating a new child. They slaughter a sheep for the meal.', 'Other Activities'),
  ('e781b975-4b04-5f89-a030-b19ade33fcaf'::uuid, 'no_reservations'::show_name, NULL, 'Chef Olivier Roellinger''s restaurant', NULL, 'Restaurants and Bars'),
  ('e849e977-bae9-55d6-926a-2d274d411cff'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Dead Weather and The Kills both performed at this house party. Tony and Matthew (Alison''s chef brother) cooked a bunch of food including apple walnut salad, fried pork dumplings, pulled pork with red cabbage, brisket, and deviled eggs because "it ain''t a party without deviled eggs."', 'Season 8'),
  ('e8733a30-eecd-56ef-b0ac-54074c9e38a3'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony had espresso with Jonathan Dawson, British journalist', 'Season 1'),
  ('e8dd8723-2184-5bf6-928e-e67524d54e26'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Izakaya. They had assorted yakitori and dumplings', 'Restaurants and Bars'),
  ('e8e66654-5310-550f-993a-f0e13b645969'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and Eric stopped at this food stand specializing in beef heart, marinated with garlic, cumin, onion, and vinegar and grilled.', 'Season 1'),
  ('e909482e-b470-5b6f-b93b-bb9700fbc0e5'::uuid, 'the_layover'::show_name, 2, 'Death metal and burgers with whiskey on tap.', NULL, 'Season 2'),
  ('e93596ef-b25a-54e1-80e4-b19c0673ed27'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony met with Tawanda Jones, founder of a youth empowerment advocacy to talk about her drill team group. He ate eggs, meat, rice and soup for breakfast.', 'Season 5'),
  ('e946c27d-b32b-50a0-99be-f55a511d92d7'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony and Eric Ripert went skiing here in the French Alps, which Tony describes as a place he fears, but is allowing Eric to have "payback" for the torture Eric endured in Sichuan China.', 'Season 10'),
  ('e95c65d2-7e21-55c2-a922-6d58fe19097e'::uuid, 'a_cooks_tour'::show_name, NULL, 'Food market', NULL, 'Disc 6: Asia'),
  ('e9abb523-daf0-586f-85c3-315e82009be3'::uuid, 'parts_unknown'::show_name, 6, NULL, 'A public food market where you can pick out the fish and they will cook it for you. Tony had snapper and parrot fish sashimi; sea grapes dressed in vinegar; gurukun (unofficial national fish of Okinawa) battered and deep-fried; porcupine fish, battered and deep-fried.', 'Season 6'),
  ('e9c5b3a2-099e-55f8-860a-1103ba99c837'::uuid, 'no_reservations'::show_name, NULL, NULL, '"The only tram in the world licensed to sell booze." Tony drank a beer on one.', 'Restaurants and Bars'),
  ('e9c94957-a5b1-53f5-be05-652b752becc8'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, '"Please God kill me now. Just strike me dead." Tony said as he sat in an empty cafe. Pastries are good though.', 'Disc 3: Europe'),
  ('ea297148-e96e-586a-9799-b6b0ed6612cd'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Bringing together different regions of artisanal and organic foods in a market. "Southern coastal bread bakers, kibbeh specialists from the mountains, wild herbs & vegetables from the Bekaa Valley, and pastries made from almost forgotten recipes. It''s all here," Tony says.', 'Food markets'),
  ('ea573c16-f0e3-5fb2-ac4a-400411cedc82'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Blintzy - a thin pancake filled with savory or sweet fillings. Tony had one with yogurt and dried apricot.', 'Disc 4: Morocco & Russia'),
  ('ea90f0ec-756a-5880-b730-59ad701ad964'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony, Eric Ripert, and Joel Robouchon ate oysters at this cafe', 'Restaurants and Bars'),
  ('ea998ca7-5e10-5ca2-8644-f51d83568b6b'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony watched a game of "shinny hockey," a pickup game of street hockey played on the ice. Meanwhile they ate Choucroute garnie a l''alsacienne (lots of meats and sausages piled on a plate).', 'Season 1'),
  ('eaadb42b-240d-5054-b635-768f786b0d4e'::uuid, 'parts_unknown'::show_name, 4, NULL, NULL, 'Season 4'),
  ('eaba3b64-03ee-5dca-8d0e-f3480562c838'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and his guide watched iguanas in the park.', 'Sightseeing'),
  ('eac2512e-edbf-5fec-bd14-cfbedec857f6'::uuid, 'a_cooks_tour'::show_name, NULL, 'Salt cod, Portuguese national dish', NULL, 'Disc 3: Europe'),
  ('eae9ca55-4e72-59bb-bd87-e2ada802b717'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Argentinian grilled meats. Upstairs is the Gardel''s Bar where Tony watched some hipster band.', 'Restaurants and Bars'),
  ('eaee0b3d-1432-55a8-8f29-1f528526c47e'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony and his Director of Photography Zach Zamboni (who lives part time in Andalucia with his wife), ate a lunch of snails in almond sauce at this eatery with seating outdoors.', 'Season 2'),
  ('eb3d8d6b-5218-5b89-ac28-b828e6a4f366'::uuid, 'no_reservations'::show_name, NULL, 'Former site of restaurant L''Espérance', NULL, 'Restaurants and Bars'),
  ('eb438d91-18bd-522d-afc5-2905b071547c'::uuid, 'the_layover'::show_name, 2, 'Great cocktails', NULL, 'Season 2'),
  ('eb466acd-22c7-582d-8841-536436436af0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Fishing village. They ate lobster at the only restaurant on the island.', 'Sightseeing'),
  ('eb4f27b5-60a9-56a5-b2be-b9eab5e227b1'::uuid, 'no_reservations'::show_name, NULL, NULL, NULL, 'Restaurants and Bars'),
  ('eb722484-0ae5-5856-a256-b83fa37c8aeb'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony watches Ottavio''s jiu jitsu match, which she wins!', 'Other Activities'),
  ('ebaf2cf7-37e8-5d07-b2af-caa4e8a05467'::uuid, 'the_layover'::show_name, 1, 'Roti, kebabs, sandwiches', NULL, 'Season 1'),
  ('ec0690e0-9a88-5c57-aa34-95354967f7fa'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony got his "meat in tube form" from this place, which deep fries the dough with the meat inside. "It''s like a hot dog donut," Tony said.', 'Restaurants and Bars'),
  ('ec37bda0-d0ed-5eb6-89aa-b5600944527f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'World famous tostada food cart. Fresh scallop with purple onion; Salt cod with onion, olives, tomato, chiles, abuelita sauce; octopus with red snapper ceviche, and avocado', 'Restaurants and Bars'),
  ('ec56d74e-f5c0-5d7d-987b-12e233b49194'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and David Choe went to this dive bar that Tony loved.', 'Season 1'),
  ('ec722246-2a05-5942-ad5e-e7d2cbf32903'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a breakfast called fooll from a food cart. Fooll is breakfast made of beans and eggs that is served with a flat bread.', 'Restaurants and Bars'),
  ('ec7be05c-d70b-553f-a1e5-ef4c26fbd94b'::uuid, 'the_layover'::show_name, 2, 'Grilled meats with rice and fixin''s', NULL, 'Season 2'),
  ('ec8f7467-f99a-5e72-8740-c5554a0ee479'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Chef Sean Brock introduced Tony to the wonders of the Waffle House, the only place for late night eats in the area. They had pecan waffles, patty melt cheeseburger, green salad with Thousand Island dressing, thin-cut pork chops, T-bone steak, hash browns', 'Season 6'),
  ('ec9e4b40-4b43-599a-ba2f-1091b7f991d7'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony ate with Chef Glen Roberts, owner of heirloom grain company Anson Mills. He ate in season soft-shell crab with pasta and shaved bottarga ("which frankly, I''d slit my best friend''s throat for"), heirloom rice and peas with suckling pig and chicken confit over Carolina Gold rice', 'Season 6'),
  ('eca6178a-c8c8-52e0-88a2-3a745271c191'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, NULL, 'Disc 1: United States'),
  ('eca6178a-c8c8-52e0-88a2-3a745271c191'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had Portuguese Kale Soup with linguisa, and crab-stuffed cod.', 'Season 4'),
  ('ecb2bd57-000b-5cba-8772-2423c0305c91'::uuid, 'no_reservations'::show_name, NULL, NULL, 'At Naschmarkt, they stopped at this butcher with a small kitchen in the back room to make cordon bleu. Tony and host bought the ingredients in the market', 'Food markets'),
  ('eccaee4d-5096-53ca-aef9-937f2836a688'::uuid, 'parts_unknown'::show_name, 8, NULL, 'One of the BEST sushi places in the world. Masa learned here. They had seared horse mackerel over green onion and ginger, maguro (bluefin tuna), Japanese tiger prawn, octopus, fluke sashimi, striped jack, anago (sea eel) rolled in seaweed, and tamagoyaki (breaded shrimp eggs and fish paste)', 'Season 8'),
  ('ecf12702-5d75-5902-b2d0-2fa116befd46'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Tony took a boat ride to this island and had fresh lobster with an anthropologist on this island that used to be a penal colony.', 'Season 12'),
  ('ed99fc5d-af58-5082-9aba-e640fbf4ca85'::uuid, 'the_layover'::show_name, 1, 'Bar', NULL, 'Season 1'),
  ('eda560a4-67f5-5976-8628-c19c1c8c87a8'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had black clams, a regional specialty. It was made into a ceviche with shrimp, red onion, cilantro, tomato, and roasted corn. Sprinkled with fried banana chips', 'Restaurants and Bars'),
  ('edb457f8-bdf2-59f5-bd07-afe73a1f3ba7'::uuid, 'the_layover'::show_name, 1, 'Beer garden', NULL, 'Season 1'),
  ('edcf0a1a-e45e-5f64-add0-54d2951c5312'::uuid, 'a_cooks_tour'::show_name, NULL, 'Just a good burger', NULL, 'Disc 1: United States'),
  ('edef901e-2899-5a89-8108-92dd1b3da78d'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had Iranian biryani here.', 'Season 4'),
  ('ee20ee7a-d4ff-57bd-9b22-a79eb98af8b5'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Closed now, it used to be Le Veau D''Or, a French restaurant since 1937', 'Restaurants and Bars'),
  ('ee3e46dc-5e44-5cea-a279-4acbf0dbd637'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony had dinner at Tomaso''s mother''s home. They had caponata; bread and tomato salad; shrimp sautéed in garlic, butter, and herbs; sardines fillet sautéed in garlic, oil, and red pepper', 'Season 2'),
  ('ee919a1c-b1f5-5d8e-801d-fd8834728042'::uuid, 'the_layover'::show_name, 2, 'Pea meal style bacon sandwich', NULL, 'Season 2'),
  ('ee920ef5-5ccc-51de-9c52-fb93d5c49a4b'::uuid, 'the_layover'::show_name, 2, 'Top Chef Stephanie Izard''s restaurant', NULL, 'Season 2'),
  ('eea00961-3a29-53cc-82bb-914db6e760b6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Closed now, but this used to be the Rusty Star BBQ, where Tony ate barbecue with Ted Nugent', 'Restaurants and Bars'),
  ('eec44a58-b156-5092-ad5a-c2cabe5eb264'::uuid, 'a_cooks_tour'::show_name, NULL, 'Meat pies', NULL, 'Disc 3: Europe'),
  ('eec597c6-b446-5534-aa67-02f4f3d9dff9'::uuid, 'parts_unknown'::show_name, 1, NULL, 'David Choe bought his parents a house in Los Feliz. Tony and David visited the home and Jane Choe, David''s mom, cooked for them. She made beef ribs stew, kimchi, chestnut rice, stuffed peppers, seaweed and jellied mung bean, japchae with shiitake, avocado eggrolls, fried squid, potato pancake.', 'Season 1'),
  ('eed22fd9-7ba1-5b7d-8970-a8defd2a8f08'::uuid, 'the_layover'::show_name, 1, NULL, 'Tony had crispy pork ears and deviled eggs', 'Season 1'),
  ('eefc11d2-7249-5208-a69e-9c8c7008c61b'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with a group of entrepreneurs to discuss the economy of Senegal to have drinks.', 'Season 7'),
  ('ef2d1c0f-4b1c-5721-b6e8-4de1bba24463'::uuid, 'parts_unknown'::show_name, 1, NULL, 'After meeting at David Choe''s secret studio where David painted Tony''s portrait, the two went to Sizzler to eat. David introduced Tony to his creation, the Salad bar meatball taco.', 'Season 1'),
  ('ef3b1e33-7da3-521b-8c41-7dc5b17fb903'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('ef5f866d-c573-57b9-a1f7-cdb928da5a58'::uuid, 'the_layover'::show_name, 2, NULL, 'He Xiang Delicious. Bamboo shoot soup with lotus leaves and savory dumplings. Lotus Rice Parcel: Steamed sticky rice with salted duck egg and pork, served with a sweet red sauce', 'Season 2'),
  ('ef727a44-a2d2-59d5-b8ca-05375471d2ab'::uuid, 'no_reservations'::show_name, NULL, 'Terrence Brennan, artisanal cheese maker.', NULL, 'Food markets'),
  ('efbf8c32-cac1-5b05-a09b-70e0fe0e8076'::uuid, 'no_reservations'::show_name, NULL, NULL, 'World Resurrection Ministries, where Tony attended a church service', 'Other Activities'),
  ('efdb01da-5acd-5c13-a08d-4e3b705005a1'::uuid, 'parts_unknown'::show_name, 8, NULL, 'An inn and a restaurant. Tony and Chef Marco Pierre White had "a pan-roasted filet of beef with escargot; pig''s trotter a la Pierre Koffman. The chef raises the pigs on the grounds of the inn.', 'Season 8'),
  ('f01c6f97-d3ee-570f-8f26-77a57ca72eb4'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony and his brother Chris ate some croissants/bread here', 'Disc 3: Europe'),
  ('f05267f3-4ac7-543f-b9b8-827b7f73d906'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate fresh uni and seafood at this market', 'Food markets'),
  ('f0539cb1-9418-5a75-9393-706edd73bda3'::uuid, 'no_reservations'::show_name, NULL, NULL, 'The owner called it a Soviet bar. They ate blood sausage that someone brought, and drank vodka.', 'Restaurants and Bars'),
  ('f0680268-ebca-56ac-8617-2ff8d61c4b26'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had beer and a burger with author Stewart O''Nan.', 'Season 10'),
  ('f079c647-5c66-5487-8abd-531440a8e7c0'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had a sandwich and fries with Sala Udin, Hill District community leader, former councilman.', 'Season 10'),
  ('f08e86b1-9fcb-50bb-ac8a-9295b4ea8866'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Somewhere on the outskirts of Stone Town, Tony visited a vendor that specializes in meats on skewers. He had beef on a stick, chicken (prepared with garlic, lime, coriander, ginger, salt, and pepper), tamarind-chili sauce, fries.', 'Season 4'),
  ('f0b4d4ab-c454-5110-be82-7708a7cf9211'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony called it "endless"', 'Disc 6: Asia'),
  ('f0b4d4ab-c454-5110-be82-7708a7cf9211'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited and reminisced about his first time at Angkor Wat, when he gave up taking pictures during his traveling, because it was so awe-inspiring it could not be captured on film.', 'Sightseeing'),
  ('f0f39a28-c9df-5daa-9120-44345c9da1b6'::uuid, 'parts_unknown'::show_name, 11, NULL, '"The gateway to Central Bhutan," Tony describes. He met with Dr. Nawang Norbu and Darren Aronofsky to have yak butter tea, yak jerky with spiced greens, yak cheese, dried chilies, ara infused with Cordyceps, a fungus that kills its caterpillar-larva host.', 'Season 11'),
  ('f0f515fb-5347-5e80-8419-964362e7e3f0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony shared a Negroni and some thin sliced mortadella with fresh bread with Chef Michael White', 'Restaurants and Bars'),
  ('f11c03e5-5306-52f5-875e-2bdbdecb0d6f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony bought a $3000 Hawaiian shirt', 'Sightseeing'),
  ('f147b132-0a69-51ea-87c8-85cfa970a4f0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met Madame Kek, a humanitarian, in this seaside town that used to be a resort town for rich people before 1970 and is now in ruins. They went to the crab market and bought crabs, shrimp, rice, and rambutan.', 'Food markets'),
  ('f15552d9-8e68-584f-b5fa-4f67de9f72dc'::uuid, 'parts_unknown'::show_name, 1, NULL, 'This restaurant is supposed to be in Goma, Rwanda, called Village Fatimata. It specializes in Congolese cuisine like grilled piri piri chicken and gugali. This is the only restaurant with the same name, cannot find it in Goma.', 'Season 1'),
  ('f157baf7-1649-5a8d-8583-5537f1db8d68'::uuid, 'the_layover'::show_name, 2, 'Bagel sandwiches, full English breakfast', NULL, 'Season 2'),
  ('f15a5b81-d614-5705-b645-e1194aa0262d'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had barbecued galeto (baby chicken), which is popular for this dish. Tony had this with potato chips, broccoli rice, and farofa.', 'Restaurants and Bars'),
  ('f194e238-6de9-5f9d-a50b-409ddf3bcf72'::uuid, 'the_layover'::show_name, 2, 'Chicago hot dog.', NULL, 'Season 2'),
  ('f197c87c-1554-50d5-84af-b2f394e0798e'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They ate soup at a restaurant where noodles are made by hand', 'Restaurants and Bars'),
  ('f1ad75cd-2045-587d-9243-063c63c12ae2'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony ate with internationally renowned author Leonardo Padura. They had fried pork and plantains with flan made out in a cut down beer can.', 'Season 6'),
  ('f1dcfdd8-409f-5d78-b261-de04df00ac35'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony visited in the winter time and met up with chefs Fred Morin and David McMillan of Joe Beef. They went ice fishing on the St. Lawrence River, then ate a fancy meal in the small cottage on the ice.', 'Season 1'),
  ('f1e4ffa0-73ba-55da-a7c1-995e31914f71'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and his friend went to the back of the shop to try fresh buffalo mozzarella and prosciutto', 'Food markets'),
  ('f1fe4970-f764-52ee-b4c2-ca617e8909e8'::uuid, 'the_layover'::show_name, 2, 'Club and nightlife', NULL, 'Season 2'),
  ('f22c09a0-2f72-50cc-879a-fd173c73d0a0'::uuid, 'parts_unknown'::show_name, 7, NULL, 'The pink lake, as it is called, is a site for harvesting salt, but is also known as the finish line "for a legendary trans-African endurance race." Tony sat with a driver as they did some offroading then had a meal together.', 'Season 7'),
  ('f244b710-a284-5fce-8b4b-0518601cd64a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'After lots of delays where the crew could not secure permission to film, they finally got to eat at this Vietnamese restaurant in Little Hanoi.', 'Restaurants and Bars'),
  ('f24c8671-6c5c-592a-bcd0-647e75b90d9b'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony ate lunch with Bill Murray here', 'Restaurants and Bars'),
  ('f27bcbb9-8cd7-546c-83c5-a282d5dfb540'::uuid, 'no_reservations'::show_name, NULL, 'Po Boys', NULL, 'Restaurants and Bars'),
  ('f295ec1a-9a97-564c-a4ce-ee528cfe30b1'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony visited this high school where football is life. Tony attends the pre-game meal of ribs, baked potatoes, and chicken.', 'Season 11'),
  ('f2b9417b-3fd4-52a1-9d2e-1d32ee03b97d'::uuid, 'the_layover'::show_name, 2, 'Dive bar', NULL, 'Season 2'),
  ('f2c12350-ecaa-5e19-879e-448acc9c6131'::uuid, 'the_layover'::show_name, 2, 'Mosaic museum', NULL, 'Season 2'),
  ('f2f6803e-1f11-57f7-83c1-40404e40e93f'::uuid, 'the_layover'::show_name, 2, 'Food and beer', NULL, 'Season 2'),
  ('f31e3630-bc3e-5314-9dc6-fab91433051d'::uuid, 'the_layover'::show_name, 1, NULL, 'Have a Peanut Pancake. They roast and grind their own peanuts.', 'Season 1'),
  ('f32306df-70d0-5274-b315-d415b1f04e92'::uuid, 'a_cooks_tour'::show_name, NULL, 'Specializes in octopus', NULL, 'Disc 3: Europe'),
  ('f325090a-099f-5bf0-8d55-470c47fa373a'::uuid, 'the_layover'::show_name, 1, 'The Cuban pork roast sandwich has a cult following.', NULL, 'Season 1'),
  ('f32c9663-9630-5b17-9262-4865eb274b0b'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony ate here with a tattoo artist that did his ouroboros tattoo, Eddie David of Borneo Ink.', 'Season 6'),
  ('f3360277-b4f1-5698-8d2a-fc2705e0e0c2'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had a meal of khash (stock flavored by roasted-beef bones) with lavash.', 'Season 11'),
  ('f37a81cb-23a2-5df2-b3f2-a3f2435114f7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'In Sheepshead Bay, clams, fried calamari, lobster fra diavolo.', 'Restaurants and Bars'),
  ('f39a7718-5a25-5c75-81e9-a81bf6f66c62'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with Chef Marco Pierre for deep fried haddock, mushy peas, and a chip butty.', 'Season 8'),
  ('f3a4e5cd-ad53-544b-bfd3-9d9efe4f9e15'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Tony ate chili dogs, but craved a hot dog without chili', 'Disc 1: United States'),
  ('f3c06a87-8ca8-5d00-a034-63f04f8a3e6a'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony camped here with Chef Boulud', 'Sightseeing'),
  ('f3cf1ac8-2300-55d6-bdf4-eecdb4c7e7b3'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Dive bar where Tony drank some Jameson Black', 'Season 3'),
  ('f43d044b-4e0b-51be-b017-aae5af219e96'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Amuse bouche of foie gras; Crab with flying fish eggs and spring vegetables in a foie gras gelee; Blood sausage ravioli (one the best things Tony had all year); Roasted veal with sauteed chanterelles with an almond rhubarb jus; cheese platter. They do a bistro menu during the day with the best ouef mayonnaise (deviled eggs) on earth.', 'Restaurants and Bars'),
  ('f44ef7f9-0b17-522c-a956-236955d39b49'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had lunch with local fisherman and discussed the economy. They had souvlaki, fries, and other Mediterranean goodies, and Mythos beer.', 'Season 7'),
  ('f45aaad1-99eb-5ad7-87df-54995a376604'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony had uni pasta and beer.', 'Season 10'),
  ('f466d790-f040-5d7c-b85e-48538f4df74d'::uuid, 'a_cooks_tour'::show_name, NULL, 'Herbal medicine + food', NULL, 'Disc 6: Asia'),
  ('f48862e1-2a4e-5be9-99a1-2cc1cb9b4050'::uuid, 'no_reservations'::show_name, NULL, 'Old imperial town', NULL, 'Sightseeing'),
  ('f48fb60c-4e99-5617-adfa-adfe522327e1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Drunken late night munchies brought Tony and his host to this sausage stand.', 'Restaurants and Bars'),
  ('f4bb96be-2676-5b54-ba66-1c13aa945326'::uuid, 'no_reservations'::show_name, NULL, 'Sprawling indoor farmer''s market opened in 1912', NULL, 'Food markets'),
  ('f4c80e0c-3663-5df9-921e-a790f7071949'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a meal with Argentina''s most famous chef, Francis Mallmann. They ate empanadas, grilled beef, and blood sausage', 'Season 7'),
  ('f51df9f1-77ea-5539-b814-2312dee25019'::uuid, 'the_layover'::show_name, 1, 'Fancy cocktails', NULL, 'Season 1'),
  ('f575a1d2-0d0f-57c8-85c4-41ca0194a704'::uuid, 'no_reservations'::show_name, NULL, 'Raw meat restaurant', NULL, 'Restaurants and Bars'),
  ('f57e12a1-de4a-5dbd-b4cd-7bd5be1fefb9'::uuid, 'the_layover'::show_name, 1, 'One of 2 main farmer''s markets', NULL, 'Season 1'),
  ('f5b4eebf-1414-5f70-bdc8-bbf2f37a6046'::uuid, 'no_reservations'::show_name, NULL, 'Lamb and beef raised grazing on the land in the farm.', NULL, 'Other Activities'),
  ('f5b7df7e-f740-50b2-8586-bf5ee0c604a6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had a proper English breakfast at The Cock Tavern which he said was directly below Smithfield Market, but I could not find that on the map', 'Restaurants and Bars'),
  ('f5c3d6a5-1d5b-5e50-b832-7c06d2ea7526'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony tastes many fruits here not found anywhere else. He also has fish called Filhote, a 600 lb. freshwater fish.', 'Food markets'),
  ('f5e0049e-8dcd-5d81-b52c-7dc3fbef7479'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Old school Cantonese Panamanian food. Roast duck, wontons.Westernized Chinese food.', 'Restaurants and Bars'),
  ('f5e81079-97e5-5090-841a-fa267828a190'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Bayshore is one of the priciest neighborhoods in the country. "I''m here as a guest of the Sabgavuds, a successful family of Lebanese Syrians," says Tony.', 'Season 9'),
  ('f60665e8-08da-5936-860d-8eff76d26a63'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony ate with renowned poet Jim Harrison, who also wrote books about food. Jim''s friend Dan cooked some spatchcock Hungarian partridge, liver loaf with elk meat, beets, quail in aspic, elk carpacchio, smoked trout.', 'Season 7'),
  ('f60b5f09-43da-56a5-ac59-e7bf2f1c4edd'::uuid, 'parts_unknown'::show_name, 9, NULL, '"Dishes like pakora and kachori which both came back from India, chapati from East Africa, and shuwa, Oman''s classic special event dish.... they slather a goat with a spicy paste consisting of cumin, coriander, red pepper, cinnamon, cardamom, and nutmeg. Then wrap the meat in palm or banana leaves, dig a hole, throw in some meat, and cover it up and leave underground for a day or two over hot coals."', 'Season 9'),
  ('f631ce19-e635-5f4c-96f3-400fac92eb44'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony hired a boat to learn the history of the canals here, remnants of the ancient Aztec city that originated here (and later became Mexico City)', 'Sightseeing'),
  ('f64f97bf-686e-557a-8b77-357823325bb7'::uuid, 'the_layover'::show_name, 1, 'Beef pot', NULL, 'Season 1'),
  ('f6604e95-aa97-56f0-a18f-3523a4552025'::uuid, 'a_cooks_tour'::show_name, NULL, 'Best pork tacos ever', NULL, 'Disc 2: Mexico and The Americas'),
  ('f66a2a0e-f551-5388-a1a8-eb37f7247154'::uuid, 'parts_unknown'::show_name, 5, NULL, 'This huge night club has many different kinds of acts. Tony met with the owner.', 'Season 5'),
  ('f679bb36-af8c-5243-bcec-661c93b78799'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony went SKIING in this mall. In the middle of the desert.', 'Other Activities'),
  ('f6802c0b-13ea-5a07-b6d8-121fffc4b177'::uuid, 'no_reservations'::show_name, NULL, 'Coffee, croissant', NULL, 'Restaurants and Bars'),
  ('f6d347da-56b2-558c-a40c-34be00f32149'::uuid, 'the_layover'::show_name, 2, 'Dive bar', NULL, 'Season 2'),
  ('f6f7e45b-7efe-53a5-97b2-3fc0afbfb13d'::uuid, 'the_layover'::show_name, 1, 'Kinda like gin, an alcohol made with juniper', NULL, 'Season 1'),
  ('f6fb2ae3-0c67-5d71-b42d-715b1514a1ac'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony and Thomas Yao pregamed here before crashing a wedding. They had moscow mules', 'Season 4'),
  ('f73ebb93-5b11-5969-8f56-3a9585f0b0f5'::uuid, 'the_layover'::show_name, 2, 'Burgers, tacos, cupcakes', NULL, 'Season 2'),
  ('f7411cac-c6f8-55c9-ad7c-237f46363646'::uuid, 'parts_unknown'::show_name, 12, NULL, 'Not sure if this is the hotel where Tony sat at the pool and said “So this, too, is Bali, I guess — or it is now. Thank you, Jimmy Buffett, for taking a big dump on the world. Another wagyu slider, my good man. Yes, thank you. By weight, how much human waste is generated by your average person on vacation. Look around you. Do the math. I want a water sample. I’m telling you, the fecal coliform count is going to be interesting. I’m sure there’s a metaphor here. Am I bitter? Am I just old? Do I just have, like, a predisposition of instinctive hatred of young people? Perhaps. Enjoy the moment. The words of Baba Ram Dass: ‘Be here now.’ But I am here now. I’m not actually having sliders. You eat those fucking things.”', 'Season 12'),
  ('f747e812-3e9c-52e5-8519-1b7e26caddbc'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony had lunch with Douglas Young, founder of Goods of Desire. They had prawn-roe noodles.', 'Season 11'),
  ('f759f5b1-6bbc-57fc-9629-468a71c1df24'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony visited singer-songwriter Margo Price''s home where her musician friends had a party and prepared food. Her husband and bass player in the band, Jeremy, made biscuits topped with pimento cheese and bacon; braised short rib on crostini with goat cheese.', 'Season 8'),
  ('f77a82b5-b55d-5455-9519-6fc06d4201d4'::uuid, 'the_layover'::show_name, 1, 'Dive Bar', NULL, 'Season 1'),
  ('f789ff06-0c9c-5f25-8d07-3025d6245cf5'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony ate here with Chef Boulud and Bill Buford, a former fiction editor at The New Yorker. They had quenelle de brochet en gratin maison (gratin dumplings)', 'Season 3'),
  ('f793cf36-4013-5eff-b637-596cecb53bee'::uuid, 'no_reservations'::show_name, NULL, 'Butcher breaking down meats the old school way', NULL, 'Food markets'),
  ('f7c352c4-a37c-5fe7-843f-d2acafe705cc'::uuid, 'the_layover'::show_name, 2, 'Surgical tools', NULL, 'Season 2'),
  ('f7ead6b3-89af-5e20-bac1-ec057ab6e50e'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony and crew headed to this town to film, but it was on full lockdown as they approached. They walked around the ruins of the town which showed the damage done when the rebellion took down Ghadafi. Afterward, they killed a lamb and barbecued it on the coast of the Mediterranean', 'Season 1'),
  ('f80f5a62-c93c-59ca-b80d-a6b6db17c1c2'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Christopher Doyle and filmmaker Jenny Suen accompanied Tony to eat corn–and–fish ball soup; fried fish ball with dried scallop, dried shrimp, and pork; sun cured salted salted egg yolks served over rice; crispy pork belly cooked in shrimp paste and yu choy', 'Season 11'),
  ('f81095ed-d0c0-5eee-9f73-3701570dbea5'::uuid, 'parts_unknown'::show_name, 2, NULL, 'Tony meets with Tamika (a professional dominatrix; Kinoko Hajime, a shibari (Japanese form of rope bondage) artist and Tamika’s partner; and Naga, a translator also joined) at this Izakaya restaurant. They have Kusaia, which is grilled fermented fish, yakitori, and motsunabe (intestine stew with miso).', 'Season 2'),
  ('f83015d1-e219-59c6-8d60-3a5b61ed1617'::uuid, 'no_reservations'::show_name, NULL, 'Canals and shopping', NULL, 'Sightseeing'),
  ('f84b1570-4ba5-56aa-bd84-9f667131a4b6'::uuid, 'the_layover'::show_name, 2, NULL, 'Tony calls this dive bar "a national treasure"', 'Season 2'),
  ('f84ea364-4eff-51c2-af6e-318591b6b4cb'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and guide bought proscuitto and sausage here', 'Food markets'),
  ('f8f447ce-3f8c-5fb1-96ab-2764ebe0842f'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met with a writer and a Fado singer in this bar to discuss the revolutionary period of the country', 'Restaurants and Bars'),
  ('f92b9d62-a86c-504d-9e52-05cb7e91c607'::uuid, 'a_cooks_tour'::show_name, NULL, 'Caribbean/Creole seafood', NULL, 'Disc 2: Mexico and The Americas'),
  ('f95405c0-1b8b-5cf2-8e38-395871add057'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony and Zamir gambled (and lost) at this casino. They played blackjack and roulette.', 'Season 7'),
  ('f95886ec-2ebb-5e12-81f8-85f748e32499'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony visited the (mostly) abandoned resorts of Salton Sea', 'Sightseeing'),
  ('f9a13e4f-2ef2-59fa-aa87-5531aa8acf4c'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Actor Danny Trejo''s restaurant. Tony had an assortment of tacos just before they had their grand opening: "jidori chicken with chipotle cream sauce, some charred branzino with summer squash and sauteed poblano peppers, and crispy pork tacos with black garlic mole and some fat sacks of uni, and lots of healthy greens."', 'Season 9'),
  ('f9ac19d6-0514-50eb-803a-0fc5d812f0b4'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony and wildlife biologist visited this area where tribal people called Maasai people live and share land with the lions', 'Season 4'),
  ('f9b02b4f-aa73-56ce-9245-89b2481f464f'::uuid, 'the_layover'::show_name, 2, 'Cheesemongers. Local cheeses', NULL, 'Season 2'),
  ('f9faa73e-bb45-5fcc-8a88-c1db4337caac'::uuid, 'parts_unknown'::show_name, 5, NULL, 'Tony is not a sweets guy, but he and Chris visited this salt water taffy place, which is a nostalgic place for them', 'Season 5'),
  ('fa22e4f2-9117-5a1c-9f2d-f3b51e13f03b'::uuid, 'no_reservations'::show_name, NULL, 'Absinthe fountain', NULL, 'Restaurants and Bars'),
  ('fa4c7e57-1b84-5cd7-a18a-b35636f77aaa'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'Many hot dog variations. Tony liked the millennium hot dog even though he was skeptical at first.', 'Disc 1: United States'),
  ('fa725461-4698-5a9c-b808-647745fd02dc'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony visited the Polar Plateau. It is 9000 feet above sea level. The altitude and extreme wind is incredibly harsh, dropping to below 50F. The base has the feel of a space station.', 'Season 9'),
  ('fa7ca0a1-b886-5eb7-89ba-2f7d9f1a1078'::uuid, 'no_reservations'::show_name, NULL, 'Working man''s bar on the marina.', NULL, 'Restaurants and Bars'),
  ('fa8dbd1b-1fad-59b1-a89e-e3eed908d936'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony and Zamir went to a Chiefs tailgate party', 'Other Activities'),
  ('fad3a483-c457-5027-aab0-d433f2546469'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony drove a Ferrari on this famously difficult racing track', 'Other Activities'),
  ('fae072d4-f9ad-5f6f-a19d-f4f327263b11'::uuid, 'the_layover'::show_name, 1, 'Roast goose, roast pork', NULL, 'Season 1'),
  ('faea030b-f88e-5314-88c4-6cc9eb0c07d6'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Farm to table food truck. Grilled quail, brussel sprouts, pork belly', 'Restaurants and Bars'),
  ('faf443c5-94bc-5873-85b4-93686af6cff7'::uuid, 'the_layover'::show_name, 2, NULL, NULL, 'Season 2'),
  ('fb117294-0196-59a3-939b-ea02636cabb0'::uuid, 'the_layover'::show_name, 1, 'Bookstore', NULL, 'Season 1'),
  ('fb126fa5-6a5f-54a1-90ce-79d8f14d67df'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had a meal with Jon Lee Anderson, a writer for the New Yorker. They had steamed dumplings and "Sichuan chicken that is about as Sichuan as I am"', 'Season 6'),
  ('fb381bc8-33e0-56f8-b6e9-48f21a5a8fc2'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony met with Nico (lead singer of band Octafonic) to have a meal at a construction site. In Argentina, construction workers often have barbecued beef together at work once a week.', 'Season 7'),
  ('fb4fc351-a424-5447-b241-6d6edb16525d'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Marseilles'' only Michelin starred restaurant when this was filmed. They had bouillabaisse and a cheese course that Bourdain was obsessed with', 'Season 6'),
  ('fbdb06ea-ce8a-507a-9af7-08f7109da6d2'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Home for "churaqueros," this is a trash dump that over 300 families live on (picking through the waste for recyclables). Tony was really disturbed by going there.', 'Other Activities'),
  ('fbe3273b-cd98-5f0e-ab8c-a1afabc075f5'::uuid, 'the_layover'::show_name, 1, NULL, NULL, 'Season 1'),
  ('fc17310e-a511-590f-8686-957bc21ad915'::uuid, 'parts_unknown'::show_name, 9, NULL, 'Tony ate here with Olatz González Abrisketa, a documentarian and professor of social anthropology at the University of the Basque Country. "Seared mushrooms with egg yolk and pine nuts... grilled tuna with marmitako sauce, a reference to a classic fishermen''s stew; peas in a consommé of Ibérico ham," and squid with a white bean cream.', 'Season 9'),
  ('fc67c884-20cc-54df-a499-82a2703f3e5e'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had pork belly (cooked with stock, heavily infused with bonito flakes), pork ears thinly sliced and dressed in rice-wine vinaigrette, slow-roasted ribs brined in sake and seasonings.', 'Season 6'),
  ('fc71b84c-17ce-5312-8bbc-4e75a96b133d'::uuid, 'the_layover'::show_name, 2, NULL, 'Where Tony stayed', 'Season 2'),
  ('fc961332-1afa-550b-827a-a170b5190498'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony played a game called Chinquilho which involves throwing a 7-lb weight at a small explosive', 'Other Activities'),
  ('fca44ffb-ca8f-59c6-aac9-b7c902b268e7'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony saw his first Australian rugby game here: The Rabbitohs vs. the Roosters', 'Other Activities'),
  ('fca9a1ac-45bf-5ae5-8b11-46622d13c3f2'::uuid, 'parts_unknown'::show_name, 4, NULL, 'Tony had coffee and a pastry at an outdoor cafe here', 'Season 4'),
  ('fcb32d7f-d27c-5ebe-ac66-f8689860db66'::uuid, 'parts_unknown'::show_name, 10, NULL, 'Tony took a 10-hour train ride to Jaffna.', 'Season 10'),
  ('fcb58eea-66fd-5833-a027-693de9efa71a'::uuid, 'a_cooks_tour'::show_name, NULL, 'A fancy restaurant', NULL, 'Disc 4: Morocco & Russia'),
  ('fd04ccb2-da03-5793-8752-b9bc72eccaf1'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony met with Kuldeep Patel, league president of the Houston Indian Cricket Club, and other local cricket players. They watched a game and then ate tandoori chicken, curried goat, and potato masala dosas.', 'Season 8'),
  ('fd58a97a-e469-50a0-84b0-bdd5f5cfa750'::uuid, 'parts_unknown'::show_name, 8, NULL, 'The Vietnamese owners fulfill a niche of the community, serving Vietnamese and Mexican food. Pho (brisket, eye round, meatball, tripe, and tendon); shrimp ceviche; tacos with eggs, jalapenos, tomatoes.', 'Season 8'),
  ('fd62a1f6-9dc9-59bb-8e80-c879b417b115'::uuid, 'parts_unknown'::show_name, 1, NULL, 'Tony rested on the beach after crashing on his ATV, had beer, and ate at a restaurant called Mar Azul (which I could not find on the map). They had cazuela, which is a fish chowder made with lobster, fish, shrimp, clams, and conch.', 'Season 1'),
  ('fd72affc-d7cc-5dfa-b1d3-e3929ad9530a'::uuid, 'the_layover'::show_name, 2, 'Medical oddities, antique medical instruments', NULL, 'Season 2'),
  ('fda69af4-a58e-58b8-bee2-fd6235ddc805'::uuid, 'parts_unknown'::show_name, 8, NULL, 'Tony and Asia Argento had pasta for dinner ringside at a boxing match.', 'Season 8'),
  ('fddb77af-dbd3-5e40-be5d-6d70726c7dfe'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony had food poisoning when he went to the beach here for surfing', 'Other Activities'),
  ('fddb807f-e7d5-5d9d-a206-293a515e7d60'::uuid, 'parts_unknown'::show_name, 8, NULL, 'A burger joint that is also a hangout for Nashville musicians. They had burgers and hot fries (smothered with cheese and hot chicken flavor), which Tony called "country poutine."', 'Season 8'),
  ('fddba49b-d3ad-5b2e-b716-a2be8a039d3b'::uuid, 'the_layover'::show_name, 2, 'Ice cream', NULL, 'Season 2'),
  ('fde41e32-33b7-5a54-a89e-09b62636eac0'::uuid, 'parts_unknown'::show_name, 3, NULL, 'Tony had tandoori chicken and fresh baked naan', 'Season 3'),
  ('fe23ab45-87a7-5c73-abc7-5fa9f558c0e7'::uuid, 'the_layover'::show_name, 1, 'Japanese barbecue (Yakinuku). Dinner only.', NULL, 'Season 1'),
  ('fe4c9ab4-5b6d-5687-bf80-6cc101af14f5'::uuid, 'no_reservations'::show_name, NULL, 'Family owned traditional Italian. Known for their wild boar.', NULL, 'Restaurants and Bars'),
  ('fe6396db-570c-502c-92b1-833a7d6a199e'::uuid, 'a_cooks_tour'::show_name, NULL, 'Beer', NULL, 'Disc 1: United States'),
  ('fe7e7b5b-a29e-5fa1-8d65-0ab5854618d5'::uuid, 'parts_unknown'::show_name, 2, NULL, 'This place has a strain of chile grown specifically for the restaurant. Tony ate enchiladas with carne adobada (pork marinated in red chile sauce), beans and rice, pozole (hominy), sopapilla (fried bread) and green chile salsa (level 3 of spiciness, which Tony said was painful).', 'Season 2'),
  ('fe83cd78-f75f-5fdb-be76-cac5b9bbbc7f'::uuid, 'parts_unknown'::show_name, 6, NULL, 'Tony had whole fried fish and an alcoholic beverage called raki', 'Season 6'),
  ('fea76431-1bde-50c0-b120-e4e0d69331d0'::uuid, 'no_reservations'::show_name, NULL, NULL, 'They had beer and complimentary beef stew', 'Restaurants and Bars'),
  ('fec5d0e9-08ee-58c2-ae5c-0482552a9b07'::uuid, 'the_layover'::show_name, 2, 'Butcher shops, cheesemongers, baguettes', NULL, 'Season 2'),
  ('fecd241a-5b83-548a-8d36-df802b943911'::uuid, 'a_cooks_tour'::show_name, NULL, NULL, 'This was Tony''s favorite restaurant on earth. It closed. He was very happy here.', 'Disc 2: Mexico and The Americas'),
  ('fee1994a-a5c5-5aab-b649-7962873112a7'::uuid, 'the_layover'::show_name, 2, 'Strip club', NULL, 'Season 2'),
  ('fef8835f-484f-55aa-9ce1-d660597e7310'::uuid, 'no_reservations'::show_name, NULL, NULL, '"Big daddy of the DC restaurant scene," says Tony of Jose Andres', 'Restaurants and Bars'),
  ('ff0b04e0-2af9-5a13-9c93-677e8fb30b0e'::uuid, 'parts_unknown'::show_name, 7, NULL, 'Tony had a meal with locals. They ate mulet farci, a stuffed baked local fish called mullet, stuffed with bread and vegetables and baked.', 'Season 7'),
  ('ff44ec00-3f8a-59e8-84ef-6c68a23390a9'::uuid, 'the_layover'::show_name, 2, NULL, 'Old school French bistro. Terrine, sausages, pate, grilled sardine', 'Season 2'),
  ('ff7ef986-2b7e-5a64-8bd8-e0a0802c41ac'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony met up with Queens of the Stone Age band member Josh Homme. They serve BBQ. Josh had the rib eye and Tony had the ribs', 'Restaurants and Bars'),
  ('ff8dd48a-edb0-59de-acfd-f66e25c4fad2'::uuid, 'parts_unknown'::show_name, 11, NULL, 'Tony, Fred Morin, and Dave McMillan had a seafood tower of "razor clams, snow crab, mussels, capelin, whelks, and sea urchin," boquerones; scallop crudo with smoked roe; tuna prepared with berries; heart of caribou tartare with alder and chanterelle mushrooms; charred whelk with crispy cod sounds (fried fish bladders); cod filet with cod liver canelé, partridge profiteroles, Jiggs dinner (a boiled dish of meat and root veggies) reinvented as a pasta dish, chanterelle ice cream.', 'Season 11'),
  ('ff9b0d60-b912-50cd-bdd5-c332f9eecfdb'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Hoisin steamed fish, locally raised steak, pork chops, baby abalone', 'Restaurants and Bars'),
  ('ffca06d0-b053-53fe-9d65-244f449b83ab'::uuid, 'the_layover'::show_name, 2, 'Sandwiches', NULL, 'Season 2'),
  ('ffe39e0d-bd0c-53d8-80a3-fd69bff1abc1'::uuid, 'no_reservations'::show_name, NULL, NULL, 'Tony skiied while his companions snowboarded down this mountain, It had a been a dream of his to someday ski here', 'Other Activities');
